// ════════════════════════════════════════════════════════════
//  CONFIG — Product catalog loaded from Supabase listings table.
//  To maximise keyword coverage, run this once in Supabase SQL Editor:
//
//  See supabase/migrations/20260611120000_get_product_catalog_panel_date.sql
//  (filters to the scrape panel day with the most rows in the last 7 days).
//  GRANT EXECUTE ON FUNCTION public.get_product_catalog() TO anon, authenticated;
// ════════════════════════════════════════════════════════════

// Clarity is network-deferred until load+idle to protect LCP, so window.clarity
// may not exist yet when early code (e.g. the OAuth-return sign-in path) fires
// events. This ensures the official queue stub exists first — the real tag
// drains .q when it arrives — so events are queued instead of dropped.
// (Launch week Jul 2026: only 2 of 27 real signups reached Clarity this way.)
function _clarity() {
  const w = window;
  if (!w.clarity) w.clarity = function () { (w.clarity.q = w.clarity.q || []).push(arguments); };
  try { w.clarity.apply(w, arguments); } catch (_) {}
}

// First-assignment Clarity event (queued until deferred tag loads). Set by the
// early AB script via sessionStorage so B→/gpt/ redirects still record it.
(function _lidClarityAbAssigned() {
  try {
    const raw = sessionStorage.getItem('_lid_ab_just_assigned');
    if (!raw) return;
    sessionStorage.removeItem('_lid_ab_just_assigned');
    const info = JSON.parse(raw) || {};
    _clarity('event', 'ab_assigned');
    if (info.v) _clarity('set', 'ab_variant', String(info.v));
    if (info.via) _clarity('set', 'ab_via', String(info.via));
  } catch (_) {}
})();

function _lidAbStamp(metadata) {
  const m = metadata && typeof metadata === 'object' ? { ...metadata } : {};
  if (m.ab_variant) return m;
  try {
    const ab = JSON.parse(localStorage.getItem('_lid_ab_v1') || 'null');
    if (ab && (ab.v === 'A' || ab.v === 'B' || ab.v === 'X')) {
      m.ab_variant = ab.v;
      if (ab.via) m.ab_via = ab.via;
    }
  } catch (_) {}
  return m;
}

const _LID_SIGNUP_EVT_KEY = '_lid_signup_evt';
const _LID_OAUTH_SIGNUP_INTENT_KEY = '_lid_oauth_signup_intent';
const _LID_SIGNUP_CTA_KEY = '_lid_signup_cta_source';

function _lidIsNewSignup(user) {
  if (!user) return false;
  try { if (sessionStorage.getItem(_LID_OAUTH_SIGNUP_INTENT_KEY) === '1') return true; } catch (_) {}
  const created = user.created_at;
  const lastIn = user.last_sign_in_at;
  if (created && lastIn) {
    if (created === lastIn) return true;
    const cMs = Date.parse(created);
    const lMs = Date.parse(lastIn);
    if (!Number.isNaN(cMs) && !Number.isNaN(lMs) && Math.abs(lMs - cMs) < 120000) return true;
    if (!Number.isNaN(cMs) && Date.now() - cMs < 300000) return true;
  }
  return false;
}

// Durable per-user "signup already recorded" marker. sessionStorage dedupe is
// not enough: session restores keep created_at === last_sign_in_at, and mobile
// tabs live for days — so returns re-fired signup_success + signup_attribution
// (observed 3x same session and again on a day-2 return, Jul 2026).
const _LID_SIGNUP_DONE_KEY = '_lid_signup_done_v1';
function _lidSignupAlreadyRecorded(userId) {
  try { return !!(JSON.parse(localStorage.getItem(_LID_SIGNUP_DONE_KEY) || '{}')[userId]); } catch (_) { return false; }
}
function _lidMarkSignupRecorded(userId) {
  try {
    const m = JSON.parse(localStorage.getItem(_LID_SIGNUP_DONE_KEY) || '{}');
    m[userId] = 1;
    localStorage.setItem(_LID_SIGNUP_DONE_KEY, JSON.stringify(m));
  } catch (_) {}
}

function _lidFireSignupSuccess() {
  try {
    if (sessionStorage.getItem(_LID_SIGNUP_EVT_KEY)) return;
    sessionStorage.setItem(_LID_SIGNUP_EVT_KEY, '1');
    sessionStorage.removeItem(_LID_OAUTH_SIGNUP_INTENT_KEY);
    _clarity('event', 'signup_success');
    _clarity('set', 'signed_up', 'true');
    const ctaSrc = sessionStorage.getItem(_LID_SIGNUP_CTA_KEY);
    if (ctaSrc) _clarity('set', 'signup_cta_source', ctaSrc);
  } catch (_) {}
}

// First-touch acquisition attribution, captured at script eval BEFORE any OAuth
// round-trip rewrites document.referrer to accounts.google.com (which hid the
// true source for most of the launch cohort). Read back in _authOnSignIn and
// attached to the signup event (Clarity tag + activity_events row).
(function _lidCaptureAttribution() {
  try {
    const KEY = '_lid_attr_v1';
    if (localStorage.getItem(KEY)) return; // first touch wins
    const ref = document.referrer || '';
    if (/accounts\.google\.com/.test(ref)) return; // OAuth bounce, not a source
    const q = new URLSearchParams(location.search);
    let abVariant = 'A';
    let abVia = '';
    try {
      const ab = JSON.parse(localStorage.getItem('_lid_ab_v1') || 'null');
      if (ab && (ab.v === 'A' || ab.v === 'B' || ab.v === 'X')) abVariant = ab.v;
      if (ab && ab.via) abVia = ab.via;
    } catch (_) {}
    const attr = {
      referrer: ref || '(direct)',
      utm_source: q.get('utm_source') || '',
      utm_medium: q.get('utm_medium') || '',
      utm_campaign: q.get('utm_campaign') || '',
      ref_code: q.get('ref') || '',
      landing: location.pathname + location.search,
      ab_variant: abVariant,
      ab_via: abVia || 'random',
      ts: new Date().toISOString(),
    };
    localStorage.setItem(KEY, JSON.stringify(attr));
  } catch (_) {}
})();

// Win-back pass capture. The claim link is ?pass=<token>, but Google OAuth
// bounces through accounts.google.com and comes back without the query string,
// so the token is parked in localStorage BEFORE any redirect and consumed after
// sign-in (see _winbackMaybeClaim). Last link wins — a newer campaign token
// should replace an older unconsumed one. The param is stripped from the URL so
// a refresh does not re-trigger and the token is not left on screen.
const LID_PASS_KEY = '_lid_pass_token_v1';
// Which SPECIFIC template variant (wb1_a vs wb1_b vs wb2_kota...) drove this
// click, for per-campaign funnel stats. Deliberately separate from
// _lid_attr_v1: that store is "first touch wins" and every winback recipient
// already has an old attribution record from their original signup, so a
// fresh utm_campaign here would otherwise be silently discarded.
const LID_PASS_CAMPAIGN_KEY = '_lid_pass_campaign_v1';
(function _lidCapturePassToken() {
  try {
    const q = new URLSearchParams(location.search);
    const tok = q.get('pass');
    if (!tok) return;
    // Real tokens are uuids; anything else is not worth storing or sending.
    if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(tok)) return;
    localStorage.setItem(LID_PASS_KEY, tok);
    const camp = q.get('utm_campaign');
    if (camp) localStorage.setItem(LID_PASS_CAMPAIGN_KEY, camp);
    q.delete('pass');
    const qs = q.toString();
    history.replaceState(null, '', location.pathname + (qs ? '?' + qs : '') + location.hash);
  } catch (_) {}
})();

// Anonymous landing/page-view logging → public.page_views via the log_page_view
// RPC (anon-executable). Powers the admin overview "Landing Views / Unique
// Visitors / Returning Visitors" cards. Fires once per browser session (per tab
// load); visitor_id persists in localStorage so a visitor returning on a later
// day is counted as a returning visitor. Fire-and-forget; never blocks boot.
function _lidVisitorId() {
  try {
    let id = localStorage.getItem('_lid_vid');
    if (!id) {
      id = (window.crypto?.randomUUID?.() || ('v' + Date.now().toString(36) + Math.random().toString(36).slice(2, 10)));
      localStorage.setItem('_lid_vid', id);
    }
    return id;
  } catch (_) { return null; }
}
function _lidLogPageView() {
  try {
    if (!_supabase) return;
    // Once per tab session.
    if (sessionStorage.getItem('_lid_pv_sent')) return;
    let sid = sessionStorage.getItem('_lid_sid');
    const isNewSession = !sid;
    if (!sid) {
      sid = (window.crypto?.randomUUID?.() || ('s' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8)));
      sessionStorage.setItem('_lid_sid', sid);
    }
    const vid = _lidVisitorId();
    if (!vid) return;
    const q = new URLSearchParams(location.search);
    // Stamp the arm so landing counts can be sliced per variant and direct_gpt
    // visits excluded from the cohort. Reuses the same _lid_ab_v1 read that
    // tags activity_events, so page_views and events agree on the arm.
    const ab = _lidAbStamp({});
    _supabase.rpc('log_page_view', {
      p_visitor_id: vid,
      p_session_id: sid,
      p_path: location.pathname,
      p_referrer: (document.referrer || '(direct)').slice(0, 300),
      p_utm_source: q.get('utm_source') || '',
      p_is_new_session: isNewSession,
      p_ab_variant: ab.ab_variant || null,
      p_ab_via: ab.ab_via || null,
    }).then((res) => {
      // Require ok:true — void/204-with-no-row used to look like success.
      if (res?.error) return;
      const body = res?.data;
      if (!(body && typeof body === 'object' && body.ok === true)) return;
      try { sessionStorage.setItem('_lid_pv_sent', '1'); } catch (_) {}
    }, () => {});
  } catch (_) {}
}

async function larisEnsureChart() {
  if (typeof Chart !== 'undefined') return;
  if (typeof ensureChartJs === 'function') await ensureChartJs();
}

async function larisEnsureJsPdf() {
  if (window.jspdf) return;
  if (typeof ensureJsPdf === 'function') await ensureJsPdf();
}

function larisBootDashboardData() {
  if (window.__larisCatalogBooted) return;
  window.__larisCatalogBooted = true;
  loadData();
  setTimeout(function () {
    if (typeof dscInit === 'function' && !_nuOnb.visible && !nuOnbPendingSync()) dscInit();
  }, 300);
  setTimeout(function () { if (typeof ylkInit === 'function') ylkInit(); }, 700);
  setTimeout(function () { if (typeof naikDaunInit === 'function') naikDaunInit(); }, 800);
}

