//  STATE
// ════════════════════════════════════════════════════════════
let allProducts    = [];
let compareList    = [];
let filtered       = [];
let activeCat      = 'all';
let searchQ        = '';
let currentProduct = null;
let prevPage       = 'home';
let activeQuick    = 'hot';
let currentUser    = null;
let savedProducts  = new Set(); // set of product IDs the user has saved
