// ════════════════════════════════════════════════════════════
//  FETCH HELPERS
// ════════════════════════════════════════════════════════════


// Fetch any Google Sheet tab as array of row objects
// ── JSONP fallback: bypasses CORS via script injection ──
// Google always calls google.visualization.Query.setResponse(), so we
// intercept it globally and use reqId to route concurrent responses.

// ════════════════════════════════════════════════════════════
//  FORMAT
// ════════════════════════════════════════════════════════════
function fmt(n) {
  if (!n && n !== 0) return '—';
  return 'Rp' + Math.round(n).toLocaleString('id-ID');
}
function fmtShort(n) {
  if (!n) return '—';
  if (n >= 1e9) return 'Rp' + (n/1e9).toFixed(1) + 'M';
  if (n >= 1e6) return 'Rp' + (n/1e6).toFixed(1) + 'jt';
  if (n >= 1e3) return 'Rp' + (n/1e3).toFixed(0) + 'rb';
  return fmt(n);
}
function fmtScore(n) {
  if (!n) return '—';
  return Math.round(parseFloat(n)).toString();
}

// Map internal app role → human label for profile pill
function profileRoleLabel(role) {
  const r = String(role || '').toLowerCase();
  if (r === 'admin') return 'Admin';
  if (r === 'leader') return 'Leader';
  if (r === 'student' || r === 'mentor') return 'Student';
  if (r === 'independent') return 'Independent';
  return 'Independent';
}

function adminRoleLabel(role) {
  return profileRoleLabel(role);
}

function adminRoleColor(role) {
  const r = String(role || '').toLowerCase();
  if (r === 'admin') return '#B5202A';
  if (r === 'leader') return '#B45309';
  if (r === 'student') return '#1A7A46';
  return '#6B7280';
}

function scoreColor(n) {
  const v = parseFloat(n);
  if (!v) return '#aaa';
  if (v >= 80) return '#1A7A46';   // green  (brand: 80–100)
  if (v >= 50) return '#B45309';   // amber  (brand: 50–79)
  return '#C0392B';                 // red    (brand: 0–49)
}

// ════════════════════════════════════════════════════════════
//  PROFILE: LOAD / SAVE / HEADSHOT
// ════════════════════════════════════════════════════════════
async function loadUserProfile() {
  if (!_supabase || !currentUser) {
    _profileState = { loaded: false, row: null, headshotUploading: false };
    return;
  }
  try {
    const { data, error } = await _supabase
      .from('user_profiles')
      .select('*')
      .eq('user_id', currentUser.id)
      .maybeSingle();
    if (error) throw error;
    _profileState = { loaded: true, row: data || null, headshotUploading: false };
    hydrateProfileEditUI();
  } catch (e) {
    console.warn('loadUserProfile error', e.message || e);
  }
}

function hydrateProfileEditUI() {
  const row = _profileState.row || {};
  const nameInput   = document.getElementById('profile-display-name-input');
  const waInput     = document.getElementById('profile-wa-input');
  const emailInput  = document.getElementById('profile-email-input');
  const shopeeInput = document.getElementById('profile-shopee-url-input');
  const bioInput    = document.getElementById('profile-bio-input');
  const rolePill    = document.getElementById('profile-role-pill');
  const avatar      = document.getElementById('profile-edit-avatar');
  const avatarImg   = document.getElementById('profile-edit-avatar-img');
  const initialsEl  = document.getElementById('profile-edit-avatar-initials');

  const fullName = (row.display_name && row.display_name.trim())
    || [row.first_name, row.last_name].filter(Boolean).join(' ').trim()
    || (currentUser?.user_metadata?.full_name || '')
    || (currentUser?.email || '').split('@')[0];

  if (nameInput) nameInput.value = fullName || '';
  if (waInput) waInput.value = row.public_whatsapp || row.wa_number || '';
  if (emailInput) emailInput.value = row.public_email || row.contact_email || (currentUser?.email || '');
  if (shopeeInput) shopeeInput.value = row.public_shopee_url || row.shopee_store_url || '';
  if (bioInput) bioInput.value = row.bio || '';

  const roleLabel = profileRoleLabel(_accessState.role);
  if (rolePill) rolePill.textContent = roleLabel;

  const initials = (fullName || '?')
    .split(' ')
    .filter(Boolean)
    .slice(0, 2)
    .map(part => part.charAt(0).toUpperCase())
    .join('') || '?';
  if (initialsEl) initialsEl.textContent = initials;

  const url = row.headshot_url || '';
  if (avatarImg && initialsEl) {
    if (url) {
      avatarImg.src = url;
      avatarImg.style.display = '';
      initialsEl.style.display = 'none';
    } else {
      avatarImg.src = '';
      avatarImg.style.display = 'none';
      initialsEl.style.display = '';
    }
  }

  // Sync sidebar + topbar avatars with headshot
  const _imgStyle = 'width:100%;height:100%;border-radius:50%;object-fit:cover;';
  const dashAvEl = document.getElementById('dash-avatar');
  if (dashAvEl) {
    if (url) {
      dashAvEl.innerHTML = `<img src="${url}" style="${_imgStyle}" alt="">`;
    } else {
      const initLetter = (initials || '?').charAt(0);
      dashAvEl.innerHTML = initLetter;
    }
  }
  const tbAvIcon = document.getElementById('dash-topbar-av-icon');
  if (tbAvIcon) {
    if (url) {
      tbAvIcon.outerHTML = `<img id="dash-topbar-av-icon" src="${url}" style="${_imgStyle}" alt="">`;
    } else {
      tbAvIcon.textContent = (initials || '?').charAt(0);
    }
  }
}

function openProfileEditModal() {
  if (!currentUser) { openAuthModal('login'); return; }
  const modal = document.getElementById('profile-edit-modal');
  if (!modal) return;
  if (!_profileState.loaded) {
    void loadUserProfile().catch(() => {});
  } else {
    hydrateProfileEditUI();
  }
  modal.style.display = 'flex';
  /* WS-D: load badge shelf + certificates when the profile opens */
  try { void renderProfileBadges(); } catch (_) {}
  try { void renderProfileCertificates(); } catch (_) {}
}

function closeProfileEditModal() {
  const modal = document.getElementById('profile-edit-modal');
  if (modal) modal.style.display = 'none';
}

async function handleProfileHeadshotChange(ev) {
  const file = ev?.target?.files?.[0];
  const statusEl = document.getElementById('profile-edit-status');
  if (!file) return;
  if (!_supabase || !currentUser) { if (statusEl) statusEl.textContent = 'Login diperlukan.'; return; }
  if (file.size > 2 * 1024 * 1024) {
    if (statusEl) statusEl.textContent = 'Ukuran foto maksimal 2 MB.';
    return;
  }
  try {
    _profileState.headshotUploading = true;
    if (statusEl) statusEl.textContent = 'Mengunggah foto...';
    const path = `headshots/${currentUser.id}/${Date.now()}-${file.name}`;
    const { error } = await _supabase.storage
      .from('profile-headshots')
      .upload(path, file, { upsert: true, cacheControl: '3600' });
    if (error) throw error;
    const { data: pub } = await _supabase.storage.from('profile-headshots').getPublicUrl(path);
    const url = pub?.publicUrl || '';
    _profileState.row = { ...(_profileState.row || {}), headshot_url: url };
    hydrateProfileEditUI();
    if (statusEl) statusEl.textContent = 'Foto berhasil diunggah.';
  } catch (e) {
    console.warn('headshot upload error', e.message || e);
    if (statusEl) statusEl.textContent = 'Gagal mengunggah foto. Coba lagi.';
  } finally {
    _profileState.headshotUploading = false;
  }
}

async function saveProfileEdits() {
  const statusEl   = document.getElementById('profile-edit-status');
  const nameInput  = document.getElementById('profile-display-name-input');
  const waInput    = document.getElementById('profile-wa-input');
  const emailInput = document.getElementById('profile-email-input');
  const shopInput  = document.getElementById('profile-shopee-url-input');
  const bioInput   = document.getElementById('profile-bio-input');
  if (!_supabase || !currentUser) { if (statusEl) statusEl.textContent = 'Login diperlukan.'; return; }

  const payload = {
    user_id: currentUser.id,
    display_name: (nameInput?.value || '').trim() || null,
    public_whatsapp: (waInput?.value || '').trim() || null,
    public_email: (emailInput?.value || '').trim() || null,
    public_shopee_url: (shopInput?.value || '').trim() || null,
    bio: (bioInput?.value || '').trim() || null,
    is_public: true,
  };
  if (_profileState.row?.headshot_url) {
    payload.headshot_url = _profileState.row.headshot_url;
  }

  try {
    if (statusEl) { statusEl.style.color = '#6B7280'; statusEl.textContent = 'Menyimpan profil...'; }
    const { data, error } = await _supabase
      .from('user_profiles')
      .upsert(payload, { onConflict: 'user_id' })
      .select('*')
      .maybeSingle();
    if (error) throw error;
    _profileState.row = data;
    _profileState.loaded = true;
    hydrateProfileEditUI();
    if (statusEl) { statusEl.style.color = '#1A7A46'; statusEl.textContent = 'Profil tersimpan.'; }
    setTimeout(() => closeProfileEditModal(), 1000);
  } catch (e) {
    console.warn('saveProfileEdits error', e.message || e);
    if (statusEl) { statusEl.style.color = '#C0392B'; statusEl.textContent = 'Gagal menyimpan profil. Coba lagi.'; }
  }
}

// Ganti password (akun yang sedang login). Uses stored access token + Supabase
// REST /auth/v1/user (PUT) — the JS-client session is intentionally not synced
// with localStorage in this app, so we call the endpoint directly.
async function changeAccountPassword() {
  const statusEl = document.getElementById('profile-pass-status');
  const btn      = document.getElementById('profile-pass-btn');
  const p1El     = document.getElementById('profile-newpass-input');
  const p2El     = document.getElementById('profile-newpass2-input');
  const setStatus = (color, msg) => { if (statusEl) { statusEl.style.color = color; statusEl.textContent = msg; } };

  const p1 = (p1El?.value || '');
  const p2 = (p2El?.value || '');

  if (!currentUser) { setStatus('#C0392B', 'Login diperlukan.'); return; }
  if (!p1 || !p2)   { setStatus('#C0392B', 'Isi password baru dua kali.'); return; }
  if (p1.length < 8){ setStatus('#C0392B', 'Password minimal 8 karakter.'); return; }
  if (p1 !== p2)    { setStatus('#C0392B', 'Password nggak sama. Cek lagi ya.'); return; }

  const stored = _authLoad();
  let token = stored?.access_token;
  // Refresh first if the token is near expiry, so the update doesn't 401.
  if (stored && stored.expires_at && stored.expires_at < Date.now() + 60000 && stored.refresh_token) {
    const fresh = await _authRefresh(stored.refresh_token);
    if (fresh?.access_token) { _authSave(fresh); token = fresh.access_token; }
  }
  if (!token) { setStatus('#C0392B', 'Sesi habis. Coba login ulang.'); return; }

  const origLabel = btn ? btn.textContent : '';
  if (btn) { btn.disabled = true; btn.textContent = '...'; }
  setStatus('#6B7280', 'Menyimpan password baru...');
  try {
    const r = await fetch(`${SUPA_URL}/auth/v1/user`, {
      method: 'PUT',
      headers: { apikey: SUPA_KEY, Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ password: p1 }),
    });
    const d = await r.json().catch(() => ({}));
    if (!r.ok) {
      const raw = d.msg || d.message || d.error_description || d.error || '';
      let msg = 'Gagal ganti password. Coba lagi.';
      if (/at least|minimum|6 char|8 char/i.test(raw)) msg = 'Password terlalu pendek. Coba yang lebih panjang.';
      else if (/same.*password|different from/i.test(raw)) msg = 'Password baru tidak boleh sama dengan yang lama.';
      else if (raw) msg = _authErrMsg(raw);
      throw new Error(msg);
    }
    if (p1El) p1El.value = '';
    if (p2El) p2El.value = '';
    setStatus('#1A7A46', 'Password berhasil diganti.');
  } catch (e) {
    setStatus('#C0392B', e.message || 'Gagal ganti password. Coba lagi.');
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = origLabel || 'Ganti Password'; }
  }
}

async function profileJoinCohortFromProfile() {
  const inp = document.getElementById('profile-cohort-code-input');
  const statusEl = document.getElementById('profile-edit-status');
  const code = (inp && inp.value || '').trim();
  if (!code) { if (statusEl) statusEl.textContent = 'Masukkan kode undangan kohort.'; return; }
  if (!_supabase || !currentUser) { openAuthModal('login'); return; }
  try {
    if (statusEl) { statusEl.style.color = '#6B7280'; statusEl.textContent = 'Memproses undangan kohort...'; }
    const { error } = await _supabase.rpc('join_cohort', { p_invite: code });
    if (error) throw error;
    if (inp) inp.value = '';
    await cohortInit();
    if (statusEl) { statusEl.style.color = '#1A7A46'; statusEl.textContent = 'Berhasil gabung kohort.'; }
  } catch (e) {
    console.warn('profileJoinCohortFromProfile error', e.message || e);
    if (statusEl) { statusEl.style.color = '#C0392B'; statusEl.textContent = 'Gagal gabung kohort. Cek kode atau hubungi mentor.'; }
  }
}

function copyProfileShareLink() {
  const statusEl = document.getElementById('profile-edit-status');
  if (!currentUser) { if (statusEl) statusEl.textContent = 'Login diperlukan.'; return; }
  const origin = window.location.origin || 'https://larisid.com';
  const url = `${origin}?view=profile&user=${encodeURIComponent(currentUser.id)}`;
  try {
    navigator.clipboard.writeText(url).then(() => {
      if (statusEl) { statusEl.style.color = '#1A7A46'; statusEl.textContent = 'Link profil disalin ke clipboard.'; }
    }).catch(() => {
      if (statusEl) { statusEl.style.color = '#6B7280'; statusEl.textContent = url; }
    });
  } catch (_) {
    if (statusEl) { statusEl.style.color = '#6B7280'; statusEl.textContent = url; }
  }
}

// ════════════════════════════════════════════════════════════
//  PARSE HELPERS
//  Handles formats like: Rp85,000 / 85.000 / 85,000 / 13,3k / 1.2M
// ════════════════════════════════════════════════════════════
function parseRp(val) {
  if (!val && val !== 0) return 0;
  // Remove currency symbols and spaces
  let s = String(val).replace(/Rp/gi, '').replace(/\s/g, '').trim();
  // Handle shorthand: 13,3k → 13300, 1,2M → 1200000, 1,2jt → 1200000
  if (/[kK]$/.test(s)) return parseFloat(s.replace(',', '.').replace(/[kK]$/, '')) * 1000;
  if (/[mM]$/.test(s)) return parseFloat(s.replace(',', '.').replace(/[mM]$/, '')) * 1000000;
  if (/jt$/i.test(s))  return parseFloat(s.replace(',', '.').replace(/jt$/i, '')) * 1000000;
  // Remove thousand separators — handles both 85,000 and 85.000 styles
  // If there's a comma followed by exactly 3 digits at end → thousand separator
  // If there's a dot followed by exactly 3 digits at end → thousand separator
  s = s.replace(/,(?=\d{3}(\D|$))/g, '').replace(/\.(?=\d{3}(\D|$))/g, '');
  // Now handle decimal comma e.g. 85,5 → 85.5
  s = s.replace(',', '.');
  return parseFloat(s) || 0;
}

// Parse trend strings → numeric %
//   "Trend Up 32.61%"  / "Tren Naik 32.61%"  → +32.61
//   "Trend Down 15%"   / "Tren Turun 15%"     → -15
//   anything else                              → null
function parseTrendPct(str) {
  if (!str) return null;
  const s = String(str).trim();
  const up = s.match(/(?:trend\s+up|tren\s+naik)\s+([\d.,]+)%?/i);
  if (up) return parseFloat(up[1].replace(',', '.'));
  const dn = s.match(/(?:trend\s+down|tren\s+turun)\s+-?([\d.,]+)%?/i);
  if (dn) return -parseFloat(dn[1].replace(',', '.'));
  return null;
}

function parseReviews(val) {
  if (!val && val !== 0) return 0;
  let s = String(val).replace(/\s/g, '').trim();
  // Handle 13,3k / 13.3k / 1,2M / 1jt etc
  if (/[kK]$/.test(s)) return Math.round(parseFloat(s.replace(',', '.').replace(/[kK]$/, '')) * 1000);
  if (/[mM]$/.test(s)) return Math.round(parseFloat(s.replace(',', '.').replace(/[mM]$/, '')) * 1000000);
  if (/jt$/i.test(s))  return Math.round(parseFloat(s.replace(',', '.').replace(/jt$/i, '')) * 1000000);
  // Remove thousand separators
  s = s.replace(/,(?=\d{3}(\D|$))/g, '').replace(/\.(?=\d{3}(\D|$))/g, '');
  return parseInt(s) || 0;
}

// ════════════════════════════════════════════════════════════
//  LOAD DATA
// ════════════════════════════════════════════════════════════
// ── SCORE + CATEGORY HELPERS (Supabase data) ─────────────────────────────
function _computeScore(totalSold, avgRating, sellerCount, topReviews) {
  // Demand: log scale, 1k→50, 10k→75, 100k→100
  const demandScore = Math.min(100, Math.log10(Math.max(1, totalSold)) / 4 * 100);
  const ratingScore = Math.min(100, Math.max(0, ((avgRating || 0) - 3) / 2 * 100));
  // Competition: log scale so 25 sellers=63pts, 200=85pts, 1000=100pts (not instant-zero)
  const compPenalty = Math.max(0, 100 - Math.min(100, Math.log10(Math.max(1, sellerCount)) / 2.7 * 100));
  const revScore    = Math.min(100, Math.log10(Math.max(1, topReviews || 1)) / 4 * 100);
  return Math.max(1, Math.round(demandScore * 0.4 + ratingScore * 0.25 + compPenalty * 0.2 + revScore * 0.15));
}

function _guessCat(kw) {
  const k = (kw || '').toLowerCase();
  if (/dapur|masak|spatula|wajan|panci|pisau|talenan|blender|parut|pengaduk|makan|sendok|garpu/.test(k)) return 'Dapur';
  if (/mandi|sabun|handuk|sikat gigi|cermin|shower/.test(k)) return 'Kamar Mandi';
  if (/baju|celana|kaos|kemeja|dress|rok|jaket|sepatu|tas|dompet|fashion|topi|hat/.test(k)) return 'Fashion';
  if (/hp|handphone|ponsel|charger|kabel|headset|earphone|powerbank|casing/.test(k)) return 'HP & Gadget';
  if (/laptop|komputer|keyboard|mouse|monitor|printer|speaker|kamera|elektronik/.test(k)) return 'Elektronik';
  if (/motor|mobil|ban|helm|oli|velg|aki/.test(k)) return 'Motor & Mobil';
  if (/bayi|anak|mainan|popok|susu|stroller/.test(k)) return 'Bayi & Anak';
  if (/kecantikan|skincare|lipstik|maskara|bedak|serum|moisturizer/.test(k)) return 'Kecantikan';
  if (/olahraga|gym|sepeda|lari|yoga|fitness|dumbbell|golf|bola/.test(k)) return 'Olahraga';
  if (/tanaman|pot|pupuk|benih|biji|hidroponik/.test(k)) return 'Tanaman';
  if (/hewan|anjing|kucing|pakan|kandang/.test(k)) return 'Hewan Peliharaan';
  if (/outdoor|camping|tenda|ransel|survival/.test(k)) return 'Outdoor & Camping';
  if (/kesehatan|obat|vitamin|masker|termometer|tensimeter/.test(k)) return 'Kesehatan';
  if (/taman|lampu taman|pupuk taman/.test(k)) return 'Taman';
  if (/gembok|kunci|cctv|alarm|brankas|keamanan/.test(k)) return 'Keamanan';
  if (/alat tulis|buku|pensil|pulpen|spidol/.test(k)) return 'Alat Tulis';
  if (/hobi|kerajinan|lukis|puzzle|menjahit/.test(k)) return 'Hobi & Kerajinan';
  return 'Rumah';
}

async function _fetchListingsPage(offset, limit = 1000) {
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), 8000);
  try {
    const resp = await fetch(
      `${SUPA_URL}/rest/v1/listings_deduped?select=keyword,product_name,price,total_sold,image_url,category,rating,reviews,item_id,shop_id&order=total_sold.desc`,
      { signal: ctrl.signal, headers: { apikey: SUPA_KEY, Authorization: `Bearer ${SUPA_KEY}`, Range: `${offset}-${offset + limit - 1}` } }
    );
    clearTimeout(t);
    if (!resp.ok) return [];
    return resp.json();
  } catch (_) { clearTimeout(t); return []; }
}

async function loadData() {

  const CACHE_KEY = 'laris_catalog_v4';
  const CACHE_TTL = 60 * 60 * 1000; // 1 hour
  const loadingMsg = '<div style="grid-column:1/-1;text-align:center;padding:40px;color:#6B7280;font-size:.85rem;">Memuat produk...</div>';
  const homeGridEl = document.getElementById('home-grid');
  const discGridEl = document.getElementById('disc-grid');
  if (homeGridEl) homeGridEl.innerHTML = loadingMsg;
  if (discGridEl) discGridEl.innerHTML = loadingMsg;

  let rows = null;
  try {
    const c = JSON.parse(localStorage.getItem(CACHE_KEY) || 'null');
    if (c?.ts && Date.now() - c.ts < CACHE_TTL && c.rows?.length) {
      rows = c.rows;
      console.log('LarisID: products from cache');
    }
  } catch (_) {}

  if (!rows) {
    try {
      // Try the efficient RPC function (skips gracefully if not yet created).
      // get_product_catalog now reads the mv_product_catalog matview (one row
      // per keyword, 876 today) instead of a distinct-on over 1.06M listings,
      // so it answers in milliseconds. It previously exceeded its own 30 s
      // server cap and NEVER beat the old 3 s abort, which silently pushed
      // every uncached visitor onto the 5×1000-row fallback below (and that
      // fallback itself 500s). 8 s leaves room for slow mobile links while
      // still degrading rather than hanging.
      const ctrl = new AbortController();
      const t = setTimeout(() => ctrl.abort(), 8000);
      const rpcResp = await fetch(`${SUPA_URL}/rest/v1/rpc/get_product_catalog`, {
        method: 'POST', signal: ctrl.signal,
        headers: { apikey: SUPA_KEY, Authorization: `Bearer ${SUPA_KEY}`, 'Content-Type': 'application/json' }, body: '{}'
      });
      clearTimeout(t);
      if (rpcResp.ok) {
        const rpcData = await rpcResp.json();
        if (Array.isArray(rpcData) && rpcData.length) {
          rows = rpcData;
          console.log('LarisID: loaded', rows.length, 'products via RPC');
        }
      }
    } catch (_) {}

    // Fallback: fetch 5 pages from listings in parallel and deduplicate
    if (!rows?.length) {
      try {
        const pages = await Promise.all([
          _fetchListingsPage(0),
          _fetchListingsPage(1000),
          _fetchListingsPage(2000),
          _fetchListingsPage(3000),
          _fetchListingsPage(4000),
        ]);
        const all = pages.flat();
        // Deduplicate by item_id+shop_id, keeping highest total_sold
        const seen = new Map();
        for (const r of all) {
          const k = `${r.item_id}_${r.shop_id}`;
          if (!seen.has(k) || (r.total_sold || 0) > (seen.get(k).total_sold || 0)) seen.set(k, r);
        }
        rows = [...seen.values()];
        console.log('LarisID: loaded', rows.length, 'products via fallback');
      } catch (e) {
        console.error('LarisID: load failed', e);
      }
    }

    if (rows?.length) {
      try { localStorage.setItem(CACHE_KEY, JSON.stringify({ ts: Date.now(), rows })); } catch (_) {}
    }
  }

  if (!rows?.length) {
    const g = document.getElementById('home-grid'), d = document.getElementById('disc-grid');
    const msg = '<div style="grid-column:1/-1;text-align:center;padding:40px;color:#C0392B;font-size:.85rem;">Gagal memuat produk. Periksa koneksi internet dan muat ulang halaman.</div>';
    if (g) g.innerHTML = msg; if (d) d.innerHTML = msg;
    return;
  }

  // Group by keyword, pick best product per keyword, compute stats
  const byKw = {};
  for (const r of rows) {
    if (!r.keyword) continue;
    if (!byKw[r.keyword]) byKw[r.keyword] = [];
    byKw[r.keyword].push(r);
  }

  let idx = 0;
  allProducts = Object.entries(byKw).map(([kw, prods]) => {
    const sorted    = [...prods].sort((a,b) => (b.total_sold||0) - (a.total_sold||0));
    const top       = sorted[0];
    const prices    = prods.map(p => p.price||0).filter(v => v > 0).sort((a,b) => a-b);
    const median    = prices.length ? prices[Math.floor(prices.length/2)] : (top.price||0);
    const totalSold = prods.reduce((s,p) => s + (p.total_sold||0), 0);
    const expSold   = sorted.slice(0,3).reduce((s,p) => s + (p.total_sold||0), 0);
    const newSold   = sorted.slice(3).reduce((s,p) => s + (p.total_sold||0), 0);
    const avgRating = prods.reduce((s,p) => s + (p.rating||0), 0) / prods.length;
    const score     = _computeScore(totalSold, avgRating, prods.length, top.reviews||0);
    const cat       = prods.find(p => p.category)?.category || _guessCat(kw);
    return {
      id: ++idx, item_id: top.item_id, shop_id: top.shop_id,
      name: kw, product_name: top.product_name, keyword: kw,
      store_name: top.store_name,
      score, medianPrice: median, price: top.price || median,
      total_sold: totalSold, rating: +avgRating.toFixed(2) || 0,
      reviews: prods.reduce((s,p) => s + (p.reviews||0), 0),
      newUnits: newSold, expUnits: expSold,
      startRevenue: median * newSold * 0.08,
      upToRevenue: median * expSold * 0.2,
      category: cat, image: top.image_url || '', image_url: top.image_url || '',
      sheetUrl: '', avgTrend: null, trending: score >= 65,
    };
  }).filter(p => p.name);

  filtered = [...allProducts];
  console.log('LarisID: catalog built —', allProducts.length, 'keywords');

  const statCount = document.getElementById('stat-count');
  if (statCount) statCount.textContent = allProducts.length + '+';
  renderHomeCats();
  renderHomeGrid();
  renderPills();
  renderDiscGrid();
  populateCategoryFilter();
  populateFinderCats();
  dscInit();
  hbdInit();
  if (typeof nuRefreshView === 'function') nuRefreshView('dashboard');
  if (typeof Chart !== 'undefined') lpRenderPreview(_LP_DEMO);
  setTimeout(startTour, 600);
}

// ════════════════════════════════════════════════════════════
//  BACKGROUND IMAGE FETCHER
//  Loads the first seller image for every product and updates
//  any card that is currently visible in the DOM.
// ════════════════════════════════════════════════════════════
// ── Image cache helpers ──────────────────────────────────────────────────────
const IMG_CACHE_KEY = 'larisid_img_v1';
const IMG_CACHE_TTL = 48 * 60 * 60 * 1000; // 48 hours

function _imgCacheLoad() {
  try {
    const raw = localStorage.getItem(IMG_CACHE_KEY);
    if (!raw) return {};
    const { ts, data } = JSON.parse(raw);
    if (Date.now() - ts > IMG_CACHE_TTL) { localStorage.removeItem(IMG_CACHE_KEY); return {}; }
    return data || {};
  } catch { return {}; }
}
function _imgCacheSave(data) {
  try { localStorage.setItem(IMG_CACHE_KEY, JSON.stringify({ ts: Date.now(), data })); } catch {}
}
function _applyImage(p, url) {
  p.image = url;
  document.querySelectorAll(`.product-card[data-pid="${p.id}"]`).forEach(card => {
    const imgDiv = card.querySelector('.card-img-inner');
    if (!imgDiv) return;
    let img = imgDiv.querySelector('img');
    if (!img) {
      img = document.createElement('img');
      img.alt = p.name;
      img.loading = 'lazy';
      img.decoding = 'async';
      img.referrerPolicy = 'no-referrer';
      img.style.cssText = 'position:absolute;inset:0;width:100%;height:100%;object-fit:cover;';
      img.onerror = function() { this.style.display = 'none'; };
      imgDiv.prepend(img);
    }
    img.src = url;
    img.style.display = '';
    const emoji = imgDiv.querySelector('.card-emoji');
    if (emoji) emoji.style.display = 'none';
  });
}

// ════════════════════════════════════════════════════════════
//  NAVIGATION
// ════════════════════════════════════════════════════════════

// Browser history — keeps Chrome back/forward inside Laris instead of leaving the site.
let _navFromPopstate = false;
let _navSilence = 0;
let _navLastSerialized = '';
let _navLastUrl = '';

function _navStateFromUrl() {
  try {
    const hash = window.location.hash || '';
    const hm = hash.match(/^#\/([a-z0-9-]+)(?:\/(.+))?$/i);
    if (hm) {
      return {
        page: 'profile',
        view: hm[1],
        product: hm[2] ? decodeURIComponent(hm[2]) : null,
      };
    }
    const u = new URLSearchParams(window.location.search || '');
    const view = u.get('view');
    if (view) return { page: 'profile', view, product: u.get('product') || null };
  } catch (_) {}
  return { page: 'landing' };
}

function _navOnProfile() {
  return document.body.classList.contains('in-dashboard')
    || !!document.getElementById('page-profile')?.classList.contains('active');
}

function _navCurrentState() {
  if (_navOnProfile()) {
    const state = { page: 'profile', view: (typeof _dashActiveView !== 'undefined' ? _dashActiveView : null) || 'dashboard' };
    if (state.view === 'deepdive' && typeof _ddCurrentP !== 'undefined' && _ddCurrentP?._listing) {
      const l = _ddCurrentP._listing;
      state.product = `${l.item_id}__${l.shop_id}`;
    }
    return state;
  }
  const active = document.querySelector('.page.active');
  return { page: active ? active.id.replace('page-', '') : 'landing' };
}

function _navBasePath() {
  const u = new URLSearchParams(window.location.search || '');
  u.delete('view');
  u.delete('product');
  const qs = u.toString();
  return window.location.pathname + (qs ? '?' + qs : '');
}

function _navUrlFromState(state) {
  const base = _navBasePath();
  if (state.page === 'profile' && state.view) {
    let hash = '#/' + state.view;
    if (state.product) hash += '/' + encodeURIComponent(state.product);
    return base + hash;
  }
  return base;
}

function _navSerialize(state) { return JSON.stringify(state); }

function _navPush() {
  if (_navFromPopstate || _navSilence > 0) return;
  const state = _navCurrentState();
  const url = _navUrlFromState(state);
  const curUrl = window.location.pathname + window.location.search + window.location.hash;
  if (url === _navLastUrl && url === curUrl) return;
  _navLastUrl = url;
  _navLastSerialized = _navSerialize(state);
  if (url === curUrl) history.replaceState(state, '', url);
  else history.pushState(state, '', url);
}

function _navReplace() {
  if (_navFromPopstate) return;
  const state = _navCurrentState();
  const url = _navUrlFromState(state);
  _navLastUrl = url;
  _navLastSerialized = _navSerialize(state);
  history.replaceState(state, '', url);
}

function _navRestore(state) {
  if (!state || !state.page) state = _navStateFromUrl();
  _navFromPopstate = true;
  _navSilence++;
  try {
    _navLastSerialized = _navSerialize(state);
    _navLastUrl = _navUrlFromState(state);
    if (state.page === 'profile') {
      if (!document.body.classList.contains('in-dashboard')) {
        if (currentUser) {
          document.body.classList.add('in-dashboard');
          document.body.classList.remove('on-landing');
          document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
          document.getElementById('page-profile')?.classList.add('active');
        } else {
          showPage('landing');
          return;
        }
      }
      const targetView = state.view || 'dashboard';
      if (state.view === 'deepdive' && state.product) {
        const curKey = (_ddCurrentP?._listing)
          ? `${_ddCurrentP._listing.item_id}__${_ddCurrentP._listing.shop_id}` : null;
        if (_dashActiveView !== 'deepdive' || curKey !== state.product) {
          dscOpenDeepDive(state.product, true);
          return;
        }
      } else if (targetView !== _dashActiveView) {
        switchDashView(targetView);
      }
    } else {
      document.body.classList.remove('in-dashboard');
      showPage(state.page || 'landing');
    }
  } finally {
    _navSilence--;
    _navFromPopstate = false;
  }
}

window.addEventListener('popstate', (e) => { _navRestore(e.state); });

function _navBack(fallbackView) {
  if (window.history.length > 1) {
    history.back();
    return;
  }
  if (fallbackView) switchDashView(fallbackView);
}

function showPage(name) {
  // Logged-in users go to dashboard instead of home/landing (not when restoring browser history)
  if ((name === 'home' || name === 'landing') && currentUser && !_navFromPopstate) { openProfile(); return; }
  // Logged-out users hitting 'home' go to landing page
  if (name === 'home' && !currentUser) { name = 'landing'; }
  const prev = document.querySelector('.page.active');
  if (prev) prevPage = prev.id.replace('page-', '');
  document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
  const target = document.getElementById('page-' + name);
  if (target) target.classList.add('active');
  window.scrollTo(0, 0);
  document.body.classList.toggle('in-dashboard', name === 'profile');
  document.body.classList.toggle('on-landing',   name === 'landing');

  closeMobileMenu();
  _navPush();
}
function goBack() { showPage(prevPage === 'detail' ? 'discover' : prevPage); }
function toggleMobileMenu() {
  const menu = document.getElementById('mobile-menu');
  const btn  = document.getElementById('nav-hamburger-btn');
  const open = menu.classList.toggle('open');
  btn.classList.toggle('open', open);
}
function closeMobileMenu() {
  document.getElementById('mobile-menu')?.classList.remove('open');
  document.getElementById('nav-hamburger-btn')?.classList.remove('open');
}

