// ── FUZZY SEARCH SUGGESTIONS ────────────────────────────────
let suggActiveIdx = -1;

function bigrams(str) {
  const s = str.toLowerCase().replace(/\s+/g, '');
  const bg = new Set();
  for (let i = 0; i < s.length - 1; i++) bg.add(s.slice(i, i + 2));
  return bg;
}

function bigramSim(a, b) {
  const bgA = bigrams(a), bgB = bigrams(b);
  if (!bgA.size || !bgB.size) return 0;
  let inter = 0;
  for (const bg of bgA) if (bgB.has(bg)) inter++;
  return (2 * inter) / (bgA.size + bgB.size);
}

function scoreProduct(name, q) {
  const n = name.toLowerCase();
  const query = q.toLowerCase().trim();
  if (!query) return 0;
  if (n === query) return 1000;
  if (n.startsWith(query)) return 900;
  if (n.includes(query)) return 800;
  // Word-level: all query words match as prefix of some name word
  const nWords = n.split(/\s+/);
  const qWords = query.split(/\s+/);
  if (qWords.every(qw => nWords.some(nw => nw.startsWith(qw)))) return 700;
  if (qWords.some(qw => nWords.some(nw => nw.startsWith(qw)))) return 600;
  // Bigram similarity for misspellings
  const sim = bigramSim(n, query);
  if (sim > 0.3) return Math.round(sim * 500);
  return 0;
}

function highlightMatch(name, q) {
  const idx = name.toLowerCase().indexOf(q.toLowerCase());
  if (idx >= 0) {
    return name.slice(0, idx) + '<mark>' + name.slice(idx, idx + q.length) + '</mark>' + name.slice(idx + q.length);
  }
  return name;
}

function showSuggestions(q) {
  const box = document.getElementById('search-suggestions');
  suggActiveIdx = -1;
  if (!q || q.trim().length < 1) { box.classList.remove('show'); return; }
  const scored = allProducts
    .map(p => ({ p, score: scoreProduct(p.name, q) }))
    .filter(x => x.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, 8);
  if (!scored.length) { box.classList.remove('show'); return; }
  box.innerHTML = scored.map(({ p }) =>
    `<div class="sugg-item" onmousedown="selectSuggestion('${p.name.replace(/'/g, "\\'")}')">
       ${highlightMatch(p.name, q)}
     </div>`
  ).join('');
  box.classList.add('show');
}

function hideSuggestions() {
  document.getElementById('search-suggestions').classList.remove('show');
  suggActiveIdx = -1;
}

function selectSuggestion(name) {
  const input = document.getElementById('search-input');
  if (input) input.value = name;
  hideSuggestions();
  _searchGoDiscover(name, 'suggestion');
}

function onSearchKey(e) {
  const box = document.getElementById('search-suggestions');
  const items = box.querySelectorAll('.sugg-item');
  if (e.key === 'Enter') {
    e.preventDefault();
    if (suggActiveIdx >= 0 && items[suggActiveIdx]) {
      items[suggActiveIdx].dispatchEvent(new MouseEvent('mousedown'));
      return;
    }
    // No suggestion picked: search the raw query anyway. (Before, Enter with
    // no matching suggestion did NOTHING — the "search is broken" experience.)
    hideSuggestions();
    _searchGoDiscover(e.target?.value, 'enter');
    return;
  }
  if (!items.length) return;
  if (e.key === 'ArrowDown') {
    e.preventDefault();
    suggActiveIdx = Math.min(suggActiveIdx + 1, items.length - 1);
  } else if (e.key === 'ArrowUp') {
    e.preventDefault();
    suggActiveIdx = Math.max(suggActiveIdx - 1, -1);
  } else if (e.key === 'Escape') {
    hideSuggestions(); return;
  } else { return; }
  items.forEach((el, i) => el.classList.toggle('active', i === suggActiveIdx));
}

function applyFilters() {
  const priceMinRaw = document.getElementById('f-price-min')?.value;
  const priceMaxRaw = document.getElementById('f-price-max')?.value;
  const revMinRaw   = document.getElementById('f-rev-min')?.value;
  const revMaxRaw   = document.getElementById('f-rev-max')?.value;
  const scorMinRaw  = document.getElementById('f-score-min')?.value;
  const priceMin = priceMinRaw ? parseFloat(priceMinRaw) : null;
  const priceMax = priceMaxRaw ? parseFloat(priceMaxRaw) : null;
  const revMin   = revMinRaw   ? parseFloat(revMinRaw)   : null;
  const revMax   = revMaxRaw   ? parseFloat(revMaxRaw)   : null;
  const scoreMin = (scorMinRaw && parseFloat(scorMinRaw) > 0) ? parseFloat(scorMinRaw) : null;
  const fCat     = document.getElementById('f-category')?.value || 'all';
  if (fCat !== 'all') activeCat = fCat;
  filtered = allProducts.filter(p => {
    const nameMatch  = !searchQ || p.name.toLowerCase().includes(searchQ);
    const catMatch   = activeCat === 'all' || p.category === activeCat;
    const priceMatch = (priceMin === null || p.medianPrice >= priceMin) && (priceMax === null || p.medianPrice <= priceMax);
    const pRevMed   = (p.startRevenue + p.upToRevenue) / 2;
    const revMatch   = (revMin   === null || pRevMed >= revMin)   && (revMax   === null || pRevMed <= revMax);
    const scoreMatch = (scoreMin === null || p.score >= scoreMin);
    return nameMatch && catMatch && priceMatch && revMatch && scoreMatch;
  });
  updateFilterBadge();
  sortProducts();
}

function sortProducts() {
  const v = document.getElementById('sort-select')?.value || 'score';
  filtered.sort((a, b) => {
    if (v === 'score')        return b.score - a.score;
    if (v === 'revenue_up')   return b.upToRevenue - a.upToRevenue;
    if (v === 'revenue_down') return a.upToRevenue - b.upToRevenue;
    if (v === 'units_down')   return b.expUnits - a.expUnits;
    if (v === 'units_up')     return a.expUnits - b.expUnits;
    if (v === 'trending') {
      // Trending products first (sorted by avgTrend desc), then non-trending by score
      const aT = a.trending ? 1 : 0, bT = b.trending ? 1 : 0;
      if (bT !== aT) return bT - aT;
      return (b.avgTrend||0) - (a.avgTrend||0);
    }
    return 0;
  });
  renderDiscGrid();
}

function renderDiscGrid() {
  const g = document.getElementById('disc-grid'); if (!g) return;
  const pcEl = document.getElementById('product-count'); if (pcEl) pcEl.textContent = filtered.length;
  g.innerHTML = filtered.length
    ? filtered.map((p, i) => cardHTML(p, i)).join('')
    : `<div style="grid-column:1/-1;text-align:center;padding:60px;color:var(--tl)">No products found.</div>`;
  if (filtered.length) decorateDiscoverOdds('#disc-grid');
  ylkInit();
  naikDaunInit();
}

// ════════════════════════════════════════════════════════════
//  PRODUCT CARD
// ════════════════════════════════════════════════════════════

// ════════════════════════════════════════════════════════════
//  COMPARE
// ════════════════════════════════════════════════════════════
function toggleCompare(e, id) {
  e.stopPropagation();
  const idx = compareList.indexOf(id);
  if (idx > -1) {
    compareList.splice(idx, 1);
  } else {
    if (compareList.length >= 3) {
      showCompareToast('Maksimal 3 produk untuk dibandingkan');
      return;
    }
    compareList.push(id);
  }
  refreshCompareBtns();
  renderCompareBar();
}

function refreshCompareBtns() {
  document.querySelectorAll('.cmp-btn').forEach(btn => {
    const pid = parseInt(btn.dataset.pid);
    if (compareList.includes(pid)) {
      btn.classList.add('selected');
      btn.title = 'Hapus dari perbandingan';
    } else {
      btn.classList.remove('selected');
      btn.title = 'Tambah ke perbandingan';
    }
  });
}

function renderCompareBar() {
  const bar = document.getElementById('compare-bar');
  const slots = document.getElementById('cmp-bar-slots');
  const goBtn = document.getElementById('cmp-go-btn');
  if (!bar || !slots) return;

  // Build 3 slots
  let html = '';
  for (let i = 0; i < 3; i++) {
    const pid = compareList[i];
    if (pid) {
      const p = allProducts.find(x => x.id === pid);
      if (p) {
        const imgHTML = p.image
          ? `<img src="${p.image}" alt="">`
          : `<span style="font-size:1.4rem">${''}</span>`;
        html += `<div class="cmp-slot">
          <div class="cmp-slot-inner">${imgHTML}<div class="cmp-slot-name">${p.name}</div></div>
          <button class="cmp-slot-rm" onclick="removeFromCompare(${p.id})" title="Hapus">×</button>
        </div>`;
      }
    } else {
      html += `<div class="cmp-slot"><span class="cmp-slot-empty">+</span></div>`;
    }
  }
  slots.innerHTML = html;

  const hint = document.getElementById('cmp-hint');
  if (hint) {
    if (compareList.length === 0) hint.textContent = 'Pilih hingga 3 produk';
    else if (compareList.length === 1) hint.textContent = '1 dipilih — tambah 1 lagi untuk membandingkan';
    else hint.textContent = compareList.length + ' produk dipilih';
  }
  const fbFloat = document.getElementById('fb-float');
  if (compareList.length > 0) {
    bar.classList.add('visible');
    if (fbFloat) fbFloat.style.bottom = (bar.offsetHeight + 12) + 'px';
  } else {
    bar.classList.remove('visible');
    if (fbFloat) fbFloat.style.bottom = '24px';
  }
  if (goBtn) goBtn.disabled = compareList.length < 2;
}

function removeFromCompare(id) {
  compareList = compareList.filter(x => x !== id);
  refreshCompareBtns();
  renderCompareBar();
}

function clearCompare() {
  compareList = [];
  hideSaveConfirm();
  refreshCompareBtns();
  renderCompareBar();
}

function openComparePage() {
  if (compareList.length < 2) return;
  prevPage = document.querySelector('.page.active')?.id.replace('page-', '') || 'discover';
  renderComparePage();
  document.querySelectorAll('.page').forEach(x => x.classList.remove('active'));
  document.getElementById('page-compare').classList.add('active');
  window.scrollTo(0, 0);
}

function renderComparePage() {
  const products = compareList.map(id => allProducts.find(x => x.id === id)).filter(Boolean);
  const thead = document.getElementById('cmp-thead');
  const tbody = document.getElementById('cmp-tbody');
  if (!thead || !tbody) return;

  // Helper: find best (max) index
  function bestIdx(vals) {
    let best = -Infinity, idx = 0;
    vals.forEach((v, i) => { if (v > best) { best = v; idx = i; } });
    return best > 0 ? idx : -1;
  }

  // Header row
  let headHTML = '<tr><th class="row-label"></th>';
  products.forEach(p => {
    const imgHTML = p.image
      ? `<img src="${p.image}" alt="">`
      : `<span>${''}</span>`;
    headHTML += `<th>
      <div class="cmp-col-head">
        <div class="cmp-col-img">${imgHTML}</div>
        <div class="cmp-col-name">${p.name}</div>
        <button class="cmp-open-btn" onclick="openDetail(${p.id})">Lihat Detail</button>
      </div>
    </th>`;
  });
  headHTML += '</tr>';
  thead.innerHTML = headHTML;

  // Rows
  const rows = [];
  function row(label, cells, isSection) {
    return { label, cells, isSection };
  }

  // ── OVERVIEW ─────────────────────────────────────────────
  rows.push(row('OVERVIEW', [], true));

  // Score
  const scores = products.map(p => p.score);
  const scoreBI = bestIdx(scores);
  rows.push(row('Skor Viabilitas', products.map((p, i) => {
    const clr = scoreColor(p.score);
    const cls = i === scoreBI ? 'cmp-best' : '';
    return `<td class="${cls}"><span class="cmp-score-pill" style="background:${clr}">${fmtScore(p.score)}</span></td>`;
  })));

  // Category
  rows.push(row('Kategori', products.map(p =>
    `<td><span style="font-size:.8rem">${p.category}</span></td>`
  )));

  // ── HARGA ────────────────────────────────────────────────
  rows.push(row('HARGA', [], true));

  // Price range (low / median / high)
  rows.push(row('Harga Terendah', products.map(p =>
    `<td style="font-size:.82rem;color:#555">${fmt(p.medianPrice * 0.75)}</td>`
  )));
  rows.push(row('Harga Median', products.map(p =>
    `<td style="font-weight:700;color:var(--orange)">${fmt(p.medianPrice)}</td>`
  )));
  rows.push(row('Harga Tertinggi', products.map(p =>
    `<td style="font-size:.82rem;color:#555">${fmt(p.medianPrice * 1.3)}</td>`
  )));

  // ── REVENUE ──────────────────────────────────────────────
  rows.push(row('POTENSI REVENUE', [], true));

  const revStart = products.map(p => p.startRevenue);
  const revStartBI = bestIdx(revStart);
  rows.push(row('Revenue Pemula/bln', products.map((p, i) => {
    const cls = i === revStartBI ? 'cmp-best' : '';
    return `<td class="${cls}">${fmtShort(p.startRevenue)}</td>`;
  })));

  const revUp = products.map(p => p.upToRevenue);
  const revUpBI = bestIdx(revUp);
  rows.push(row('Revenue Pro/bln', products.map((p, i) => {
    const cls = i === revUpBI ? 'cmp-best' : '';
    return `<td class="${cls}">${fmtShort(p.upToRevenue)}</td>`;
  })));

  const revMid = products.map(p => (p.startRevenue + p.upToRevenue) / 2);
  const revMidBI = bestIdx(revMid);
  rows.push(row('Revenue Rata-rata/bln', products.map((p, i) => {
    const cls = i === revMidBI ? 'cmp-best' : '';
    return `<td class="${cls}">${fmtShort((p.startRevenue + p.upToRevenue) / 2)}</td>`;
  })));

  // ── VOLUME ───────────────────────────────────────────────
  rows.push(row('VOLUME PENJUALAN', [], true));

  const unitsNew = products.map(p => p.newUnits);
  const unitsNewBI = bestIdx(unitsNew);
  rows.push(row('Units/bln (Pemula)', products.map((p, i) => {
    const cls = i === unitsNewBI ? 'cmp-best' : '';
    return `<td class="${cls}">${Math.round(p.newUnits).toLocaleString('id-ID')}</td>`;
  })));

  const unitsExp = products.map(p => p.expUnits);
  const unitsExpBI = bestIdx(unitsExp);
  rows.push(row('Units/bln (Pro)', products.map((p, i) => {
    const cls = i === unitsExpBI ? 'cmp-best' : '';
    return `<td class="${cls}">${Math.round(p.expUnits).toLocaleString('id-ID')}</td>`;
  })));

  // ── TOKO ─────────────────────────────────────────────────
  rows.push(row('INFO TOKO', [], true));

  // Avg store age — pulled from sellerCache if loaded, else show '—'
  rows.push(row('Rata-rata Usia Toko', products.map(p => {
    const cached = window._sellerCache && window._sellerCache[p.id];
    if (cached && cached.length > 0) {
      const now = new Date();
      const ages = cached.map(s => {
        if (!s.listingDate) return null;
        const d = new Date(s.listingDate);
        if (isNaN(d)) return null;
        return (now - d) / (1000 * 60 * 60 * 24 * 365.25);
      }).filter(a => a !== null && a > 0);
      if (ages.length > 0) {
        const avg = (ages.reduce((a,b) => a+b, 0) / ages.length);
        const display = avg >= 1 ? avg.toFixed(1) + ' thn' : Math.round(avg * 12) + ' bln';
        return `<td style="font-weight:700">${display}</td>`;
      }
    }
    return `<td style="color:#aaa;font-size:.8rem">Buka dulu</td>`;
  })));

  tbody.innerHTML = rows.map(r => {
    if (r.isSection) {
      const colCount = products.length;
      return `<tr><td class="row-label section" colspan="${colCount + 1}">${r.label}</td></tr>`;
    }
    return `<tr><td class="row-label">${r.label}</td>${r.cells.join('')}</tr>`;
  }).join('');
}

function showCompareToast(msg) {
  const toast = document.getElementById('copy-toast');
  if (!toast) return;
  const orig = toast.textContent;
  toast.textContent = msg;
  toast.classList.add('show');
  setTimeout(() => { toast.classList.remove('show'); toast.textContent = orig; }, 2200);
}


function cardHTML(p, idx) {
  const delay = Math.min(idx * 0.04, 0.5);
  return `
  <div class="product-card" onclick="openDetail(${p.id})" data-pid="${p.id}"
       style="animation:fadeUp .35s ease ${delay}s both;">
    <div class="card-img">
      <div class="card-img-inner" style="position:absolute;inset:0;">
        ${p.image ? `<img src="${p.image}" alt="" loading="lazy" decoding="async" referrerpolicy="no-referrer" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;" onerror="this.style.display='none'">` : ''}
        <div class="card-emoji" ${p.image ? 'style="display:none"' : ''}>${''}</div>
      </div>
      <div class="score-pill" style="--score-clr:${scoreColor(p.score)}">${fmtScore(p.score)}</div>
      ${p.trending ? '<div class="trend-badge">Trending</div>' : ''}
      ${savedProducts.has(p.id)
        ? `<button class="save-btn saved" data-pid="${p.id}" onclick="toggleSave(event,${p.id})" title="Hapus dari simpanan"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg></button>`
        : `<button class="save-btn" data-pid="${p.id}" onclick="toggleSave(event,${p.id})" title="Simpan produk"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#B5202A" stroke-width="2.5"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/></svg></button>`
      }
    </div>
    <button class="cmp-btn ${compareList.includes(p.id)?'selected':''}" data-pid="${p.id}" onclick="toggleCompare(event,${p.id})" title="Bandingkan">
      <svg viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="3"><polyline points="20 6 9 17 4 12"/></svg>
    </button>
    <div class="card-body">
      <div class="card-name">${p.name}</div>
      <div style="display:flex;align-items:center;gap:5px;"><div class="card-cat">${p.category}</div><img src="images/shopee-logo.png" alt="Shopee" style="width:14px;height:14px;flex-shrink:0;"></div>
      <div class="card-odds" data-kw="${(p.keyword||'').replace(/"/g,'&quot;')}" data-price="${p.medianPrice||p.price||0}"></div>
    </div>
  </div>`;
}

// Reality-check chip on Discover cards: "Pemula: 1 dari N tembus" — the honest
// base rate of NEW products reaching 100+ sold in that niche (mv_niche_breakout).
// Batched per render; best-effort enrichment (cards work fine without it).
async function decorateDiscoverOdds(sel) {
  try {
    const cont = document.querySelector(sel);
    if (!cont || !_supabase) return;
    const chips = Array.from(cont.querySelectorAll('.card-odds'));
    if (!chips.length) return;
    const kws = [...new Set(chips.map(c => c.dataset.kw).filter(Boolean))];
    const need = kws.filter(k => _nicheStatsCache[k] === undefined);
    if (need.length) {
      need.forEach(k => { _nicheStatsCache[k] = null; });
      for (let i = 0; i < need.length; i += 200) {
        const chunk = need.slice(i, i + 200);
        const { data } = await _supabase
          .from('mv_niche_breakout')
          .select('keyword,new_items,breakouts,breakout_rate,median_new_sold,median_winner_price,median_winner_reviews')
          .in('keyword', chunk);
        (data || []).forEach(row => { _nicheStatsCache[row.keyword] = row; });
      }
    }
    chips.forEach(chip => {
      const kw = chip.dataset.kw;
      const niche = kw ? _nicheStatsCache[kw] : null;
      if (!niche || (niche.new_items || 0) < 15 || niche.breakout_rate == null) {
        chip.className = 'card-odds'; chip.innerHTML = ''; return;
      }
      const rate = Number(niche.breakout_rate);
      const n = Math.max(2, Math.round(100 / Math.max(rate, 1)));
      const o = calcBreakoutOdds(Number(chip.dataset.price) || 0, niche);
      chip.className = 'card-odds on ' + o.cls;
      chip.title = `~${o.pct}% produk baru di niche ini tembus 100+ terjual · median produk baru: ${niche.median_new_sold} terjual`;
      chip.innerHTML = `<span class="od-dot"></span>Pemula: 1 dari ${n} tembus`;
    });
  } catch (e) { /* enrichment is best-effort */ }
}

// ── Yang Laku dari Kotamu ─────────────────────────────────────────────────────
// Regions specialize: Surabaya/Sidoarjo win cheap kitchenware, Bandung/Jkt-Utara
// fashion, Jkt-Pusat electronics, Tangerang home goods. Steer sellers to the
// category their city actually wins, from mv_region_category. Free for everyone.
const YLK_LS_KEY = 'larisid_region_v1';
let _ylkInited = false;
let _ylkRegions = null;

async function ylkInit() {
  if (_ylkInited) return;
  const card = document.getElementById('ylk-card');
  const sel = document.getElementById('ylk-region');
  if (!card || !sel || !_supabase) return; // not ready — allow a later retry
  _ylkInited = true;
  try {
    const { data } = await _supabase
      .from('mv_region_category')
      .select('location,breakouts')
      .order('breakouts', { ascending: false })
      .limit(1000);
    const totals = {};
    (data || []).forEach(r => { totals[r.location] = (totals[r.location] || 0) + (r.breakouts || 0); });
    _ylkRegions = Object.entries(totals)
      .filter(([, n]) => n >= 30)
      .sort((a, b) => b[1] - a[1])
      .map(([loc]) => loc);
    if (!_ylkRegions.length) { _ylkInited = false; return; }
    let saved = localStorage.getItem(YLK_LS_KEY) || '';
    if (!saved && currentUser) {
      try {
        const { data: prefs } = await _supabase.from('user_onboarding_prefs')
          .select('region').eq('user_id', currentUser.id).maybeSingle();
        if (prefs?.region) {
          saved = prefs.region;
          try { localStorage.setItem(YLK_LS_KEY, saved); } catch (_) {}
        }
      } catch (_) {}
    }
    sel.innerHTML = '<option value="">Pilih kotamu…</option>' +
      _ylkRegions.map(loc => `<option value="${loc.replace(/"/g, '&quot;')}"${loc === saved ? ' selected' : ''}>${loc}</option>`).join('');
    card.style.display = '';
    // Render even if `saved` isn't in the gated dropdown list — an obscure city
    // (below the >=30 aggregated-breakouts threshold) should still get an
    // explicit "no data yet" message from ylkRender, not silence.
    if (saved) ylkRender(saved);
    else {
      const hl = document.getElementById('ylk-highlights');
      if (hl) hl.innerHTML = `<div class="ylk-pick">
        <div class="ylk-pick-icon"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#B5202A" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 22s-8-4.5-8-11.8A8 8 0 0 1 12 2a8 8 0 0 1 8 8.2c0 7.3-8 11.8-8 11.8z"/><circle cx="12" cy="10" r="3"/></svg></div>
        <div>
          <div class="ylk-pick-title">Pilih kotamu dulu</div>
          <div class="ylk-pick-sub">Kami tunjukkan produk terlaris dari kotamu & sekitarnya, sesuai minat & pencarianmu.</div>
        </div>
      </div>`;
    }
  } catch (e) { _ylkInited = false; }
}

// B5: make sure YLK shows products WITHOUT a manual pick. ylkInit often runs
// at boot before the auth session resolves (currentUser null), renders the
// "Pilih kotamu dulu" prompt and never retries — this resolves the region
// after login (localStorage → onboarding location → IP), syncs the dropdown,
// and renders.
async function ylkEnsureRegion() {
  try {
    if (!_ylkInited) await ylkInit();
    const sel = document.getElementById('ylk-region');
    if (!sel || sel.value || !sel.options.length) return;
    let region = '';
    try { region = (localStorage.getItem(YLK_LS_KEY) || '').trim(); } catch (_) {}
    if (!region && currentUser && _supabase) {
      try {
        const { data: prefs } = await _supabase.from('user_onboarding_prefs')
          .select('region').eq('user_id', currentUser.id).maybeSingle();
        region = (prefs?.region || '').trim();
      } catch (_) {}
    }
    if (!region && typeof _nuOnb !== 'undefined' && _nuOnb.location && _nuOnb.location !== '__other__') region = _nuOnb.location;
    if (!region) { const r = await fetchRegionFromIp(); region = (r?.region || '').trim(); }
    if (!region) return;
    // The dropdown holds listing-location names (e.g. "Kota Bekasi") — match
    // the city loosely against them.
    const opts = Array.from(sel.options).map(o => o.value).filter(Boolean);
    const rl = region.toLowerCase();
    const match = opts.find(o => o === region)
      || opts.find(o => o.toLowerCase() === rl)
      || opts.find(o => o.toLowerCase().includes(rl) || rl.includes(o.toLowerCase()));
    if (!match) return;
    sel.value = match;
    try { localStorage.setItem(YLK_LS_KEY, match); } catch (_) {}
    ylkRender(match);
  } catch (_) {}
}

async function ylkOnRegionChange() {
  const sel = document.getElementById('ylk-region');
  const region = sel ? sel.value : '';
  try { region ? localStorage.setItem(YLK_LS_KEY, region) : localStorage.removeItem(YLK_LS_KEY); } catch (_) {}
  ylkPersistRegion(region);
  if (region) ylkRender(region);
  else {
    const hl = document.getElementById('ylk-highlights'); if (hl) hl.innerHTML = '';
    const allcats = document.getElementById('ylk-allcats'); if (allcats) allcats.style.display = 'none';
    const emptyEl = document.getElementById('ylk-empty'); if (emptyEl) emptyEl.style.display = 'none';
  }
}

async function ylkPersistRegion(region) {
  if (!_supabase || !currentUser || !region) return;
  try { await _supabase.from('user_onboarding_prefs').update({ region }).eq('user_id', currentUser.id); } catch (_) {}
}

async function ylkRender(region) {
  const hl = document.getElementById('ylk-highlights');
  const allcats = document.getElementById('ylk-allcats');
  const emptyEl = document.getElementById('ylk-empty');
  const subEl = document.getElementById('ylk-sub');
  if (!hl || !_supabase) return;
  hl.innerHTML = '<div class="ylk-empty">Memuat…</div>';
  if (allcats) allcats.style.display = 'none';
  if (emptyEl) emptyEl.style.display = 'none';
  try {
    // What to match against: onboarding interest categories + recently searched keywords.
    const prefCats = (typeof _nuOnb !== 'undefined' && _nuOnb && Array.isArray(_nuOnb.cats)) ? _nuOnb.cats.filter(Boolean) : [];
    let recentKw = [];
    try { recentKw = await searchHistoryRecentKeywordsRemote(12); } catch (_) { recentKw = searchHistoryRecentKeywords(12); }
    const kwSet  = new Set(recentKw.map(k => String(k).toLowerCase()).filter(Boolean));
    const catSet = new Set(prefCats);

    // Rekomendasi Steven: the same weekly, shared-per-city list for everyone in
    // this city, sourced from mv_city_weekly_recs (young listings already past
    // 100 sales, ranked by sales-per-day). Preferred over the raw
    // `order by total_sold desc` fallback below, which surfaces old mega-sellers
    // no new seller can realistically enter against.
    const steven = await _ylkFetchStevenPicks(region);
    if (steven.length) {
      _ylkRenderSteven(region, steven, subEl, hl, emptyEl);
      return;
    }

    // "From their region or near their region": pull the metro cluster, fall back to region-only.
    const regions = _ylkNearbyRegions(region);
    let cands = await _ylkFetchRegionProducts(regions);
    if (!cands.length && regions.length > 1) cands = await _ylkFetchRegionProducts([region]);

    if (!cands.length) {
      hl.innerHTML = '';
      if (emptyEl) { emptyEl.textContent = `Belum ada data produk untuk ${region}. Kami terus menambah kota — coba lagi nanti, atau pilih kota lain.`; emptyEl.style.display = ''; }
      return;
    }

    // Score by interest/search match: +2 for a chosen category, +1 for a recent-search hit.
    const scored = cands.map(r => {
      let s = 0;
      if (catSet.size && catSet.has(r.category)) s += 2;
      if (kwSet.size) {
        const hay = ((r.product_name || '') + ' ' + (r.keyword || '')).toLowerCase();
        for (const kw of kwSet) { if (kw && hay.includes(kw)) { s += 1; break; } }
      }
      return { r, s };
    });
    const matched = scored.filter(x => x.s > 0);
    let picks, personalized;
    if (matched.length) {
      picks = matched.sort((a, b) => b.s - a.s || (b.r.total_sold || 0) - (a.r.total_sold || 0)).slice(0, 5).map(x => x.r);
      if (picks.length < 5) { // top up with the region's best sellers so the row stays full
        const have = new Set(picks.map(r => r.item_id));
        for (const c of cands) { if (picks.length >= 5) break; if (!have.has(c.item_id)) { picks.push(c); have.add(c.item_id); } }
      }
      personalized = true;
    } else {
      // No interest/search signal yet → random products from their region.
      picks = _ylkSample(cands, 5);
      personalized = false;
    }

    if (subEl) subEl.textContent = personalized
      ? `Produk terlaris dari ${region} & sekitarnya, dipilih dari kategori & pencarianmu.`
      : `Produk populer dari ${region} & sekitarnya. Pilih kategori minatmu di Discover biar makin pas.`;
    hl.innerHTML = picks.map(_ylkProductCard).join('');
  } catch (e) { hl.innerHTML = '<div class="ylk-empty">Gagal memuat data.</div>'; }
}

// Metro clusters so "near your region" also pulls neighbouring kota/kabupaten.
const YLK_CLUSTERS = [
  ['Jakarta Barat', 'Jakarta Timur', 'Jakarta Selatan', 'Jakarta Utara', 'Jakarta Pusat', 'Kota Tangerang', 'Tangerang Selatan', 'Kab. Tangerang', 'Kota Bekasi', 'Kab. Bekasi', 'Kota Depok', 'Depok', 'Kota Bogor', 'Kab. Bogor'],
  ['Bandung', 'Kota Bandung', 'Kab. Bandung', 'Kab. Bandung Barat', 'Cimahi', 'Kota Cimahi'],
  ['Surabaya', 'Sidoarjo', 'Kab. Sidoarjo', 'Gresik', 'Kab. Gresik'],
  ['Semarang', 'Kota Semarang', 'Kab. Semarang'],
  ['Yogyakarta', 'Kota Yogyakarta', 'Sleman', 'Kab. Sleman', 'Bantul', 'Kab. Bantul'],
  ['Medan', 'Kota Medan', 'Kab. Deli Serdang'],
  ['Makassar', 'Kota Makassar'],
];
function _ylkNearbyRegions(region) {
  const cluster = YLK_CLUSTERS.find(c => c.includes(region));
  return cluster ? cluster.slice() : [region];
}

// Top-selling products for the given region(s), deduped by item, real sellers only.
async function _ylkFetchRegionProducts(regions) {
  if (!regions || !regions.length || !_supabase) return [];
  try {
    let q = _supabase.from('listings_deduped')
      .select('item_id,shop_id,product_name,store_name,price,total_sold,category,image_url,url,keyword,location,rating,reviews')
      .order('total_sold', { ascending: false })
      .limit(200);
    q = regions.length === 1 ? q.eq('location', regions[0]) : q.in('location', regions);
    const { data } = await q;
    const seen = new Set();
    const out = [];
    for (const r of (data || [])) {
      if (r.item_id == null || seen.has(r.item_id)) continue;
      seen.add(r.item_id);
      if ((r.total_sold || 0) > 0) out.push(r);
    }
    return out;
  } catch (_) { return []; }
}

// Map the user's free-text region onto a canonical city bucket. region is
// genuinely unconstrained — five writers produce "Jakarta", "Jakarta Pusat" and
// lowercase "kediri" — so reuse the normaliser that already handles the
// Kota/Kab. prefixes and aliases rather than string-matching here.
function _ylkCanonicalCity(region) {
  try {
    if (typeof _admMapCanonical === 'function') {
      const c = _admMapCanonical(region);
      if (c) return c;
    }
  } catch (_) {}
  return region;
}

async function _ylkFetchStevenPicks(region) {
  if (!_supabase) return [];
  try {
    const city = _ylkCanonicalCity(region);
    const { data } = await _supabase.from('mv_city_weekly_recs')
      .select('item_id,shop_id,store_name,product_name,category,keyword,price,total_sold,reviews,rating,location,image_url,url,age_days,sold_per_day,rn,week_start')
      .eq('city', city)
      .order('rn', { ascending: true })
      .limit(20);
    return data || [];
  } catch (_) { return []; }
}

function _ylkRenderSteven(region, rows, subEl, hl, emptyEl) {
  const city = _ylkCanonicalCity(region);
  if (emptyEl) emptyEl.style.display = 'none';
  const titleEl = document.querySelector('#ylk-card .ylk-title');
  if (titleEl) {
    titleEl.innerHTML = `<img src="/images/steven-avatar.webp" alt="" width="24" height="24" loading="lazy"
        style="width:24px;height:24px;border-radius:50%;object-fit:cover;object-position:center top;vertical-align:-6px;margin-right:8px;"
        onerror="this.style.display='none'">Rekomendasi Steven &middot; ${city}`;
  }
  if (subEl) {
    subEl.textContent = `${rows.length} produk yang lagi jalan buat penjual baru di ${city} — listing baru (di bawah 4 bulan) yang sudah tembus 100+ terjual. Daftar ini ganti tiap minggu.`;
  }
  hl.innerHTML = rows.map(_ylkProductCard).join('');
  try { logUserEvent('steven_recs_view', { city, count: rows.length, week_start: rows[0]?.week_start || null }); } catch (_) {}
}

function _ylkSample(arr, n) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
  return a.slice(0, n);
}

function _ylkProductCard(r) {
  const img = r.image_url
    ? `<img src="${r.image_url}" alt="" loading="lazy" referrerpolicy="no-referrer" style="width:100%;height:120px;object-fit:cover;display:block;" onerror="this.style.display='none'">`
    : '';
  const sold = (typeof _supFmtSold === 'function') ? _supFmtSold(r.total_sold) : (r.total_sold || 0);
  const loc  = r.location || '';
  const cat  = r.category || '';
  const sid  = r.shop_id == null ? '' : r.shop_id;
  return `<div class="ylk-hl-card" style="padding:0;overflow:hidden;" role="button" tabindex="0"
      onclick="ylkOpenProduct('${r.item_id}','${sid}')"
      onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();ylkOpenProduct('${r.item_id}','${sid}');}">
    <div style="position:relative;background:#F3ECE6;min-height:120px;">${img}${cat ? `<span style="position:absolute;top:8px;left:8px;background:rgba(255,255,255,.92);color:#B5202A;font-size:.6rem;font-weight:800;padding:3px 8px;border-radius:999px;">${cat}</span>` : ''}</div>
    <div style="padding:12px 13px 14px;">
      <div style="font-size:.8rem;font-weight:700;color:#1A1A1A;line-height:1.3;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;min-height:2.1em;">${(r.product_name || '—').slice(0, 70)}</div>
      <div style="font-size:.92rem;font-weight:800;color:#B5202A;margin-top:6px;">Rp ${Number(r.price || 0).toLocaleString('id-ID')}</div>
      <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:6px;font-size:.66rem;color:#6B7280;font-weight:600;">
        <span style="display:inline-flex;align-items:center;gap:3px;min-width:0;overflow:hidden;">${loc ? wIcon('map-pin', 10) : ''}<span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${loc}</span></span>
        <span style="white-space:nowrap;flex-shrink:0;">${sold} terjual</span>
      </div>
    </div>
  </div>`;
}

function ylkOpenProduct(itemId, shopId) {
  try { logUserEvent('ylk_open_product', { item_id: itemId, region: document.getElementById('ylk-region')?.value }); } catch (_) {}
  if (typeof dscOpenDeepDive === 'function' && shopId && shopId !== 'null') {
    void dscOpenDeepDive(`${itemId}__${shopId}`);
  }
}

// ── Naik Daun ─────────────────────────────────────────────────────────────────
// Young products (listed <120d) already selling fast — be a fast second. Velocity
// is sales-since-listing (true weekly momentum needs the listing_deltas pipeline
// revived). Lightly personalised by onboarding category.
const _naikDaun = { rows: null, inited: false };
async function naikDaunInit() {
  if (_naikDaun.inited) return;
  const card = document.getElementById('nd-card');
  const strip = document.getElementById('nd-strip');
  if (!card || !strip || !_supabase) return;
  try {
    if (journeyLoad().naikDaunDismissed) { card.style.display = 'none'; return; }
  } catch (_) {}
  _naikDaun.inited = true;
  try {
    const { data } = await _supabase.from('mv_naik_daun')
      .select('item_id,shop_id,store_name,product_name,category,keyword,price,total_sold,reviews,rating,location,image_url,url,age_days,sold_per_day')
      .order('sold_per_day', { ascending: false }).limit(200);
    _naikDaun.rows = data || [];
    if (!_naikDaun.rows.length) { _naikDaun.inited = false; return; }
    naikDaunRender();
    card.style.display = '';
  } catch (e) { _naikDaun.inited = false; }
}
function naikDaunDismissAfterSearch() {
  try {
    journeySave({ naikDaunDismissed: true });
  } catch (_) {}
  const card = document.getElementById('nd-card');
  if (card) card.style.display = 'none';
}
function naikDaunRender() {
  const strip = document.getElementById('nd-strip');
  if (!strip) return;
  let rows = _naikDaun.rows || [];
  try {
    // B6: prefer-then-fill — products in the user's onboarding categories come
    // first (any number of picks), global movers keep the strip full. The old
    // rule (>=3 cats AND >=6 matches, else silently global) meant a Dapur
    // picker still saw mobil items up top.
    const cats = (typeof _nuOnb !== 'undefined' && _nuOnb && Array.isArray(_nuOnb.cats)) ? _nuOnb.cats.filter(Boolean) : [];
    if (cats.length) {
      const matched = rows.filter(r => cats.includes(r.category));
      if (matched.length) rows = matched.concat(rows.filter(r => !cats.includes(r.category)));
    }
  } catch (_) {}
  rows = rows.slice(0, 12);
  strip.innerHTML = rows.map(r => {
    const img = r.image_url ? `<img src="${r.image_url}" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.style.display='none'">` : '';
    const vel = r.sold_per_day >= 1 ? `≈${_supFmtSold(r.sold_per_day)}/hari` : '';
    return `<div class="nd-item" onclick="naikDaunOpen('${r.item_id}')">
      <div class="nd-item-img">${img}<span class="nd-vel">${vel}</span></div>
      <div class="nd-item-body">
        <div class="nd-item-name">${r.product_name || '—'}</div>
        <div class="nd-item-meta"><span class="nd-item-price">Rp ${Number(r.price || 0).toLocaleString('id-ID')}</span><span class="nd-item-age">${r.age_days}h · ${_supFmtSold(r.total_sold)} terjual</span></div>
      </div>
    </div>`;
  }).join('');
}
function naikDaunOpen(itemId) {
  const r = (_naikDaun.rows || []).find(x => String(x.item_id) === String(itemId));
  if (!r) return;
  // The strip lives inside the dashboard Discover view — open the Deep Dive.
  // (openDetail() is the legacy public detail page and dead-ends from here;
  // dscOpenDeepDive resolves the freshest listing itself, incl. a DB fetch.)
  if (typeof dscOpenDeepDive === 'function' && r.shop_id != null) {
    void dscOpenDeepDive(`${r.item_id}__${r.shop_id}`);
    return;
  }
  // Legacy fallback (public detail page) if the deep-dive flow is unavailable.
  const p = {
    id: r.item_id, name: r.product_name || '—', category: r.category || 'Umum',
    image: r.image_url || null, keyword: r.keyword || null, medianPrice: r.price || 0,
    price: r.price || 0, score: 65, total_sold: r.total_sold || 0, reviews: r.reviews || 0,
    item_id: r.item_id, shop_id: r.shop_id, _listing: r,
  };
  try { if (typeof allProducts !== 'undefined' && !allProducts.find(x => x.id === p.id)) allProducts.push(p); } catch (_) {}
  if (typeof openDetail === 'function') openDetail(p.id);
}

// ════════════════════════════════════════════════════════════
//  DETAIL PAGE
// ════════════════════════════════════════════════════════════
async function openDetail(id) {
  const p = allProducts.find(x => x.id === id);
  if (!p) return;
  trackView(p.category); // personalized discover
  logSearchHistory(p.keyword || p.name, p.item_id != null ? p.item_id : null, 'product_open');
  currentProduct = p;
  prevPage = document.querySelector('.page.active')?.id.replace('page-', '') || 'discover';
  renderDetail(p);
  document.querySelectorAll('.page').forEach(x => x.classList.remove('active'));
  document.getElementById('page-detail').classList.add('active');
  window.scrollTo(0, 0);
  // Reset sourcing analyze button
  const analyzeBtn  = document.getElementById('sourcing-analyze-btn');
  const analyzeWrap = document.getElementById('sourcing-analyze-wrap');
  const sourResult  = document.getElementById('sourcing-result');
  if (analyzeBtn)  { analyzeBtn.disabled = false; analyzeBtn.classList.remove('done'); }
  if (analyzeWrap) analyzeWrap.style.display = '';
  if (sourResult)  sourResult.innerHTML = '';
  // Load plan if logged in
  if (currentUser) {
    await loadPlanForProduct(p.id);
    showPlanPanel();
  }
  loadSellerData(p);           // fetch seller sheet in background
  loadVotes(p.id);             // load vote state for this product
  loadKeywordRankings(p.name); // load keyword ad recommendations
}

