const _AUTH_SK = 'laris_auth_v1';

function _authSave(session) {
  try { localStorage.setItem(_AUTH_SK, JSON.stringify({ access_token: session.access_token, refresh_token: session.refresh_token, expires_at: Date.now() + (session.expires_in || 3600) * 1000, user: session.user })); } catch(_) {}
}
function _authClear() { try { localStorage.removeItem(_AUTH_SK); } catch(_) {} }
function _authLoad() { try { return JSON.parse(localStorage.getItem(_AUTH_SK) || 'null'); } catch(_) { return null; } }

async function _authRefresh(refreshToken) {
  try {
    const r = await fetch(`${SUPA_URL}/auth/v1/token?grant_type=refresh_token`, { method:'POST', headers:{ apikey:SUPA_KEY, 'Content-Type':'application/json' }, body:JSON.stringify({ refresh_token:refreshToken }) });
    if (!r.ok) return null;
    const d = await r.json();
    if (d.access_token) return d;
  } catch(_) {}
  return null;
}

const PENDING_INVITE_KEY = 'larisid_pending_invite';
const ADMIN_PREVIEW_COHORT_KEY = 'larisid_admin_preview_cohort_id';

/** Which cohort the platform admin is previewing as leader (sessionStorage UUID). */
function cohortPickAdminPreviewCohort(led) {
  const list = led || [];
  if (!list.length) return null;
  let saved = '';
  try { saved = (sessionStorage.getItem(ADMIN_PREVIEW_COHORT_KEY) || '').trim(); } catch (_) {}
  if (saved) {
    const m = list.find(c => c.id === saved);
    if (m) return m;
  }
  const ob = list.find(c => String(c.slug || '').toLowerCase() === 'ocean-blue');
  if (ob) return ob;
  return list[0];
}

function cohortAdminSetPreviewCohort(cohortId) {
  const id = String(cohortId || '').trim();
  if (!id) return;
  try { sessionStorage.setItem(ADMIN_PREVIEW_COHORT_KEY, id); } catch (_) {}
  cohortInit().catch(() => {});
}

function cohortPopulateAdminCohortPicker(led) {
  const sel = document.getElementById('cohort-admin-cohort-picker');
  if (!sel) return;
  if (!isPlatformAdmin() || !led || !led.length) {
    sel.style.display = 'none';
    sel.innerHTML = '';
    return;
  }
  sel.style.display = '';
  sel.innerHTML = (led || []).map(c => {
    const label = _cohortEsc((c.name || c.slug || c.id || '').toString());
    return `<option value="${c.id}">${label}</option>`;
  }).join('');
  const cur = (_cohortState.primaryMentorCohort && _cohortState.primaryMentorCohort.id) || '';
  if (cur) sel.value = cur;
}

function captureInviteFromUrl() {
  try {
    const u = new URLSearchParams(window.location.search || '');
    let code = (u.get('invite') || u.get('cohort') || '').trim();
    if (!code) return;
    if (code.length > 64) code = code.slice(0, 64);
    sessionStorage.setItem(PENDING_INVITE_KEY, code);
    u.delete('invite');
    u.delete('cohort');
    const qs = u.toString();
    const path = window.location.pathname + (qs ? '?' + qs : '') + (window.location.hash || '');
    history.replaceState(null, '', path);
  } catch (_) {}
}

function getPendingInvite() {
  try { return (sessionStorage.getItem(PENDING_INVITE_KEY) || '').trim(); } catch (_) { return ''; }
}

function setPendingInvite(code) {
  try {
    const c = (code || '').trim().slice(0, 64);
    if (c) sessionStorage.setItem(PENDING_INVITE_KEY, c);
    else sessionStorage.removeItem(PENDING_INVITE_KEY);
  } catch (_) {}
}

function clearPendingInvite() {
  try { sessionStorage.removeItem(PENDING_INVITE_KEY); } catch (_) {}
}

async function pendingCohortJoinIfAny() {
  const code = getPendingInvite();
  if (!code || !_supabase || !currentUser) return;
  const { error } = await _supabase.rpc('join_cohort', { p_invite: code });
  if (!error) {
    clearPendingInvite();
    const inp = document.getElementById('cohort-invite-input');
    if (inp) inp.value = '';
    const authInv = document.getElementById('auth-invite-code');
    if (authInv) authInv.value = '';
    if (typeof cohortInit === 'function' && document.body.classList.contains('in-dashboard')) {
      switchDashView('cohort');
      await cohortInit();
    }
  } else {
    console.warn('join_cohort:', error.message);
    clearPendingInvite();
    try {
      const ov = document.getElementById('auth-overlay');
      const er = document.getElementById('auth-error');
      if (er && ov && ov.style.display === 'flex') {
        er.style.display = '';
        er.style.color = '#e74c3c';
        er.textContent = 'Kode kohort tidak valid atau kedaluwarsa.';
      }
    } catch (_) {}
  }
}

async function _authOnSignIn(session) {
  currentUser = session.user || _decodeJwtUser(session.access_token);
  if (!currentUser) { _clearSessionRestoring(); return; }
  if (!session.user) {
    session.user = currentUser;
    _authSave(session);
  }
  // Clarity: tie session replays to this user_id (enables per-signup replay/funnels), and count
  // new signups from ANY auth path incl. Google OAuth (email/pass path also fires at submit time;
  // the sessionStorage flag dedupes so a single signup is never counted twice).
  // _clarity() queues through the stub, so this works even before the deferred tag loads.
  let isNewSignup = false;
  try {
    _clarity('identify', currentUser.id, undefined, undefined, currentUser.email || undefined);
    isNewSignup = _lidIsNewSignup(currentUser) && !_lidSignupAlreadyRecorded(currentUser.id);
    if (isNewSignup) {
      _lidMarkSignupRecorded(currentUser.id);
      _lidFireSignupSuccess();
      // True acquisition source captured pre-OAuth (see _lidCaptureAttribution).
      // Logged to activity_events too, so source attribution no longer depends
      // on Clarity at all.
      let attr = null;
      try { attr = JSON.parse(localStorage.getItem('_lid_attr_v1') || 'null'); } catch (_) {}
      if (!attr) attr = {};
      try {
        const ab = JSON.parse(localStorage.getItem('_lid_ab_v1') || 'null');
        if (ab && (ab.v === 'A' || ab.v === 'B' || ab.v === 'X')) {
          attr.ab_variant = ab.v;
          if (ab.via) attr.ab_via = ab.via;
        } else if (!attr.ab_variant) {
          attr.ab_variant = 'X';
        }
      } catch (_) {
        if (!attr.ab_variant) attr.ab_variant = 'X';
      }
      try { localStorage.setItem('_lid_attr_v1', JSON.stringify(attr)); } catch (_) {}
      const src = attr.utm_source || (attr.ref_code && 'referral') || attr.referrer || '(direct)';
      _clarity('set', 'signup_source', String(src).slice(0, 120));
      _clarity('set', 'ab_variant_at_signup', String(attr.ab_variant || 'X'));
      if (attr.ab_via) _clarity('set', 'ab_via', String(attr.ab_via));
      // Deferred: the Supabase client only gets this session via setSession()
      // a few lines below, and an unauthed insert would fail RLS.
      setTimeout(() => { void logUserEvent('signup_attribution', attr); }, 2500);
    }
  } catch (_) {}
  // Route away from marketing/landing immediately on refresh — never wait on network calls first.
  if (!document.body.classList.contains('in-dashboard')) void openProfile();
  try {
    larisBootDashboardData();
    // Inject access token into Supabase JS client so database queries are authenticated
    if (_supabase) {
      try {
        await _supabase.auth.setSession({ access_token: session.access_token, refresh_token: session.refresh_token });
      } catch (_) {}
    }
    // Track signup vs return visit for analytics
    if (_supabase && currentUser) {
      const isNewUser = isNewSignup || _lidIsNewSignup(currentUser);
      _supabase.from('user_sessions').insert({ user_id: currentUser.id, is_new_user: isNewUser }).then(() => {});
    }
    // Best-effort IP region backfill for users without a saved location (onboarding
    // skip, legacy accounts, or users who never finished step 1).
    setTimeout(() => { void backfillUserRegionIfMissing(); }, 1200);
    funnelNoteActiveDay();
    // If they answered the landing finder before signing up, run it now.
    setTimeout(() => { try { lfdReplayPending(); } catch (_) {} }, 700);
    // Same for an in-progress tracker wizard interrupted by this login.
    setTimeout(() => { try { ltkReplayPending(); } catch (_) {} }, 700);
    await loadCurrentAccess().catch(() => {});
    void _winbackMaybeClaim();
    void journeyHydrateFromRemote();
    updateAuthUI();
    loadSavedProducts();
    checkMentorApplication();
    renderHomeGrid();
    if (currentProduct) renderDetail(currentProduct);
    setTimeout(() => { pendingCohortJoinIfAny().catch(() => {}); }, 400);
    setTimeout(() => { cohortLoadLightForTheme().catch(() => {}); }, 600);
    if (document.body.classList.contains('in-dashboard') && typeof _dashActiveView !== 'undefined' && _dashActiveView === 'cohort') {
      queueMicrotask(() => { cohortInit().catch(() => {}); });
    }
    if (document.body.classList.contains('in-dashboard') && typeof _dashActiveView !== 'undefined' && _dashActiveView === 'discover') {
      void dscLoadScrapeRequests();
    }
  } finally {
    _clearSessionRestoring();
  }
}

/** Close fixed overlays so logout is visible immediately (mobile "Lainnya" sheet uses a delayed hide that browsers throttle in background tabs). */
function dismissLogoutChrome() {
  try { document.getElementById('dash-topbar-menu')?.classList.remove('open'); } catch (_) {}
  try { closeSidebar(); } catch (_) {}
  try {
    const ov = document.getElementById('mbn-sheet-overlay');
    const s = document.getElementById('mbn-more-sheet');
    if (ov) ov.style.display = 'none';
    if (s) {
      s.style.display = 'none';
      s.style.transform = 'translateY(100%)';
    }
  } catch (_) {}
  try {
    const em = document.getElementById('dash-email-modal');
    if (em) em.style.display = 'none';
    const xm = document.getElementById('ext-link-modal');
    if (xm) xm.style.display = 'none';
    const cg = document.getElementById('cg-overlay');
    if (cg) cg.style.display = 'none';
    const lo = document.getElementById('loading-overlay');
    if (lo) lo.style.display = 'none';
  } catch (_) {}
  try { closeAuthModal(); } catch (_) {}
  try { endTour(); } catch (_) {}
}

function _authOnSignOut() {
  currentUser = null;
  _accessState = { loaded: false, role: 'independent', isAdmin: false, isLeader: false };
  _authClear();
  _clearSessionRestoring();
  updateAuthUI();
  savedProducts.clear();
  try { renderProfileSaved(); } catch (_) {}
  cohortClearDashboardTheme();
  _navLastUrl = '';
  _navLastSerialized = '';
  _navSilence++;
  showPage('landing');
  _navReplace();
  _navSilence--;
  renderHomeGrid();
  dismissLogoutChrome();
}

function initSupabase() {
  // Clear any stale Supabase JS-client sessions that trigger spurious INITIAL_SESSION redirects
  try {
    Object.keys(localStorage).filter(k => k.startsWith('sb-') && k.endsWith('-auth-token')).forEach(k => localStorage.removeItem(k));
  } catch(_) {}
  // Init JS client (needed for DB queries + OAuth)
  if (typeof window.supabase !== 'undefined') {
    // detectSessionInUrl:false — the head scrubber already stripped the OAuth hash before
    // this client loads, so the client can't (and shouldn't) parse it. We consume it manually
    // via consumeOAuthHash() to keep tokens out of analytics-recorded URLs.
    try { _supabase = window.supabase.createClient(SUPA_URL, SUPA_KEY, { auth: { detectSessionInUrl: false } }); } catch(e) { console.error('Supabase init failed', e); }
  }
  // Restore session from localStorage (bypasses JS-client auth which returns 204 for sb_publishable keys)
  const stored = _authLoad();
  if (stored?.access_token) {
    const tokenFresh = stored.expires_at && stored.expires_at > Date.now() + 30000;
    if (tokenFresh) {
      void _authOnSignIn(stored).catch(() => { _authClear(); _clearSessionRestoring(); });
    } else if (stored.refresh_token) {
      _authRefresh(stored.refresh_token).then(s => {
        if (!s) { _authClear(); _clearSessionRestoring(); return; }
        _authSave(s);
        void _authOnSignIn(s).catch(() => { _authClear(); _clearSessionRestoring(); });
      });
    } else {
      _authClear();
      _clearSessionRestoring();
    }
  } else {
    _clearSessionRestoring();
  }
  // Watch for OAuth sign-ins (Google) via JS client.
  // ONLY handle SIGNED_IN, not INITIAL_SESSION — session restoration is done above via _authLoad().
  // INITIAL_SESSION fires with stale localStorage data and would call openProfile() on users who aren't logged in.
  if (_supabase) {
    _supabase.auth.onAuthStateChange((event, session) => {
      if (event === 'SIGNED_IN' && session?.access_token && !currentUser) {
        _authSave(session);
        void _authOnSignIn(session).catch(() => {});
      }
    });
  }
  // Log this visit (anonymous-friendly) for the admin landing-view metrics.
  _lidLogPageView();
}

function updateAuthUI() {
  const loginBtn = document.getElementById('nav-login-btn');
  const userBtn  = document.getElementById('nav-user-btn');
  if (!loginBtn || !userBtn) return;
  if (currentUser) {
    loginBtn.style.display = 'none';
    userBtn.style.display  = 'flex';
    const initials = (currentUser.user_metadata?.full_name || currentUser.email || '?')
      .charAt(0).toUpperCase();
    userBtn.textContent = initials;
    const mLogin = document.getElementById('mobile-login-link');
    const mProfile = document.getElementById('mobile-profile-link');
    if (mLogin) mLogin.style.display = 'none';
    if (mProfile) mProfile.style.display = '';
  } else {
    loginBtn.style.display = '';
    userBtn.style.display  = 'none';
    const mLogin = document.getElementById('mobile-login-link');
    const mProfile = document.getElementById('mobile-profile-link');
    if (mLogin) mLogin.style.display = '';
    if (mProfile) mProfile.style.display = 'none';
  }
  // Update sidebar avatar/name/email
  const dashAvatar = document.getElementById('dash-avatar');
  const dashEmail  = document.getElementById('dash-email');
  const dashName   = document.getElementById('dash-name');
  if (currentUser) {
    const name = currentUser.user_metadata?.full_name || currentUser.email || '?';
    if (dashAvatar) dashAvatar.textContent = name.charAt(0).toUpperCase();
    if (dashName)   dashName.textContent   = name;
    if (dashEmail)  dashEmail.textContent  = currentUser.email;
    // show admin nav for owner only
    const adminNav = document.getElementById('dash-nav-admin');
    if (adminNav) adminNav.style.display = isPlatformAdmin() ? '' : 'none';
    // supplier probe: hidden from normal users until SUPPLIER_PROBE_PUBLIC flips
    try { supplierSyncNavVisibility(); } catch (_) {}
    // show admin preview bar + float widget and restore saved view mode
    if (isPlatformAdmin()) { _adminViewModeInit(); adminFloatInit(); }
    // topbar avatar
    const tbAvIcon = document.getElementById('dash-topbar-av-icon');
    const tbUn = document.getElementById('dash-topbar-uname');
    if (tbAvIcon) tbAvIcon.textContent = name.charAt(0).toUpperCase();
    if (tbUn) tbUn.textContent = name;
  }
  // Legacy profile hero elements (kept for compatibility)
  const avatarLg = document.getElementById('profile-avatar-lg');
  const dispName = document.getElementById('profile-display-name');
  const dispEmail = document.getElementById('profile-display-email');
  if (avatarLg && currentUser) {
    const name = currentUser.user_metadata?.full_name || currentUser.email || '?';
    avatarLg.textContent = name.charAt(0).toUpperCase();
    if (dispName) dispName.textContent = name;
    if (dispEmail) dispEmail.textContent = currentUser.email;
  }
  void cohortRefreshCohortPillFromServer();
  // Load profile in background so headshot shows in sidebar/topbar avatars
  if (currentUser && !_profileState.loaded) {
    void loadUserProfile().catch(() => {});
  }
}

let _authMode = 'login'; // 'login', 'signup', or 'reset'
let _authInviteExpanded = false;

function openAuthModal(mode, source) {
  if (currentUser) { void openProfile(); return; }
  if (mode === 'signup') {
    try { sessionStorage.setItem(_LID_SIGNUP_CTA_KEY, source || 'unknown'); } catch (_) {}
    if (typeof larisClarityEvent === 'function') {
      larisClarityEvent('event', 'cta_signup_click');
      larisClarityEvent('set', 'signup_cta_source', source || 'unknown');
    }
  }
  _authMode = mode || 'login';
  if (_authMode !== 'signup') _authInviteExpanded = false;
  document.getElementById('auth-overlay').style.display = 'flex';
  renderAuthModal();
  const inv = document.getElementById('auth-invite-code');
  if (inv) inv.value = getPendingInvite();
}

function toggleAuthInviteField() {
  _authInviteExpanded = !_authInviteExpanded;
  const wrap = document.getElementById('auth-invite-wrap');
  const toggle = document.getElementById('auth-invite-toggle');
  if (wrap) wrap.style.display = _authInviteExpanded ? '' : 'none';
  if (toggle) toggle.textContent = _authInviteExpanded ? 'Sembunyikan kode kohort' : 'Punya kode kohort?';
}

function closeAuthModal() {
  document.getElementById('auth-overlay').style.display = 'none';
}

function renderAuthModal() {
  const m = _authMode;
  var el;
  // Hide tab switcher on reset mode; reset to email tab otherwise
  el = document.getElementById('auth-tabs-wrap'); if(el) el.style.display = m==='reset'?'none':'';
  if(m !== 'reset') _authTabSwitch('email');
  el = document.getElementById('auth-title');      if(el) el.textContent = m==='reset'?'Reset Password':m==='signup'?'Buat Akun Gratis':'Masuk ke LarisID';
  el = document.getElementById('auth-subtitle');   if(el) el.textContent = m==='reset'?'Masukkan email kamu dan kami kirim link reset.':m==='signup'?'Paling cepat: lanjutkan dengan Google. Gratis 3 deep dive tiap hari.':'Login untuk melihat produk trending & simpan favorit kamu';
  el = document.getElementById('auth-submit-btn'); if(el) el.textContent = m==='reset'?'Kirim Link Reset':m==='signup'?'Daftar dengan Email':'Masuk';
  el = document.getElementById('auth-toggle-text');if(el) el.innerHTML = m==='reset'?'<a onclick="_authMode=\'login\';renderAuthModal()">Kembali ke Login</a>':m==='signup'?'Sudah punya akun? <a onclick="_authMode=\'login\';renderAuthModal()">Masuk</a>':'Belum punya akun? <a onclick="_authMode=\'signup\';renderAuthModal()">Daftar</a>';
  el = document.getElementById('auth-name-wrap');  if(el) el.style.display = m==='signup'?'':'none';
  el = document.getElementById('auth-pass-wrap');  if(el) el.style.display = m==='reset'?'none':'';
  el = document.getElementById('auth-forgot-wrap');if(el) el.style.display = m==='login'?'':'none';
  el = document.getElementById('auth-social-wrap');if(el) el.style.display = m==='reset'?'none':'';
  el = document.getElementById('auth-invite-wrap'); if (el) el.style.display = (m === 'reset' || ((m === 'signup' || m === 'login') && !_authInviteExpanded && !getPendingInvite())) ? 'none' : '';
  el = document.getElementById('auth-invite-toggle'); if (el) el.style.display = ((m === 'signup' || m === 'login') && !getPendingInvite()) ? '' : 'none';
  el = document.getElementById('auth-google-btn'); if (el) el.classList.toggle('social-btn--primary', m === 'signup');
  el = document.getElementById('auth-error');      if(el) el.style.display = 'none';
}

function _authErrMsg(msg) {
  const map = {
    'Invalid login credentials': 'Email atau password salah.',
    'Email not confirmed': 'Email belum dikonfirmasi. Cek inbox (atau folder spam) kamu.',
    'User already registered': 'Email sudah terdaftar. Coba login.',
    'Password should be at least 6 characters': 'Password minimal 6 karakter.',
    'Unable to validate email address: invalid format': 'Format email tidak valid.',
  };
  return map[msg] || msg;
}

async function submitAuth() {
  const errEl = document.getElementById('auth-error');
  const btn   = document.getElementById('auth-submit-btn');
  const email = (document.getElementById('auth-email')?.value || '').trim();
  const pass  = document.getElementById('auth-pass')?.value || '';
  const name  = (document.getElementById('auth-name')?.value || '').trim();
  const hdrs  = { apikey: SUPA_KEY, 'Content-Type': 'application/json' };

  const showErr = msg => { if (!errEl) return; errEl.style.color='#e74c3c'; errEl.textContent=_authErrMsg(msg); errEl.style.display=''; };
  const showOk  = msg => { if (!errEl) return; errEl.style.color='var(--green)'; errEl.textContent=msg; errEl.style.display=''; };
  const btnLabel = () => _authMode === 'reset' ? 'Kirim Link Reset' : _authMode === 'signup' ? 'Daftar dengan Email' : 'Masuk';

  const netErr = 'Gagal terhubung ke server. Cek koneksi internet kamu dan coba lagi.';

  if (_authMode === 'reset') {
    if (!email) { showErr('Masukkan email kamu.'); return; }
    btn.textContent='...'; btn.disabled=true;
    try {
      await fetch(`${SUPA_URL}/auth/v1/recover`, { method:'POST', headers:hdrs, body:JSON.stringify({ email }) });
      showOk('Link reset sudah dikirim! Cek email kamu.');
    } catch (_) {
      showErr(netErr);
    } finally {
      btn.textContent=btnLabel(); btn.disabled=false;
    }
    return;
  }

  if (!email || !pass) { showErr('Email dan password wajib diisi.'); return; }
  if (pass.length < 6) { showErr('Password minimal 6 karakter.'); return; }

  if (_authMode === 'signup') {
    const invEl = document.getElementById('auth-invite-code');
    if (invEl && invEl.value.trim()) setPendingInvite(invEl.value);
    btn.textContent='...'; btn.disabled=true;
    try {
      // Auto-confirm via edge function so Yahoo/Outlook/etc. can register without
      // waiting on often-undelivered Supabase confirmation emails.
      const r = await fetch(`${SUPA_URL}/functions/v1/email-signup`, {
        method: 'POST',
        headers: { apikey: SUPA_ANON, Authorization: 'Bearer ' + SUPA_ANON, 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password: pass, full_name: name }),
      });
      const d = await r.json().catch(() => ({}));
      if (!r.ok || !d.access_token) {
        showErr(d.error || d.msg || d.error_description || 'Daftar gagal. Coba lagi.');
        return;
      }
      if (d.is_new_user !== false) _lidFireSignupSuccess();
      _authSave(d);
      closeAuthModal();
      void _authOnSignIn(d).catch(() => {});
    } catch (_) {
      showErr(netErr);
    } finally {
      btn.textContent=btnLabel(); btn.disabled=false;
    }
    return;
  }

  const invEl2 = document.getElementById('auth-invite-code');
  if (invEl2 && invEl2.value.trim()) setPendingInvite(invEl2.value);
  btn.textContent='...'; btn.disabled=true;
  try {
    // Login via direct REST — bypasses JS-client 204 issue with sb_publishable keys
    const r = await fetch(`${SUPA_URL}/auth/v1/token?grant_type=password`, { method:'POST', headers:hdrs, body:JSON.stringify({ email, password:pass }) });
    const d = await r.json().catch(() => ({}));
    if (!r.ok || !d.access_token) { showErr(d.msg || d.error_description || d.error || 'Login gagal.'); return; }
    _authSave(d);
    closeAuthModal();
    void _authOnSignIn(d).catch(() => {});
  } catch (_) {
    showErr(netErr);
  } finally {
    btn.textContent=btnLabel(); btn.disabled=false;
  }
}

// Holds the recovery session (tokens) parsed from the email link until the
// user sets a new password.
let _recoverySession = null;

// On load: detect Supabase recovery link (#access_token=...&type=recovery&...)
// and show the set-new-password screen. Returns true if a recovery flow started.
function handleRecoveryHash() {
  // The head scrubber already moved the hash out of the URL into window.__larisAuthHash.
  let hash = window.__larisAuthHash || '';
  if (!hash || hash.indexOf('access_token') === -1) return false;
  const params = new URLSearchParams(hash.replace(/^#/, ''));
  const type = params.get('type');
  const accessToken = params.get('access_token');
  if (type !== 'recovery' || !accessToken) return false; // not a recovery link — leave for consumeOAuthHash()
  _recoverySession = {
    access_token: accessToken,
    refresh_token: params.get('refresh_token') || '',
    expires_in: parseInt(params.get('expires_in') || '3600', 10),
  };
  // Consumed — clear the stash so consumeOAuthHash() doesn't also process it.
  window.__larisAuthHash = '';
  const ov = document.getElementById('recovery-overlay');
  if (ov) ov.style.display = 'flex';
  setTimeout(() => { const f = document.getElementById('recovery-pass'); if (f) f.focus(); }, 50);
  return true;
}

// On load: establish a session from a stashed OAuth (Google) hash. detectSessionInUrl is off
// and the head scrubber already stripped the URL, so we parse window.__larisAuthHash manually.
function _clearOAuthReturning() {
  window.__larisOAuthReturning = false;
  try { document.documentElement.classList.remove('oauth-returning'); } catch (_) {}
}

function _clearSessionRestoring() {
  try { document.documentElement.classList.remove('session-restoring'); } catch (_) {}
}

// Decode the user claims straight from the access_token JWT (no network round-trip).
function _decodeJwtUser(token) {
  try {
    const part = token.split('.')[1].replace(/-/g, '+').replace(/_/g, '/');
    const payload = JSON.parse(decodeURIComponent(escape(atob(part))));
    if (!payload.sub) return null;
    return {
      id: payload.sub,
      email: payload.email || '',
      phone: payload.phone || '',
      user_metadata: payload.user_metadata || {},
      app_metadata: payload.app_metadata || {},
      role: payload.role || 'authenticated',
    };
  } catch (_) { return null; }
}

async function consumeOAuthHash() {
  const hash = window.__larisAuthHash || '';
  if (!hash || hash.indexOf('access_token') === -1) { window.__larisAuthHash = ''; _clearOAuthReturning(); return false; }
  const params = new URLSearchParams(hash.replace(/^#/, ''));
  window.__larisAuthHash = '';
  if (params.get('type') === 'recovery') { _clearOAuthReturning(); return false; } // recovery handled by handleRecoveryHash()
  const access_token = params.get('access_token');
  if (!access_token) { _clearOAuthReturning(); return false; }
  const refresh_token = params.get('refresh_token') || '';
  const expires_in = parseInt(params.get('expires_in') || '3600', 10);
  try {
    let user = _decodeJwtUser(access_token);
    // Always fetch full user so created_at / last_sign_in_at are available for signup analytics.
    try {
      const r = await fetch(`${SUPA_URL}/auth/v1/user`, { headers: { apikey: SUPA_KEY, Authorization: `Bearer ${access_token}` } });
      if (r.ok) user = await r.json();
    } catch (_) {}
    const sess = { access_token, refresh_token, expires_in, user };
    _authSave(sess);
    await _authOnSignIn(sess).catch(() => {});
    return true;
  } finally {
    _clearOAuthReturning();
  }
}

async function submitRecoveryPassword() {
  const errEl = document.getElementById('recovery-error');
  const btn   = document.getElementById('recovery-submit-btn');
  const p1    = (document.getElementById('recovery-pass')?.value || '');
  const p2    = (document.getElementById('recovery-pass2')?.value || '');
  const showErr = msg => { if (errEl) { errEl.style.color = '#e74c3c'; errEl.textContent = msg; errEl.style.display = ''; } };
  const showOk  = msg => { if (errEl) { errEl.style.color = 'var(--green)'; errEl.textContent = msg; errEl.style.display = ''; } };

  if (!_recoverySession?.access_token) { showErr('Link reset sudah tidak berlaku. Minta link baru lewat "Lupa password?".'); return; }
  if (!p1 || !p2) { showErr('Isi password baru dua kali.'); return; }
  if (p1.length < 8) { showErr('Password minimal 8 karakter.'); return; }
  if (p1 !== p2) { showErr('Password nggak sama. Cek lagi ya.'); return; }

  const orig = btn ? btn.textContent : '';
  if (btn) { btn.disabled = true; btn.textContent = '...'; }
  try {
    const r = await fetch(`${SUPA_URL}/auth/v1/user`, {
      method: 'PUT',
      headers: { apikey: SUPA_KEY, Authorization: `Bearer ${_recoverySession.access_token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ password: p1 }),
    });
    const d = await r.json().catch(() => ({}));
    if (!r.ok) {
      const raw = d.msg || d.message || d.error_description || d.error || '';
      if (/expired|invalid|jwt|token/i.test(raw)) throw new Error('Link reset sudah kedaluwarsa. Minta link baru lewat "Lupa password?".');
      throw new Error(_authErrMsg(raw) || 'Gagal mengganti password. Coba lagi.');
    }
    // Recovery succeeded — we now have a valid session, so log the user straight in.
    _authSave(_recoverySession);
    _recoverySession = null;
    showOk('Password berhasil diganti! Mengalihkan...');
    setTimeout(() => {
      const ov = document.getElementById('recovery-overlay');
      if (ov) ov.style.display = 'none';
      void _authOnSignIn(_authLoad()).catch(() => {});
    }, 900);
  } catch (e) {
    showErr(e.message || 'Gagal mengganti password. Coba lagi.');
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = orig || 'Simpan Password Baru'; }
  }
}

async function signInWithProvider(provider) {
  if (!_supabase) return;
  try {
    const invEl = document.getElementById('auth-invite-code');
    if (invEl && invEl.value.trim()) setPendingInvite(invEl.value);
    if (_authMode === 'signup') sessionStorage.setItem(_LID_OAUTH_SIGNUP_INTENT_KEY, '1');
  } catch (_) {}
  // Pending invite is in sessionStorage (?invite= on load or typed in modal); OAuth redirect does not need to carry the code.
  const { error } = await _supabase.auth.signInWithOAuth({ provider, options:{ redirectTo:'https://larisid.com' } });
  if (error) {
    const errEl = document.getElementById('auth-error');
    errEl.style.color='#e74c3c'; errEl.textContent='Login dengan '+provider+' gagal. Coba lagi.'; errEl.style.display='';
  }
}

// ── WHATSAPP OTP AUTH ─────────────────────────────────────
let _waPhone = '';

function _authTabSwitch(tab) {
  const emailPanel = document.getElementById('auth-email-panel');
  const waPanel    = document.getElementById('auth-wa-panel');
  const tabEmail   = document.getElementById('auth-tab-email');
  const tabWa      = document.getElementById('auth-tab-wa');
  if (!emailPanel || !waPanel) return;
  if (tab === 'wa') {
    emailPanel.style.display = 'none';
    waPanel.style.display    = '';
    tabEmail.classList.remove('active');
    tabWa.classList.add('active');
    // Always start at phone step when switching to WA
    document.getElementById('wa-step-phone').style.display = '';
    document.getElementById('wa-step-otp').style.display   = 'none';
    const we = document.getElementById('wa-error');
    if (we) { we.textContent = ''; we.style.display = 'none'; }
  } else {
    emailPanel.style.display = '';
    waPanel.style.display    = 'none';
    tabEmail.classList.add('active');
    tabWa.classList.remove('active');
  }
}

async function sendWhatsappOtp(isResend) {
  const phoneEl = document.getElementById('wa-phone-input');
  const errEl   = document.getElementById('wa-error');
  const btn     = document.getElementById('wa-send-btn');
  const rawPhone = (phoneEl?.value || '').trim();
  if (!rawPhone) {
    errEl.textContent = 'Masukkan nomor WhatsApp kamu.';
    errEl.style.display = '';
    return;
  }
  errEl.style.display = 'none';
  btn.textContent = '...'; btn.disabled = true;
  try {
    const res = await fetch(`${SUPA_URL}/functions/v1/send-whatsapp-otp`, {
      method: 'POST',
      headers: { apikey: SUPA_ANON, Authorization: 'Bearer ' + SUPA_ANON, 'Content-Type': 'application/json' },
      body: JSON.stringify({ phone: rawPhone }),
    });
    const data = await res.json();
    if (!res.ok || !data.ok) {
      errEl.textContent = data.error || 'Gagal mengirim OTP. Coba lagi.';
      errEl.style.display = '';
      btn.textContent = 'Kirim Kode OTP'; btn.disabled = false;
      return;
    }
    _waPhone = data.phone;
    // Show OTP step
    document.getElementById('wa-step-phone').style.display = 'none';
    document.getElementById('wa-step-otp').style.display   = '';
    const hint = document.getElementById('wa-otp-hint');
    if (hint) hint.textContent = 'Kode OTP sudah dikirim ke WhatsApp ' + _waPhone + '. Masukkan 6 digit di bawah.';
    const otpErr = document.getElementById('wa-otp-error');
    if (otpErr) { otpErr.textContent = ''; otpErr.style.display = 'none'; }
    setTimeout(() => document.getElementById('wa-otp-input')?.focus(), 100);
    _waStartResendCooldown();
  } catch (e) {
    errEl.textContent = 'Terjadi kesalahan. Coba lagi.';
    errEl.style.display = '';
  } finally {
    btn.textContent = 'Kirim Kode OTP'; btn.disabled = false;
  }
}

function _waStartResendCooldown() {
  const link = document.getElementById('wa-resend-link');
  if (!link) return;
  let secs = 60;
  link.style.pointerEvents = 'none'; link.style.color = 'var(--tl)';
  link.textContent = 'Kirim ulang (' + secs + 's)';
  const t = setInterval(() => {
    secs--;
    if (secs <= 0) {
      clearInterval(t);
      link.style.pointerEvents = ''; link.style.color = 'var(--orange)';
      link.textContent = 'Kirim ulang kode';
    } else {
      link.textContent = 'Kirim ulang (' + secs + 's)';
    }
  }, 1000);
}

async function verifyWhatsappOtp() {
  const otpEl  = document.getElementById('wa-otp-input');
  const errEl  = document.getElementById('wa-otp-error');
  const btn    = document.getElementById('wa-verify-btn');
  const otp = (otpEl?.value || '').replace(/\s/g, '');
  if (!otp || !/^\d{6}$/.test(otp)) {
    errEl.textContent = 'Masukkan 6 digit kode OTP.';
    errEl.style.display = '';
    return;
  }
  errEl.style.display = 'none';
  btn.textContent = '...'; btn.disabled = true;
  try {
    const res = await fetch(`${SUPA_URL}/functions/v1/verify-whatsapp-otp`, {
      method: 'POST',
      headers: { apikey: SUPA_ANON, Authorization: 'Bearer ' + SUPA_ANON, 'Content-Type': 'application/json' },
      body: JSON.stringify({ phone: _waPhone, otp }),
    });
    const data = await res.json();
    if (!res.ok || !data.ok) {
      errEl.textContent = data.error || 'Verifikasi gagal. Periksa kode OTP kamu.';
      errEl.style.display = '';
      btn.textContent = 'Verifikasi'; btn.disabled = false;
      return;
    }
    const session = data.session;
    _authSave(session);
    closeAuthModal();
    void _authOnSignIn(session).catch(() => {});
  } catch (e) {
    errEl.textContent = 'Terjadi kesalahan. Coba lagi.';
    errEl.style.display = '';
    btn.textContent = 'Verifikasi'; btn.disabled = false;
  }
}

async function signOut() {
  const stored = _authLoad();
  const access = stored?.access_token;
  if (access) {
    fetch(`${SUPA_URL}/auth/v1/logout`, { method:'POST', headers:{ apikey:SUPA_KEY, Authorization:`Bearer ${access}`, 'Content-Type':'application/json' } }).catch(()=>{});
  }
  _authOnSignOut();
  if (_supabase?.auth?.signOut) {
    try { _supabase.auth.signOut(); } catch (_) {}
  }
}

let _loadSavedInFlight = false;
async function loadSavedProducts() {
  if (!_supabase || !currentUser) return;
  if (_loadSavedInFlight) return;   // deduplicate concurrent calls
  _loadSavedInFlight = true;
  try {
    const { data, error } = await _supabase
      .from('saved_products')
      .select('product_id')
      .eq('user_id', currentUser.id);
    // Only update if we got a real response (don't wipe on transient errors)
    if (!error && data) {
      savedProducts = new Set(data.map(r => r.product_id));
    }
  } finally {
    _loadSavedInFlight = false;
  }
  // Update save button states on any visible cards
  document.querySelectorAll('.save-btn').forEach(btn => {
    const pid = parseInt(btn.dataset.pid);
    const isSaved = savedProducts.has(pid);
    btn.classList.toggle('saved', isSaved);
    if (isSaved) {
      btn.title = 'Lihat Produk Tersimpan';
      btn.innerHTML = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg>`;
      btn.onclick = function(ev) { ev.stopPropagation(); openProfile(); };
    }
  });
  // Only re-render profile grid if profile page is currently visible
  const profilePage = document.getElementById('page-profile');
  if (profilePage && profilePage.classList.contains('active')) {
    renderProfileSaved();
    loadDashboardData();
  }
}

async function saveCompareList() {
  if (!currentUser) { openAuthModal('login'); return; }
  const unsaved = compareList.filter(id => !savedProducts.has(id));
  if (!unsaved.length) { alert('Semua produk yang dipilih sudah tersimpan!'); return; }
  await Promise.all(unsaved.map(pid =>
    _supabase.from('saved_products').insert({ user_id: currentUser.id, product_id: pid }).then(() => savedProducts.add(pid))
  ));
  unsaved.forEach(pid => { cohortLogActivity('product_saved', { product_id: pid }); });
  // Update save button states on cards
  unsaved.forEach(pid => {
    document.querySelectorAll(`.save-btn[data-pid="${pid}"]`).forEach(btn => btn.classList.add('saved'));
  });
  renderProfileSaved();
  // Show inline confirmation
  const confirm = document.getElementById('cmp-save-confirm');
  if (confirm) confirm.style.display = 'flex';
}

function hideSaveConfirm() {
  const confirm = document.getElementById('cmp-save-confirm');
  if (confirm) confirm.style.display = 'none';
}

async function toggleSave(e, pid) {
  e.stopPropagation();
  if (!currentUser) { openAuthModal('login'); return; }
  if (!_supabase) return;
  if (savedProducts.has(pid)) {
    await _supabase.from('saved_products').delete()
      .eq('user_id', currentUser.id).eq('product_id', pid);
    savedProducts.delete(pid);
  } else {
    const wasFirstSave = savedProducts.size === 0;
    await _supabase.from('saved_products').insert({ user_id: currentUser.id, product_id: pid });
    savedProducts.add(pid);
    cohortLogActivity('product_saved', wasFirstSave ? { product_id: pid, complete_milestone_key: 'first_save' } : { product_id: pid });
    /* WS-D: badge for first product saved (idempotent) */
    awardAchievement('first_product_lookup');
  }
  const isSaved = savedProducts.has(pid);
  // Update all save buttons for this product
  document.querySelectorAll(`.save-btn[data-pid="${pid}"]`).forEach(btn => {
    btn.classList.toggle('saved', isSaved);
    if (isSaved) {
      btn.title = 'Lihat Produk Tersimpan';
      btn.innerHTML = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg>`;
      btn.onclick = function(ev) { ev.stopPropagation(); openProfile(); };
    } else {
      btn.title = 'Save product';
      btn.innerHTML = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#B5202A" stroke-width="2.5"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/></svg>`;
      btn.onclick = function(ev) { toggleSave(ev, pid); };
    }
  });
  renderProfileSaved();
  syncDetailSaveBtn();
}

function syncDetailSaveBtn() {
  const btn = document.getElementById('det-save-btn');
  const lbl = document.getElementById('det-save-label');
  if (!btn || !currentProduct) return;
  const isSaved = savedProducts.has(currentProduct.id);
  btn.classList.toggle('saved', isSaved);
  if (lbl) lbl.textContent = isSaved ? 'Tersimpan ✓' : 'Simpan Produk';
}

async function toggleDetailSave() {
  if (!currentProduct) return;
  if (!currentUser) { openAuthModal('login'); return; }
  const pid = currentProduct.id;
  if (!_supabase) return;
  if (savedProducts.has(pid)) {
    await _supabase.from('saved_products').delete()
      .eq('user_id', currentUser.id).eq('product_id', pid);
    savedProducts.delete(pid);
  } else {
    await _supabase.from('saved_products').insert({ user_id: currentUser.id, product_id: pid });
    savedProducts.add(pid);
  }
  syncDetailSaveBtn();
  showPlanPanel(); // show/hide plan section based on new save state
  // Update card buttons too
  const isSaved = savedProducts.has(pid);
  document.querySelectorAll(`.save-btn[data-pid="${pid}"]`).forEach(btn => {
    btn.classList.toggle('saved', isSaved);
    if (isSaved) {
      btn.title = 'Lihat Produk Tersimpan';
      btn.innerHTML = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg>`;
      btn.onclick = function(ev) { ev.stopPropagation(); openProfile(); };
    } else {
      btn.title = 'Simpan produk';
      btn.innerHTML = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#B5202A" stroke-width="2.5"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/></svg>`;
      btn.onclick = function(ev) { toggleSave(ev, pid); };
    }
  });
  renderProfileSaved();
}

