async function loadUsage() {
  if (!_supabase || !currentUser) return;
  try {
    const { data, error } = await _supabase.rpc('get_my_usage');
    if (!error && data) {
      _usage = data;
      _usageFetchedAt = Date.now();
      renderUsageUI();
    }
  } catch (_) {}
}

function _usageSecondsLeft() {
  if (!_usage) return null;
  const elapsed = Math.floor((Date.now() - _usageFetchedAt) / 1000);
  return Math.max(0, (_usage.seconds_until_reset || 0) - elapsed);
}

// "5 j 12 m" — the wait until the daily quota resets (midnight WIB, server-computed)
function _usageResetLabel() {
  const s = _usageSecondsLeft();
  if (s == null) return '';
  const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60);
  return h > 0 ? `${h} j ${m} m` : `${Math.max(1, m)} m`;
}

function _usageApply(data) {
  // Merge a use_dive/use_ai response into the cached usage snapshot
  if (!data || data.unlimited) return;
  _usage = _usage || {};
  if (data.dives_used != null) _usage.dives_used = data.dives_used;
  if (data.dive_limit != null) _usage.dive_limit = data.dive_limit;
  if (data.ai_used != null) _usage.ai_used = data.ai_used;
  if (data.ai_limit != null) _usage.ai_limit = data.ai_limit;
  if (data.bonus_dives != null) _usage.bonus_dives = data.bonus_dives;
  if (data.can_spin != null) _usage.can_spin = data.can_spin;
  if (data.can_claim_feedback != null) _usage.can_claim_feedback = data.can_claim_feedback;
  // Keep the pass window in sync, and clear it when a plain metered response
  // arrives — otherwise a pass that expires mid-session would keep showing the
  // infinity meter until the next full reload.
  if (data.pass_expires_at != null) _usage.pass_expires_at = data.pass_expires_at;
  else if (data.dive_limit != null) _usage.pass_expires_at = null;
  if (data.seconds_until_reset != null) {
    _usage.seconds_until_reset = data.seconds_until_reset;
    _usageFetchedAt = Date.now();
  }
  renderUsageUI();
}

// ── Daily spin (prize wheel) ──────────────────────────────────────────────
// Offered after the user's 2nd dive of the day rather than at the wall: the
// research found 4 of 30 users' LAST action was a limit event, so meeting them
// only once they are already blocked is too late.
let _spinOffered = false;
const _spinPreviewAwards = [0, 1, 2, 5];
function _spinPreviewPickAward() {
  return _spinPreviewAwards[Math.floor(Math.random() * _spinPreviewAwards.length)];
}

function spinShow() {
  const api = window.LarisDailySpin;
  if (!api || typeof api.open !== 'function') return;
  api.open({
    hostId: 'daily-spin-root',
    onSpin: async () => {
      if (!_supabase) throw new Error('no_supabase');
      const { data, error } = await _supabase.rpc('spin_daily_bonus');
      if (error) throw error;
      if (data && data.allowed === false) {
        // Admin/privileged users are unlimited; allow a visual spin preview
        // without touching quota state so they can QA the experience.
        if (data.reason === 'unlimited' && (_usage?.unlimited || isPlatformAdmin())) {
          return { allowed: true, award: _spinPreviewPickAward(), preview: true };
        }
        _usageApply({ ...data, can_spin: false });
        return data;
      }
      if (data) {
        _usageApply({ ...data, can_spin: false });
      }
      return data;
    },
    onAwarded: (data) => {
      if (data?.preview) {
        void logUserEvent('spin_preview', { award: data.award, source: 'unlimited' });
        return;
      }
      void logUserEvent('spin_awarded', { award: data.award, dive_limit: data.dive_limit });
    },
    onCta: () => {
      try { switchDashView('discover'); } catch (_) {}
    },
    onClose: () => {},
  });
  const root = document.getElementById('daily-spin-root');
  if (root) root.setAttribute('aria-hidden', 'false');
  void logUserEvent('spin_shown', { dives_used: _usage?.dives_used ?? null });
}

function spinClose() {
  try { window.LarisDailySpin?.close?.(); } catch (_) {}
  const root = document.getElementById('daily-spin-root');
  if (root) root.setAttribute('aria-hidden', 'true');
}

// The wheel is RELIEF, not an interruption. It used to fire proactively at the
// 2nd dive — which showed it to 19 users while only 13 ever hit the wall, and
// only 8 of those took a prize. With the cap at 10 that trigger would fire at 20%
// usage, which is absurd. So this is now a no-op: the only entry point is the
// daily-limit modal (see usageLimitShow / #cg-spin-btn), where "+1 dive" actually
// means something. Kept as a named function so existing call sites stay valid.
function spinMaybeOffer() { /* intentionally empty — wheel is offered at the wall only */ }

// Can this user still be offered a spin today? Used to decide whether the limit
// modal shows its spin button.
function spinCanOffer() {
  return !!(currentUser && _usage && !_usage.unlimited && _usage.can_spin !== false);
}

async function spinDo() {
  // Center hub on the shared wheel calls onSpin; kept for any legacy onclick.
  try { document.getElementById('dsw-hub')?.click(); } catch (_) {}
}

// From the limit modal: send the user to the feedback form, then grant +3 once
// they actually submit something real (server checks ownership, same-day and a
// 10-character message).
function spinOpenFeedbackForBonus() {
  try {
    _fbBonusPending = true;
    cgClose();
    openFeedback();
  } catch (_) {}
}

let _fbBonusPending = false;

async function spinClaimFeedbackBonus(feedbackId) {
  if (!_supabase || !feedbackId) return;
  try {
    const { data, error } = await _supabase.rpc('claim_feedback_bonus', { p_feedback_id: feedbackId });
    if (error) throw error;
    if (data && data.allowed) {
      _usageApply({ ...data, can_claim_feedback: false });
      void logUserEvent('feedback_bonus_awarded', { award: data.award, dive_limit: data.dive_limit });
    }
  } catch (_) {}
}

// Consume a win-back pass token after sign-in. Idempotent server-side: a second
// claim returns already_claimed and never re-extends the window.
async function _winbackMaybeClaim() {
  let token = null, campaign = null;
  try {
    token = localStorage.getItem(LID_PASS_KEY);
    campaign = localStorage.getItem(LID_PASS_CAMPAIGN_KEY);
  } catch (_) {}
  if (!token || !currentUser || !_supabase) return;
  try {
    const { data, error } = await _supabase.rpc('claim_comeback_pass', { p_token: token });
    if (error) return; // keep the token; a transient failure should not burn it
    // Only clear on a definitive answer. 'wrong_user' means this token belongs to
    // someone else's inbox, so drop it too — retrying can never succeed.
    if (data && (data.ok || data.reason === 'wrong_user' || data.reason === 'invalid_token')) {
      try { localStorage.removeItem(LID_PASS_KEY); localStorage.removeItem(LID_PASS_CAMPAIGN_KEY); } catch (_) {}
    }
    if (!data || !data.ok) return;
    await loadUsage().catch(() => {});
    void logUserEvent('winback_claim', { reason: data.reason, expires_at: data.expires_at || null, campaign });
    if (data.reason === 'claimed') {
      try { showCompareToast('Akses riset tanpa batas aktif sampai ' + _winbackPassLabel(data.expires_at) + '.'); } catch (_) {}
    }
  } catch (_) {}
}

// "8 Agustus" — same month names the emails use.
function _winbackPassLabel(iso) {
  try {
    const d = new Date(iso);
    if (isNaN(d.getTime())) return '';
    const M = ['Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni',
               'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'];
    return `${d.getDate()} ${M[d.getMonth()]}`;
  } catch (_) { return ''; }
}

function renderUsageUI() {
  // A comeback pass lifts the DIVE cap only — the AI pool stays metered at
  // 5/day. Showing infinity for AI would be a straight lie the server then
  // refuses, so pass holders get the real AI counter.
  const passUntil = _usage && _usage.pass_expires_at ? _usage.pass_expires_at : null;
  const unlimited = (_usage && _usage.unlimited) || (currentUser && (isPlatformAdmin() || _accessState.isLeader));
  const pill = document.getElementById('dash-topbar-credit-pill');
  const dEl = document.getElementById('dash-usage-dive');
  const aEl = document.getElementById('dash-usage-ai');
  const badge = document.getElementById('dash-nav-credit-badge');
  if (badge) badge.style.display = 'none';
  if (passUntil) {
    if (dEl) dEl.textContent = '∞';
    if (aEl) aEl.textContent = `${_usage.ai_used ?? 0}/${_usage.ai_limit ?? 5}`;
    if (pill) pill.title = `Riset tanpa batas sampai ${_winbackPassLabel(passUntil)}`;
  } else if (unlimited) {
    if (dEl) dEl.textContent = '∞';
    if (aEl) aEl.textContent = '∞';
    if (pill) pill.title = 'Akses tanpa batas';
  } else if (_usage) {
    if (dEl) dEl.textContent = `${_usage.dives_used ?? 0}/${_usage.dive_limit ?? 10}`;
    if (aEl) aEl.textContent = `${_usage.ai_used ?? 0}/${_usage.ai_limit ?? 5}`;
    if (pill) pill.title = `Jatah harian — reset dalam ${_usageResetLabel()}`;
  }
  const resetLine = document.getElementById('cg-reset-line');
  if (resetLine && _usage) resetLine.textContent = `Jatah baru tersedia dalam ${_usageResetLabel()}.`;
  try { _mlsAiUpdateCounter(); } catch (_) {}
  try { if (typeof usageRenderPage === 'function') usageRenderPage(); } catch (_) {}
  // Keep the countdown ticking; refresh from the server once the day rolls over
  if (!_usageTicker) {
    _usageTicker = setInterval(() => {
      if (!_usage) return;
      if (_usageSecondsLeft() <= 0) { loadUsage(); return; }
      renderUsageUI();
    }, 60000);
  }
}

// Consume 1 daily dive for a product (idempotent server-side: re-opening an
// already-accessed product is free). Returns true when the deep dive may open.
// Network errors fail OPEN with a small session cap so a blip never bricks the
// app — real enforcement is the server counter.
async function _useDive(productKey) {
  if (!currentUser) { try { openAuthModal('login'); } catch (_) {} return false; }
  if (!_supabase || !productKey) return true;
  try {
    const { data, error } = await _supabase.rpc('use_dive', { p_product_key: productKey });
    if (error) throw error;
    if (data && data.allowed === false) {
      _usageApply(data);
      usageLimitShow('dive');
      return false;
    }
    _usageApply(data);
    if (data && !data.unlimited && data.already_accessed === false) {
      spinMaybeOffer(); // offer the daily spin after dive 2, before they hit the wall
    }
    return true;
  } catch (_) {
    if (_diveFailOpen >= 3) { usageLimitShow('dive'); return false; }
    _diveFailOpen++;
    return true;
  }
}

// Consume from the daily AI pool (chat 1 · path 2 · photo 3 — weighted server-side).
// Fails CLOSED: AI calls cost real money, so no ack means no generation.
async function _useAi(action) {
  if (_isCreditPrivileged()) return true;
  if (!_supabase || !currentUser) { try { openAuthModal('login'); } catch (_) {} return false; }
  try {
    const { data, error } = await _supabase.rpc('use_ai', { p_action: action });
    if (error) throw error;
    if (data && data.allowed === false) { _usageApply(data); return false; }
    _usageApply(data);
    return true;
  } catch (_) { return false; }
}

