async function mlsGenRecs(path) {
  const out = document.getElementById('mls-path-recs');
  if (!out) return;
  out.style.display = '';
  const ctx = _mlsContext || {}, p = ctx.product || {};
  const name = p.product_name || p.name || ctx.keyword || 'produk ini';
  const kw = ctx.keyword || p.keyword || '';
  const med = ctx.medianPrice ? `Rp ${Math.round(ctx.medianPrice).toLocaleString('id-ID')}` : '—';
  out.innerHTML = `<div class="dd-card" style="padding:16px;"><div style="font-size:.8rem;color:#6B7280;">AI sedang menyiapkan rekomendasi…</div></div>`;
  if (!(await mlsSpendAi(2, 'ai_path_' + path))) { out.innerHTML = ''; return; }
  const system = `Kamu konsultan jualan Shopee Indonesia. Jawab ringkas dan praktis dalam Bahasa Indonesia ("kamu"), pakai poin bernomor. Tanpa basa-basi.`;
  const prompt = path === 'resell'
    ? `Saya mau JUAL ULANG (reseller) produk "${name}" (keyword "${kw}", median harga pasar ${med}). Beri rekomendasi sourcing: (1) apa yang harus dicek saat memilih supplier, (2) target harga beli ideal supaya margin sehat, (3) bahan/spesifikasi penting yang harus diperhatikan, (4) 2 tips menang vs kompetitor. Maks 6 poin.`
    : `Saya mau BIKIN SENDIRI (creator) produk di niche "${kw}" (acuan "${name}", median harga pasar ${med}). Beri rekomendasi: (1) ide produk/variasi yang belum digarap kompetitor, (2) estimasi biaya produksi ideal & target harga jual, (3) 2-3 ide diferensiasi unik. Maks 6 poin.`;
  let reply;
  try { reply = await _mlsAIRaw(system, [{ role: 'user', content: prompt }]); }
  catch (_) { reply = 'Gagal memuat rekomendasi. Coba lagi.'; }
  out.innerHTML = `<div class="dd-card" style="padding:16px;">
    <div style="font-size:.8rem;font-weight:800;color:#111;margin-bottom:8px;">${path === 'resell' ? 'Rekomendasi Sourcing (Reseller)' : 'Rekomendasi Bikin Produk (Creator)'}</div>
    <div style="font-size:.8rem;color:#374151;line-height:1.6;white-space:pre-wrap;">${_mlsEsc(reply)}</div>
  </div>`;
}

async function mlsPhotoUpload(event) {
  const file = event.target.files && event.target.files[0];
  if (!file) return;
  if (file.size > 5 * 1024 * 1024) { alert('Foto terlalu besar (maks 5 MB).'); event.target.value = ''; return; }
  const preview = document.getElementById('mls-photo-preview');
  const result = document.getElementById('mls-photo-result');
  const reader = new FileReader();
  reader.onload = async () => {
    const dataUrl = String(reader.result || '');
    if (preview) { preview.src = dataUrl; preview.style.display = ''; }
    const m = /^data:(image\/[\w.+-]+);base64,(.+)$/.exec(dataUrl);
    if (!m) { if (result) result.innerHTML = '<div style="font-size:.78rem;color:#B5202A;">Format foto tidak didukung.</div>'; return; }
    const mime = m[1], b64 = m[2];
    if (result) result.innerHTML = '<div style="font-size:.8rem;color:#6B7280;">AI sedang menganalisis foto…</div>';
    if (!(await mlsSpendAi(3, 'ai_photo'))) { if (result) result.innerHTML = ''; return; }
    const ctx = _mlsContext || {}, kw = ctx.keyword || '';
    const med = ctx.medianPrice ? `Rp ${Math.round(ctx.medianPrice).toLocaleString('id-ID')}` : '—';
    const system = `Kamu asisten jualan Shopee Indonesia. Dari foto produk, buat materi jualan dalam Bahasa Indonesia. Jawab PERSIS dengan format:\nJudul: <judul SEO maks 70 karakter>\nDeskripsi: <2-3 kalimat jualan>\nHarga: <rentang harga jual dalam Rp>`;
    const userPrompt = `Konteks pasar: keyword "${kw}", median harga ${med}. Buat judul, deskripsi, dan saran harga untuk produk di foto ini.`;
    let reply;
    try {
      reply = await _mlsAIRaw(system, [{ role: 'user', content: [ { type: 'image', source: { type: 'base64', media_type: mime, data: b64 } }, { type: 'text', text: userPrompt } ] }], { forceClaude: true });
    } catch (_) { reply = 'Gagal menganalisis foto. Coba lagi.'; }
    if (result) result.innerHTML = `<div style="background:#F8FAFC;border:1px solid #E5E7EB;border-radius:10px;padding:14px;font-size:.8rem;color:#374151;line-height:1.6;white-space:pre-wrap;">${_mlsEsc(reply)}</div>`;
  };
  reader.readAsDataURL(file);
}

