// Session dedupe: re-asking the same question is free (the answer is already in
// the thread). The daily pool itself is enforced server-side by use_ai().
let _mlsAiAskedSet = new Set();
function _mlsAiNorm(q) { return String(q || '').toLowerCase().replace(/\s+/g, ' ').trim(); }

// Conversation history for the Mulai Berjualan AI chat (reset per product)
let _mlsAiHistory = [];

function _mlsEsc(s) {
  return String(s).replace(/[&<>"']/g, c => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' }[c]));
}

let _mlsAiAttentionOff = false;

function mlsAiDismissAttention() {
  _mlsAiAttentionOff = true;
  const box = document.getElementById('mls-ai-box');
  if (box) box.classList.remove('mls-ai-box-attn');
}

function mlsAiBoxClick(e) {
  if (e.target.closest('.mls-ai-send')) return;
  const input = document.getElementById('mls-ai-input');
  if (input) input.focus();
}

function mlsAiEnableAttention() {
  if (_mlsAiAttentionOff || _mlsAiHistory.length) return;
  const box = document.getElementById('mls-ai-box');
  if (box) box.classList.add('mls-ai-box-attn');
}

function _mlsAiResetThread() {
  _mlsAiHistory = [];
  _mlsAiAskedSet = new Set();
  _mlsAiAttentionOff = false;
  const respEl = document.getElementById('mls-ai-response');
  if (respEl) { respEl.style.display = 'none'; respEl.innerHTML = ''; }
  const box = document.getElementById('mls-ai-box');
  if (box) box.classList.remove('mls-ai-box-attn');
  requestAnimationFrame(() => setTimeout(mlsAiEnableAttention, 350));
}

function _mlsAiRenderThread(typing) {
  const respEl = document.getElementById('mls-ai-response');
  if (!respEl) return;
  if (!_mlsAiHistory.length && !typing) { respEl.style.display = 'none'; respEl.innerHTML = ''; return; }
  respEl.style.display = 'flex';
  let html = _mlsAiHistory.map(m =>
    `<div class="mls-ai-msg ${m.role === 'user' ? 'user' : 'ai'}">${_mlsEsc(m.content).replace(/\n/g, '<br>')}</div>`
  ).join('');
  if (typing) html += `<div class="mls-ai-msg ai mls-ai-typing">AI sedang mengetik…</div>`;
  respEl.innerHTML = html;
  respEl.scrollTop = respEl.scrollHeight;
}

/** Pick reply language from the user's message. Mixed → most prevalent markers. */
function detectReplyLanguage(text) {
  const raw = String(text || '').toLowerCase();
  const tokens = raw.match(/[a-zà-ÿ]+/g) || [];
  const idWords = new Set([
    'yang', 'dan', 'untuk', 'dengan', 'apa', 'berapa', 'bagaimana', 'kenapa', 'mengapa',
    'ini', 'itu', 'harga', 'jual', 'jualan', 'produk', 'saya', 'aku', 'kah', 'tidak',
    'adalah', 'gimana', 'bisa', 'kalau', 'kalo', 'sama', 'dari', 'juga', 'sudah', 'udah',
    'belum', 'mau', 'akan', 'karena', 'jadi', 'lebih', 'kurang', 'banyak', 'sedikit',
    'bagus', 'laris', 'toko', 'penjual', 'kompetitor', 'omset', 'omzet', 'modal', 'untung',
    'apakah', 'dimana', 'di mana', 'kapan', 'siapa', 'kok', 'dong', 'sih', 'nya', 'lah',
    'pun', 'tapi', 'atau', 'nggak', 'gak', 'ga', 'aja', 'banget', 'nih', 'deh', 'buat',
    'punya', 'masih', 'harus', 'boleh', 'tolong', 'dong', 'nih', 'juga', 'sekali',
    'bagusan', 'lebih', 'cocok', 'layak', 'jualannya', 'penjualannya',
  ]);
  const enWords = new Set([
    'the', 'and', 'for', 'with', 'what', 'how', 'why', 'this', 'that', 'price', 'sell',
    'selling', 'product', 'products', 'my', 'is', 'are', 'can', 'if', 'same', 'from',
    'also', 'already', 'not', 'will', 'because', 'so', 'more', 'less', 'many', 'good',
    'shop', 'seller', 'competitor', 'profit', 'capital', 'when', 'where', 'who', 'which',
    'should', 'would', 'could', 'about', 'into', 'than', 'then', 'just', 'only', 'really',
    'please', 'thanks', 'hello', 'does', 'do', 'did', 'have', 'has', 'been', 'being',
    'their', 'there', 'these', 'those', 'your', 'you', 'me', 'we', 'our', 'of', 'to',
    'in', 'on', 'at', 'by', 'or', 'but', 'as', 'an', 'be', 'it', 'its', 'was', 'were',
    'best', 'better', 'worth', 'market', 'margin', 'cost', 'compare', 'versus', 'vs',
  ]);
  let id = 0, en = 0;
  for (const w of tokens) {
    if (idWords.has(w)) id += 1;
    if (enWords.has(w)) en += 1;
  }
  // Strong Indo particles even if sparse token list
  if (/\b(nggak|gak|gimana|berapa|dong|sih|banget|kah|lah|kok|udah|kalo)\b/.test(raw)) id += 2;
  // Strong English question openers
  if (/^(what|how|why|should|could|would|is|are|does|do|can|which|where|when)\b/.test(raw.trim())) en += 2;
  if (en > id) return 'en';
  if (id > en) return 'id';
  // Exact tie / no markers: prefer English if the message has no Indo particles
  // and looks like Latin English prose; otherwise Bahasa (default product locale).
  if (en === 0 && id === 0 && /\b[a-z]{3,}\b/.test(raw) && !/\b(yang|dan|untuk|dengan|apa|ini|itu)\b/.test(raw)) {
    const asciiLetters = (raw.match(/[a-z]/g) || []).length;
    if (asciiLetters >= 8) return 'en';
  }
  return 'id';
}

function replyLanguageLabel(code) {
  return code === 'en' ? 'English' : 'Bahasa Indonesia';
}

function _mlsAiMedian(arr) {
  const s = [...arr].sort((a, b) => a - b);
  return s.length ? s[Math.floor(s.length / 2)] : 0;
}

function _toMonthly(r) {
  // Prefer the current nowcast, then the day-of-scrape estimate, then the crude
  // lifetime/6 heuristic.
  if (r.nowcast_omset_monthly != null && r.nowcast_omset_monthly >= 0) return r.nowcast_omset_monthly;
  if (r.est_omset_monthly != null && r.est_omset_monthly >= 0) return r.est_omset_monthly;
  return (r.price || 0) * (r.total_sold || 0) / 6;
}

async function _mlsFetchKeywordMarket(keyword) {
  const empty = { rows: [], mPrice: 0, mSold: 0, totalOmset: 0, sigSellers: [], top5: [] };
  if (!keyword || !_supabase) return empty;
  const { data: rawData } = await _supabase
    .from('listings_deduped')
    .select('product_name, store_name, image_url, price, total_sold, reviews, location, item_id, shop_id, keyword, url, est_omset_monthly')
    .eq('keyword', keyword)
    .order('total_sold', { ascending: false })
    .limit(300);
  const seen = new Map();
  for (const r of (rawData || [])) {
    const k = `${r.item_id}_${r.shop_id}`;
    if (!seen.has(k) || (r.total_sold || 0) > (seen.get(k).total_sold || 0)) seen.set(k, r);
  }
  const rows = [...seen.values()].sort((a, b) => (b.total_sold || 0) - (a.total_sold || 0));
  const prices = rows.map(r => r.price || 0).filter(v => v > 0);
  const solds  = rows.map(r => r.total_sold || 0).filter(v => v > 0);
  const mPrice = _mlsAiMedian(prices);
  const mSold  = _mlsAiMedian(solds);
  const totalOmset = rows.reduce((sum, r) => sum + _toMonthly(r), 0);
  const sigSellers = totalOmset > 0 ? rows.filter(r => _toMonthly(r) / totalOmset >= 0.005) : [];
  return { rows, mPrice, mSold, totalOmset, sigSellers, top5: rows.slice(0, 5) };
}

async function _mlsAiEnsureRows(ctx) {
  if (ctx.allRows?.length) return ctx.allRows;
  const kw = ctx.keyword || ctx.product?.keyword;
  if (!kw) return [];
  const market = await _mlsFetchKeywordMarket(kw);
  ctx.allRows = market.rows;
  ctx.medianPrice = market.mPrice;
  ctx.medianSold = market.mSold;
  ctx.top5 = market.top5;
  ctx.sigSellers = market.sigSellers;
  ctx.totalOmset = market.totalOmset;
  return market.rows;
}

const _MLS_SPEC_GROUPS = [
  { label: 'plastik/plastic', terms: ['plastik', 'plastic', 'tritan', 'pp botol', 'pet '] },
  { label: 'kaca/glass', terms: ['kaca', 'glass', 'borosilicate', 'tempered'] },
  { label: 'stainless', terms: ['stainless', '304', '316'] },
  { label: 'silikon/silicone', terms: ['silikon', 'silicone'] },
  { label: 'kayu/bamboo', terms: ['kayu', 'bamboo', 'bambu'] },
  { label: 'keramik', terms: ['keramik', 'ceramic', 'porcelain'] },
  { label: 'LED', terms: ['led ', 'lumen', ' watt', 'wattage'] },
  { label: 'rechargeable/USB', terms: ['recharge', 'usb', 'type-c', 'type c', 'cas ', 'charging'] },
];

function _mlsAiBuildSpecStats(rows, question) {
  if (!rows?.length) return '';
  const total = rows.length;
  const qLower = (question || '').toLowerCase();
  const groups = [];
  for (const g of _MLS_SPEC_GROUPS) {
    const matched = rows.filter(r => g.terms.some(t => (r.product_name || '').toLowerCase().includes(t)));
    if (matched.length < 2) continue;
    const prices = matched.map(r => r.price || 0).filter(v => v > 0);
    const solds  = matched.map(r => r.total_sold || 0).filter(v => v > 0);
    groups.push({
      ...g,
      matched,
      pct: Math.round(matched.length / total * 100),
      medPrice: _mlsAiMedian(prices),
      medSold: _mlsAiMedian(solds),
      qHit: g.terms.some(t => qLower.includes(t)),
    });
  }
  if (!groups.length) return '';
  groups.sort((a, b) => {
    if (a.qHit !== b.qHit) return a.qHit ? -1 : 1;
    return b.matched.length - a.matched.length;
  });
  const lines = groups.slice(0, 6).map(g =>
    `${g.label}: ${g.pct}% listing (${g.matched.length}/${total}), median harga Rp ${Math.round(g.medPrice).toLocaleString('id-ID')}, median terjual ${Math.round(g.medSold).toLocaleString('id-ID')}`
  );
  if (groups.length >= 2 && groups[0].medPrice && groups[1].medPrice) {
    const hi = groups[0].medPrice >= groups[1].medPrice ? groups[0] : groups[1];
    const lo = hi === groups[0] ? groups[1] : groups[0];
    const diff = Math.round((hi.medPrice / lo.medPrice - 1) * 100);
    if (diff > 0) lines.push(`${hi.label} median harga ~${diff}% lebih tinggi dari ${lo.label}.`);
  }
  return 'STATISTIK SPESIFIKASI (dari nama produk — pakai angka ini saat jawab pertanyaan material/spesifikasi):\n' + lines.join('\n');
}

async function mlsAiAsk(prompt) {
  const ctx = _mlsContext || {};
  const p   = ctx.product || {};
  const inputEl = document.getElementById('mls-ai-input');
  const q   = (prompt || inputEl?.value?.trim() || '');
  if (!q) return;
  if (!document.getElementById('mls-ai-response')) return;

  mlsAiDismissAttention();
  // Show the user's turn immediately, with a typing indicator
  if (inputEl) inputEl.value = '';
  _mlsAiHistory.push({ role: 'user', content: q });
  _mlsAiRenderThread(true);

  const kw = ctx.keyword || p.keyword;
  if (!kw) {
    _mlsAiHistory.push({ role: 'assistant', content: 'Pilih produk dulu dari dropdown di atas.' });
    _mlsAiRenderThread();
    return;
  }

  // Daily AI pool: charged up-front (1 poin per chat question) so a generated
  // answer is never clawed back. Admin/leader exempt; re-asking the same
  // question this session is free.
  const _isPrivileged = currentUser && (isPlatformAdmin() || _accessState.isLeader);
  const _qNorm = _mlsAiNorm(q) + '|' + (kw || '');
  const _isRepeat = _mlsAiAskedSet.has(_qNorm);
  if (!_isPrivileged && !_isRepeat) {
    if (q.length < 4) {
      _mlsAiHistory.push({ role: 'assistant', content: 'Coba tanya yang lebih spesifik ya — misalnya soal harga, bahan, atau strategi jualan produk ini.' });
      _mlsAiRenderThread();
      return;
    }
    if (!(await _useAi('mls_chat'))) {
      _mlsAiHistory.push({ role: 'assistant', content: `Jatah AI kamu hari ini sudah habis. Jatah baru tersedia dalam ${_usageResetLabel() || 'beberapa jam'}.` });
      _mlsAiRenderThread();
      return;
    }
  }

  // Ensure market rows are loaded (handles race if user asks before fetch completes)
  let allRows;
  try { allRows = await _mlsAiEnsureRows(ctx); } catch (_) { allRows = ctx.allRows || ctx.top5 || []; }

  const prodName = p.product_name || p.name || allRows[0]?.product_name || kw;
  const top10Comps = allRows.slice(0, 10).map((r, i) =>
    `${i+1}. ${(r.product_name||'').slice(0,50)} — Rp ${Math.round(r.price||0).toLocaleString('id-ID')}, terjual ${(r.total_sold||0).toLocaleString('id-ID')}`
  ).join('\n');

  const allPrices = allRows.map(r => r.price||0).filter(v => v > 0).sort((a,b) => a-b);
  const _pct = (arr, pc) => arr.length ? arr[Math.floor(arr.length * pc / 100)] : 0;
  const priceMin = allPrices[0] || 0;
  const priceP25 = _pct(allPrices, 25);
  const priceP75 = _pct(allPrices, 75);
  const priceMax = allPrices[allPrices.length - 1] || 0;

  const nameSample = allRows.slice(0, 40).map((r, i) =>
    `${i+1}. ${(r.product_name||'').slice(0, 60)}`
  ).join('\n');
  const specStats = _mlsAiBuildSpecStats(allRows, q);

  const replyLang = replyLanguageLabel(detectReplyLanguage(q));

  const systemCtx = [
    `You are LarisID's selling assistant for Shopee Indonesia. The user already selected keyword "${kw}" — NEVER ask what product they mean or ask clarifying questions.`,
    `LANGUAGE: Write ONLY in ${replyLang}.`,
    `STYLE (strict): Exactly 1-3 short sentences. No emojis. No bullet lists. No numbered follow-up questions. No preamble ("Halo", "Pertanyaan bagus"). Lead with a direct, data-backed answer.`,
    `For material/spec questions (plastik vs kaca, size, color, watt, etc.): cite STATISTIK SPESIFIKASI percentages and price gaps. Example: "Sekitar 65% listing plastik; listing kaca median harga ~15% lebih tinggi." If no stat line matches, infer from product names and still give a numeric estimate.`,
    `Never say data is empty when ${allRows.length} market listings exist below. Never ask the user to specify the product again.`,
    `You have no live internet. Don't pretend to fetch Alibaba/Google data.`,
    `\nPRODUK YANG DILIHAT: "${prodName}"`,
    `Keyword: ${kw} | Harga: Rp ${p.price ? Math.round(p.price).toLocaleString('id-ID') : (ctx.medianPrice ? Math.round(ctx.medianPrice).toLocaleString('id-ID') : '—')} | Terjual: ${(p.total_sold||0).toLocaleString('id-ID')} | Rating: ${p.rating||'—'}`,
    `\nDATA PASAR — keyword "${kw}" (${allRows.length} listing di database LarisID):`,
    `Penjual signifikan: ${(ctx.sigSellers||[]).length} | Median harga: Rp ${ctx.medianPrice ? Math.round(ctx.medianPrice).toLocaleString('id-ID') : '—'} | Total omset pasar: Rp ${ctx.totalOmset ? Math.round(ctx.totalOmset).toLocaleString('id-ID') : '—'}/bln`,
    allPrices.length ? `Distribusi harga: Min Rp ${Math.round(priceMin).toLocaleString('id-ID')} | P25 Rp ${Math.round(priceP25).toLocaleString('id-ID')} | Median Rp ${ctx.medianPrice ? Math.round(ctx.medianPrice).toLocaleString('id-ID') : '—'} | P75 Rp ${Math.round(priceP75).toLocaleString('id-ID')} | Max Rp ${Math.round(priceMax).toLocaleString('id-ID')}` : '',
    specStats,
    top10Comps ? `\nTOP 10 PENJUAL:\n${top10Comps}` : '',
    nameSample ? `\nSAMPLE NAMA PRODUK (${allRows.length} total):\n${nameSample}` : '',
    `\nAnswer in ${replyLang}. Max 3 sentences.`,
  ].filter(Boolean).join('\n');

  const userOpenAiKey = localStorage.getItem('larisid_openai_key');
  const userModel     = localStorage.getItem('larisid_anthropic_model') || 'claude-haiku-4-5-20251001';
  const convo = _mlsAiHistory.slice(-12);

  let reply;
  try {
    if (userOpenAiKey) {
      const res = await fetch('https://api.openai.com/v1/chat/completions', {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${userOpenAiKey}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ model: 'gpt-4o', max_tokens: 150, messages: [{ role: 'system', content: systemCtx }, ...convo] })
      });
      const d = await res.json();
      reply = d.choices?.[0]?.message?.content || d.error?.message || 'Tidak ada respons.';
    } else {
      // Route through claude-proxy Edge Function — API key stays server-side
      const session = _supabase ? (await _supabase.auth.getSession()).data?.session : null;
      if (!session) {
        _mlsAiHistory.push({ role: 'assistant', content: 'Login untuk menggunakan fitur AI.' });
        _mlsAiRenderThread();
        return;
      }
      const res = await fetch(`${SUPA_URL}/functions/v1/claude-proxy`, {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${session.access_token}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ model: userModel, max_tokens: 150, system: systemCtx, messages: convo })
      });
      const d = await res.json();
      if (res.status === 429) {
        _mlsAiHistory.push({ role: 'assistant', content: 'Batas penggunaan AI hari ini sudah tercapai (10 permintaan/hari).' });
        _mlsAiRenderThread();
        return;
      }
      reply = d.content?.[0]?.text || d.error?.message || 'Tidak ada respons.';
    }
    _mlsAiHistory.push({ role: 'assistant', content: reply });
    _mlsAiRenderThread();
    _mlsAiCounterInc();
    if (!_isPrivileged && !_isRepeat) _mlsAiAskedSet.add(_qNorm);
  } catch (e) {
    _mlsAiHistory.push({ role: 'assistant', content: 'Gagal menghubungi AI. Coba lagi.' });
    _mlsAiRenderThread();
  }
}

// ── PERSONALIZED DISCOVER ─────────────────────────────────
const _VIEW_KEY = 'laris_viewed_cats';

function trackView(category) {
  if (!category) return;
  try {
    const raw  = JSON.parse(localStorage.getItem(_VIEW_KEY) || '{}');
    raw[category] = (raw[category] || 0) + 1;
    localStorage.setItem(_VIEW_KEY, JSON.stringify(raw));
  } catch (_) {}
}

function getTopCats(n = 3) {
  try {
    const raw = JSON.parse(localStorage.getItem(_VIEW_KEY) || '{}');
    return Object.entries(raw).sort((a,b) => b[1]-a[1]).slice(0,n).map(([c]) => c);
  } catch (_) { return []; }
}

function renderForYou() {
  const topCats = getTopCats(3);
  const source = _dscAllListings.length ? _dscAllListings : _dscBrowsePool;
  if (!topCats.length || !source.length) return;
  const seen = new Set();
  const pool = source.filter(p => {
    if (!p.category || !topCats.includes(p.category)) return false;
    const key = `${p.item_id}_${p.shop_id}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  }).slice(0, 12);
  if (!pool.length) return;
  const existingForYou = document.getElementById('discover-for-you');
  if (existingForYou) existingForYou.remove();
  const layout = document.querySelector('#dash-view-discover .dsc-layout');
  if (!layout || !layout.parentElement) return;
  const kwMap = {};
  source.forEach(r => { const k = r.keyword || '__'; if (!kwMap[k]) kwMap[k] = []; kwMap[k].push(r); });
  const section = document.createElement('div');
  section.id = 'discover-for-you';
  section.className = 'dsc-for-you';
  section.innerHTML = `
    <div class="dsc-for-you-head">
      <div class="dsc-for-you-title">Untuk Kamu</div>
      <div class="dsc-for-you-sub">Berdasarkan produk yang kamu lihat</div>
      <button type="button" class="dsc-for-you-reset" onclick="clearViewHistory()">Reset</button>
    </div>
    <div class="dsc-for-you-row" id="for-you-grid">
      ${pool.map(p => dscCardHtml(p, kwMap)).join('')}
    </div>`;
  layout.parentElement.insertBefore(section, layout);
  void hydrateViewCountsForListings(pool, section);
}

function clearViewHistory() {
  localStorage.removeItem(_VIEW_KEY);
  document.getElementById('discover-for-you')?.remove();
}

