// A8: notifications bell — was a dead placeholder. Opens a small dropdown that
// shows recent credit activity + shortcuts to tracked products and the
// WhatsApp/Email update opt-in.
function toggleNotifMenu(force) {
  const m = document.getElementById('dash-notif-menu');
  if (!m) return;
  const willOpen = (typeof force === 'boolean') ? force : !m.classList.contains('open');
  document.getElementById('dash-topbar-menu')?.classList.remove('open');
  m.classList.toggle('open', willOpen);
  if (willOpen) renderNotifMenu();
}
async function renderNotifMenu() {
  const list = document.getElementById('dash-notif-list');
  if (!list) return;
  list.innerHTML = '<div style="padding:10px 14px;font-size:.74rem;color:#9CA3AF;">Memuat…</div>';
  let rows = [];
  let deltas = [];
  try {
    if (_supabase && currentUser) {
      const [evRes, dl] = await Promise.all([
        _supabase.from('usage_events')
          .select('kind,action,weight,product_key,created_at')
          .eq('user_id', currentUser.id)
          .order('created_at', { ascending: false }).limit(6),
        (typeof trkFetchDeltas === 'function' ? trkFetchDeltas() : Promise.resolve([])),
      ]);
      rows = evRes.data || [];
      deltas = dl || [];
    }
  } catch (_) {}
  if (!rows.length && !deltas.length) {
    list.innerHTML = '<div style="padding:10px 14px;font-size:.74rem;color:#9CA3AF;">Belum ada notifikasi baru.</div>';
    return;
  }
  const descOf = ev => ev.kind === 'dive' ? 'Deep dive dibuka'
    : ev.action === 'mls_chat' ? 'Tanya AI'
    : ev.action === 'path' ? 'Rekomendasi jalur AI'
    : ev.action === 'photo' ? 'Analisis foto AI'
    : 'Aktivitas';
  const deltaHtml = deltas.slice(0, 3).map(d => `
    <div class="dash-topbar-menu-item" style="justify-content:space-between;gap:8px;" onclick="switchDashView('tracker');toggleNotifMenu(false)">
      <span style="font-size:.74rem;color:#374151;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;"><strong>${d.name}</strong></span>
      <span style="font-size:.7rem;font-weight:700;color:${d.soldDelta > 0 ? '#059669' : '#B45309'};white-space:nowrap;">${d.soldDelta > 0 ? `+${trkUnits(d.soldDelta)} terjual` : (d.priceDelta > 0 ? 'harga naik' : 'harga turun')}</span>
    </div>`).join('');
  const evHtml = rows.map(ev => {
    const amt = ev.kind === 'dive' ? '1 dive' : `${ev.weight ?? 1} poin AI`;
    return `<div class="dash-topbar-menu-item" style="justify-content:space-between;cursor:default;">
      <span style="font-size:.74rem;color:#374151;">${descOf(ev)}</span>
      <span style="font-size:.72rem;font-weight:700;color:#6B7280;white-space:nowrap;">${amt}</span>
    </div>`;
  }).join('');
  list.innerHTML = deltaHtml + evHtml;
}
function mlsForceNotifyPopup() {
  try { localStorage.removeItem('larisid_mls_notify_v1'); } catch (_) {}
  mlsMaybeShowNotifyPopup();
}

async function openProfile() {
  if (!currentUser) { openAuthModal('login'); return; }
  clearCompare();
  // switch page immediately — don't let background async calls block navigation
  document.body.classList.add('in-dashboard');
  document.body.classList.remove('on-landing');
  document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
  document.getElementById('page-profile').classList.add('active');
  window.scrollTo(0, 0);
  // Sync fast-path: show onboarding wizard immediately for likely new users — never
  // wait on Supabase first (avoids mobile flash of Discover category picker).
  const onbFast = nuOnbPendingSync();
  if (onbFast) {
    _navSilence++;
    try {
      nuOnbShowInPage(true);
      switchDashView('discover');
      _navReplace();
    } finally {
      _navSilence--;
    }
  }
  const needsOnb = await nuOnbCheckNeeded();
  _navSilence++;
  try {
    const u = new URLSearchParams(window.location.search || '');
    if (needsOnb) {
      if (!onbFast) {
        nuOnbShowInPage(!_nuOnb.visible);
        switchDashView('discover');
        _navReplace();
      }
    } else {
      if (_nuOnb.visible) nuOnbHideInPage();
      const urlView = u.get('view');
      const product = u.get('product');
      if (urlView === 'deepdive' && product) {
        switchDashView('deepdive');
        setTimeout(() => { dscOpenDeepDive(product, true); _navReplace(); }, 50);
      } else if (urlView && typeof PDB_VIEWS !== 'undefined' && PDB_VIEWS.includes(urlView)) {
        switchDashView(urlView);
        _navReplace();
      } else {
        switchDashView('dashboard');
        _navReplace();
      }
      setTimeout(() => nuScheduleHint('dashboard'), 3000);
    }
  } finally {
    _navSilence--;
  }
  _clearSessionRestoring();
  // load data in background after page is visible
  try { await loadAllPlans(); } catch(_) {}
  try { renderProfileSaved(); } catch(_) {}
  try { loadDashboardData(); } catch(_) {}
  try { loadUsage(); } catch(_) {}
  try { redeemPendingReferral(); } catch(_) {} // B6: credit the referrer if signed up via ?ref=
  try { await loadUserProfile(); } catch(_) {}
  // Personalization needs the saved category/region picks (write-only until
  // 2026-07-16): hydrate, then re-rank Naik Daun and make sure YLK rendered.
  try { await nuOnbHydratePrefs(); naikDaunRender(); void ylkEnsureRegion(); } catch(_) {}
  try {
    const u = new URLSearchParams(window.location.search || '');
    const pv = u.get('preview');
    if (pv === 'student' || pv === 'leader') {
      try { sessionStorage.setItem('larisid_admin_cohort_shell', pv); } catch (_) {}
    }
  } catch (_) {}
  setTimeout(() => { cohortLoadLightForTheme().catch(() => {}); }, 0);
  journeyApplyNavGating();
  void journeyHydrateFromRemote();
}

async function journeyHydrateFromRemote() {
  if (!_supabase || !currentUser) return;
  try {
    const { data } = await _supabase.from('user_journey_stats')
      .select('deepdive_count,first_deepdive_at,last_discover_at,full_deepdive_unlocked')
      .eq('user_id', currentUser.id).maybeSingle();
    if (!data) return;
    const local = journeyLoad();
    journeySave({
      deepdiveCount: Math.max(local.deepdiveCount || 0, data.deepdive_count || 0),
      firstDeepDiveAt: local.firstDeepDiveAt || data.first_deepdive_at,
      lastDiscoverAt: local.lastDiscoverAt || data.last_discover_at,
      fullDeepDive: !!(local.fullDeepDive || data.full_deepdive_unlocked),
    });
    journeyApplyNavGating();
  } catch (_) {}
}

