// ════════════════════════════════════════════════════════════
//  JUNGLE SCOUT-STYLE DASHBOARD — view switching, Product DB
// ════════════════════════════════════════════════════════════

const PDB_VIEWS = ['home','product-database','product-tracker','opportunity-finder','category-trends','suppliers','keywords','estimator','marketing','saved','education','dashboard','discover','tracker','deepdive','ai','credits','cohort','admin','mytoko','about','extension'];
const PDB_SUB_MAP = {'product-database':'research','product-tracker':'research','opportunity-finder':'research','category-trends':'research'};

// View titles for topbar
const VIEW_TITLES = {
  'dashboard':'Dashboard','discover':'Discover','tracker':'Alerts',
  'deepdive':'Deep Dive','ai':'Mulai Berjualan','credits':'Penggunaan','cohort':'Kohort',
  'home':'Home Dashboard','product-database':'Product Database',
  'product-tracker':'Product Tracker','opportunity-finder':'Opportunity Finder',
  'saved':'Produk Tersimpan','education':'Edukasi','mytoko':'My Toko','about':'Tentang',
  'extension':'Chrome Extension','suppliers':'Cari Supplier',
};

const VIEW_TITLE_IMG = {
  dashboard: 'dashboard',
  discover: 'discover',
  tracker: 'alerts',
  deepdive: 'deep-dive',
  ai: 'mulai-berjualan',
  mytoko: 'my-toko',
  extension: 'chrome-extension',
};

function renderPageTitleEl(el, view, forceText) {
  if (!el) return;
  const slug = !forceText && VIEW_TITLE_IMG[view];
  const alt = VIEW_TITLES[view] || view || forceText || '';
  if (slug) {
    const topbar = el.classList.contains('dash-topbar-title') || el.classList.contains('dash-topbar-view-page');
    el.innerHTML = `<img class="page-title-img${topbar ? ' page-title-img--topbar' : ''}" src="/images/titles/${slug}.webp" alt="${alt.replace(/"/g, '&quot;')}" decoding="async">`;
    el.classList.add('is-page-title-img');
  } else {
    el.textContent = forceText || alt;
    el.classList.remove('is-page-title-img');
  }
}

/** Tracks which dashboard pane is visible (used after auth/session sync). */
let _dashActiveView = 'dashboard';

// New nav items for the redesigned sidebar
const NEW_NAV_IDS = ['dashboard','discover','deepdive','tracker','ai','credits'];
const PDB_CATS = ['Bayi & Anak','Motor & Mobil','Rumah','Hewan Peliharaan','Dapur','Kamar Mandi','Elektronik','Fashion','Kecantikan','Kesehatan','Olahraga','Outdoor & Camping','Sepeda','Tanaman','Taman','Keamanan','Hobi & Kerajinan','Alat Tulis','HP & Gadget'];

let _pdbSortField  = 'total_sold';
let _pdbSortDir    = 'desc';
let _pdbRows       = [];
let _pdbCatsInited = false;

function toggleResearchToolsNav() {
  const sub = document.getElementById('dash-sub-research-tools');
  const parent = document.getElementById('dash-nav-research-tools');
  if (sub) sub.classList.toggle('open');
  if (parent) parent.classList.toggle('open');
}

function switchDashView(view) {
  if (view === 'alerts') view = 'tracker';
  // Supplier probe is hidden until launch — bounce direct hits (#/suppliers,
  // stale history entries) instead of showing an empty shell.
  if (view === 'suppliers' && !supplierProbeVisible()) view = 'dashboard';
  const prevView = _dashActiveView;
  if (view !== prevView) {
    try { void logUserEvent('view_open', { ui: 'A', view }); } catch (_) {}
  }
  if (prevView === 'discover' && view !== 'discover') {
    _dscScrollTop = document.getElementById('dash-content')?.scrollTop || 0;
    _dscHideLoadingUi();
    // Persist loaded listings so returning to Discover is instant
    if (_dscAllListings.length) {
      try { dscSaveCache(_dscAllListings.slice(0, DSC_PAGE_SIZE)); } catch (_) {}
    }
  }
  if (prevView === 'deepdive' && view !== 'deepdive') {
    // Order matters: _refMaybeGoodDiveNudge zeroes _ddEnterTs, so dwell logs first.
    try { _ddLogDwell('nav'); } catch (_) {}
    try { void _refMaybeGoodDiveNudge(); } catch (_) {}
  }
  _dashActiveView = view;
  try { journeyApplyNavGating(); } catch (_) {}
  PDB_VIEWS.forEach(v => {
    const el = document.getElementById(`dash-view-${v}`);
    if (el) el.style.display = (v === view) ? '' : 'none';
  });

  // Populate the filter category grids right after the view is shown — before any
  // cosmetic nav code below that could throw — so categories never end up blank
  // while the (static) filter panel is visible.
  if (view === 'product-database') { try { _initPdbCats(); } catch (_) {} }
  if (view === 'opportunity-finder') { try { _initOfCats(); } catch (_) {} }
  // Leaving the deep dive: drop the section observer so it doesn't keep firing
  // against a hidden panel or leak across products.
  if (view !== 'deepdive') {
    try { ddDisconnectSections(); } catch (_) {}
    // The rail is product-scoped; it has no meaning outside the deep dive.
    try { window.LarisSidePanel?.close(); } catch (_) {}
  }
  // YLK ("Yang Laku dari Kotamu") now lives on the Dashboard — init it when shown.
  if (view === 'dashboard') { try { if (typeof ylkInit === 'function') { ylkInit(); void ylkEnsureRegion(); } } catch (_) {} }
  if (view === 'dashboard') { try { ltrMount(); } catch (_) {} }
  if (view === 'discover') { try { lcpMount(); } catch (_) {} }
  if (view === 'credits') { try { crLoadReferral(); } catch (_) {} }

  // Update topbar title
  try { cohortSyncDashTopbarTitle(view); } catch (_) {}

  // New sidebar nav: highlight correct item
  const _rtViews = new Set(['discover','deepdive','tracker','ai']);
  ['dashboard','discover','deepdive','tracker','ai','cohort','extension'].forEach(k => {
    const el = document.getElementById(`dash-nav-${k}`);
    if (!el) return;
    el.classList.toggle('active', k === view);
  });
  const _rtParent = document.getElementById('dash-nav-research-tools');
  const _rtSub = document.getElementById('dash-sub-research-tools');
  if (_rtParent) _rtParent.classList.toggle('active', _rtViews.has(view));
  if (_rtSub && _rtViews.has(view)) _rtSub.classList.add('open');

  // Legacy top-level nav (keep working for old views)
  const topNavKeys = ['home','research','suppliers','keywords','estimator','marketing','saved','education'];
  topNavKeys.forEach(k => {
    const el = document.getElementById(`dash-nav-${k}`);
    if (!el) return;
    const isResearch = k === 'research' && PDB_SUB_MAP[view] === 'research';
    const isDirect   = k === view;
    el.classList.toggle('active', isDirect || isResearch);
    if (k === 'research') el.classList.toggle('open', isResearch || el.classList.contains('open'));
  });

  // Sub-item highlighting
  ['product-database','product-tracker','opportunity-finder','category-trends'].forEach(k => {
    const el = document.getElementById(`dash-sub-${k}`);
    if (el) el.classList.toggle('active', k === view);
  });

  // Open research submenu when a sub-view is active
  if (PDB_SUB_MAP[view] === 'research') {
    const sub = document.getElementById('dash-sub-research');
    const nav = document.getElementById('dash-nav-research');
    if (sub) sub.classList.add('open');
    if (nav) nav.classList.add('open');
  }

  if (view === 'product-database') _initPdbCats();
  if (view === 'opportunity-finder') _initOfCats();
  if (view === 'product-tracker') ptRender();
  if (view === 'category-trends') loadCategoryTrends();
  if (view === 'keywords') _kxLoadKeywordList();
  if (view === 'home') _renderDashHome();
  if (view === 'estimator') loadSalesEstimator();
  if (view === 'admin') loadAdminStats();
  if (view === 'discover'  && typeof dscInit     === 'function') {
    if (!_nuOnb.visible && !nuOnbPendingSync()) {
      dscInit();
      renderForYou();
    }
    // B8: never re-enter Discover with the filter drawer stuck half-open from
    // a previous visit (drawer state lives in classes that survive view swaps).
    try { dscCloseFilter(); } catch (_) {}
    nuOnbSyncDiscoverLayout();
    journeyApplyDiscoverChrome();
    journeyMarkDiscoverView();
    if (_dscScrollTop) {
      const dc = document.getElementById('dash-content');
      if (dc) requestAnimationFrame(() => { dc.scrollTop = _dscScrollTop; });
    }
  }
  if (view === 'deepdive') {
    if (prevView !== 'deepdive') _ddEnterTs = Date.now();
    journeyApplyDeepDiveChrome();
    requestAnimationFrame(ddResizeActiveCharts);
  }
  if (view === 'tracker'   && typeof trkOpen     === 'function') trkOpen();
  if (view === 'dashboard' && typeof hbdInit     === 'function') hbdInit();
  if (view === 'ai'        && typeof mlsInit     === 'function') mlsInit();
  if (view === 'mytoko'    && typeof myTokoInit  === 'function') myTokoInit();
  if (view === 'credits'   && typeof creditsInit  === 'function') creditsInit();
  if (view === 'cohort'    && typeof cohortInit   === 'function') cohortInit();
  if (view === 'suppliers' && typeof suppliersInit === 'function') suppliersInit();
  mbnSync(view);
  // Role layout first; nuRefreshView runs last so empty-state + recommendations win.
  if (view === 'dashboard') _syncDashboardRoleLayout();
  nuRefreshView(view);
  nuScheduleHint(view);
  // Legacy tour disabled — nuScheduleHint replaces dashboard onboarding
  // For non-dashboard views when in student/leader preview, update nav chrome
  if (isPlatformAdmin() && _adminViewMode !== 'admin' && view !== 'dashboard' && view !== 'admin') {
    _hbdApplyLeaderMode(_adminViewMode === 'leader');
  }
  // Always open a freshly-navigated view scrolled to the top. The window is the
  // scroll container on mobile and .dash-content on desktop, so reset both.
  // Discover restores its own saved position above, so skip the reset there.
  if (!(view === 'discover' && _dscScrollTop)) {
    const _dcTop = document.getElementById('dash-content');
    if (_dcTop) _dcTop.scrollTop = 0;
    window.scrollTo(0, 0);
  }
  _navPush();
}

