function _dscPerPage() {
  const beginner = isJourneyBeginner() && !journeyBypassGating();
  const q = (_dscCommittedQ || '').trim();
  if (q) return Math.max(DSC_SEARCH_MIN_PER_PAGE, DSC_PER_PAGE);
  const tier0Cap = beginner && userJourneyTier() === 0;
  if (tier0Cap) return JOURNEY_BEGINNER_DISCOVER_CAP;
  return DSC_PER_PAGE;
}

function dscGoPage(n) {
  const perPage = _dscPerPage();
  // Card grid pages over markets, table over listings.
  if (_dscViewMode === 'card' && _dscTypeRows.length) {
    const tPages = Math.max(1, Math.ceil(_dscTypeRows.length / perPage));
    if (n < 1 || n > tPages) return;
    _dscPage = n;
    dscRenderTable();
    document.getElementById('dsc-card-grid')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    return;
  }
  const pages = Math.ceil(_dscFiltered.length / perPage);
  if (n < 1) return;
  if (n > pages && !_dscHasMore) return;
  _dscPage = n;

  // If the requested page isn't loaded yet, show a spinner and fetch the next batch.
  // dscApplyFilters(false) preserves _dscPage, so no page-restore hack needed.
  const needsFetch = _dscHasMore && !_dscLoading && n > pages;
  if (needsFetch) {
    const cardGrid   = document.getElementById('dsc-card-grid');
    const tableInner = document.getElementById('dsc-table-inner');
    const skelCard = `<div class="dsc-skel"><div class="dsc-skel-img"></div><div class="dsc-skel-body"><div class="dsc-skel-line"></div><div class="dsc-skel-line short"></div></div></div>`;
    const spinHtml = Array(8).fill(skelCard).join('');
    if (_dscViewMode === 'card'  && cardGrid)   cardGrid.innerHTML   = spinHtml;
    if (_dscViewMode === 'table' && tableInner) tableInner.innerHTML = `<table class="dsc-table" style="width:100%"><tbody>${spinHtml.replace('grid-column:1/-1;', '')}</tbody></table>`;
    dscLoadListings(); // dscApplyFilters(false) inside preserves _dscPage = n
  } else {
    dscRenderTable();
  }
  scrollResultsToTop();
}

function dscTerapkanFilter() {
  _dscLogApplyUnlessJustLogged();
  _dscSnapAppliedFromUI();
  // Force a fresh server re-fetch regardless of current load state
  _dscLoadGen++;
  _dscAllListings = [];
  _dscOffset = 0;
  _dscPage = 1;              // reset to page 1 so results appear immediately
  _dscHasMore = true;
  _dscLoading = false;       // release any stale in-flight guard so new fetch can proceed
  _dscLoaded = true;         // allow dscApplyFilters to proceed past the guard
  _dscLastSrvFilters = '';   // non-null sentinel so key comparison always triggers re-fetch
  try { sessionStorage.removeItem(DSC_CACHE_KEY); } catch (_) {}  // bust stale cache
  dscApplyFilters();
  dscCloseFilter(); // close drawer on mobile after applying
}

function dscResetFilters() {
  _dscLogFilter('reset', 'reset');
  const g = id => document.getElementById(id);
  _dscCurrentCatFilter  = ''; // clear server-side category filter
  _dscCurrentCatFilters = null;
  try { sessionStorage.removeItem(_DSC_CAT_SS_KEY); } catch {}
  document.querySelectorAll('#dsc-cat-checks input[type=checkbox]').forEach(c => c.checked = true);
  if (g('dsc-search'))     g('dsc-search').value     = '';
  _dscCommittedQ = '';
  dscHideSuggestions();
  if (g('dsc-price-min'))  g('dsc-price-min').value  = DSC_DEFAULT_PRICE_MIN;
  if (g('dsc-price-max'))  g('dsc-price-max').value  = DSC_DEFAULT_PRICE_MAX;
  if (g('dsc-omset-min'))  g('dsc-omset-min').value  = 0;
  if (g('dsc-omset-max'))  g('dsc-omset-max').value  = 500000000;
  if (g('dsc-skor-min'))   { g('dsc-skor-min').value = DSC_DEFAULT_MIN_SCOR; const lbl = g('dsc-skor-min-lbl'); if (lbl) lbl.textContent = String(DSC_DEFAULT_MIN_SCOR); }
  if (g('dsc-sort')) g('dsc-sort').value = 'random';
  document.querySelectorAll('.dsc-chip').forEach(c => c.classList.remove('active'));
  _dscSnapAppliedFromUI();
  dscUpdateDualRange('price');
  dscUpdateDualRange('omset');
  dscTerapkanFilter();
}

// ── TRACKED PRODUCTS ───────────────────────────────────────────
const _TRK_KEY = 'larisid_tracked_v1';
function trkLoad() { try { return JSON.parse(localStorage.getItem(_TRK_KEY) || '[]'); } catch { return []; } }
function trkSave(arr) {
  localStorage.setItem(_TRK_KEY, JSON.stringify(arr));
  // Mirror to Supabase for logged-in users (fire and forget)
  if (currentUser && _supabase) _trkSyncToSupabase(arr).catch(() => {});
}
function trkKey(listing) { return `${listing.item_id}_${listing.shop_id}`; }
function trkIsTracked(listing) { return trkLoad().some(t => t.key === trkKey(listing)); }

// ── Tracked-product deltas: "what changed since you last checked" ────────────
// Baseline = last acknowledged snapshot (localStorage); current = listings_latest.
// Cached per session so the bell and the return strip agree.
const _TRK_SEEN_SNAP_KEY = 'larisid_trk_seen_snap_v1';
let _trkDeltasCache = null;

function _trkSeenSnap() { try { return JSON.parse(localStorage.getItem(_TRK_SEEN_SNAP_KEY) || '{}'); } catch { return {}; } }
function _trkSeenSnapSave(m) { try { localStorage.setItem(_TRK_SEEN_SNAP_KEY, JSON.stringify(m)); } catch (_) {} }

async function trkFetchDeltas() {
  if (_trkDeltasCache) return _trkDeltasCache;
  const tracked = trkLoad();
  if (!tracked.length || !_supabase) return (_trkDeltasCache = []);
  const ids = [...new Set(tracked.map(t => Number(t.item_id)).filter(Boolean))].slice(0, 20);
  if (!ids.length) return (_trkDeltasCache = []);
  let rows = [];
  try {
    const { data, error } = await _supabase
      .from('listings_latest')
      .select('item_id,shop_id,price,total_sold,scraped_at')
      .in('item_id', ids);
    if (error) return (_trkDeltasCache = []);
    rows = data || [];
  } catch (_) { return (_trkDeltasCache = []); }
  const latest = {};
  rows.forEach(r => { latest[`${r.item_id}_${r.shop_id}`] = r; });
  const snap = _trkSeenSnap();
  const deltas = [];
  tracked.forEach(t => {
    const k = trkKey(t);
    const curr = latest[k];
    if (!curr) return;
    const base = snap[k] || { price: t.price || 0, total_sold: t.total_sold || 0 };
    const soldDelta  = (curr.total_sold || 0) - (base.total_sold || 0);
    const priceDelta = (curr.price || 0) - (base.price || 0);
    const priceMoved = Math.abs(priceDelta) >= Math.max(500, (base.price || 0) * 0.02);
    if (soldDelta > 0 || priceMoved) {
      deltas.push({
        key: k, item_id: t.item_id, shop_id: t.shop_id,
        name: t.product_name || t.keyword || 'Produk',
        image: t.image_url || '',
        soldDelta, priceDelta,
        currPrice: curr.price || 0, currSold: curr.total_sold || 0,
      });
    }
  });
  _trkDeltasCache = deltas;
  trkUpdateNotifDot();
  return deltas;
}

// Move the baseline forward once the user has actually seen the changes.
function trkAckDeltas() {
  if (!_trkDeltasCache || !_trkDeltasCache.length) return;
  const snap = _trkSeenSnap();
  _trkDeltasCache.forEach(d => { snap[d.key] = { price: d.currPrice, total_sold: d.currSold }; });
  _trkSeenSnapSave(snap);
}

function trkUnits(n) {
  n = Math.round(n || 0);
  if (n >= 1e6) return (n / 1e6).toFixed(1).replace('.', ',') + 'jt';
  if (n >= 1e3) return (n / 1e3).toFixed(1).replace('.', ',').replace(',0', '') + 'rb';
  return String(n);
}

function trkDeltaMsg(d) {
  const parts = [];
  if (d.soldDelta > 0) parts.push(`terjual +${trkUnits(d.soldDelta)}`);
  if (Math.abs(d.priceDelta) >= 500) parts.push(`harga ${d.priceDelta > 0 ? 'naik' : 'turun'} ${fmtShort(Math.abs(d.priceDelta))}`);
  return parts.join(' · ') + ' sejak terakhir kamu cek';
}

function trkUpdateNotifDot() {
  const dot = document.getElementById('dash-notif-dot');
  if (dot) dot.style.display = (_trkDeltasCache && _trkDeltasCache.length) ? '' : 'none';
}

// ── Supabase sync helpers ────────────────────────────────────
let _trkSellingSet = new Set(); // set of "itemId_shopId" marked is_selling

function _trkAlertPrefs(t) {
  return {
    email:        t.alert_email !== false,
    whatsapp:     !!t.alert_whatsapp,
    competitors:  t.alert_competitors !== false,
    triggers:     ['price', 'keywords', 'sales_5pct'],
  };
}

async function _trkSyncToSupabase(arr) {
  if (!currentUser || !_supabase || !arr.length) return;
  const rows = arr.map(t => ({
    user_id:      currentUser.id,
    item_id:      Number(t.item_id),
    shop_id:      Number(t.shop_id),
    keyword:      t.keyword      || null,
    product_name: t.product_name || null,
    category:     t.category     || null,
    image_url:    t.image_url    || null,
    price:        t.price        || null,
    total_sold:   t.total_sold   || null,
    store_name:   t.store_name   || null,
    is_selling:   _trkSellingSet.has(`${t.item_id}_${t.shop_id}`),
    alert_prefs:  _trkAlertPrefs(t),
  }));
  await _supabase.from('user_tracked_products').upsert(rows, { onConflict: 'user_id,item_id,shop_id', ignoreDuplicates: false });
}

async function _trkLoadSellingFromSupabase() {
  if (!currentUser || !_supabase) return;
  try {
    const { data } = await _supabase
      .from('user_tracked_products')
      .select('item_id,shop_id,is_selling')
      .eq('user_id', currentUser.id)
      .eq('is_selling', true);
    _trkSellingSet = new Set((data || []).map(r => `${r.item_id}_${r.shop_id}`));
  } catch (_) {}
}

async function trkToggleSelling(itemId, shopId) {
  if (!currentUser) { openAuthModal('login'); return; }
  const k = `${itemId}_${shopId}`;
  const nowSelling = !_trkSellingSet.has(k);
  if (nowSelling) _trkSellingSet.add(k); else _trkSellingSet.delete(k);
  /* WS-D: badge + activity when a seller marks a product they sell (idempotent) */
  if (nowSelling) {
    awardAchievement('first_sale');
    void cohortLogActivity('sale_marked', { item_id: itemId, shop_id: shopId });
  }
  // Update checkbox UI immediately
  const cb = document.getElementById(`trk-sell-${k}`);
  if (cb) {
    cb.checked = nowSelling;
    const lbl = cb.nextElementSibling;
    if (lbl) lbl.textContent = nowSelling ? 'Saya jual ini' : 'Saya jual ini';
    lbl && lbl.style && (lbl.style.color = nowSelling ? '#B5202A' : '#6B7280');
  }
  // Persist to Supabase
  if (_supabase) {
    const tracked = trkLoad().find(t => String(t.item_id) === String(itemId) && String(t.shop_id) === String(shopId));
    if (tracked) {
      await _supabase.from('user_tracked_products').upsert({
        user_id:      currentUser.id,
        item_id:      Number(itemId),
        shop_id:      Number(shopId),
        keyword:      tracked.keyword      || null,
        product_name: tracked.product_name || null,
        category:     tracked.category     || null,
        image_url:    tracked.image_url    || null,
        price:        tracked.price        || null,
        total_sold:   tracked.total_sold   || null,
        store_name:   tracked.store_name   || null,
        is_selling:   nowSelling,
        alert_prefs:  _trkAlertPrefs(tracked),
      }, { onConflict: 'user_id,item_id,shop_id' });
    }
  }
  // Refresh My Toko badge if visible
  const myTokoEl = document.getElementById('dash-view-mytoko');
  if (myTokoEl && myTokoEl.style.display !== 'none') myTokoInit();
}

let _ddPendingTrackListing = null;

function ddSyncTrackAlertChannelUI() {
  const emailWrap = document.getElementById('ta-ch-email-wrap');
  const waWrap    = document.getElementById('ta-ch-wa-wrap');
  const emailCh   = document.getElementById('ta-ch-email');
  const waCh      = document.getElementById('ta-ch-wa');
  if (emailWrap && emailCh) emailWrap.classList.toggle('checked', emailCh.checked);
  if (waWrap && waCh) waWrap.classList.toggle('checked', waCh.checked);
}

function ddShowTrackAlertModal(listing) {
  _ddPendingTrackListing = listing;
  const ctx = document.getElementById('ta-product-context');
  const kw  = (listing.keyword || '').trim();
  const name = listing.product_name || 'Produk ini';
  if (ctx) {
    ctx.innerHTML = kw
      ? `<strong>${wsdEsc(name)}</strong> · pesaing di pencarian <strong>“${wsdEsc(kw)}”</strong>`
      : `<strong>${wsdEsc(name)}</strong> · pesaing di pencarian keyword yang sama`;
  }
  const emailCh = document.getElementById('ta-ch-email');
  const waCh    = document.getElementById('ta-ch-wa');
  if (emailCh) emailCh.checked = true;
  if (waCh) waCh.checked = false;
  ddSyncTrackAlertChannelUI();
  const overlay = document.getElementById('ta-overlay');
  if (overlay) overlay.style.display = 'flex';
}

function ddCloseTrackAlertModal() {
  const overlay = document.getElementById('ta-overlay');
  if (overlay) overlay.style.display = 'none';
  _ddPendingTrackListing = null;
}

function ddTrackWithDefaultAlerts() {
  const emailCh = document.getElementById('ta-ch-email');
  const waCh    = document.getElementById('ta-ch-wa');
  if (emailCh) emailCh.checked = true;
  if (waCh) waCh.checked = false;
  ddConfirmTrackAlert();
}

function ddConfirmTrackAlert() {
  const listing = _ddPendingTrackListing;
  if (!listing) return;
  const email    = !!document.getElementById('ta-ch-email')?.checked;
  const whatsapp = !!document.getElementById('ta-ch-wa')?.checked;
  if (!email && !whatsapp) {
    showCompareToast('Pilih Email, WhatsApp, atau keduanya');
    return;
  }
  const key = trkKey(listing);
  let a = trkLoad();
  if (!a.find(t => t.key === key)) {
    a.push({
      key,
      item_id:           listing.item_id,
      shop_id:           listing.shop_id,
      product_name:      listing.product_name || '—',
      store_name:        listing.store_name   || '—',
      image_url:         listing.image_url    || null,
      category:          listing.category     || '',
      price:             listing.price        || 0,
      total_sold:        listing.total_sold   || 0,
      keyword:           listing.keyword      || '',
      tracked_at:        new Date().toISOString(),
      alert_email:       email,
      alert_whatsapp:    whatsapp,
      alert_competitors: true,
    });
    trkSave(a);
    journeyApplyNavGating();
  }
  ddUpdateTrackBtn(listing);
  ddCloseTrackAlertModal();
  if (typeof mlsInit === 'function') mlsInit();
  nuHintMark('deepdive_track');
  switchDashView('tracker');
}

function ddToggleTrack() {
  const listing = _ddKwListing || _ddCurrentP?._listing;
  if (!listing) return;
  dashboardTourHandleTrackClick();
  const key = trkKey(listing);
  let arr = trkLoad();
  const idx = arr.findIndex(t => t.key === key);
  void logUserEvent('track_toggle', { on: idx < 0, source: 'deepdive', item_id: listing.item_id ?? null });
  if (idx >= 0) {
    // Remove from tracker
    arr.splice(idx, 1);
    trkSave(arr);
    ddUpdateTrackBtn(listing);
    return;
  }
  // Adding to tracker — free (retention hook: deltas feed the bell + return strip)
  if (!currentUser) { openAuthModal('login'); return; }
  ddShowTrackAlertModal(listing);
}

// Syncs the two deep-dive tracking affordances (revived 2026-07-10: the Jun 23
// "tracking lives in My Toko only" change left ddToggleTrack reachable only via
// the post-unlock nudge, and deliberate tracking went to zero — starving the
// bell / return strip / weekly digest): the full-view topbar pill
// (#dd-track-btn2) and the simple-view action button (#dd-sact-track).
function ddUpdateTrackBtn(listing) {
  const l = listing || _ddKwListing || _ddCurrentP?._listing || null;
  const tracked = l ? trkIsTracked(l) : false;
  const pill  = document.getElementById('dd-track-btn2');
  if (pill) {
    pill.classList.toggle('tracked', tracked);
    const lbl = document.getElementById('dd-track2-label');
    if (lbl) lbl.textContent = tracked ? 'Dilacak' : 'Lacak Produk';
    const ic = document.getElementById('dd-track2-icon');
    if (ic) ic.setAttribute('fill', tracked ? 'currentColor' : 'none');
  }
  const act = document.getElementById('dd-sact-track');
  if (act) {
    act.classList.toggle('tracked', tracked);
    const t = document.getElementById('dd-sact-track-title');
    if (t) t.textContent = tracked ? 'Dilacak' : 'Lacak Produk';
    const s = document.getElementById('dd-sact-track-sub');
    if (s) s.textContent = tracked
      ? 'Update harga & penjualan masuk ke lonceng notifikasi'
      : 'Kabari aku tiap harga atau penjualannya berubah';
    const ic2 = act.querySelector('.dd-sact-icon svg');
    if (ic2) ic2.setAttribute('fill', tracked ? 'currentColor' : 'none');
  }
}

// ── DEEP DIVE ──────────────────────────────────────────────────
let _ddChartTrend = null, _ddChartDist = null, _ddChartShopAge = null, _ddChartCatperf = null;
let _ddCatPerfGen = 0;
const DD_SHOP_AGE_LABELS = ['< 6 bln', '6 bln – 1 th', '1 – 2 th', '2 – 5 th', '> 5 th'];
const DD_SHOP_AGE_COLORS = ['#1E3A8A', '#3B82F6', '#60A5FA', '#93C5FD', '#BFDBFE'];
const _ddDistImagePlugin = {
  id: 'ddDistImages',
  afterDatasetsDraw(chart) {
    if (chart.canvas?.id !== 'dd-chart-dist') return;
    const ctx = chart.ctx;
    const meta = chart.getDatasetMeta(0);
    if (!meta?.data?.length) return;
    meta.data.forEach((point, i) => {
      const raw = chart.data.datasets[0].data[i];
      if (!raw || raw.x == null) return;
      const { x, y } = point.getProps(['x', 'y'], true);
      const r = 11;
      ctx.save();
      ctx.beginPath();
      ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.closePath();
      ctx.clip();
      const img = raw._img;
      if (img?.complete && img.naturalWidth) {
        ctx.drawImage(img, x - r, y - r, r * 2, r * 2);
      } else {
        ctx.fillStyle = raw._color || '#B5202A';
        ctx.fill();
        const letter = (raw.label || '?').trim().charAt(0).toUpperCase();
        ctx.fillStyle = '#fff';
        ctx.font = 'bold 10px system-ui,sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(letter, x, y + 0.5);
      }
      ctx.restore();
      ctx.strokeStyle = '#fff';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.stroke();
    });
  },
};
function ddShopAgeBuckets(rows) {
  const shopMap = new Map();
  (rows || []).forEach(r => {
    const sid = String(r.shop_id || r.store_name || '');
    if (!sid || !r.listing_date) return;
    const cur = shopMap.get(sid);
    if (!cur || new Date(r.listing_date) < new Date(cur)) shopMap.set(sid, r.listing_date);
  });
  const buckets = [0, 0, 0, 0, 0];
  [...shopMap.values()].forEach(d => {
    const days = (Date.now() - new Date(d).getTime()) / 86400000;
    if (days < 180) buckets[0]++;
    else if (days < 365) buckets[1]++;
    else if (days < 730) buckets[2]++;
    else if (days < 1825) buckets[3]++;
    else buckets[4]++;
  });
  const total = buckets.reduce((s, n) => s + n, 0) || 1;
  return { buckets, pcts: buckets.map(n => Math.round(n / total * 100)), total: buckets.reduce((s, n) => s + n, 0) };
}
function ddUpdateShopAgeChart(rows) {
  const { buckets, pcts, total } = ddShopAgeBuckets(rows);
  const sub = document.getElementById('dd-age-sub');
  if (sub) sub.textContent = total ? `${total} toko unik di keyword ini` : 'Belum ada data usia toko';
  const legend = document.getElementById('dd-age-legend');
  if (legend) {
    legend.innerHTML = DD_SHOP_AGE_LABELS.map((l, i) => buckets[i]
      ? `<div class="dd-age-legend-item"><span class="dd-age-legend-dot" style="background:${DD_SHOP_AGE_COLORS[i]}"></span><span>${l}</span><span class="dd-age-legend-pct">${pcts[i]}%</span></div>`
      : '').join('');
  }
  if (!_ddChartShopAge) return;
  _ddChartShopAge.data.datasets = DD_SHOP_AGE_LABELS.map((label, i) => ({
    label,
    data: [pcts[i] || 0],
    backgroundColor: DD_SHOP_AGE_COLORS[i],
    borderWidth: 0,
    stack: 'age',
  }));
  _ddChartShopAge.update('none');
}
function ddPrimeDistImages(chart, points) {
  if (!chart || !points?.length) return;
  const palette = ['#B5202A', '#3B82F6', '#10B981', '#F59E0B', '#8B5CF6', '#EC4899'];
  points.forEach((p, i) => {
    p._color = palette[i % palette.length];
    if (!p.image_url) return;
    const img = new Image();
    img.crossOrigin = 'anonymous';
    img.onload = () => { if (_ddChartDist === chart) chart.update('none'); };
    img.onerror = () => { p._img = null; };
    img.src = p.image_url;
    p._img = img;
  });
}
let _ddCompAll = [], _ddCompShowing = 5;
let _ddTrendCache = null;
let _ddTrendInflight = null;

function ddTrendProductKey(listing) {
  if (!listing?.item_id || listing?.shop_id == null) return '';
  return `${listing.item_id}__${listing.shop_id}`;
}
function ddCloneTrendDatasets(datasets) {
  return (datasets || []).map(ds => ({ ...ds, data: Array.isArray(ds.data) ? [...ds.data] : ds.data }));
}
function ddSaveTrendCache(listing, payload) {
  const key = ddTrendProductKey(listing);
  if (!key) return;
  _ddTrendCache = { key, ...payload };
}
function ddApplyTrendChartPayload(payload) {
  if (!payload || !_ddChartTrend) return false;
  _ddChartTrend.data.labels = payload.labels || [];
  _ddChartTrend.data.datasets = ddCloneTrendDatasets(payload.datasets);
  _ddChartTrend.update('none');
  return true;
}
function ddRestoreTrendFootnotes(extras) {
  document.getElementById('dd-trend-nodata')?.remove();
  document.getElementById('dd-trend-peernote')?.remove();
  document.getElementById('dd-trend-lastupdated')?.remove();
  document.getElementById('dd-trend-ceiling-note')?.remove();
  if (!extras) return;
  const parent = document.getElementById('dd-chart-trend')?.parentElement;
  if (!parent) return;
  if (extras.nodataMsg) {
    const el = document.createElement('div');
    el.id = 'dd-trend-nodata';
    el.style.cssText = 'text-align:center;padding:28px 0;font-size:.75rem;color:#9CA3AF;';
    el.innerHTML = extras.nodataMsg;
    parent.insertBefore(el, parent.querySelector('canvas')?.nextSibling || null);
  }
  if (extras.ceilingNote) {
    const el = document.createElement('div');
    el.id = 'dd-trend-ceiling-note';
    el.style.cssText = 'font-size:.68rem;color:#9CA3AF;margin-top:6px;text-align:center;';
    el.textContent = extras.ceilingNote;
    parent.appendChild(el);
  }
  if (extras.lastUpdated) {
    const el = document.createElement('div');
    el.id = 'dd-trend-lastupdated';
    el.style.cssText = 'font-size:.64rem;color:#9CA3AF;margin-top:4px;text-align:right;';
    el.textContent = extras.lastUpdated;
    parent.appendChild(el);
  }
  if (extras.peerNote) {
    const el = document.createElement('div');
    el.id = 'dd-trend-peernote';
    el.style.cssText = 'font-size:.68rem;color:#9CA3AF;margin-top:6px;text-align:center;';
    el.textContent = extras.peerNote;
    parent.appendChild(el);
  }
}
function ddApplyTrendHeroStats(hero) {
  if (!hero) return;
  const _fmtV = v => v >= 1e9 ? 'Rp '+(v/1e9).toFixed(1)+'M' : v >= 1e6 ? 'Rp '+(v/1e6).toFixed(1)+'jt' : 'Rp '+(v/1e3).toFixed(0)+'rb';
  const _fmtDelta = pct => pct == null ? '—' : pct >= 0 ? `↑ ${pct}%` : `↓ ${Math.abs(pct)}%`;
  const unitEl  = document.getElementById('dd-h-unit');
  const omsetEl = document.getElementById('dd-h-omset');
  const unitDEl  = document.getElementById('dd-h-unit-d');
  const omsetDEl = document.getElementById('dd-h-omset-d');
  const unitSubEl  = document.getElementById('dd-h-unit-sub');
  const omsetSubEl = document.getElementById('dd-h-omset-sub');
  if (unitEl)  unitEl.textContent  = hero.monthlyUnits > 0 ? hero.monthlyUnits.toLocaleString('id-ID') : '—';
  if (omsetEl) { omsetEl.textContent = hero.monthlyOmset > 0 ? _fmtV(hero.monthlyOmset) : '—'; omsetEl.dataset.omsetRaw = hero.monthlyOmset > 0 ? hero.monthlyOmset : 0; }
  if (unitDEl)  { unitDEl.textContent  = _fmtDelta(hero.wowUnitPct);  unitDEl.style.color  = (hero.wowUnitPct  ?? 0) >= 0 ? '#10B981' : '#B5202A'; }
  if (omsetDEl) { omsetDEl.textContent = _fmtDelta(hero.wowOmsetPct); omsetDEl.style.color = (hero.wowOmsetPct ?? 0) >= 0 ? '#10B981' : '#B5202A'; }
  if (unitSubEl)  unitSubEl.textContent  = `Est. unit / bulan · ${hero.periodNote || ''}`;
  if (omsetSubEl) omsetSubEl.textContent = `Est. omset / bulan · ${hero.periodNote || ''}`;
  if (_ddCurrentP && typeof ddRenderBeginnerVerdict === 'function') ddRenderBeginnerVerdict(_ddCurrentP);
}
function ddRestoreTrendChart(listing) {
  const key = ddTrendProductKey(listing);
  if (!key || !_ddTrendCache || _ddTrendCache.key !== key || !_ddChartTrend) return false;
  if (_ddTrendCache.empty) {
    _ddChartTrend.data.labels = [];
    _ddChartTrend.data.datasets.forEach(d => { d.data = []; });
    _ddChartTrend.update('none');
    ddRestoreTrendFootnotes(_ddTrendCache.extras);
    if (_ddTrendCache.hero) ddApplyTrendHeroStats(_ddTrendCache.hero);
    return true;
  }
  if (!ddApplyTrendChartPayload(_ddTrendCache)) return false;
  ddRestoreTrendFootnotes(_ddTrendCache.extras);
  if (_ddTrendCache.hero) ddApplyTrendHeroStats(_ddTrendCache.hero);
  return true;
}
function ddResizeActiveCharts() {
  [_ddChartTrend, _ddChartDist, _ddChartShopAge, _ddChartCatperf].forEach(ch => {
    try { ch?.resize(); } catch (_) {}
  });
}
function ddCommitTrendChart(listing, labels, datasets, meta) {
  const payload = { labels, datasets: ddCloneTrendDatasets(datasets), hero: meta?.hero, extras: meta?.extras };
  ddSaveTrendCache(listing, payload);
  if (ddTrendProductKey(listing) !== ddTrendProductKey(_ddCurrentP?._listing || _ddKwListing)) return;
  if (!ddApplyTrendChartPayload(payload)) return;
  ddRestoreTrendFootnotes(meta?.extras);
  if (meta?.hero) ddApplyTrendHeroStats(meta.hero);
}
function ddRefreshRingkasan() {
  if (!_ddCurrentP) return;
  const listing = _ddCurrentP._listing || _ddKwListing;
  const restored = ddRender(_ddCurrentP);
  if (listing && !restored) void ddLoadTrendHistory(listing);
  requestAnimationFrame(ddResizeActiveCharts);
}
document.addEventListener('visibilitychange', () => {
  if (document.hidden || _dashActiveView !== 'deepdive') return;
  requestAnimationFrame(ddResizeActiveCharts);
});

function _ddRng(seed) {
  let s = seed;
  return function() { s = (s * 1664525 + 1013904223) & 0xffffffff; return (s >>> 0) / 0xffffffff; };
}

