  // Usia toko — 100% stacked horizontal bar
  if (_ddChartShopAge) _ddChartShopAge.destroy();
  _ddChartShopAge = new Chart(document.getElementById('dd-chart-shop-age'), {
    type: 'bar',
    data: {
      labels: [''],
      datasets: DD_SHOP_AGE_LABELS.map((label, i) => ({
        label,
        data: [0],
        backgroundColor: DD_SHOP_AGE_COLORS[i],
        borderWidth: 0,
        stack: 'age',
      })),
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      indexAxis: 'y',
      plugins: { legend: { display: false }, tooltip: { callbacks: { label: ctx => ` ${ctx.dataset.label}: ${ctx.parsed.x}%` } } },
      scales: {
        x: { stacked: true, max: 100, display: false, grid: { display: false } },
        y: { stacked: true, display: false, grid: { display: false } },
      },
      animation: { duration: 400 },
    },
  });
  ddUpdateShopAgeChart(_ddKwRows);

  ddInitCatPerfChart(p);
  // When the keyword context is already loaded (e.g. ddRender re-runs on the "Lihat
  // Data Lengkap" expand, which destroys + recreates the price-distribution chart as
  // an empty scatter), re-apply the peer-derived data so Distribusi Harga, the price
  // range bar, shop-age, category performance and AI insights repopulate instead of
  // staying blank. On a fresh open _ddKwRows is [] so this is skipped, and
