      if (date > t1) break;
      const frac = d / daysDiff;
      const dUnit = dayWeights ? delta * dayWeights[d - 1] : delta / daysDiff;
      const key = ddTrendWKey(date);
      const dayStr = date.toISOString().slice(0, 10);
      if (!weekMap.has(key)) weekMap.set(key, { label: ddTrendWLabel(date), units: 0, omset: 0, days: 0, calendarDays: new Set(), firstDate: ddTrendMondayOf(date) });
      const wk = weekMap.get(key);
      wk.units += dUnit;
      wk.omset += dUnit * (p0 + (p1 - p0) * frac);
      if (dayCounter === 'calendarDays') wk.calendarDays.add(dayStr);
      else wk.days += 1;
