/* ── Server-side daily series ────────────────────────────────────────────────
   `product_daily_series` returns one point per day for ANY window, for every
   product, always: days inside an observed interval carry the measured rate,
   days after the last scrape carry the recency-weighted nowcast decaying toward
   the product's peer cohort, days before the first scrape carry the cohort
   prior. That is the honest version of what the client code below does by hand
   in five layers — one of which (ddTrendFillZeroDeltas) floors every empty gap
   at 1 unit, so a genuinely dead product can never chart a zero.

   Rollback: set localStorage 'larisid_server_series' to '0' to fall back to the
   client path. Remove both the flag and the client path once this is proven. */
const DD_SERIES_DEFAULT_DAYS = 30;

function ddServerSeriesEnabled() {
  try { return localStorage.getItem('larisid_server_series') !== '0'; }
  catch (_) { return true; }
}

async function ddFetchDailySeries(listing, days = DD_SERIES_DEFAULT_DAYS) {
  if (!_supabase || !listing?.item_id) return null;
  const to = new Date();
  const from = new Date(to.getTime() - (Math.max(7, days) - 1) * 86400000);
  const iso = d => d.toISOString().slice(0, 10);
  try {
    const { data, error } = await _supabase.rpc('product_daily_series', {
      p_item_id: listing.item_id,
      p_shop_id: listing.shop_id,
      p_from: iso(from),
      p_to: iso(to),
    });
    if (error || !Array.isArray(data) || !data.length) return null;
    return data;
  } catch (_) {
    return null;
  }
}

/** Bucket the server's per-day rows into ISO weeks. No gap filling needed —
    the server guarantees a row for every day in the window. */
function ddTrendWeeksFromDailySeries(rows) {
  const weekMap = new Map();
  for (const r of rows) {
    const date = new Date(String(r.d) + 'T12:00:00');
    if (isNaN(date)) continue;
    const key = ddTrendWKey(date);
    if (!weekMap.has(key)) {
      weekMap.set(key, {
        label: ddTrendWLabel(date), units: 0, omset: 0, days: 0,
        firstDate: ddTrendMondayOf(date),
      });
    }
    const wk = weekMap.get(key);
    wk.units += Number(r.units) || 0;
    wk.omset += Number(r.omset) || 0;
    wk.days  += 1;
  }
  // A short week here is a real window edge, never missing data, so scaling it
  // to a 7-day equivalent keeps the last bar comparable to the rest.
  return [...weekMap.values()]
    .sort((a, b) => a.firstDate - b.firstDate)
    .map(w => {
      const scale = w.days > 0 && w.days < 7 ? 7 / w.days : 1;
      return {
        label: w.label,
        units: Math.round(w.units * scale),
        omset: Math.round(w.omset * scale),
        firstDate: w.firstDate,
      };
    });
}

/** Server-backed equivalent of ddTrendComputeWeekly. Returns the same shape so
    callers need only skip larisTrendAnchorMondayWindow (see serverSeries). */
async function ddTrendComputeWeeklyServer(listing, opts = {}) {
  const rows = await ddFetchDailySeries(listing, opts.days || DD_SERIES_DEFAULT_DAYS);
  if (!rows) return null;
  const weeks = ddTrendWeeksFromDailySeries(rows);
  if (!weeks.length) return null;

  // dbRows still comes from product_trend_history: the UI reports how many real
  // scrape sessions back the chart, which the daily series deliberately hides.
  const dbRows = await ddTrendFetchScrapeRows(listing, { since: opts.since || null, limit: opts.limit || 80 });
  const totalUnitsRaw = weeks.reduce((s, w) => s + (w.units || 0), 0);
  const modelled = rows.filter(r => r.source === 'forecast' || r.source === 'prior').length;

  return {
    ok: true,
    serverSeries: true,
    dailyRows: rows,
    dbRows: dbRows || [],
    weeks,
    totalUnitsRaw,
    isEstimated: modelled > 0,
    isPeerEstimated: modelled >= rows.length,
    peerWeeklyRate: 0,
    peerWeeklyRates: [],
    peerCount: 0,
    peerSoldMin: 0,
    peerSoldMax: 0,
    trendCeilingNote: null,
    mult: null,
    atCeiling: false,
  };
}

async function ddTrendComputeWeekly(listing, opts = {}) {
  const { since = null, limit = 80, minRows = 2, peerRowsOverride = null, cohortByListing = null } = opts;
  if (!listing?.item_id) return null;

  // Prefer the server series. It cannot come back empty for a real product, so
  // a null here means the RPC is missing or errored — fall through to the old
  // client path rather than showing nothing.
  if (ddServerSeriesEnabled() && !cohortByListing) {
    const srv = await ddTrendComputeWeeklyServer(listing, opts);
    if (srv) return srv;
  }

  let dbRows = cohortByListing
    ? ddTrendDedupeRows(cohortByListing)
    : await ddTrendFetchScrapeRows(listing, { since, limit });

  const state = {
    isPeerEstimated: false,
    isEstimated: false,
    peerWeeklyRate: 0,
    peerWeeklyRates: [],
    peerCount: 0,
    peerSoldMin: 0,
    peerSoldMax: 0,
    trendCeilingNote: null,
  };
  let peerResult = null;
  async function ensurePeerTrend() {
    if (peerResult !== null) return peerResult;
    peerResult = await ddEstimateTrendFromPeers(listing, peerRowsOverride);
    state.peerWeeklyRate = peerResult?.medianRate ?? 0;
    state.peerWeeklyRates = peerResult?.weeklyRates || (state.peerWeeklyRate > 0 ? [state.peerWeeklyRate] : []);
    if (peerResult) {
      state.peerCount = peerResult.peerCount;
      state.peerSoldMin = peerResult.soldMin;
      state.peerSoldMax = peerResult.soldMax;
    }
    return peerResult;
  }
  function applyPeerSyntheticRows(rateOrRates, anchorDate) {
    state.isPeerEstimated = true;
    state.isEstimated = true;
    const rates = Array.isArray(rateOrRates) ? rateOrRates : (state.peerWeeklyRates.length ? state.peerWeeklyRates : [rateOrRates]);
    dbRows = ddTrendPeerSyntheticRows(listing, rates, anchorDate, listing.total_sold || 0);
  }

  if (!cohortByListing && dbRows.length < minRows) {
    const prevKey = `${listing.item_id}_${listing.shop_id}`;
    const prevSnap = _dscPrevMap[prevKey];
    const prevSold = typeof prevSnap === 'object' && prevSnap != null
      ? (prevSnap.total_sold ?? null)
      : prevSnap;
    const currDate = listing.scraped_at ? new Date(listing.scraped_at) : new Date();
    const currRow = {
      scraped_at: currDate.toISOString(),
      total_sold: listing.total_sold,
      price: listing.price,
      reviews: listing.reviews,
      category: listing.category,
      est_sold: listing.est_sold,
      sold_tier: listing.sold_tier,
    };
    if (dbRows.length === 1) {
      const dbDate = new Date(dbRows[0].scraped_at);
      dbRows = dbDate < currDate ? [dbRows[0], currRow] : [currRow, dbRows[0]];
    } else if (prevSold != null) {
      const prevDate = new Date(currDate.getTime() - 7 * 86400000);
      const prevRow = (typeof prevSnap === 'object' && prevSnap != null)
        ? {
            scraped_at: prevSnap.scraped_at || prevDate.toISOString(),
            total_sold: prevSold,
            price: listing.price,
            reviews: prevSnap.reviews,
            category: listing.category,
            est_sold: prevSnap.est_sold,
            sold_tier: prevSnap.sold_tier,
          }
        : { scraped_at: prevDate.toISOString(), total_sold: prevSold, price: listing.price, reviews: null, category: listing.category };
      dbRows = [prevRow, currRow];
    }
    if (dbRows.length < minRows) {
      const gotPeer = await ensurePeerTrend();
      if (gotPeer && state.peerWeeklyRate > 0) applyPeerSyntheticRows(state.peerWeeklyRates, currDate);
      else if (dbRows.length < minRows) return { ok: false, reason: 'insufficient_rows', dbRows };
    }
  }

  let { unitData, corrDeltas, isEstimated, trendCeilingNote, mult, atCeiling } = ddTrendComputeDeltas(dbRows, listing, { isPeerEstimated: state.isPeerEstimated });
  state.isEstimated = isEstimated;
  state.trendCeilingNote = trendCeilingNote;

  const trendCategory = listing?.category || dbRows[dbRows.length - 1]?.category;
  const rawSoldFlat = ddTrendRawSoldUnchanged(dbRows);
  const meaningfulRev = ddTrendHasMeaningfulReviewSignal(dbRows, trendCategory);

  if (!state.isPeerEstimated && (listing.total_sold ?? 0) > 0) {
    if (rawSoldFlat && !meaningfulRev) {
      const gotPeer = await ensurePeerTrend();
      if (gotPeer && state.peerWeeklyRate > 0) {
        applyPeerSyntheticRows(state.peerWeeklyRates, listing.scraped_at ? new Date(listing.scraped_at) : new Date());
        ({ unitData, corrDeltas, isEstimated, trendCeilingNote } = ddTrendComputeDeltas(dbRows, listing, { isPeerEstimated: true }));
        state.isEstimated = true;
        state.trendCeilingNote = trendCeilingNote;
      }
    } else if (rawSoldFlat && meaningfulRev) {
      state.isEstimated = true;
    }
  }

  if (!state.peerWeeklyRate && (state.isEstimated || meaningfulRev || corrDeltas.some(d => d === 0))) {
    await ensurePeerTrend();
  }
  const selfWeeklyRate = ddTrendSelfWeeklyRateFromDeltas(dbRows, corrDeltas);
  const skipSyntheticFill = rawSoldFlat && !meaningfulRev && !state.isPeerEstimated;
  if (!skipSyntheticFill && ddTrendFillZeroDeltas(dbRows, corrDeltas, listing, {
    peerWeeklyRate: state.peerWeeklyRate,
    selfWeeklyRate,
  })) {
    state.isEstimated = true;
  }

  const fallbackPrice = listing.price || dbRows[dbRows.length - 1]?.price || 0;
  const epochMon = since ? ddTrendMondayOf(new Date(since + 'T12:00:00')) : null;
  let weeks = ddTrendBuildWeeklyRows(dbRows, corrDeltas, fallbackPrice, {
    epochMon,
    dayCounter: since ? 'calendarDays' : 'days',
    reviewBiased: state.isEstimated || isEstimated,
  });
  if (state.isEstimated || isEstimated) weeks = ddTrendBreakFlatEstimatedWeeks(weeks);
  let totalUnitsRaw = weeks.reduce((s, w) => s + w.units, 0);

  if (!state.isPeerEstimated && rawSoldFlat && !meaningfulRev &&
      (totalUnitsRaw === 0 || ddTrendWeeksAreFlatNoise(weeks))) {
    weeks = [];
    totalUnitsRaw = 0;
    const atBucketNow = dbRows.every(r => ddTrendSoldIsBucket(r.total_sold, r.sold_tier));
    state.trendCeilingNote = state.trendCeilingNote || (atBucketNow
      ? 'Penjualan bucket Shopee (mis. 5rb+) — total terjual tidak berubah antar scrape. Tren akan muncul saat ada perubahan terjual atau ulasan yang signifikan.'
      : 'Belum ada perubahan terjual atau ulasan yang terdeteksi antar scrape untuk produk ini.');
  }

  return {
    ok: totalUnitsRaw > 0 || weeks.length > 0,
    dbRows,
    weeks,
    totalUnitsRaw,
    ...state,
    mult,
    atCeiling,
  };
}

async function ddEstimateTrendFromPeers(listing, peerRowsOverride) {
  if (!_supabase || !listing?.item_id || !(listing.total_sold > 0)) return null;

  let peerListing = listing;
  if (!peerListing.keyword) {
    const { data: kwRow } = await _supabase
      .from('listings')
      .select('keyword')
      .eq('item_id', listing.item_id)
      .eq('shop_id', listing.shop_id)
      .not('keyword', 'is', null)
      .limit(1)
      .maybeSingle();
    if (kwRow?.keyword) peerListing = { ...listing, keyword: kwRow.keyword };
  }

  let peerPool = peerRowsOverride || _ddKwRows;
  if ((!peerPool || peerPool.length < 2) && peerListing.keyword) {
    const { data } = await _supabase
      .from('listings')
      .select('item_id,shop_id,total_sold,product_name,store_name,category,keyword')
      .eq('keyword', peerListing.keyword)
      .order('total_sold', { ascending: false })
      .limit(80);
    peerPool = data || [];
  }
  if (!peerPool || peerPool.length < 2) return null;

  const target = listing.total_sold;

  function _peers(lo, hi) {
    return peerPool.filter(r =>
      !(String(r.item_id) === String(listing.item_id) && String(r.shop_id) === String(listing.shop_id)) &&
      (r.total_sold || 0) >= lo && (r.total_sold || 0) <= hi
    );
  }

  let peers = _peers(target * 0.25, target * 4);
  if (peers.length < 3) peers = _peers(target * 0.1, target * 10);
  if (peers.length < 2) return null;

  const { data: peerHistory } = await _supabase
    .from('listings')
    .select('item_id,shop_id,scraped_at,total_sold,reviews,category,est_sold,sold_tier')
    .in('item_id', peers.map(r => r.item_id))
    .order('scraped_at', { ascending: false })
    .limit(300);

  const peerMap = new Map();
  for (const r of (peerHistory || [])) {
    const k = `${r.item_id}_${r.shop_id}`;
    if (!peerMap.has(k)) peerMap.set(k, []);
    peerMap.get(k).push(r);
  }

  const weeklyRates = [];
  for (const [, rows] of peerMap) {
    const deduped = ddTrendDedupeRows(rows);
    const rate = ddTrendListingWeeklyRate(deduped, listing.category || deduped[deduped.length - 1]?.category);
    if (rate > 0) weeklyRates.push(rate);
  }

  if (weeklyRates.length < 1) {
    const soldVals = peers.map(r => r.total_sold || 0).filter(v => v > 0);
    if (!soldVals.length) return null;
    const implied = ddTrendSoldImpliedWeeklyRate(ddTrendMedianRate(soldVals));
    return {
      medianRate: implied,
      weeklyRates: [implied],
      peerCount: peers.length,
      soldMin: Math.min(...soldVals),
      soldMax: Math.max(...soldVals),
    };
  }

  const medianRate = ddTrendMedianRate(weeklyRates);
  const soldVals = peers.map(r => r.total_sold || 0).filter(v => v > 0);
  console.log('[ddPeerTrend] medianRate/week:', Math.round(medianRate), 'peers:', weeklyRates.length);
  return { medianRate, weeklyRates, peerCount: weeklyRates.length, soldMin: Math.min(...soldVals), soldMax: Math.max(...soldVals) };
}

// Fetches up to 20 scrape points, interpolates deltas day-by-day between consecutive
// scrapes, and buckets into ISO calendar weeks. Shows weekly units + weekly omset so
// even sparse scrapes produce a smooth weekly view, plus a forecast point for next
// Monday (avg of last 2 weeks). IMPORTANT: the real (red/blue) series arrays must
// stay SHORTER than the labels array — never push a trailing null onto them to
// "reach" the forecast index. A past incident had the forecast bleed through and
// render in the real series' color, making a future date look like already-
// scraped data. Only the separate green dashed Forecast series may have a value
// at the future index.
async function ddLoadTrendHistory(listing) {
  if (!listing?.item_id) return;
  const loadKey = ddTrendProductKey(listing);
  if (!loadKey) return;
  if (_ddTrendInflight?.key === loadKey) return _ddTrendInflight.promise;

  const run = async () => {
  // Helper: show no-data message inside chart container
  function _noDataMsg(msg) {
    document.getElementById('dd-trend-nodata')?.remove();
    const el = document.getElementById('dd-chart-trend');
    if (el) el.closest('.dd-card')?.querySelector('.dd-card-title')?.insertAdjacentHTML('afterend',
      `<div id="dd-trend-nodata" style="text-align:center;padding:28px 0;font-size:.75rem;color:#9CA3AF;">${msg}</div>`);
    ddSaveTrendCache(listing, { empty: true, extras: { nodataMsg: msg } });
    if (_ddChartTrend && ddTrendProductKey(_ddCurrentP?._listing || _ddKwListing) === loadKey) {
      _ddChartTrend.data.labels = [];
      _ddChartTrend.data.datasets.forEach(d => { d.data = []; });
      _ddChartTrend.update('none');
    }
  }
  document.getElementById('dd-trend-nodata')?.remove();
  document.getElementById('dd-trend-peernote')?.remove();

  try {
    console.log('[ddTrend] start item_id:', listing?.item_id, 'shop_id:', listing?.shop_id, 'sold:', listing?.total_sold, 'reviews:', listing?.reviews);
    const trend = await ddTrendComputeWeekly(listing, { limit: 20 });
    if (!trend || trend.reason === 'insufficient_rows') {
      _noDataMsg('Belum cukup data scrape untuk menampilkan tren.<br>Data akan muncul setelah 2+ scrape.');
      return;
    }

    const { dbRows, weeks: weeklyRowsAll, isPeerEstimated, peerWeeklyRate, peerCount, peerSoldMin, peerSoldMax, trendCeilingNote } = trend;
    let isEstimated = !!trend.isEstimated;
    const weeklyRows = weeklyRowsAll || [];

    if (!weeklyRows.length || trend.totalUnitsRaw === 0) {
      const snapMap = new Map();
      for (const r of dbRows) {
        const key = ddTrendWKey(new Date(r.scraped_at));
        if (!snapMap.has(key)) snapMap.set(key, { label: ddTrendWLabel(new Date(r.scraped_at)), units: 0, omset: 0, firstDate: ddTrendMondayOf(new Date(r.scraped_at)) });
      }
      const snapRows = [...snapMap.values()].sort((a, b) => a.firstDate - b.firstDate);
      if (!snapRows.length) {
        _noDataMsg('Belum ada data scrape untuk produk ini.');
        return;
      }
      const bucketMsg = trendCeilingNote ||
        (weeklyRows.length > 0
          ? 'Data tidak berubah antar scrape — produk kemungkinan di bucket Shopee (mis. 5rb+). Tren akan muncul saat total terjual atau ulasan berubah secara signifikan.'
          : 'Baru 1 sesi scrape tersedia — nilai menunjukkan total kumulatif. Prediksi berdasarkan rata-rata pasar.');
      const snapRowsDisplay = larisTrendFillZeroWeeks(snapRows.slice(-4), snapRows);
      // Real series arrays stay SHORTER than `snapLabels` (no trailing null) so the
      // red/blue "actual" lines have nothing to plot at the forecast index — only the
      // separate green dashed "Prediksi" series may touch the future label.
      const avgUnits = Math.round(snapRowsDisplay.reduce((s, r) => s + r.units, 0) / snapRowsDisplay.length);
      const avgOmset = Math.round(snapRowsDisplay.reduce((s, r) => s + r.omset, 0) / snapRowsDisplay.length);
      const lastMon = snapRowsDisplay[snapRowsDisplay.length - 1].firstDate;
      const nextMon = new Date(lastMon.getTime() + 7 * 86400000);
      const snapLabels = [...snapRowsDisplay.map(r => r.label), `${nextMon.getDate()} ${DD_TREND_MO[nextMon.getMonth()]} ▶`];
      const snapUnits = snapRowsDisplay.map(r => r.units);
      const snapOmset = snapRowsDisplay.map(r => r.omset);
      const fcSnapUnits = new Array(snapLabels.length).fill(null);
      const fcSnapOmset = new Array(snapLabels.length).fill(null);
      fcSnapUnits[snapRowsDisplay.length - 1] = snapRowsDisplay[snapRowsDisplay.length - 1].units;
      fcSnapOmset[snapRowsDisplay.length - 1] = snapRowsDisplay[snapRowsDisplay.length - 1].omset;
      fcSnapUnits[snapRowsDisplay.length] = avgUnits;
      fcSnapOmset[snapRowsDisplay.length] = avgOmset;
      const snapDatasets = [
        { label:'Omset (snapshot)', data:snapOmset, borderColor:'#B5202A', backgroundColor:'rgba(181,32,42,.06)', borderWidth:2.5, fill:true, tension:0.3, pointRadius:5, pointBackgroundColor:'#B5202A', yAxisID:'y', borderDash:[4,4], spanGaps:false },
        { label:'Unit Terjual', data:snapUnits, borderColor:'#4F46E5', backgroundColor:'transparent', borderWidth:2, tension:0.3, pointRadius:4, pointBackgroundColor:'#4F46E5', yAxisID:'y2', borderDash:[4,4], spanGaps:false },
        { label:'Prediksi Omset', data:fcSnapOmset, borderColor:'#10B981', backgroundColor:'transparent', borderWidth:2, tension:0.3, pointRadius:6, pointBackgroundColor:'#10B981', yAxisID:'y', borderDash:[5,4], spanGaps:false, pointStyle:'triangle' },
        { label:'Prediksi Unit', data:fcSnapUnits, borderColor:'#10B981', backgroundColor:'transparent', borderWidth:2, tension:0.3, pointRadius:6, pointBackgroundColor:'#10B981', yAxisID:'y2', borderDash:[5,4], spanGaps:false, pointStyle:'triangle' },
      ];
      const snapExtras = { nodataMsg: bucketMsg };
      const _snapLastScrape = dbRows.length ? dbRows[dbRows.length - 1].scraped_at : null;
      if (_snapLastScrape) {
        const _sld = new Date(_snapLastScrape);
        snapExtras.lastUpdated = `Data terakhir: ${_sld.getDate()} ${DD_TREND_MO[_sld.getMonth()]} ${_sld.getFullYear()}`;
      }
      ddCommitTrendChart(listing, snapLabels, snapDatasets, { extras: snapExtras });
      return;
    }

    // A5: anchor to current Monday + previous 3; incomplete weeks inherit prior scrape avg.
    // Skipped on the server path — that series already spans the whole window.
    let weeklyRowsFilled = trend?.serverSeries ? weeklyRows : larisTrendAnchorMondayWindow(weeklyRows, {
      mondayOf: ddTrendMondayOf, wKey: ddTrendWKey, wLabel: ddTrendWLabel,
    });
    if (weeklyRowsFilled.some(w => w.gapEstimated)) isEstimated = true;
    const labels = weeklyRowsFilled.map(w => w.label);
    // Real series arrays stay SHORTER than `labels` (no trailing null) so the
    // red/blue "actual" lines have nothing to plot at the forecast index — only the
    // separate green dashed "Forecast" series may touch the future label.
    const chartUnitData = weeklyRowsFilled.map(w => w.units);
    const chartOmsetData = weeklyRowsFilled.map(w => w.omset);
    const nW = weeklyRowsFilled.length;
    const slice2 = weeklyRowsFilled.slice(-2);
    const fcUnit = Math.round(slice2.reduce((s, w) => s + w.units, 0) / slice2.length);
    const fcOmset = Math.round(slice2.reduce((s, w) => s + w.omset, 0) / slice2.length);
    const nextWeek = new Date(weeklyRowsFilled[nW - 1].firstDate.getTime() + 7 * 86400000);
    labels.push(ddTrendWLabel(nextWeek) + ' ▶');
    const fUnitW = new Array(labels.length).fill(null);
    const fOmsetW = new Array(labels.length).fill(null);
    fUnitW[nW - 1] = weeklyRowsFilled[nW - 1].units;
    fOmsetW[nW - 1] = weeklyRowsFilled[nW - 1].omset;
    fUnitW[nW] = fcUnit;
    fOmsetW[nW] = fcOmset;

    const trendDatasets = [
      { label: isEstimated ? 'Omset Est./Minggu' : 'Omset/Minggu', data:chartOmsetData, borderColor:'#B5202A', backgroundColor:'rgba(181,32,42,.06)', borderWidth:2.5, fill:true, tension:0.3, pointRadius:4, pointBackgroundColor:'#B5202A', yAxisID:'y', spanGaps:false, borderDash: isEstimated ? [3,3] : [] },
      { label: isEstimated ? 'Unit Est./Minggu' : 'Unit/Minggu', data:chartUnitData, borderColor:'#4F46E5', backgroundColor:'transparent', borderWidth:2, fill:false, tension:0.3, pointRadius:3, pointBackgroundColor:'#4F46E5', yAxisID:'y2', spanGaps:false, borderDash: isEstimated ? [3,3] : [] },
      { label:'Forecast Omset', data:fOmsetW, borderColor:'#10B981', backgroundColor:'transparent', borderWidth:2, fill:false, tension:0.3, pointRadius:5, pointBackgroundColor:'#10B981', yAxisID:'y', borderDash:[5,4], spanGaps:false, pointStyle:'triangle' },
      { label:'Forecast Unit', data:fUnitW, borderColor:'#10B981', backgroundColor:'transparent', borderWidth:2, fill:false, tension:0.3, pointRadius:5, pointBackgroundColor:'#10B981', yAxisID:'y2', borderDash:[5,4], spanGaps:false, pointStyle:'triangle' },
    ];
    const totalUnits = weeklyRowsFilled.reduce((s, w) => s + w.units, 0);
    const totalOmset = weeklyRowsFilled.reduce((s, w) => s + w.omset, 0);
    const monthlyUnits = Math.round(totalUnits / nW * (30 / 7));
    const monthlyOmset = Math.round(totalOmset / nW * (30 / 7));
    const wowUnitPct = weeklyRowsFilled[0].units > 0 ? Math.round((weeklyRowsFilled[nW - 1].units - weeklyRowsFilled[0].units) / weeklyRowsFilled[0].units * 100) : null;
    const wowOmsetPct = weeklyRowsFilled[0].omset > 0 ? Math.round((weeklyRowsFilled[nW - 1].omset - weeklyRowsFilled[0].omset) / weeklyRowsFilled[0].omset * 100) : null;
    const periodNote = isPeerEstimated ? `peer est. · ${nW} minggu` : isEstimated ? `est. ulasan${peerWeeklyRate ? '+peer' : ''} · ${nW} minggu` : `${nW} minggu · ${dbRows.length} scrape`;
    const trendExtras = {};
    const _lastScrape = dbRows.length ? dbRows[dbRows.length - 1].scraped_at : null;
    if (_lastScrape) {
      const _lsDate = new Date(_lastScrape);
      trendExtras.lastUpdated = `Data terakhir: ${_lsDate.getDate()} ${DD_TREND_MO[_lsDate.getMonth()]} ${_lsDate.getFullYear()}`;
    }
    if (isPeerEstimated) {
      const _fmtS = v => v >= 1e6 ? (v/1e6).toFixed(1)+'jt' : v >= 1000 ? Math.round(v/1000)+'rb' : String(v);
      trendExtras.peerNote = `Estimasi dari ${peerCount} produk serupa (${_fmtS(peerSoldMin)}–${_fmtS(peerSoldMax)} terjual) — bukan data nyata.`;
    } else if (isEstimated && peerWeeklyRate > 0) {
      const _fmtS = v => v >= 1e6 ? (v/1e6).toFixed(1)+'jt' : v >= 1000 ? Math.round(v/1000)+'rb' : String(v);
      trendExtras.peerNote = `Penjualan diestimasi dari perubahan ulasan; celah tanpa sinyal diisi dari ${peerCount} produk serupa (${_fmtS(peerSoldMin)}–${_fmtS(peerSoldMax)} terjual).`;
    } else if (isEstimated) {
      trendExtras.peerNote = 'Penjualan diestimasi dari perubahan ulasan (total terjual Shopee dalam bucket).';
    }
    if (trendCeilingNote) trendExtras.ceilingNote = trendCeilingNote;
    ddCommitTrendChart(listing, labels, trendDatasets, {
      extras: trendExtras,
      hero: { monthlyUnits, monthlyOmset, wowUnitPct, wowOmsetPct, periodNote },
    });
  } catch(e) {
    console.warn('ddLoadTrendHistory:', e);
  }
  };
  const promise = run();
  _ddTrendInflight = { key: loadKey, promise };
  return promise.finally(() => {
    if (_ddTrendInflight?.key === loadKey) _ddTrendInflight = null;
  });
}

function ddRenderCompetitors() {
  const rows = _ddCompAll.slice(0, _ddCompShowing);
  const totalSold = _ddKwTotal || Math.max(_ddCompAll.reduce((s,c)=>s+(c.total_sold||0),0), 1);
  document.getElementById('dd-comp-tbody').innerHTML = rows.length ? rows.map(c => {
    const estMonthly = Math.round((c.total_sold||0) / 6 * (c.price||0));
    const sharePct   = totalSold > 0 ? (c.total_sold||0) / totalSold * 100 : 0;
    const tierColor  = sharePct >= 10 ? '#EF4444' : sharePct >= 3 ? '#F97316' : sharePct >= 1 ? '#3B82F6' : '#9CA3AF';
    const tierLabel  = sharePct >= 10 ? 'Dominan' : sharePct >= 3 ? 'Signifikan' : sharePct >= 1 ? 'Menengah' : 'Kecil';
    const barW       = Math.min(100, Math.round((c.total_sold||0) / Math.max(..._ddCompAll.map(r=>r.total_sold||0),1) * 100));
    const imgHtml    = c.image_url ? `<img src="${c.image_url}" style="width:32px;height:32px;border-radius:4px;object-fit:cover;flex-shrink:0;" onerror="this.style.display='none'">` : '';
    const ratingHtml = c.rating ? `<span style="color:#F59E0B;font-size:.6rem;">★ ${c.rating.toFixed(1)}</span>` : '';
    const reviewsHtml = c.reviews ? `<span style="font-size:.58rem;color:#9CA3AF;">(${c.reviews >= 1000 ? (c.reviews/1000).toFixed(1)+'rb' : c.reviews} ulasan)</span>` : '';
    const locationHtml = c.location ? `<span style="font-size:.58rem;color:#9CA3AF;display:inline-flex;align-items:center;gap:2px;">${wIcon('map-pin', 10)}${c.location}</span>` : '';
    const listingAgeHtml = c.listing_date ? (() => {
      const d = new Date(c.listing_date);
      const months = Math.max(0, Math.floor((Date.now() - d) / (1000*60*60*24*30)));
      const label = months < 1 ? 'Baru' : months < 12 ? `${months} bln` : `${Math.floor(months/12)} thn`;
      return `<span style="font-size:.58rem;color:#9CA3AF;">Sejak ${label}</span>`;
    })() : '';
    const rowClick = (c.item_id && c.shop_id)
      ? ` style="cursor:pointer;" onclick="ddOpenFromKompetitor('${c.item_id}','${c.shop_id}')"`
      : '';
    return `<tr${rowClick}>
      <td style="color:#9CA3AF;font-weight:600;font-size:.72rem;">${c.rank}</td>
      <td style="min-width:180px;">
        <div style="display:flex;align-items:flex-start;gap:7px;">
          ${imgHtml}
          <div>
            <div style="font-size:.68rem;font-weight:600;color:#111827;line-height:1.2;max-width:160px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${c.product_name}</div>
            <div style="font-size:.6rem;color:#6B7280;margin-top:2px;">${c.store_name} ${ratingHtml} ${reviewsHtml}</div>
            <div style="display:flex;gap:6px;margin-top:2px;">${locationHtml} ${listingAgeHtml}</div>
          </div>
        </div>
      </td>
      <td style="font-size:.68rem;font-weight:600;white-space:nowrap;">Rp ${(c.price||0).toLocaleString('id-ID')}</td>
      <td style="min-width:110px;">
        <div style="font-size:.68rem;font-weight:600;">Rp ${estMonthly.toLocaleString('id-ID')}</div>
        <div style="font-size:.58rem;color:#9CA3AF;">${(c.total_sold||0).toLocaleString('id-ID')} terjual</div>
      </td>
      <td style="min-width:100px;">
        <div style="display:flex;align-items:center;gap:5px;">
          <div style="height:6px;width:60px;background:#F3F4F6;border-radius:3px;overflow:hidden;"><div style="height:100%;width:${barW}%;background:${tierColor};border-radius:3px;"></div></div>
          <span style="font-size:.6rem;color:${tierColor};font-weight:600;">${tierLabel}</span>
        </div>
        <div style="font-size:.56rem;color:#9CA3AF;">${sharePct.toFixed(1)}% pasar</div>
      </td>
      <td>${c.url ? `<a href="${c.url}" target="_blank" rel="noopener" onclick="event.stopPropagation()" style="font-size:.68rem;font-weight:600;color:#B5202A;text-decoration:none;white-space:nowrap;">Lihat →</a>` : '—'}</td>
    </tr>`;
  }).join('') : `<tr><td colspan="6" style="padding:20px;text-align:center;color:#9CA3AF;font-size:.72rem;">Data kompetitor akan muncul setelah keyword dimuat.</td></tr>`;
  const btn = document.getElementById('dd-show-more-btn');
  if (btn) {
    const showing = _ddCompShowing >= _ddCompAll.length;
    btn.innerHTML = showing
      ? `<svg width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path d="M18 15l-6-6-6 6"/></svg> Sembunyikan`
      : `<svg width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path d="M6 9l6 6 6-6"/></svg> Lihat Semua ${_ddCompAll.length} Kompetitor`;
  }
}

function ddToggleCompetitors() {
  _ddCompShowing = _ddCompShowing >= _ddCompAll.length ? 5 : _ddCompAll.length;
  ddRenderCompetitors();
}

// dscOpenDeepDive defined above (uses item_id__shop_id key from _dscAllListings)

// ── TRACKER (alerts hub) ───────────────────────────────────────
const CHART_COLORS = ['#B5202A','#4F46E5','#10B981','#F59E0B','#EC4899','#06B6D4'];
const TRK_SALES_ALERT_PCT = 5;
function _trkFmtScrapeDate(iso) {
  if (!iso) return '—';
  try {
    return new Date(iso).toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' });
  } catch { return '—'; }
}

/* ───────────────────────────────────────────────────────────────────────────
   Daily keyword/store tracking — Site A host for the shared LarisTracker module.

   The module owns every pixel and all screen state. This adapter only supplies
   data callbacks (which own the Supabase client) and app-local services
   (formatters, toast, navigation). Same split as the daily spin wheel.
   ────────────────────────────────────────────────────────────────────────── */

let _trkFreeDive = false;     // one-shot: exempt the next deep dive from _useDive
let _trkAdapterObj = null;
// Same shape as LFD_PENDING_KEY/lfdReplayPending above — the shared tracker
// module's commit() calls adapter.savePendingDraft() right before a login
// gate would otherwise wipe an in-progress wizard (picked keywords/stores).
const LTK_PENDING_KEY = '_lid_tracker_pending_v1';

// switchDashView('tracker') entry point. The module renders the whole view,
// including its own Keyword/Toko scope tabs — Site A used to wrap it in a
// second, outer tab row that said the same thing twice, plus a legacy
// per-product alert pane that predated it. Both are gone; A and B now show the
// identical tracker.
function trkOpen(resumeDraft) {
  if (!window.LarisTracker) return;
  window.LarisTracker.mount({ hostId: 'laris-tracker-root', site: 'a', adapter: trkAdapter() });
  const p = window.LarisTracker.open({ touch: true });
  if (resumeDraft) {
    Promise.resolve(p).then(() => {
      try { window.LarisTracker.resumeDraft(resumeDraft); } catch (_) {}
    });
  }
  try { logUserEvent('tracker_tab', { tab: 'keyword', ui: 'A' }); } catch (_) {}
}

function ltkReplayPending() {
  if (!currentUser) return;
  let draft = null;
  try { draft = JSON.parse(localStorage.getItem(LTK_PENDING_KEY) || 'null'); } catch (_) {}
  if (!draft) return;
  try { localStorage.removeItem(LTK_PENDING_KEY); } catch (_) {}
  switchDashView('tracker');
  trkOpen(draft);
}

// ── Deep-dive side panel ─────────────────────────────────────────────────────
// Kalkulator / Kompetitor / Serupa live in a persistent right rail instead of the
// tab strip. Same module contract as LarisTracker: the module owns its pixels,
// we hand it services and data through an adapter and never let it reach into
// app globals.
let _lspAdapterObj = null;

function lspAdapter() {
  if (_lspAdapterObj) return _lspAdapterObj;
  _lspAdapterObj = {
    esc: wsdEsc,
    fmtRp: _dscFmtRpFull,
    fmtRpShort: fmtShort,
    fmtSold: (n) => fmtShort(n || 0),
    toast: showCompareToast,
    track(evt, props) { try { logUserEvent(evt, Object.assign({ ui: 'A' }, props || {})); } catch (_) {} },

    getProduct() { return _ddCurrentP || _ddKwListing || null; },
    // The deep dive has usually already loaded the keyword's peer set for the
    // Kompetitor tab; reuse it rather than re-querying.
    getPeers() { return Array.isArray(_ddKwRows) ? _ddKwRows : []; },
    async fetchPeers(keyword) {
      if (!_supabase || !keyword) return [];
      const { data, error } = await _supabase
        .from('listings_deduped')
        .select('item_id,shop_id,product_name,store_name,price,total_sold,reviews,rating,location,image_url,keyword,category,listing_date')
        .ilike('keyword', `%${String(keyword).slice(0, 40)}%`)
        .gt('total_sold', 0)
        .order('total_sold', { ascending: false })
        .limit(60);
      if (error) throw error;
      return data || [];
    },
    openProduct(p) {
      if (!p || !p.item_id) return;
      try { dscOpenDeepDive(`${p.item_id}__${p.shop_id}`); } catch (_) {}
    },
  };
  return _lspAdapterObj;
}

function ddOpenTool(mode) {
  if (!window.LarisSidePanel) return;
  window.LarisSidePanel.mount({ hostId: 'laris-side-panel-root', site: 'a', adapter: lspAdapter() });
  window.LarisSidePanel.setProduct(lspAdapter().getProduct());
  window.LarisSidePanel.open(mode);
}

// ── Two-level category picker ────────────────────────────────────────────────
// Taxonomy comes from the DB (category_map + keyword_subgroup), not a hardcoded
// list — that is the whole point of those tables, and Site A was the one arm
// still not reading them, so its category names could drift from Site B and SQL.
const LCP_CANON_CACHE_KEY = '_lid_canon_cats_v1';
let _lcpSubCache = Object.create(null);

async function lcpLoadCategories() {
  try {
    const cached = JSON.parse(localStorage.getItem(LCP_CANON_CACHE_KEY) || 'null');
    if (cached && cached.ts && Date.now() - cached.ts < 864e5 && Array.isArray(cached.cats) && cached.cats.length) {
      return cached.cats;
    }
  } catch (_) {}
  if (!_supabase) return [];
  const { data, error } = await _supabase
    .from('category_map').select('canonical,sort_order').order('sort_order', { ascending: true });
  if (error) return [];
  const seen = new Set(); const cats = [];
  (data || []).forEach(r => { if (r.canonical && !seen.has(r.canonical)) { seen.add(r.canonical); cats.push(r.canonical); } });
  try { localStorage.setItem(LCP_CANON_CACHE_KEY, JSON.stringify({ ts: Date.now(), cats })); } catch (_) {}
  return cats;
}

async function lcpLoadSubgroups(cat) {
  if (!cat) return [];
  if (_lcpSubCache[cat]) return _lcpSubCache[cat];
  if (!_supabase) return [];
  const { data, error } = await _supabase
    .from('keyword_subgroup').select('subgroup').eq('canonical', cat);
  if (error) return [];
  const seen = new Set(); const out = [];
  (data || []).forEach(r => { if (r.subgroup && !seen.has(r.subgroup)) { seen.add(r.subgroup); out.push(r.subgroup); } });
  out.sort((a, b) => a.localeCompare(b, 'id'));
  _lcpSubCache[cat] = out;
  return out;
}

// ── Landing finder ───────────────────────────────────────────────────────────
// Four steps: kota, kategori, modal, pengalaman. Only kota + kategori gate the
// CTA. Budget is deliberately optional: A CUT its post-signup budget step on
// 2026-07-09 because it was the #1 skip point (17 skips/30d, 3 of the last 4
// signups bailed there) — asking about money read like a payment question. This
// finder is pre-signup and pre-search rather than post-signup onboarding, and B
// sees 74% completion with it present, so it stays — but as a refinement the
// user can walk past, never a gate.
const LFD_PENDING_KEY = '_lid_finder_pending_v1';

function lfdMount() {
  if (!window.LarisFinder || !document.getElementById('laris-finder-root')) return;
  window.LarisFinder.mount({
    hostId: 'laris-finder-root',
    site: 'A',
    adapter: {
      esc: wsdEsc,
      track(evt, props) { try { logUserEvent(evt, props || {}); } catch (_) {} },
      cities() {
        try { return Object.keys(ADM_MAP_CITY_COORDS).sort((a, b) => a.localeCompare(b, 'id')); }
        catch (_) { return []; }
      },
      categories: lcpLoadCategories,
      onSubmit(ans) { lfdSubmit(ans); },
    },
  });
}

// Anonymous visitors cannot reach Discover, so park the answers and replay them
// once they are signed in — the same shape as arm B's pendingFinder.
function lfdSubmit(ans) {
  try { localStorage.setItem(LFD_PENDING_KEY, JSON.stringify(ans || {})); } catch (_) {}
  if (!currentUser) { openAuthModal('signup', 'finder'); return; }
  lfdApply(ans);
}

function lfdApply(ans) {
  if (!ans) return;
  try { localStorage.removeItem(LFD_PENDING_KEY); } catch (_) {}
  try {
    switchDashView('discover');
    // NOTE: the city answer is captured and logged but NOT applied as a filter —
    // A's Discover has no location filter to apply it to (dscFetchPage filters on
    // category, price, omset and score only). Wiring one is a separate change;
    // silently dropping the answer here would be less honest than saying so.
    const box = document.getElementById('dsc-search');
    if (box) box.value = '';
    _dscCommittedQ = '';
    if (ans.category) dscPickCategory(ans.category);
    else dscTerapkanFilter();
    if (window.LarisCatPicker && ans.category) window.LarisCatPicker.setCategory(ans.category);
  } catch (_) {}
}

function lfdReplayPending() {
  if (!currentUser) return;
  let ans = null;
  try { ans = JSON.parse(localStorage.getItem(LFD_PENDING_KEY) || 'null'); } catch (_) {}
  if (ans && (ans.city || ans.category)) lfdApply(ans);
}

// ── Trending card ─────────────────────────────────────────────────────────────
// Ported from Site B verbatim math (growth is baseline-relative, not WoW — the
// scrape cadence can't support true week-over-week for most rows). Lives on the
// Dashboard, right after "Yang Laku dari Kotamu".
let _ltrAdapterObj = null;

function ltrAdapter() {
  if (_ltrAdapterObj) return _ltrAdapterObj;
  _ltrAdapterObj = {
    esc: wsdEsc,
    fmtRp: _dscFmtRpFull,
    fmtSold: (n) => fmtShort(n || 0),
    track(evt, props) { try { logUserEvent(evt, Object.assign({ ui: 'A' }, props || {})); } catch (_) {} },
    async fetchTrending() {
      if (!_supabase) return [];
      const { data, error } = await _supabase.from('mv_trending')
        .select('item_id,shop_id,store_name,product_name,category,keyword,price,total_sold,reviews,rating,location,image_url,url,delta_7d,delta_prev_7d,delta_14d,delta_prev_14d,delta_30d,anchor_at')
        .order('delta_7d', { ascending: false })
        .limit(300);
      if (error) throw error;
      return data || [];
    },
    openProduct(row) {
      if (!row || !row.item_id) return;
      try { dscOpenDeepDive(`${row.item_id}__${row.shop_id}`); } catch (_) {}
    },
  };
  return _ltrAdapterObj;
}

function ltrMount() {
  if (!window.LarisTrending || !document.getElementById('laris-trending-root')) return;
  window.LarisTrending.mount({ hostId: 'laris-trending-root', site: 'a', adapter: ltrAdapter() });
}

function lcpMount() {
  if (!window.LarisCatPicker || !document.getElementById('laris-catpicker-root')) return;
  window.LarisCatPicker.mount({
    hostId: 'laris-catpicker-root',
    site: 'A',
    adapter: {
      esc: wsdEsc,
      track(evt, props) { try { logUserEvent(evt, props || {}); } catch (_) {} },
      loadCategories: lcpLoadCategories,
      loadSubgroups: lcpLoadSubgroups,
      // Category maps onto the existing checkbox filter so one code path still
      // owns "what is being filtered". Sub-group has no filter column behind it,
      // so it rides the search box — which now shares arm B's query planner.
      onChange({ category, subgroup }) {
        try {
          if (!category) { dscResetFilters(); return; }
          const box = document.getElementById('dsc-search');
          if (box) box.value = subgroup || '';
          _dscCommittedQ = subgroup || '';
          dscPickCategory(category);
        } catch (_) {}
      },
    },
  });
}

function trkAdapter() {
  if (_trkAdapterObj) return _trkAdapterObj;
  const rpc = async (name, params) => {
    if (!_supabase) return null;
    const { data, error } = await _supabase.rpc(name, params || {});
    if (error) throw error;
    return data;
  };
  _trkAdapterObj = {
    // ── services ──────────────────────────────────────────────────────────
    esc:        wsdEsc,
    fmtRp:      _dscFmtRpFull,
    fmtRpShort: fmtShort,
    fmtUnits:   trkUnits,
    fmtDate:    _trkFmtScrapeDate,
    toast:      showCompareToast,
    isAuthed() { return !!currentUser; },
    requireAuth() {
      if (currentUser) return true;
      try { openAuthModal('login'); } catch (_) {}
      return false;
    },
    savePendingDraft(snapshot) {
      try { localStorage.setItem(LTK_PENDING_KEY, JSON.stringify(snapshot || {})); } catch (_) {}
    },
    track(evt, props) { try { logUserEvent(evt, props || {}); } catch (_) {} },
    openProduct(row) {
      if (!row || !row.item_id) return;
      // Tracked-origin opens are free — see the _trkFreeDive comment in
      // dscOpenDeepDive. Flag is consumed there, so it can never leak into an
      // unrelated open.
      _trkFreeDive = true;
      try { dscOpenDeepDive(`${row.item_id}__${row.shop_id}`); }
      catch (e) { _trkFreeDive = false; showCompareToast('Gagal membuka produk'); }
    },
    openDiscovery(cat) {
      try { if (cat) dscPickCategory(cat); } catch (_) {}
      switchDashView('discover');
    },
    openHowCalculated() {
      showCompareToast('Angka di atas perkiraan dari data scrape harian kami.');
    },

    // ── data ──────────────────────────────────────────────────────────────
    getTracking()               { return rpc('get_my_tracking'); },
    // Reads mv_keyword_daily / mv_shop_daily, which aggregate `listings`
    // directly. get_tracker_deltas is kept only for clients cached before this
    // shipped — it reads listing_deltas, which the daily scrape never refreshes.
    getRollup(days, scope)      { return rpc('get_tracker_rollup', { p_days: days, p_scope: scope || 'keyword' }); },
    getDeltas(days)             { return rpc('get_tracker_deltas', { p_days: days }); },
    // Dense daily series — same RPCs Site B uses. De-overlaps sparse scrape
    // buckets and fills gaps from the velocity nowcast so pantauan charts
    // and omset/unit headlines never disagree.
    async getKeywordSeries(keyword, days) {
      if (!keyword || !_supabase) return [];
      try {
        const to = new Date();
        const from = new Date(to.getTime() - (Number(days) || 14) * 86400000);
        const iso = d => new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString().slice(0, 10);
        const { data, error } = await _supabase.rpc('keyword_daily_series', {
          p_keyword: String(keyword).trim().toLowerCase(),
          p_from: iso(from), p_to: iso(to),
        });
        if (error) throw error;
        return data || [];
      } catch (_) { return []; }
    },
    async getStoreSeries(shopId, days) {
      if (shopId == null || !_supabase) return [];
      try {
        const to = new Date();
        const from = new Date(to.getTime() - (Number(days) || 14) * 86400000);
        const iso = d => new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString().slice(0, 10);
        const { data, error } = await _supabase.rpc('store_daily_series', {
          p_shop_id: Number(shopId),
          p_from: iso(from), p_to: iso(to),
        });
        if (error) throw error;
        return data || [];
      } catch (_) { return []; }
    },
    touchViewed()               { return rpc('touch_tracker_viewed'); },
    addKeyword(kw, cat)         { return rpc('add_tracked_keyword', { p_keyword: kw, p_category: cat || '' }); },
    addStore(shopId, name)      { return rpc('add_tracked_store', { p_shop_id: shopId, p_store_name: name || '' }); },
    getStoresByCategory(cat)    { return rpc('find_shops_by_category', { p_category: cat, p_limit: 30 }); },
    removeKeyword(id)           { return rpc('remove_tracked_keyword', { p_id: id }); },
    setMetrics(list)            { return rpc('set_tracker_metrics', { p_metrics: list }); },
    async getStoreInfo(shopId) {
      if (!_supabase || shopId == null) return null;
      // Head-count only: we want the SKU number, not the rows.
      const { count } = await _supabase.from('listings_latest')
        .select('item_id', { count: 'exact', head: true }).eq('shop_id', shopId);
      const { data } = await _supabase.from('listings_latest')
        .select('store_name').eq('shop_id', shopId).limit(1);
      return { store_name: (data && data[0] && data[0].store_name) || '', n_products: count ?? null };
    },
    removeStore(id)             { return rpc('remove_tracked_store', { p_id: id }); },

    async getCategories() {
      try { await dscLoadCanonicalCats(); } catch (_) {}
      return (DSC_CANON_CATS && DSC_CANON_CATS.length) ? DSC_CANON_CATS : DSC_ALL_CATS;
    },

    async getCategoryKeywords(cat, limit) {
      if (!_supabase) return [];
      const { data } = await _supabase
        .from('product_types_v')
        .select('keyword,category,n_sellers,price_median,total_sold_sum,rep_image_url')
        .eq('city', 'ALL').eq('category', cat)
        .gte('n_listings', 3)
        .order('omset_top15', { ascending: false })
        .limit(limit || 24);
      return data || [];
    },

    async getSeedCandidates() {
      const out = { fromTracked: [], categories: [] };
      if (!_supabase || !currentUser) return out;
      try {
        const { data } = await _supabase.from('user_tracked_products')
          .select('keyword,category').eq('user_id', currentUser.id)
          .order('tracked_at', { ascending: false }).limit(20);
        (data || []).forEach(r => { if (r.keyword) out.fromTracked.push({ keyword: r.keyword, category: r.category || '' }); });
      } catch (_) {}
      try {
        await nuOnbHydratePrefs();
        if (_nuOnb && _nuOnb.cats && _nuOnb.cats.length) out.categories = _nuOnb.cats.slice(0, 4);
      } catch (_) {}
      return out;
    },

    // Typeahead over product types. Category is a filter, not a prerequisite —
    // an empty category searches everything.
    async searchKeywords(o) {
      const q = String(o?.q || '').trim();
      if (!_supabase || !q) return [];
      let sel = _supabase
        .from('product_types_v')
        .select('keyword,category,category_canonical,n_sellers,price_median,n_listings,rep_image_url,total_sold_sum')
        .eq('city', 'ALL')
        .gte('n_listings', 3)
        .ilike('keyword', `%${q.slice(0, 40)}%`)
        .order('omset_top15', { ascending: false, nullsFirst: false })
        .limit(o?.limit || 8);
      if (o?.category) sel = sel.eq('category_canonical', o.category);
      const { data } = await sel;
      return data || [];
    },

    async searchStores(q) {
      if (!_supabase || !q) return [];
      // find_shops_by_name is trigram-ranked over the 130k-row mv_shops; the
      // old ilike scan of listings_latest returned 60 rows to dedupe client-side.
      const { data, error } = await _supabase.rpc('find_shops_by_name', { p_q: q, p_limit: 8 });
      if (error || !data) return [];
      return (data || []).map(r => ({
        shop_id: r.shop_id,
        store_name: r.store_name || `Toko ${r.shop_id}`,
        n_products: r.n_listings,
      }));
    },

    async getFallbackMovers(cats, n) {
      if (!_supabase) return [];
      let q = _supabase.from('mv_trending')
        .select('item_id,shop_id,product_name,image_url,price,keyword,category,delta_7d,store_name')
        .order('delta_7d', { ascending: false }).limit(n || 8);
      if (cats && cats.length) q = q.in('category', cats);
      const { data } = await q;
      if (data && data.length) return data;
      // Last resort so the fall-through is never itself empty.
      try {
        await _dscEnsureBrowsePool(60);
        return (_dscPickFallback(n || 8) || []).map(l => ({
          item_id: l.item_id, shop_id: l.shop_id, product_name: l.product_name,
          image_url: l.image_url, price: l.price, keyword: l.keyword,
          category: l.category, delta_7d: 0, store_name: l.store_name,
        }));
      } catch (_) { return []; }
    },

    async getKeywordBaseline(keywords) {
      if (!_supabase || !keywords || !keywords.length) return [];
      const { data } = await _supabase.from('product_types_v')
        .select('keyword,n_sellers,price_median,rep_product_name,rep_image_url')
        .eq('city', 'ALL').in('keyword', keywords).limit(20);
      return (data || []).map(r => ({
        keyword: r.keyword, n_sellers: r.n_sellers, price_median: r.price_median,
        top_name: r.rep_product_name, top_image: r.rep_image_url,
      }));
    },
    async getShopLogoCache(shopIds) {
      if (!_supabase || !shopIds || !shopIds.length) return [];
      const { data } = await _supabase.from('shop_logo_cache')
        .select('shop_id,logo_url,fetched_at')
        .in('shop_id', shopIds);
      return data || [];
    },
    async fetchShopLogo(shopId) {
      if (!_supabase || shopId == null) return null;
      const { data, error } = await _supabase.functions.invoke('get-shop-logo', {
        body: { shop_id: Number(shopId) },
      });
      if (error) throw error;
      return data;
    },
    async getStoreOldestListingDates(shopIds) {
      if (!_supabase || !shopIds || !shopIds.length) return {};
      const { data } = await _supabase.from('listings_deduped')
        .select('shop_id,listing_date')
        .in('shop_id', shopIds)
        .not('listing_date', 'is', null);
      const out = {};
      (data || []).forEach(r => {
        if (r.shop_id == null || !r.listing_date) return;
        const key = String(r.shop_id);
        if (!out[key] || r.listing_date < out[key]) out[key] = r.listing_date;
      });
      return out;
    },
  };
  return _trkAdapterObj;
}



// ── DASHBOARD ──────────────────────────────────────────────────
let _hbdChartPerf = null, _hbdTab = 'growth';

function _hbdRng(seed) {
  let s = seed;
  return function() { s = (s * 1664525 + 1013904223) & 0xffffffff; return (s >>> 0) / 0xffffffff; };
}

function hbdSetTab(btn, tab) {
  document.querySelectorAll('.hbd-tab').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  _hbdTab = tab;
  hbdInit();
}

function _hbdBuildChart() {
  void (async function () {
  await larisEnsureChart();
  if (!allProducts || !allProducts.length) return;
  const prods = allProducts.slice(0, 5);
  const weeks = ['M1','M2','M3','M4','M5','M6','M7','M8','M9','M10','M11','M12'];
  const datasets = prods.map((p, ci) => {
    const rng = _hbdRng(p.id * (ci+1) * 777);
    let data;
    if (_hbdTab === 'growth') {
      const base = 40 + rng()*30;
      data = weeks.map(() => Math.max(5, Math.round(base + (rng()-0.3)*25)));
    } else if (_hbdTab === 'price') {
      const base = p.medianPrice || 85000;
      data = weeks.map(() => Math.round(base * (0.9 + rng()*0.2)));
    } else {
      data = weeks.map(() => Math.round(30 + rng()*60));
    }
    return {
      label: p.name.split(' ').slice(0,2).join(' '),
      data,
      borderColor: CHART_COLORS[ci],
      backgroundColor: 'transparent',
      borderWidth: 2,
      tension: 0.4,
      pointRadius: 2,
      pointBackgroundColor: CHART_COLORS[ci],
    };
  });
  if (_hbdChartPerf) _hbdChartPerf.destroy();
  _hbdChartPerf = new Chart(document.getElementById('hbd-chart-perf'), {
    type: 'line',
    data: { labels: weeks, datasets },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: { legend: { display: false } },
      scales: {
        x: { ticks: { font: { size: 9 } } },
        y: { ticks: { font: { size: 9 }, callback: v => _hbdTab==='price' ? 'Rp'+(v/1000).toFixed(0)+'rb' : v } }
      },
      animation: { duration: 300 }
    }
  });
  document.getElementById('hbd-legend').innerHTML = prods.map((p,ci) =>
    `<div class="trk-legend-item"><div class="trk-legend-dot" style="background:${CHART_COLORS[ci]}"></div>${p.name.split(' ').slice(0,2).join(' ')}</div>`
  ).join('');
  })();
}

async function hbdInit() {
  const tracked = trkLoad();

  if (!tracked.length) {
    document.getElementById('hbd-subtitle').textContent = 'Selamat datang — mulai riset produk pertamamu hari ini.';
    nuRefreshView('dashboard');
    void journeyRenderReturnStrip();
    void hbdRenderCohortDigest();
    if (_supabase && currentUser && typeof cohortInit === 'function') cohortInit().catch(() => {}).finally(() => { _syncDashboardRoleLayout(); nuRefreshView('dashboard'); });
    else { void hbdRenderMentorDigest(); _syncDashboardRoleLayout(); nuRefreshView('dashboard'); }
    return;
  }

  const nuPanel = document.getElementById('hbd-new-user-panel');
  if (nuPanel) nuPanel.style.display = 'none';
  const leaderMode = _effectiveLeaderMode();
  if (!leaderMode) {
    ['hbd-stats-row','hbd-product-opp-col','hbd-trending-section'].forEach(id => {
      const el = document.getElementById(id);
      if (el) el.style.display = '';
    });
  }

  document.getElementById('hbd-subtitle').textContent = leaderMode
    ? 'Pantau progres siswa dan aktivitas kohort kamu.'
    : 'Berikut ringkasan produk kamu hari ini.';

  // Fetch last 2 scrape rows per tracked product
  const enriched = await Promise.all(tracked.map(async t => {
    try {
      const { data } = await _supabase
        .from('listings')
        .select('total_sold, price, scraped_at')
        .eq('item_id', t.item_id)
        .eq('shop_id', t.shop_id)
        .order('scraped_at', { ascending: false })
        .limit(2);
      const curr = data?.[0];
      const prev = data?.[1];
      const delta = (curr && prev) ? Math.max(0, (curr.total_sold||0) - (prev.total_sold||0)) : 0;
      return { ...t, curr_sold: curr?.total_sold||t.total_sold||0, curr_price: curr?.price||t.price||0, delta, scraped_at: curr?.scraped_at };
    } catch { return { ...t, curr_sold: t.total_sold||0, curr_price: t.price||0, delta: 0 }; }
  }));

  const count    = enriched.length;
  const avgPrice = enriched.reduce((s,p) => s + (p.curr_price||0), 0) / count;
  const totalOmset = enriched.reduce((s,p) => s + ((p.curr_price||0) * (p.curr_sold||0) / 6), 0);
  const nUp      = enriched.filter(p => p.delta > 0).length;

  document.getElementById('hbd-s1').textContent = count;
  document.getElementById('hbd-s1-sub').textContent = 'produk terpantau';
  document.getElementById('hbd-s2').textContent = 'Rp ' + Math.round(avgPrice).toLocaleString('id-ID');
  document.getElementById('hbd-s2-sub').textContent = 'rata-rata harga produk';
  document.getElementById('hbd-s3').textContent = totalOmset >= 1e6 ? 'Rp ' + (totalOmset/1e6).toFixed(1) + ' jt' : 'Rp ' + Math.round(totalOmset).toLocaleString('id-ID');
  document.getElementById('hbd-s3-sub').textContent = 'estimasi omset/bln';
  document.getElementById('hbd-s4').textContent = nUp;
  document.getElementById('hbd-s4-sub').textContent = 'produk tren naik';

  // (Insight AI card removed from dashboard — no hbd-ai-list to populate)

  // Recent tracked products as activity
  document.getElementById('hbd-activity-list').innerHTML = enriched.slice(0,6).map(p => {
    const name = (p.product_name||'').split(' ').slice(0,3).join(' ') || p.keyword;
    const upSvg = `<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="18 15 12 9 6 15"/></svg>`;
    const flatSvg = `<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><line x1="5" y1="12" x2="19" y2="12"/></svg>`;
    const cls = p.delta > 0 ? 'up' : 'info';
    return `<div class="hbd-activity-item">
      <div class="hbd-act-icon ${cls}">${p.delta>0?upSvg:flatSvg}</div>
      <div class="hbd-act-body">
        <div class="hbd-act-title">${name}</div>
        <div class="hbd-act-desc">${p.delta>0?'+'+p.delta+' unit sejak scrape terakhir':'Belum ada perubahan unit'}</div>
      </div>
      <div class="hbd-act-time">${(p.category||'').split(' ')[0]||'—'}</div>
    </div>`;
  }).join('');

  // Opportunities: products with highest delta
  const oppProds = [...enriched].sort((a,b) => b.delta - a.delta).slice(0,6);
  document.getElementById('hbd-opp-list').innerHTML = oppProds.map(p => {
    const name = (p.product_name||'').split(' ').slice(0,4).join(' ') || p.keyword;
    const hot = p.delta > 0;
    return `<div class="hbd-opp-item">
      <img src="${p.image_url||''}" onerror="this.style.display='none'" style="width:32px;height:32px;object-fit:cover;border-radius:6px;flex-shrink:0;">
      <div class="hbd-opp-body">
        <div class="hbd-opp-name">${name}</div>
        <div class="hbd-opp-cat">${p.category||p.keyword||'—'}</div>
      </div>
      <span class="hbd-opp-badge ${hot?'hot':'ok'}">${hot?'▲ +'+p.delta:'Stabil'}</span>
    </div>`;
  }).join('');

  // ── Tracked product visual strip ──────────────────────────
  const trackedStrip = document.getElementById('hbd-tracked-strip');
  const trackedCards = document.getElementById('hbd-tracked-cards');
  if (!leaderMode && trackedStrip && trackedCards && enriched.length) {
    trackedStrip.style.display = 'block';
    const fmtRp = v => 'Rp ' + Math.round(v||0).toLocaleString('id-ID');
    trackedCards.innerHTML = enriched.slice(0, 8).map(p => {
      const name = (p.product_name||'').split(' ').slice(0,3).join(' ') || p.keyword || '—';
      const priceDelta = p.curr_price - (p.price || p.curr_price);
      const deltaChip = p.delta > 0
        ? `<span style="background:#ECFDF5;color:#16A34A;font-size:.65rem;font-weight:700;padding:2px 6px;border-radius:10px;">▲ ${p.delta}</span>`
        : priceDelta < -500
          ? `<span style="background:#FFF7ED;color:#C2410C;font-size:.65rem;font-weight:700;padding:2px 6px;border-radius:10px;">↓ harga</span>`
          : `<span style="background:#F9FAFB;color:#9CA3AF;font-size:.65rem;padding:2px 6px;border-radius:10px;">Stabil</span>`;
      return `<div style="flex-shrink:0;width:120px;background:#fff;border:1px solid #E5E7EB;border-radius:10px;overflow:hidden;cursor:pointer;" onclick="switchDashView('tracker')">
        <div style="height:80px;background:#F3F4F6;overflow:hidden;">
          <img src="${p.image_url||''}" onerror="this.style.display='none'" style="width:100%;height:100%;object-fit:cover;">
        </div>
        <div style="padding:8px;">
          <div style="font-size:.7rem;font-weight:600;color:#111;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-bottom:4px;">${name}</div>
          <div style="font-size:.68rem;color:#6B7280;margin-bottom:4px;">${fmtRp(p.curr_price)}</div>
          ${deltaChip}
        </div>
      </div>`;
    }).join('');
  }

  // ── Price-change alert strip ───────────────────────────────
  const alertStrip = document.getElementById('hbd-alerts-strip');
  if (!leaderMode && alertStrip) {
    const bigChanges = enriched.filter(p => {
      const pricePct = p.price > 0 ? Math.abs((p.curr_price - p.price) / p.price * 100) : 0;
      const soldPct  = p.total_sold > 0 ? Math.abs(p.delta / p.total_sold * 100) : 0;
      return pricePct > 10 || soldPct > 20;
    });
    if (bigChanges.length) {
      alertStrip.style.display = 'block';
      alertStrip.innerHTML = bigChanges.slice(0,3).map(p => {
        const name = (p.product_name||'').split(' ').slice(0,4).join(' ') || p.keyword;
        const pricePct = p.price > 0 ? ((p.curr_price - p.price) / p.price * 100).toFixed(0) : 0;
        const msg = p.delta > 0 ? `Penjualan naik +${p.delta} unit` : `Harga berubah ${pricePct > 0 ? '+' : ''}${pricePct}%`;
        const color = p.delta > 0 ? '#16A34A' : '#C2410C';
        return `<div style="display:flex;align-items:center;gap:10px;background:#fff;border:1px solid #E5E7EB;border-left:3px solid ${color};border-radius:8px;padding:10px 14px;font-size:.78rem;">
          <img src="${p.image_url||''}" onerror="this.style.display='none'" style="width:28px;height:28px;border-radius:5px;object-fit:cover;flex-shrink:0;">
          <div><strong>${name}</strong> — ${msg}</div>
        </div>`;
      }).join('');
    }
  }

  // ── Trending for you from allProducts ─────────────────────
  // Must open Deep Dive (hbdNuRecoOpenById) — openDetail targets the removed
  // legacy #page-detail and looks like a dead click inside the dashboard.
  const trendingCards = document.getElementById('hbd-trending-cards');
  if (!leaderMode && trendingCards && allProducts.length) {
    const trending = [...allProducts]
      .sort((a, b) => (b.avgTrend || 0) - (a.avgTrend || 0) || (b.score || 0) - (a.score || 0) || (b.total_sold || 0) - (a.total_sold || 0))
      .slice(0, 6);
    trendingCards.innerHTML = trending.map(p => {
      const scoreColor = p.score >= 70 ? '#16A34A' : p.score >= 45 ? '#B45309' : '#C0392B';
      return `<div style="background:#fff;border:1px solid #E5E7EB;border-radius:10px;overflow:hidden;cursor:pointer;" role="button" tabindex="0" onclick="hbdNuRecoOpenById(${p.id})" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();hbdNuRecoOpenById(${p.id});}">
        <div style="height:80px;background:#F3F4F6;position:relative;overflow:hidden;">
          <img src="${p.image||''}" onerror="this.style.display='none'" style="width:100%;height:100%;object-fit:cover;" alt="">
          <span style="position:absolute;top:6px;right:6px;background:${scoreColor};color:#fff;font-size:.6rem;font-weight:800;padding:2px 6px;border-radius:8px;">${p.score}</span>
        </div>
        <div style="padding:8px;">
          <div style="font-size:.7rem;font-weight:600;color:#111;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${p.name||'—'}</div>
          <div style="font-size:.65rem;color:#6B7280;margin-top:2px;">↑ Trending · ${p.category||'—'}</div>
        </div>
      </div>`;
    }).join('');
  }

  const tips = [
    'Lacak lebih banyak produk untuk mendapatkan analisis yang lebih akurat.',
    'Produk dengan delta penjualan tinggi adalah kandidat bagus untuk mulai berjualan.',
    'Coba gunakan Kalkulator Profit di halaman Mulai Berjualan untuk menghitung kelayakan.',
  ];
  void tips;

  // Build chart with tracked products (dashboard chart section hidden)
  const prods = enriched.slice(0,6).map(p => ({
    name: (p.product_name||p.keyword||'').split(' ').slice(0,3).join(' '),
    delta: p.delta || 0,
    price: p.curr_price || 0,
    sold:  p.curr_sold  || 0,
  }));
  _hbdBuildChartFromTracked(prods);
  void hbdRenderCohortDigest();
  const _finishHbdLayout = () => { _syncDashboardRoleLayout(); nuRefreshView('dashboard'); };
  if (_supabase && currentUser && typeof cohortInit === 'function') cohortInit().catch(() => {}).finally(_finishHbdLayout);
  else { void hbdRenderMentorDigest(); _finishHbdLayout(); }
}

async function hbdRenderMentorDigest() {
  const wrap = document.getElementById('hbd-mentor-wrap');
  if (!wrap || !_supabase || !currentUser) return;
  if (_effectiveIndependentMode()) { wrap.style.display = 'none'; return; }
  if (!_cohortState || !_cohortState.hasMentorCohort || !_cohortState.primaryMentorCohort) {
    wrap.style.display = 'none';
    return;
  }
  wrap.style.display = '';
  const c = _cohortState.primaryMentorCohort;
  const nameEl = document.getElementById('hbd-mentor-cohort-name');
  const statsEl = document.getElementById('hbd-mentor-stats');
  const inacEl = document.getElementById('hbd-mentor-inactive-list');
  const feedEl = document.getElementById('hbd-mentor-feed-list');
  if (nameEl) nameEl.textContent = c.name || 'Kohort';
  const since7d = new Date(Date.now() - 7 * 86400000).toISOString();
  const [{ data: members }, { data: recent }] = await Promise.all([
    _supabase.from('cohort_members').select('user_id,role,status,last_seen_at').eq('cohort_id', c.id).eq('status', 'active'),
    _supabase.from('activity_events').select('user_id').eq('cohort_id', c.id).gte('created_at', since7d),
  ]);
  const studs = (members || []).filter(m => m.role === 'student');
  const activeSet = new Set((recent || []).map(r => r.user_id));
  const inactive = studs.filter(s => !activeSet.has(s.user_id));
  await cohortLoadMemberNames(c.id);
  if (statsEl) statsEl.innerHTML = `<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:8px;">
    <div style="background:#F9FAFB;border-radius:8px;padding:10px;text-align:center;"><div style="font-size:1.3rem;font-weight:900;color:#111;">${studs.length}</div><div class="cohort-muted" style="font-size:.6rem;">Siswa</div></div>
    <div style="background:${inactive.length?'#FEF2F0':'#F0FDF4'};border-radius:8px;padding:10px;text-align:center;"><div style="font-size:1.3rem;font-weight:900;color:${inactive.length?'#C0392B':'#1A7A46'};">${inactive.length}</div><div class="cohort-muted" style="font-size:.6rem;">Perlu perhatian</div></div>
    <div style="background:#F9FAFB;border-radius:8px;padding:10px;text-align:center;"><div style="font-size:1.3rem;font-weight:900;color:#111;">${studs.length-inactive.length}</div><div class="cohort-muted" style="font-size:.6rem;">Aktif 7 hari</div></div>
  </div>`;
  if (inacEl) inacEl.innerHTML = inactive.length
    ? `<div style="font-size:.65rem;font-weight:700;color:#C0392B;margin-bottom:4px;">Tidak aktif 7 hari:</div>`
      + inactive.slice(0,5).map(s => `<div style="font-size:.72rem;padding:4px 0;border-bottom:1px solid #F3F4F6;">${_cohortEsc(cohortCohortDisplayName(s.user_id,null))}</div>`).join('')
      + (inactive.length > 5 ? `<div class="cohort-muted" style="font-size:.65rem;margin-top:4px;">+${inactive.length-5} lainnya</div>` : '')
    : '<div style="font-size:.72rem;color:#1A7A46;font-weight:700;">Semua siswa aktif minggu ini ' + wIcon('sparkles', 12) + '</div>';
  if (feedEl) {
    const { data: posts } = await _supabase.from('community_posts').select('author_id,body,kind,created_at').eq('cohort_id',c.id).gte('created_at',since7d).order('created_at',{ascending:false}).limit(6);
    const kindLbl = {win:'Menang',milestone_share:'Milestone',product_share:'Produk',general:'Umum',question:'Pertanyaan'};
    feedEl.innerHTML = (posts||[]).length ? (posts||[]).map(p =>
      `<div style="padding:6px 0;border-bottom:1px solid #F3F4F6;"><div style="display:flex;align-items:center;gap:6px;margin-bottom:2px;"><span style="font-size:.58rem;font-weight:700;text-transform:uppercase;color:#9CA3AF;">${_cohortEsc(kindLbl[p.kind]||p.kind||'')}</span><span style="font-size:.68rem;font-weight:700;color:#111;">${_cohortEsc(cohortCohortDisplayName(p.author_id,null))}</span></div><div style="font-size:.72rem;color:#374151;line-height:1.4;">${_cohortEsc((p.body||'').slice(0,90))}${(p.body||'').length>90?'…':''}</div></div>`
    ).join('') : '<div class="cohort-muted" style="font-size:.72rem;">Belum ada postingan minggu ini.</div>';
  }
}

// ── DAILY-ROTATING, PERSONALIZED RECOMMENDATIONS ────────────
// Deterministic seed from YYYY-MM-DD (local) + user id: stable within a day,
// rotates across days. NOT Math.random() so reloads on the same day are stable.
function _recDailySeed(extra) {
  const d = new Date();
  const day = d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
  const str = day + '|' + (extra || '');
  let h = 2166136261 >>> 0; // FNV-1a
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return h >>> 0;
}

// Mulberry32 PRNG seeded deterministically — used for the day-stable shuffle.
function _recRng(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function _recSeededShuffle(arr, rng) {
  const out = arr.slice();
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [out[i], out[j]] = [out[j], out[i]];
  }
  return out;
}

// Build the recommended set: blend interest-matched products (from recent
// search/browsing history) with high-score discovery picks, rotated by day.
// - recentKeywords: lowercased keywords, newest first.
// Returns up to `count` allProducts items. A fresh user (no history) still gets
// strong discovery picks; a user who searched "battery pack"/"shirt" sees those
// categories surface. The set varies day to day via the date seed.
function recBuildPersonalized(products, recentKeywords, userId, count = 5) {
  if (!products || !products.length) return [];
  const recent = (recentKeywords || []).map(k => String(k || '').toLowerCase().trim()).filter(Boolean);
  const matchScore = (p) => {
    const hay = ((p.keyword || '') + ' ' + (p.name || '') + ' ' + (p.category || '')).toLowerCase();
    for (let i = 0; i < recent.length; i++) {
      const kw = recent[i];
      if (!kw) continue;
      if (hay.includes(kw)) return recent.length - i; // recency weight
      // also match on individual significant words of the search
      const words = kw.split(/\s+/).filter(w => w.length >= 3);
      if (words.length && words.some(w => hay.includes(w))) return Math.max(1, recent.length - i - 1);
    }
    return 0;
  };

  const seed = _recDailySeed(userId || 'anon');
  const rng = _recRng(seed);

  // Interest pool: products matching recent history, best matches first, then by score.
  const interest = products
    .map(p => ({ p, m: matchScore(p) }))
    .filter(x => x.m > 0)
    .sort((a, b) => (b.m - a.m) || ((b.p.score || 0) - (a.p.score || 0)))
    .map(x => x.p);

  // Discovery pool: high-score products, day-shuffled among near-top so picks
  // rotate but stay quality. Take a wider top band then seeded-shuffle it.
  const byScore = [...products].sort((a, b) => (b.score || 0) - (a.score || 0));
  const topBand = byScore.slice(0, Math.min(byScore.length, Math.max(count * 4, 20)));
  const discovery = _recSeededShuffle(topBand, rng);

  // Blend: when history exists, fill ~60% from interest, rest from discovery.
  const out = [];
  const usedIds = new Set();
  const push = (p) => { if (p && !usedIds.has(p.id)) { usedIds.add(p.id); out.push(p); } };
  const interestTarget = recent.length ? Math.min(interest.length, Math.ceil(count * 0.6)) : 0;
  const interestRotated = _recSeededShuffle(interest.slice(0, Math.max(interestTarget * 2, interestTarget)), rng);
  for (let i = 0; i < interestRotated.length && out.length < interestTarget; i++) push(interestRotated[i]);
  for (let i = 0; i < discovery.length && out.length < count; i++) push(discovery[i]);
  // Safety fill (e.g. tiny catalog) from full score order.
  for (let i = 0; i < byScore.length && out.length < count; i++) push(byScore[i]);
  return out.slice(0, count);
}

// Open a recommended product in dashboard Deep Dive (not landing-page detail).
function hbdNuRecoOpen(p) {
  if (!p || p.item_id == null || p.shop_id == null) return;
  if (!window._dscAllListings) window._dscAllListings = [];
  let listing = _dscAllListings.find(r => String(r.item_id) === String(p.item_id) && String(r.shop_id) === String(p.shop_id));
  if (!listing) {
    listing = {
      item_id: p.item_id,
      shop_id: p.shop_id,
      product_name: p.product_name || p.name || p.keyword,
      keyword: p.keyword || p.name,
      category: p.category || 'Umum',
      image_url: p.image_url || p.image || '',
      price: p.price || p.medianPrice || 0,
      total_sold: p.total_sold || 0,
      store_name: p.store_name || '',
    };
    _dscAllListings.push(listing);
  }
  dscOpenDeepDive(`${p.item_id}__${p.shop_id}`);
}

function hbdNuRecoOpenById(id) {
  const p = (allProducts || []).find(x => x.id === id);
  if (p) hbdNuRecoOpen(p);
}

// Pick 5–6 products from the full catalog, shuffled by day (stable within a day).
function recBuildDailyRandom(products, userId, minCount = 5, maxCount = 6) {
  if (!products || !products.length) return [];
  const seed = _recDailySeed(userId || 'anon');
  const rng = _recRng(seed);
  const count = Math.min(
    minCount + Math.floor(rng() * (maxCount - minCount + 1)),
    products.length
  );
  return _recSeededShuffle(products.slice(), rng).slice(0, count);
}

// Recommended products beneath the search prompt on student/independent dashboards.
// Shows 5–6 daily-random catalog picks (new set each day).
function hbdRenderNuReco() {
  const sec  = document.getElementById('hbd-nu-reco');
  const grid = document.getElementById('hbd-nu-reco-cards');
  if (!sec || !grid) return;
  sec.style.display = '';
  if (typeof allProducts === 'undefined' || !allProducts || !allProducts.length) {
    grid.innerHTML = '<div style="grid-column:1/-1;color:#9CA3AF;font-size:.75rem;padding:8px 0;">Memuat rekomendasi...</div>';
    return;
  }
  const picks = recBuildDailyRandom(allProducts, currentUser && currentUser.id, 5, 6);
  if (!picks.length) {
    grid.innerHTML = '<div style="grid-column:1/-1;color:#9CA3AF;font-size:.75rem;padding:8px 0;">Belum ada rekomendasi.</div>';
    return;
  }
  grid.innerHTML = picks.map(p => {
    const scoreColor = p.score >= 70 ? '#16A34A' : p.score >= 45 ? '#B45309' : '#C0392B';
    const name = (p.name || p.keyword || '—');
    return `<div class="hbd-nu-reco-card" role="button" tabindex="0" onclick="hbdNuRecoOpenById(${p.id})" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();hbdNuRecoOpenById(${p.id});}">
      <div class="hbd-nu-reco-thumb">
        <img src="${p.image||''}" onerror="this.style.display='none'" alt="">
        <span class="hbd-nu-reco-score" style="background:${scoreColor};">${p.score != null ? p.score : '—'}</span>
      </div>
      <div class="hbd-nu-reco-meta">
        <div class="hbd-nu-reco-name">${name}</div>
        <div class="hbd-nu-reco-cat">Rekomendasi &middot; ${p.category||'—'}</div>
      </div>
    </div>`;
  }).join('');
}

/**
 * Beranda digest: mentor announcements + cohort activity teaser (win / milestone / product_share)
 * + recommended products — personalized to the user's recent search/browsing
 *   history and rotated daily via a date-seeded shuffle (see recBuildPersonalized).
 * Privacy: author labels via cohort_member_names RPC only; no emails; hidden posts excluded.
 */
async function hbdRenderCohortDigest() {
  const wrap = document.getElementById('hbd-cohort-digest-wrap');
  const annEl = document.getElementById('hbd-cohort-announce-list');
  const actEl = document.getElementById('hbd-cohort-activity-list');
  const recEl = document.getElementById('hbd-cohort-rec-list');
  if (!wrap || !annEl || !actEl || !recEl) return;
  if (_effectiveIndependentMode()) { wrap.style.display = 'none'; return; }
  if (!_supabase || !currentUser) {
    wrap.style.display = 'none';
    return;
  }
  const { data: mem } = await _supabase
    .from('cohort_members')
    .select('cohort_id,role,status')
    .eq('user_id', currentUser.id)
    .eq('status', 'active');
  const stu = (mem || []).find(m => m.role === 'student');
  const pcid = stu ? stu.cohort_id : null;
  if (!pcid) {
    wrap.style.display = 'none';
    return;
  }
  wrap.style.display = 'block';
  const { data: cRow } = await _supabase.from('cohorts').select('mentor_user_id,name').eq('id', pcid).maybeSingle();
  const mentorId = cRow && cRow.mentor_user_id;
  await cohortLoadMemberNames(pcid);
  const kindLbl = { win: 'Menang', milestone_share: 'Milestone', product_share: 'Produk' };
  const kindIcon = { win: wIcon('sparkles', 16), milestone_share: wIcon('flag', 16), product_share: wIcon('box', 16) };
  const [{ data: ann }, { data: postsRaw, error: postErr }] = await Promise.all([
    _supabase.from('cohort_announcements').select('title,body,created_at').eq('cohort_id', pcid).order('created_at', { ascending: false }).limit(3),
    _supabase.from('community_posts').select('body,created_at,author_id,kind,metadata').eq('cohort_id', pcid).is('hidden_at', null).in('kind', ['win', 'milestone_share', 'product_share']).order('created_at', { ascending: false }).limit(16),
  ]);
  if (postErr) console.warn('hbd cohort digest posts', postErr);
  if (!(ann || []).length) {
    annEl.innerHTML = '<div style="color:#9CA3AF;font-size:.75rem;">Belum ada pengumuman dari mentor.</div>';
  } else {
    annEl.innerHTML = (ann || []).map(a => {
      const snip = String(a.body || '').trim().slice(0, 100);
      const more = (a.body || '').length > 100 ? '…' : '';
      return `<div class="hbd-cohort-ann-item"><strong>${_cohortEsc(a.title)}</strong>${snip ? `<div class="hbd-cohort-act-snippet">${_cohortEsc(snip)}${more}</div>` : ''}<div class="hbd-cohort-ann-meta">${_cohortEsc((a.created_at || '').slice(0, 10))}</div></div>`;
    }).join('');
  }
  const postsList = [...(postsRaw || [])].sort((a, b) => {
    const aself = a.author_id === currentUser.id ? 1 : 0;
    const bself = b.author_id === currentUser.id ? 1 : 0;
    if (aself !== bself) return aself - bself;
    return new Date(b.created_at).getTime() - new Date(a.created_at).getTime();
  }).slice(0, 5);
  if (!postsList.length) {
    actEl.innerHTML = '<div style="color:#9CA3AF;font-size:.75rem;">Belum ada aktivitas (menang, milestone, bagikan produk) di feed kohort.</div>';
  } else {
    actEl.innerHTML = postsList.map(p => {
      const mine = p.author_id === currentUser.id;
      const isMentor = mentorId && p.author_id === mentorId;
      const who = mine ? 'Kamu' : (isMentor ? 'Mentor' : cohortCohortDisplayName(p.author_id, null));
      const k = p.kind || 'general';
      const meta = p.metadata || {};
      const url = meta.listing_url || meta.product_url || meta.url || '';
      const note = (meta.note || meta.jumlah || '').trim();
      const bodyShort = String(p.body || '').trim().slice(0, 88);
      const extra = url ? ' · tautan produk' : (note ? ' · ' + note.slice(0, 40) : '');
      const icon = kindIcon[k] || '•';
      const lbl = kindLbl[k] || k;
      return `<div class="hbd-activity-item">
        <div class="hbd-act-icon info" style="font-size:1rem;line-height:1;">${icon}</div>
        <div class="hbd-act-body">
          <div class="hbd-act-title">${_cohortEsc(lbl)} · ${_cohortEsc(who)}</div>
          <div class="hbd-act-desc">${_cohortEsc(bodyShort)}${(p.body || '').length > 88 ? '…' : ''}${_cohortEsc(extra)}</div>
        </div>
        <div class="hbd-act-time">${_cohortEsc((p.created_at || '').slice(0, 10))}</div>
      </div>`;
    }).join('');
  }
  let recHtml = '';
  if (typeof allProducts !== 'undefined' && allProducts && allProducts.length) {
    // Personalized + daily-rotating: bias toward the user's recent searches/opens,
    // blended with day-shuffled high-score discovery picks (recBuildPersonalized).
    let recentKw = [];
    try { recentKw = await searchHistoryRecentKeywordsRemote(12); } catch (_) { recentKw = searchHistoryRecentKeywords(12); }
    const top = recBuildPersonalized(allProducts, recentKw, currentUser && currentUser.id, 5);
    recHtml = top.map(p => {
      const name = (p.name || p.keyword || 'Produk').split(' ').slice(0, 5).join(' ') || 'Produk';
      const sc = p.score >= 70 ? 'hot' : 'ok';
      return `<div class="hbd-opp-item" role="button" tabindex="0" style="cursor:pointer;" onclick="hbdNuRecoOpenById(${p.id})" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();hbdNuRecoOpenById(${p.id});}">
        <div class="hbd-opp-emoji">${wIcon('trending-up', 18, '#B5202A')}</div>
        <div class="hbd-opp-body">
          <div class="hbd-opp-name">${_cohortEsc(name)}</div>
          <div class="hbd-opp-cat">${_cohortEsc(p.category || '—')}</div>
        </div>
        <span class="hbd-opp-badge ${sc}">${p.score != null ? p.score : '—'}</span>
      </div>`;
    }).join('');
  } else {
    const panel = await _getLatestPanelDate();
    const latestDate = panel.date;
    if (latestDate) {
      let q = _supabase.from('listings').select('keyword,category,score,image_url');
      q = _applyPanelDateFilter(q, latestDate);
      const { data: rows } = await q
        .order('score', { ascending: false })
        .limit(40);
      const seen = new Set();
      const uniq = [];
      (rows || []).forEach(r => {
        const kw = r.keyword;
        if (!kw || seen.has(kw)) return;
        seen.add(kw);
        uniq.push(r);
      });
      recHtml = uniq.slice(0, 5).map(r => {
        const hot = (r.score || 0) >= 70;
        const safeKw = JSON.stringify(String(r.keyword || ''));
        return `<div class="hbd-opp-item" onclick="openKwDetail(${safeKw})">
          <div class="hbd-opp-emoji">${wIcon('search', 18, '#B5202A')}</div>
          <div class="hbd-opp-body">
            <div class="hbd-opp-name">${_cohortEsc(r.keyword)}</div>
            <div class="hbd-opp-cat">${_cohortEsc(r.category || '—')}</div>
          </div>
          <span class="hbd-opp-badge ${hot ? 'hot' : 'ok'}">${r.score != null ? r.score : '—'}</span>
        </div>`;
      }).join('');
    }
  }
  if (!recHtml) {
    recEl.innerHTML = '<div style="color:#9CA3AF;font-size:.75rem;">Buka Discover untuk melihat produk dan keyword terbaru.</div>';
  } else {
    recEl.innerHTML = recHtml;
  }
}

function _hbdBuildChartFromTracked(prods) {
  void (async function () {
  await larisEnsureChart();
  const canvas = document.getElementById('hbd-chart-perf');
  if (!canvas || !prods.length) return;
  if (window._hbdChart) { window._hbdChart.destroy(); window._hbdChart = null; }
  const labels = prods.map(p => p.name);
  const data   = prods.map(p => p.delta);
  window._hbdChart = new Chart(canvas.getContext('2d'), {
    type: 'bar',
    data: {
      labels,
      datasets: [{ label: 'Unit Delta', data, backgroundColor: CHART_COLORS.slice(0,prods.length), borderRadius: 6 }]
    },
    options: {
      responsive: true, maintainAspectRatio: false,
      plugins: { legend: { display: false } },
      scales: { y: { beginAtZero: true, ticks: { font: { size: 10 } } }, x: { ticks: { font: { size: 10 } } } }
    }
  });
  document.getElementById('hbd-legend').innerHTML = prods.map((p,i) =>
    `<div class="trk-legend-item"><div class="trk-legend-dot" style="background:${CHART_COLORS[i]}"></div>${p.name}</div>`
  ).join('');
  })();
}

// ── MULAI BERJUALAN ────────────────────────────────────────────
const _MLS_APIKEY = 'larisid_anthropic_key';
let _mlsContext = null;   // { keyword, medianPrice, medianSold, top5 }
let _mlsChatHistory = []; // { role, content }

function mlsInit() {
  mlsUpdateModelBadge();
  _mlsAiUpdateCounter();
  const tracked = trkLoad();
  const pick = document.getElementById('mls-product-cards');
  const noTrk = document.getElementById('mls-no-tracked');
  if (!pick) return;

  // Merge tracked (localStorage) with saved (in-memory savedProducts Set backed by Supabase).
  // Build a unified list keyed by item_id_shop_id to avoid duplicates.
  const merged = new Map();
  tracked.forEach(t => {
    const k = t.key || `${t.item_id}_${t.shop_id}`;
    merged.set(k, t);
  });
  // Add saved products that aren't already tracked — pull from _dscAllListings if available
  if (savedProducts && savedProducts.size > 0 && _dscAllListings && _dscAllListings.length) {
    _dscAllListings.forEach(p => {
      if (savedProducts.has(p.item_id)) {
        const k = `${p.item_id}_${p.shop_id}`;
        if (!merged.has(k)) {
          merged.set(k, { key: k, item_id: p.item_id, shop_id: p.shop_id,
            product_name: p.product_name, store_name: p.store_name,
            image_url: p.image_url, category: p.category,
            price: p.price, total_sold: p.total_sold, keyword: p.keyword,
            tracked_at: new Date().toISOString() });
        }
      }
    });
  }
  const allPicks = [...merged.values()];

  // Clear and rebuild picker cards
  pick.innerHTML = '';
  if (!allPicks.length) {
    pick.style.display = 'none';
    if (noTrk) noTrk.style.display = 'none';
    const heroEl = document.getElementById('mls-hero');
    if (heroEl) heroEl.style.display = 'none';
    const mlsEmpty = document.getElementById('mls-empty-state');
    const mlsMain  = document.getElementById('mls-main-content');
    if (mlsEmpty) mlsEmpty.style.display = '';
    if (mlsMain)  mlsMain.style.display  = 'none';
    journeyRenderEmptyReco('mls-empty-reco', 'ai');
    return;
  }
  const mlsEmpty = document.getElementById('mls-empty-state');
  const mlsMain  = document.getElementById('mls-main-content');
  if (mlsEmpty) mlsEmpty.style.display = 'none';
  if (mlsMain)  mlsMain.style.display  = '';
  pick.style.display = 'grid';
  const compact = document.getElementById('mls-picker-compact');
  if (compact) compact.classList.remove('visible');
  const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  allPicks.forEach(t => {
    const key   = t.key || `${t.item_id}_${t.shop_id}`;
    const name  = t.product_name || t.keyword || 'Produk';
    const price = t.price ? 'Rp ' + Math.round(t.price).toLocaleString('id-ID') : '';
    const sold  = t.total_sold ? Number(t.total_sold).toLocaleString('id-ID') + ' terjual' : '';
    const meta  = [t.keyword, sold].filter(Boolean).join(' · ');
    const card  = document.createElement('button');
    card.type = 'button';
    card.className = 'mls-pcard';
    card.dataset.key = key;
    card.onclick = () => mlsSelectProduct(key);
    card.innerHTML =
      (t.image_url ? `<img class="mls-pcard-img" src="${esc(t.image_url)}" alt="" loading="lazy" onerror="this.style.visibility='hidden'">` : `<div class="mls-pcard-img"></div>`) +
      `<div class="mls-pcard-body">` +
        `<div class="mls-pcard-name">${esc(name)}</div>` +
        (meta ? `<div class="mls-pcard-meta">${esc(meta)}</div>` : '') +
        (price ? `<div class="mls-pcard-price">${esc(price)}</div>` : '') +
      `</div>`;
    pick.appendChild(card);
  });

  // Restore API key status
  const saved = localStorage.getItem(_MLS_APIKEY);
  const statusEl = document.getElementById('mls-apikey-status');
  const inputRow = document.getElementById('mls-apikey-input-row');
  if (saved) {
    if (statusEl) statusEl.textContent = 'Tersimpan';
    if (inputRow) inputRow.style.display = 'none';
  }

  // Init calculator
  setTimeout(() => kalcCalc(), 100);
}

function mlsSwitchTab(tab) {
  document.querySelectorAll('#mls-tabs .dd-tab').forEach(el => {
    el.classList.toggle('active', el.dataset.tab === tab);
  });
  document.querySelectorAll('[id^="mls-tab-"]').forEach(el => {
    el.style.display = el.id === `mls-tab-${tab}` ? '' : 'none';
  });
}

function mlsExpandPicker() {
  const compact = document.getElementById('mls-picker-compact');
  const cards = document.getElementById('mls-product-cards');
  if (compact) compact.classList.remove('visible');
  if (cards) cards.style.display = '';
}

async function mlsSelectProduct(val, fallbackListing) {
  // Highlight the selected card
  document.querySelectorAll('#mls-product-cards .mls-pcard').forEach(c => {
    c.classList.toggle('active', c.dataset.key === val);
  });
  // Search both tracked (localStorage) and saved (Supabase-backed) sources
  const tracked = trkLoad();
  let t = tracked.find(p => (p.key || `${p.item_id}_${p.shop_id}`) === val);
  if (!t && _dscAllListings && _dscAllListings.length) {
    const found = _dscAllListings.find(p => `${p.item_id}_${p.shop_id}` === val);
    if (found) t = { key: val, item_id: found.item_id, shop_id: found.shop_id,
      product_name: found.product_name, store_name: found.store_name,
      image_url: found.image_url, category: found.category,
      price: found.price, total_sold: found.total_sold, keyword: found.keyword };
  }
  // Fallback: product handed off from Deep Dive that isn't tracked/saved yet
  if (!t && fallbackListing && fallbackListing.item_id != null) {
    const f = fallbackListing;
    t = { key: val, item_id: f.item_id, shop_id: f.shop_id,
      product_name: f.product_name, store_name: f.store_name,
      image_url: f.image_url, category: f.category,
      price: f.price, total_sold: f.total_sold, keyword: f.keyword };
  }
  const heroEl = document.getElementById('mls-hero');
  if (!t) { if (heroEl) heroEl.style.display = 'none'; return; }

  // Ensure the main content is visible (mlsInit hides it when there are no tracked picks)
  const mlsEmpty = document.getElementById('mls-empty-state');
  const mlsMain  = document.getElementById('mls-main-content');
  if (mlsEmpty) mlsEmpty.style.display = 'none';
  if (mlsMain)  mlsMain.style.display  = '';

  _mlsContext = { keyword: t.keyword, product: t };
  _mlsAiResetThread();
  if (heroEl) heroEl.style.display = 'block';

  const compact = document.getElementById('mls-picker-compact');
  const cards = document.getElementById('mls-product-cards');
  const activeImg = document.getElementById('mls-picker-active-img');
  const activeName = document.getElementById('mls-picker-active-name');
  if (compact) compact.classList.add('visible');
  if (cards) cards.style.display = 'none';
  if (activeImg) activeImg.src = t.image_url || '';
  if (activeName) activeName.textContent = t.product_name || t.name || '—';

  const compErr = document.getElementById('mls-comp-error');
  if (compErr) { compErr.style.display = 'none'; compErr.textContent = ''; }

  const set = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v; };
  set('mls-hero-name',  t.product_name || t.name || '—');
  set('mls-hero-kw',    t.keyword || '—');
  set('mls-hero-price', t.price ? 'Rp ' + Math.round(t.price).toLocaleString('id-ID') : '—');
  set('mls-hero-sold',  t.total_sold ? Number(t.total_sold).toLocaleString('id-ID') : '—');
  set('mls-hero-cats',  t.category || '—');

  // Main image
  const mainImg = document.getElementById('mls-main-img');
  if (mainImg) { mainImg.src = t.image_url || ''; mainImg.style.opacity = '1'; }

  // Score badge
  const score = t.score || (typeof calcLarisScore === 'function' ? calcLarisScore(t, null) : null);
  const scoreNum = document.getElementById('mls-score-num');
  const scoreBadge = document.getElementById('mls-score-badge');
  if (scoreNum) scoreNum.textContent = score ?? '—';
  if (scoreBadge && score) {
    const [bg, border, color] = score >= 70 ? ['#ECFDF5','#6EE7B7','#065F46'] : score >= 50 ? ['#EFF6FF','#BFDBFE','#1D4ED8'] : ['#FEF2F2','#FECACA','#991B1B'];
    scoreBadge.style.cssText = `flex-shrink:0;width:78px;height:78px;border-radius:14px;display:flex;flex-direction:column;align-items:center;justify-content:center;border:2px solid ${border};background:${bg};`;
    if (scoreNum) scoreNum.style.color = color;
  }

  set('mls-kw-badge', t.keyword || '—');
  set('mls-median-price', '…');
  set('mls-p-omset','…'); set('mls-p-listing','…'); set('mls-p-dom','…'); set('mls-p-sig','…');

  const compSection = document.getElementById('mls-comp-section');
  if (compSection) compSection.style.display = 'none';

  try {
    const { rows, mPrice, mSold, totalOmset, sigSellers, top5 } = await _mlsFetchKeywordMarket(t.keyword);
    const top3Omset  = rows.slice(0, 3).reduce((sum, r) => sum + (r.price || 0) * (r.total_sold || 0) / 6, 0);
    const dom3       = totalOmset > 0 ? Math.round(top3Omset / totalOmset * 100) : 0;

    _mlsContext.medianPrice = mPrice;
    _mlsContext.medianSold  = mSold;
    _mlsContext.top5        = top5;
    _mlsContext.sigSellers  = sigSellers;
    _mlsContext.totalOmset  = totalOmset;
    _mlsContext.allRows     = rows;   // full deduped set for AI category context

    // Pre-fill calculator from product + market data
    await kalcApplyDefaults(t, mPrice);

    // Pasar cards
    const fmt = n => n >= 1e9 ? 'Rp ' + (n/1e9).toFixed(1) + 'M' : n >= 1e6 ? 'Rp ' + (n/1e6).toFixed(0) + 'jt' : 'Rp ' + Math.round(n).toLocaleString('id-ID');
    set('mls-p-omset',   fmt(totalOmset));
    set('mls-p-listing', rows.length + ' listing');
    set('mls-median-price', mPrice ? 'Rp ' + Math.round(mPrice).toLocaleString('id-ID') : '—');
    const mSoldEl = document.getElementById('mls-median-sold');
    if (mSoldEl) mSoldEl.textContent = mSold ? mSold.toLocaleString('id-ID') + ' unit / bulan' : '— unit / bulan';
    set('mls-p-dom', dom3 + '%');
    set('mls-p-sig', sigSellers.length + ' penjual');

    // Build thumbnails from similar competitors only (same keyword + name overlap)
    const thumbRow = document.getElementById('mls-thumb-row');
    if (thumbRow) {
      const baseName = t.product_name || '';
      const similar = rows
        .filter(r => r.image_url && r.image_url !== t.image_url)
        .map(r => ({ r, sim: _mlsNameSimilarity(baseName, r.product_name) }))
        .filter(x => x.sim >= 0.2)
        .sort((a, b) => b.sim - a.sim)
        .map(x => x.r);
      const fallback = rows.filter(r => r.image_url && r.image_url !== t.image_url);
      const related = (similar.length ? similar : fallback).slice(0, 9);
      const allThumbs = [t, ...related];
      thumbRow.innerHTML = allThumbs.map((r, i) => `
        <div class="mls-thumb${i===0?' active':''}" onclick="mlsSetThumb(this,'${(r.image_url||'').replace(/'/g,"\\'")}')">
          <img src="${r.image_url||''}" onerror="this.style.opacity='.3'" alt="">
        </div>`).join('');
      mlsSetImages(allThumbs.map(r => r.image_url).filter(Boolean));
    }

    mlsRenderMarketRec(top5, mPrice);

    // Populate Ringkasan bar
    const kompScore = rows.length > 0 ? Math.min(100, Math.round(Math.log10(Math.max(1, rows.length)) / 2.7 * 100)) : 0;
    const kompLabel = kompScore >= 70 ? 'Tinggi' : kompScore >= 40 ? 'Sedang' : 'Rendah';
    const kompColor = kompScore >= 70 ? '#DC2626' : kompScore >= 40 ? '#D97706' : '#16A34A';
    const rbKomp  = document.getElementById('mls-rb-kompetisi');
    const rbHarga = document.getElementById('mls-rb-harga');
    const rbOmset = document.getElementById('mls-rb-omset');
    const rbPenjual = document.getElementById('mls-rb-penjual');
    if (rbKomp)    { rbKomp.textContent = kompLabel; rbKomp.style.color = kompColor; }
    if (rbHarga)   rbHarga.textContent = mPrice ? 'Rp ' + Math.round(mPrice).toLocaleString('id-ID') : '—';
    if (rbOmset)   rbOmset.textContent = fmt(totalOmset) + '/bln';
    if (rbPenjual) rbPenjual.textContent = rows.length + ' listing';

    // Top 15 competitors — row table (default) + card grid (toggle)
    const top15 = rows.slice(0, 15);
    const compSection = document.getElementById('mls-comp-section');
    const compSub     = document.getElementById('mls-comp-sub');
    const compTbody   = document.getElementById('mls-comp-tbody');   // <tbody> in table
    const compCards   = document.getElementById('mls-comp-cards');    // card grid
    if (compSection) compSection.style.display = top15.length ? 'block' : 'none';
    if (compSub) compSub.textContent = `${top15.length} produk teratas di keyword "${t.keyword}"`;
    if (compErr && !top15.length) {
      compErr.style.display = 'block';
      compErr.textContent = rows.length
        ? 'Belum cukup data kompetitor untuk ditampilkan.'
        : `Belum ada listing kompetitor untuk keyword "${t.keyword || '—'}" di database LarisID.`;
    }
    const rankColors = ['#B5202A','#C9974B','#9CA3AF'];

    // ── Row view (table) ──
    if (compTbody) compTbody.innerHTML = top15.map((r, i) => {
      const omset  = _toMonthly(r);  // monthly estimate (lifetime/6)
      const share  = totalOmset > 0 ? (omset / totalOmset * 100) : 0;
      const rank   = i + 1;
      const rc     = rankColors[i] || '#6366F1';
      const rankBadge = `<span style="display:inline-flex;align-items:center;justify-content:center;width:22px;height:22px;border-radius:50%;background:${rc};color:#fff;font-size:.65rem;font-weight:800;flex-shrink:0;">${rank}</span>`;
      const imgHtml = r.image_url ? `<img src="${r.image_url}" style="width:32px;height:32px;border-radius:6px;object-fit:cover;" onerror="this.style.display='none'">` : `<div style="width:32px;height:32px;border-radius:6px;background:#F3F4F6;"></div>`;
      const soldFmt = (r.total_sold||0) >= 1000 ? ((r.total_sold||0)/1000).toFixed(1) + 'rb' : String(r.total_sold||0);
      const reviewsFmt = (r.reviews||0) >= 1000 ? ((r.reviews||0)/1000).toFixed(1) + 'rb' : String(r.reviews||0);
      const shopUrl = r.url ? `<a href="${r.url}" target="_blank" onclick="event.stopPropagation()" style="color:#3B82F6;text-decoration:none;font-size:.6rem;">↗</a>` : '';
      return `<tr style="border-bottom:1px solid #F9FAFB;cursor:pointer;" onclick="mlsOpenCompDive('${r.item_id}','${r.shop_id}')">
        <td style="padding:9px 6px;">${rankBadge}</td>
        <td style="padding:9px 8px;">
          <div style="display:flex;align-items:center;gap:7px;">
            ${imgHtml}
            <div style="font-size:.68rem;font-weight:600;line-height:1.3;max-width:160px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${(r.product_name||'—').slice(0,48)} ${shopUrl}</div>
          </div>
        </td>
        <td style="padding:9px 6px;font-size:.65rem;color:#374151;max-width:90px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${(r.store_name||'—').slice(0,20)}</td>
        <td style="padding:9px 6px;font-size:.63rem;color:#9CA3AF;white-space:nowrap;">${r.location||'—'}</td>
        <td style="padding:9px 6px;text-align:right;font-size:.72rem;font-weight:700;color:#111827;white-space:nowrap;">Rp ${(r.price||0).toLocaleString('id-ID')}</td>
        <td style="padding:9px 6px;text-align:right;font-size:.7rem;font-weight:700;color:#374151;white-space:nowrap;">${soldFmt}</td>
        <td style="padding:9px 6px;text-align:right;font-size:.7rem;color:#6B7280;white-space:nowrap;">${reviewsFmt}</td>
        <td style="padding:9px 6px;text-align:right;font-size:.68rem;font-weight:700;color:#B5202A;white-space:nowrap;">${share.toFixed(1)}%</td>
      </tr>`;
    }).join('');

    // ── Card view (hidden by default) ──
    if (compCards) compCards.innerHTML = top15.map((r, i) => {
      const omset  = _toMonthly(r);  // monthly estimate (lifetime/6)
      const share  = totalOmset > 0 ? (omset / totalOmset * 100) : 0;
      const rank   = i + 1;
      const rc     = rankColors[i] || '#E5E7EB';
      const rankCls = i < 3 ? `rank-${rank}` : '';
      const storeName = (r.store_name || '—').substring(0, 24);
      const soldFmt = (r.total_sold||0) >= 1000 ? ((r.total_sold||0)/1000).toFixed(1) + 'rb' : String(r.total_sold||0);
      return `<div class="mls-seller-card ${rankCls}" style="cursor:pointer;" onclick="mlsOpenCompDive('${r.item_id}','${r.shop_id}')">
        <div class="mls-seller-img-wrap">
          <img class="mls-seller-img" src="${r.image_url||''}" onerror="this.src='';this.style.background='#F0EDE8';" alt="${r.product_name||''}">
          <div class="mls-seller-rank" style="background:${rc};">${rank}</div>
        </div>
        <div class="mls-seller-body">
          <div class="mls-seller-store">${storeName}</div>
          <div class="mls-seller-price">Rp ${(r.price||0).toLocaleString('id-ID')}</div>
          <div style="font-size:.6rem;color:#9CA3AF;">${r.location||''}</div>
          <div class="mls-seller-stats">
            <span>${soldFmt} terjual</span><span style="color:#9CA3AF;">·</span>
            <span style="color:#B5202A;">${share.toFixed(1)}% share</span>
          </div>
          <div class="mls-seller-share-bar"><div class="mls-seller-share-fill" style="width:${Math.min(share*4,100)}%;background:${rc};"></div></div>
        </div>
      </div>`;
    }).join('');

  } catch(e) {
    console.warn('mlsSelectProduct error', e);
    const compErr = document.getElementById('mls-comp-error');
    if (compErr) {
      compErr.style.display = 'block';
      compErr.textContent = 'Gagal memuat data kompetitor. Periksa koneksi Anda lalu pilih produk lagi.';
    }
  }
}

