function openFeedback() { openFeedbackModal(); }

// ── Native Feedback Modal ─────────────────────────────────────────────────────

let _fbType = 'product';
let _fbElementCtx = null; // { element, section, value } when opened from a flag button

function openFeedbackModal(ctx) {
  const overlay = document.getElementById('feedback-modal-overlay');
  if (!overlay) return;
  _fbElementCtx = ctx || null;
  const isElement = !!ctx;

  // title + subtitle
  const title = document.getElementById('fb-modal-title');
  const sub = document.getElementById('fb-modal-sub');
  if (title) title.textContent = isElement ? 'Laporkan Masalah' : 'Pesan ke Steven';
  if (sub) sub.textContent = isElement
    ? 'Pilih jenis masalah dan tambahkan catatan jika perlu.'
    : 'Steven (founder LarisID) baca setiap pesan. Minta produk, ide, fitur, atau kasih feedback — langsung ketik saja.';

  // element context banner
  const banner = document.getElementById('fb-ctx-banner');
  const ctxLabel = document.getElementById('fb-ctx-label');
  if (banner) banner.style.display = isElement ? 'flex' : 'none';
  if (ctxLabel && ctx) ctxLabel.textContent = ctx.element + (ctx.section ? ' · ' + ctx.section : '');

  // chip set
  const gChips = document.getElementById('fb-chips-general');
  const eChips = document.getElementById('fb-chips-element');
  if (gChips) gChips.style.display = isElement ? 'none' : 'flex';
  if (eChips) eChips.style.display = isElement ? 'flex' : 'none';

  const defaultType = isElement ? 'wrong_data' : 'product';
  _fbType = defaultType;
  fbSetType(defaultType);

  const msg = document.getElementById('fb-message');
  if (msg) {
    msg.value = '';
    msg.style.borderColor = '#E5E7EB';
    msg.placeholder = isElement
      ? 'Opsional — jelaskan lebih lanjut apa yang terlihat salah...'
      : 'Tulis pesanmu untuk Steven…';
  }
  const status = document.getElementById('fb-submit-status');
  if (status) { status.textContent = ''; status.style.color = ''; }
  const btn = document.getElementById('fb-submit-btn');
  if (btn) { btn.disabled = false; btn.textContent = 'Kirim ke Steven'; }
  overlay.style.display = 'flex';
}

function closeFeedbackModal() {
  const overlay = document.getElementById('feedback-modal-overlay');
  if (overlay) overlay.style.display = 'none';
  _fbElementCtx = null;
}

// The chips are UI labels; `feedback.type` is a CHECK-constrained column that
// only accepts bug | feature | other | wrong_data | not_working | request_edit.
// 'product' (the default chip) and 'idea' are not in that list, so every
// general feedback message from Site A was rejected with 23514 and the user was
// told "Gagal mengirim" — a retry prompt for something that could never
// succeed. Same class of bug as bd7857d on Site B. Translate here, once, so a
// future chip rename cannot silently kill submissions again.
const FB_DB_TYPES = ['bug', 'feature', 'other', 'wrong_data', 'not_working', 'request_edit'];
const FB_TYPE_TO_DB = {
  product: 'feature',   // "Request Produk" — a request for coverage we don't have
  idea: 'feature',
  other2: 'other',
};
function _fbDbType(t) {
  const mapped = FB_TYPE_TO_DB[t] || t;
  return FB_DB_TYPES.includes(mapped) ? mapped : 'other';
}

function fbSetType(type) {
  _fbType = type;
  const allChips = ['product','idea','feature','other','wrong_data','not_working','request_edit','other2','bug'];
  allChips.forEach(t => {
    const chip = document.getElementById('fb-chip-' + t);
    if (!chip) return;
    const match = t === type || (t === 'other2' && type === 'other');
    chip.style.borderColor = match ? '#B5202A' : '#E5E7EB';
    chip.style.background  = match ? '#F9EAE4' : '#fff';
    chip.style.color       = match ? '#B5202A' : '#374151';
  });
}

// Attach flag buttons to all [data-fb-element] containers
function initFlagButtons() {
  document.querySelectorAll('[data-fb-element]').forEach(el => {
    if (el.querySelector(':scope > .fb-flag-btn')) return;
    if (!el.classList.contains('fb-flaggable')) el.classList.add('fb-flaggable');
    const btn = document.createElement('button');
    btn.className = 'fb-flag-btn';
    btn.title = 'Laporkan masalah pada bagian ini';
    btn.setAttribute('aria-label', 'Laporkan masalah');
    btn.innerHTML = '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="#6B7280" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M4 15s1-1 4-1 5 2 8 2 4-1 4-1V3s-1 1-4 1-5-2-8-2-4 1-4 1z"/><line x1="4" y1="22" x2="4" y2="15"/></svg>';
    btn.onclick = (e) => {
      e.stopPropagation();
      openFeedbackModal({
        element: el.dataset.fbElement || '',
        section: el.dataset.fbSection || '',
        value:   el.dataset.fbValue   || '',
      });
    };
    el.appendChild(btn);
  });
}

async function submitFeedback() {
  const msg = (document.getElementById('fb-message')?.value || '').trim();
  const status = document.getElementById('fb-submit-status');
  const btn = document.getElementById('fb-submit-btn');
  const minLen = _fbElementCtx ? 0 : 10;
  if (msg.length < minLen) {
    if (status) { status.textContent = 'Tulis minimal 10 karakter ya.'; status.style.color = '#B5202A'; }
    const ta = document.getElementById('fb-message');
    if (ta) ta.style.borderColor = '#B5202A';
    return;
  }
  if (btn) { btn.disabled = true; btn.textContent = 'Mengirim...'; }
  if (status) { status.textContent = ''; }
  try {
    const record = {
      user_id:         currentUser?.id    || null,
      user_email:      currentUser?.email || null,
      type:            _fbDbType(_fbType),
      message:         msg,
      page:            document.title || window.location.hash || 'app',
      element_context: _fbElementCtx || null,
    };
    const { data: inserted, error } = await _supabase
      .from('feedback').insert(record).select('id').single();
    if (error) throw error;
    const recordWithId = { ...record, id: inserted?.id };
    void logUserEvent('feedback_submitted', { ui: 'classic', from_wall: _fbBonusPending });
    // fire-and-forget: email + AI analysis in parallel
    _supabase.functions.invoke('notify-feedback',  { body: { record: recordWithId } })
      .then(({ error }) => { if (error) console.warn('notify-feedback:', error.message); });
    _supabase.functions.invoke('analyze-feedback', { body: { record: recordWithId } })
      .then(({ data, error }) => {
        if (error) console.warn('analyze-feedback invoke:', error.message);
        else if (data?.errors?.length) console.warn('analyze-feedback errors:', data.errors);
      });
    // Grant the +3 dive bonus when this submission came from the limit modal.
    // The server re-checks ownership, same WIB day and a real message, so this
    // is only the trigger, not the authority.
    if (_fbBonusPending && inserted?.id) {
      _fbBonusPending = false;
      void spinClaimFeedbackBonus(inserted.id);
      if (status) { status.textContent = 'Terkirim! +3 dive buat hari ini.'; status.style.color = '#16A34A'; }
    } else if (status) { status.textContent = 'Terkirim! Steven akan baca pesanmu.'; status.style.color = '#16A34A'; }
    if (btn) { btn.textContent = 'Terkirim'; }
    setTimeout(closeFeedbackModal, 1800);
  } catch (err) {
    console.error('feedback submit failed:', err?.code || '', err?.message || err);
    // Carry the code into the visible message: when someone screenshots this,
    // that string is the only evidence we get of a failure that writes no row.
    const code = err?.code ? ' (kode ' + err.code + ')' : '';
    if (status) { status.textContent = 'Gagal mengirim. Coba lagi' + code + '.'; status.style.color = '#B5202A'; }
    if (btn) { btn.disabled = false; btn.textContent = 'Kirim ke Steven'; }
  }
}

let _admFbView = 'inbox';

function admFbSetView(view) {
  _admFbView = view === 'vault' ? 'vault' : 'inbox';
  ['inbox', 'vault'].forEach(v => {
    const btn = document.getElementById('adm-fb-tab-' + v);
    if (btn) btn.classList.toggle('active', v === _admFbView);
  });
  loadAdminFeedback();
}

function renderFeedbackCard(row, opts = {}) {
  const inVault = opts.inVault === true;
  const badge = {
    product:      ['#FFEDD5','#C2410C','Produk'],
    idea:         ['#EDE9FE','#6D28D9','Ide'],
    bug:          ['#FEE2E2','#DC2626','Bug'],
    feature:      ['#DBEAFE','#1D4ED8','Fitur'],
    wrong_data:   ['#FEF9C3','#B45309','Data Salah'],
    not_working:  ['#FEE2E2','#DC2626','Tidak Berfungsi'],
    request_edit: ['#DCFCE7','#15803D','Minta Edit'],
    other:        ['#F3F4F6','#6B7280','Feedback'],
  };
  const statOpts = ['new','reviewing','done','dismissed'];
  const [bg, fg, lbl] = badge[row.type] || badge.other;
  const diff = Math.floor((Date.now() - new Date(row.created_at).getTime()) / 60000);
  const rel = diff < 2 ? 'Baru saja' : diff < 60 ? diff + ' mnt lalu' : diff < 1440 ? Math.floor(diff/60) + ' jam lalu' : Math.floor(diff/1440) + ' hari lalu';
  const txt = (row.message || '—').substring(0, 240).replace(/</g, '&lt;') + ((row.message?.length || 0) > 240 ? '…' : '');
  const ctx = row.element_context;
  const ctxHtml = ctx?.element
    ? `<div style="display:flex;align-items:center;gap:5px;margin-bottom:6px;font-size:.65rem;color:#6B7280;">
         <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="#B5202A" stroke-width="2.5"><path d="M4 15s1-1 4-1 5 2 8 2 4-1 4-1V3s-1 1-4 1-5-2-8-2-4 1-4 1z"/><line x1="4" y1="22" x2="4" y2="15"/></svg>
         <span style="font-weight:700;color:#1A1A1A;">${ctx.element}</span>${ctx.section ? ' &middot; ' + ctx.section : ''}
       </div>`
    : '';
  const aiPriBadge = {
    critical: ['#FEE2E2','#DC2626','CRITICAL'],
    high:     ['#FFEDD5','#C2410C','HIGH'],
    medium:   ['#FEF9C3','#B45309','MEDIUM'],
    low:      ['#DBEAFE','#1D4ED8','LOW'],
    personal: ['#F3F4F6','#6B7280','PERSONAL'],
  };
  const aiActBadge = {
    'fix-now':    ['#FEE2E2','#DC2626','fix-now'],
    'investigate':['#FFEDD5','#C2410C','investigate'],
    'monitor':    ['#DBEAFE','#1D4ED8','monitor'],
    'note-only':  ['#F3F4F6','#6B7280','note-only'],
  };
  const [pBg, pFg, pLbl] = aiPriBadge[row.ai_priority] || ['#F3F4F6','#9CA3AF','—'];
  const [aBg, aFg, aLbl] = aiActBadge[row.ai_action]   || ['#F3F4F6','#9CA3AF','—'];
  const aiPanel = row.ai_analyzed_at ? `
    <div style="border-top:1px solid #F3F4F6;margin-top:8px;padding-top:8px;">
      <div style="display:flex;align-items:center;gap:5px;margin-bottom:5px;flex-wrap:wrap;">
        <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="#9CA3AF" stroke-width="2"><circle cx="12" cy="12" r="10"/><path d="M12 8v4l3 3"/></svg>
        <span style="font-size:.58rem;font-weight:700;color:#9CA3AF;letter-spacing:.05em;">ANALISIS AI</span>
        <span style="background:${pBg};color:${pFg};font-size:.58rem;font-weight:700;padding:1px 6px;border-radius:20px;">${pLbl}</span>
        <span style="background:${aBg};color:${aFg};font-size:.58rem;font-weight:700;padding:1px 6px;border-radius:20px;">${aLbl}</span>
      </div>
      <div style="font-size:.74rem;color:#374151;line-height:1.55;">${(row.ai_notes || '').replace(/</g,'&lt;')}</div>
    </div>` : `
    <div style="border-top:1px solid #F3F4F6;margin-top:8px;padding-top:6px;display:flex;align-items:center;justify-content:space-between;gap:8px;">
      <span style="font-size:.62rem;color:#D1D5DB;font-style:italic;">AI analysis pending...</span>
      <button type="button" style="font-size:.6rem;padding:2px 8px;border:1px solid #E5E7EB;border-radius:6px;background:#fff;color:#6B7280;cursor:pointer;" onclick="retryFeedbackAnalysis('${row.id}')">Retry AI</button>
    </div>`;
  const cardBg = inVault ? '#F9FAFB' : '#FAFAFA';
  return `<div style="border:1px solid #E5E7EB;border-radius:10px;padding:12px 14px;margin-bottom:8px;background:${cardBg};${inVault ? 'opacity:.92;' : ''}">
    ${ctxHtml}
    <div style="display:flex;align-items:flex-start;gap:10px;margin-bottom:8px;">
      <span style="background:${bg};color:${fg};font-size:.62rem;font-weight:700;padding:2px 8px;border-radius:20px;flex-shrink:0;margin-top:2px;">${lbl}</span>
      <div style="font-size:.8rem;color:#374151;flex:1;line-height:1.5;">${txt}</div>
    </div>
    <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;">
      <div style="font-size:.65rem;color:#9CA3AF;">${row.user_email || 'Anonim'} &middot; ${rel}${inVault ? ' &middot; <span style="color:#9CA3AF;">archived</span>' : ''}</div>
      <select style="font-size:.65rem;padding:3px 6px;border:1px solid #E5E7EB;border-radius:6px;background:#fff;color:#374151;cursor:pointer;" onchange="updateFeedbackStatus('${row.id}',this.value)">
        ${statOpts.map(s => `<option value="${s}"${(row.status || 'new') === s ? ' selected' : ''}>${s}</option>`).join('')}
      </select>
    </div>
    ${aiPanel}
  </div>`;
}

let _admFbPendingLast = -1;

async function loadAdminFeedback() {
  const list = document.getElementById('adm-feedback-list');
  if (!list || !_supabase) return;
  list.innerHTML = '<div style="text-align:center;padding:24px;color:#9CA3AF;font-size:.78rem;">Memuat...</div>';
  const isVault = _admFbView === 'vault';
  let q = _supabase.from('feedback').select('*').order('created_at', { ascending: false }).limit(80);
  if (isVault) {
    q = q.in('status', ['done', 'dismissed']);
  } else {
    q = q.or('status.eq.new,status.eq.reviewing,status.is.null');
  }
  const { data, error } = await q;
  if (error) {
    list.innerHTML = '<div style="text-align:center;padding:24px;color:#9CA3AF;font-size:.78rem;">Gagal memuat masukan.</div>';
    console.warn('loadAdminFeedback:', error.message);
    return;
  }

  // Count pending AI analysis across all inbox items (not just current view)
  const pendingInData = (data || []).filter(r => !r.ai_analyzed_at).length;
  const pendingCount = isVault ? _admFbPendingLast : pendingInData;

  if (!isVault) {
    const navDot = document.getElementById('adm-fb-nav-dot');
    if (navDot) navDot.style.display = pendingCount > 0 ? 'block' : 'none';
    const chip = document.getElementById('adm-fb-pending-chip');
    if (chip) {
      chip.style.display = pendingCount > 0 ? 'inline' : 'none';
      chip.textContent = `${pendingCount} AI Pending`;
    }
    if (_admFbPendingLast > 0 && pendingCount < _admFbPendingLast) {
      const done = _admFbPendingLast - pendingCount;
      _admShowToast(`AI analyzed ${done} feedback item${done > 1 ? 's' : ''}`);
    }
    _admFbPendingLast = pendingCount;
  }

  if (!data?.length) {
    list.innerHTML = '<div style="text-align:center;padding:24px;color:#9CA3AF;font-size:.78rem;">' +
      (isVault ? 'Vault kosong — selesaikan masukan dari Inbox.' : 'Inbox kosong — belum ada masukan aktif.') + '</div>';
    return;
  }
  list.innerHTML = data.map(row => renderFeedbackCard(row, { inVault: isVault })).join('');
}

function _admShowToast(msg) {
  let t = document.getElementById('adm-toast');
  if (!t) {
    t = document.createElement('div');
    t.id = 'adm-toast';
    t.style.cssText = 'position:fixed;bottom:80px;right:20px;z-index:10001;background:#1A1A1A;color:#fff;font-size:.75rem;font-weight:700;padding:10px 16px;border-radius:10px;box-shadow:0 4px 16px rgba(0,0,0,.25);transition:opacity .3s;pointer-events:none;';
    document.body.appendChild(t);
  }
  t.textContent = msg;
  t.style.opacity = '1';
  clearTimeout(t._timer);
  t._timer = setTimeout(() => { t.style.opacity = '0'; }, 3500);
}

async function updateFeedbackStatus(id, status) {
  if (!_supabase) return;
  const { error } = await _supabase.from('feedback').update({ status }).eq('id', id);
  if (error) { console.warn('updateFeedbackStatus:', error.message); return; }
  if (status === 'done' || status === 'dismissed') {
    _admFbView = 'vault';
    ['inbox', 'vault'].forEach(v => {
      const btn = document.getElementById('adm-fb-tab-' + v);
      if (btn) btn.classList.toggle('active', v === 'vault');
    });
  }
  loadAdminFeedback();
}

async function retryFeedbackAnalysis(id) {
  if (!_supabase || !id) return;
  const { data, error } = await _supabase.functions.invoke('analyze-feedback', { body: { record: { id } } });
  if (error) { console.warn('retryFeedbackAnalysis:', error.message); alert('AI retry failed: ' + error.message); return; }
  if (data?.errors?.length) {
    console.warn('retryFeedbackAnalysis errors:', data.errors);
    alert('AI error: ' + data.errors[0].error);
    return;
  }
  setTimeout(loadAdminFeedback, 1500);
}

// ── Broadcast Email ───────────────────────────────────────────────────────────

let _admBcSeg = 'all';
let _admBcUsers = null;

function admBcSetSeg(seg) {
  _admBcSeg = seg;
  ['all','leaders','students','independents','specific'].forEach(s => {
    const btn = document.getElementById('adm-bc-seg-' + s);
    if (btn) btn.classList.toggle('active', s === seg);
  });
  const wrap = document.getElementById('adm-bc-specific-wrap');
  if (wrap) wrap.style.display = seg === 'specific' ? 'block' : 'none';
  if (seg === 'specific' && !_admBcUsers) admBcLoadUsers();
  document.getElementById('adm-bc-count').textContent = '';
}

async function admBcLoadUsers() {
  if (!_supabase) return;
  const { data } = await _supabase.rpc('admin_user_directory');
  _admBcUsers = (data || []).filter(u => u.email);
}

function admBcSearchUser(query) {
  const dropdown = document.getElementById('adm-bc-specific-dropdown');
  const hidden   = document.getElementById('adm-bc-specific-email');
  if (!dropdown) return;
  hidden.value = '';
  const q = query.trim().toLowerCase();
  if (!q) { dropdown.style.display = 'none'; return; }
  const matches = (_admBcUsers || []).filter(u =>
    (u.display_name || '').toLowerCase().includes(q) || (u.email || '').toLowerCase().includes(q)
  ).slice(0, 10);
  if (!matches.length) { dropdown.style.display = 'none'; return; }
  const esc = s => (s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/"/g,'&quot;');
  dropdown.innerHTML = matches.map(u => {
    const name = u.display_name || u.email;
    const safeE = u.email.replace(/\\/g,'\\\\').replace(/\'/g,"\\'");
    const safeN = name.replace(/\\/g,'\\\\').replace(/\'/g,"\\'");
    return `<div style="padding:9px 12px;cursor:pointer;border-bottom:1px solid #F3F4F6;" onmousedown="admBcSelectUser('${safeE}','${safeN}')">
      <div style="font-size:.78rem;font-weight:700;color:#1A1A1A;">${esc(name)}</div>
      <div style="font-size:.68rem;color:#6B7280;">${esc(u.email)}</div>
    </div>`;
  }).join('');
  dropdown.style.display = 'block';
}

function admBcSelectUser(email, name) {
  document.getElementById('adm-bc-specific-search').value = name + ' <' + email + '>';
  document.getElementById('adm-bc-specific-email').value  = email;
  document.getElementById('adm-bc-specific-dropdown').style.display = 'none';
}

document.addEventListener('click', e => {
  const wrap = document.getElementById('adm-bc-specific-wrap');
  if (wrap && !wrap.contains(e.target)) {
    const dd = document.getElementById('adm-bc-specific-dropdown');
    if (dd) dd.style.display = 'none';
  }
});

document.addEventListener('change', e => {
  if (e.target.id !== 'adm-bc-attachment') return;
  const info = document.getElementById('adm-bc-attachment-info');
  if (info) {
    const file = e.target.files?.[0];
    info.textContent = file ? `${file.name} (${(file.size/1024).toFixed(1)} KB)` : '';
  }
});

async function admBcSend() {
  const subject  = (document.getElementById('adm-bc-subject')?.value || '').trim();
  const body     = (document.getElementById('adm-bc-body')?.value || '').trim();
  const statusEl = document.getElementById('adm-bc-status');
  const sendBtn  = document.getElementById('adm-bc-send-btn');
  if (!subject || !body) { if (statusEl) statusEl.textContent = 'Isi subjek dan pesan terlebih dahulu.'; return; }
  let specificEmail = '';
  if (_admBcSeg === 'specific') {
    specificEmail = (document.getElementById('adm-bc-specific-email')?.value || '').trim();
    if (!specificEmail) {
      // Fallback: accept a directly typed valid email
      const typed = (document.getElementById('adm-bc-specific-search')?.value || '').trim();
      if (/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(typed)) specificEmail = typed;
    }
    if (!specificEmail) { if (statusEl) statusEl.textContent = 'Pilih penerima dari daftar atau ketik email yang valid.'; return; }
  }
  let attachment = null;
  const fileInput = document.getElementById('adm-bc-attachment');
  if (fileInput?.files?.length) {
    const file = fileInput.files[0];
    attachment = await new Promise((res, rej) => {
      const r = new FileReader();
      r.onload = () => res({ filename: file.name, content: r.result.split(',')[1], content_type: file.type || 'application/octet-stream' });
      r.onerror = rej;
      r.readAsDataURL(file);
    });
  }
  const confirmMsg = _admBcSeg === 'specific'
    ? `Kirim email ke ${specificEmail}?\n\nSubjek: ${subject}`
    : `Kirim email ke segmen "${_admBcSeg}"?\n\nSubjek: ${subject}`;
  if (!confirm(confirmMsg)) return;
  if (sendBtn) { sendBtn.disabled = true; sendBtn.textContent = 'Mengirim…'; }
  if (statusEl) statusEl.textContent = '';
  try {
    const session = (await _supabase?.auth.getSession())?.data?.session;
    const payload = { segment: _admBcSeg, subject, body };
    if (_admBcSeg === 'specific') payload.specific_email = specificEmail;
    if (attachment) payload.attachment = attachment;
    const res = await fetch(`${SUPA_URL}/functions/v1/send-broadcast`, {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${session?.access_token || ''}`, 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });
    const json = await res.json();
    if (res.ok) {
      const failMsg = json.failed?.length
        ? ` Gagal: ${json.failed.length}.${json.fail_reasons?.[0] ? ' (' + json.fail_reasons[0] + ')' : ''}`
        : '';
      const toList = (json.recipients || []).join(', ');
      const idHint = json.resend_ids?.[0] ? ` ID Resend: ${json.resend_ids[0]}.` : '';
      const fromHint = json.from ? ` Dari: ${json.from}.` : '';
      const spamHint = json.sent > 0 ? ' Cek folder spam/promosi jika tidak masuk inbox.' : '';
      if (statusEl) {
        statusEl.textContent = `Diterima Resend (${json.sent}/${json.total_targets || json.sent}) → ${toList || '—'}.${fromHint}${idHint}${failMsg}${spamHint}`;
        statusEl.style.color = json.failed?.length ? '#B45309' : '#1A7A46';
      }
      document.getElementById('adm-bc-subject').value = '';
      document.getElementById('adm-bc-body').value = '';
      if (_admBcSeg === 'specific') {
        document.getElementById('adm-bc-specific-search').value = '';
        document.getElementById('adm-bc-specific-email').value = '';
      }
      if (fileInput) { fileInput.value = ''; document.getElementById('adm-bc-attachment-info').textContent = ''; }
    } else {
      if (statusEl) statusEl.textContent = `Error: ${json.error || res.status}`;
    }
  } catch (e) {
    if (statusEl) statusEl.textContent = 'Gagal mengirim. Coba lagi.';
  }
  if (sendBtn) { sendBtn.disabled = false; sendBtn.textContent = 'Kirim Email'; }
}

// ─── Leader email broadcast (shared state + prefix-based logic) ───────────────

let _ldrBcSeg      = 'all_cohort';
let _ldrBcStudents = null; // [{user_id, email, display_name, status, engagement_score}]
let _ldrBcGroups   = null; // [{id, name, member_count}]

// Generic: set segment on any email panel identified by id-prefix
function _ldrEmailSetSeg(seg, pfx) {
  _ldrBcSeg = seg;
  ['all_cohort','specific','custom_group'].forEach(s => {
    const btn = document.getElementById(pfx + 'seg-' + s);
    if (btn) btn.classList.toggle('active', s === seg);
  });
  const sw = document.getElementById(pfx + 'specific-wrap');
  const gw = document.getElementById(pfx + 'group-wrap');
  if (sw) sw.style.display = seg === 'specific'     ? 'block' : 'none';
  if (gw) gw.style.display = seg === 'custom_group' ? 'block' : 'none';
}

// Generic: render student autocomplete into a dropdown element
function _ldrEmailSearchStudent(query, dropdownId, hiddenId) {
  const dropdown = document.getElementById(dropdownId);
  const hidden   = document.getElementById(hiddenId);
  if (!dropdown) return;
  if (hidden) hidden.value = '';
  const q = query.trim().toLowerCase();
  if (!q) { dropdown.style.display = 'none'; return; }
  const matches = (_ldrBcStudents || []).filter(u =>
    (u.display_name || '').toLowerCase().includes(q) || (u.email || '').toLowerCase().includes(q)
  ).slice(0, 10);
  if (!matches.length) { dropdown.style.display = 'none'; return; }
  const esc = s => (s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/"/g,'&quot;');
  dropdown.innerHTML = matches.map(u => {
    const name  = u.display_name || u.email;
    const safeE = u.email.replace(/\\/g,'\\\\').replace(/'/g,"\\'");
    const safeN = name.replace(/\\/g,'\\\\').replace(/'/g,"\\'");
    // Encode the target field IDs so we know where to write the selection
    return `<div style="padding:9px 12px;cursor:pointer;border-bottom:1px solid #F3F4F6;" onmousedown="_ldrEmailSelectStudent('${safeE}','${safeN}','${dropdownId}','${hiddenId}')">
      <div style="font-size:.78rem;font-weight:700;color:#1A1A1A;">${esc(name)}</div>
      <div style="font-size:.68rem;color:#6B7280;">${esc(u.email)}</div>
    </div>`;
  }).join('');
  dropdown.style.display = 'block';
}

function _ldrEmailSelectStudent(email, name, dropdownId, hiddenId) {
  const dropdown = document.getElementById(dropdownId);
  const hidden   = document.getElementById(hiddenId);
  // The search input id is derived: "xxx-specific-dropdown" → "xxx-specific-search"
  const searchId = dropdownId.replace('-dropdown', '-search');
  const search   = document.getElementById(searchId);
  if (search) search.value = name + ' <' + email + '>';
  if (hidden) hidden.value = email;
  if (dropdown) dropdown.style.display = 'none';
}

// Rebuild the group <select> inside a given panel (by prefix)
function _ldrEmailRebuildGroupSelect(pfx) {
  const sel = document.getElementById(pfx + 'group-select');
  if (!sel) return;
  const cur = sel.value;
  sel.innerHTML = '<option value="">— Pilih grup —</option>';
  (_ldrBcGroups || []).forEach(g => {
    const opt = document.createElement('option');
    opt.value = g.id;
    opt.textContent = `${g.name} (${g.member_count} siswa)`;
    if (g.id === cur) opt.selected = true;
    sel.appendChild(opt);
  });
}

// Generic: send email via send-leader-broadcast using a given panel's prefix
async function _ldrEmailSend(pfx) {
  const c        = _cohortState?.primaryMentorCohort;
  const subject  = (document.getElementById(pfx + 'subject')?.value  || '').trim();
  const body     = (document.getElementById(pfx + 'body')?.value     || '').trim();
  const statusEl = document.getElementById(pfx + 'status');
  const sendBtn  = document.getElementById(pfx + 'send-btn');

  if (!c)                { if (statusEl) statusEl.textContent = 'Tidak ada kohort aktif.'; return; }
  if (!subject || !body) { if (statusEl) statusEl.textContent = 'Isi subjek dan pesan terlebih dahulu.'; return; }

  let specificEmail = '';
  let groupId       = '';

  if (_ldrBcSeg === 'specific') {
    specificEmail = (document.getElementById(pfx + 'specific-email')?.value || '').trim();
    if (!specificEmail) {
      const typed = (document.getElementById(pfx + 'specific-search')?.value || '').trim();
      if (/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(typed)) specificEmail = typed;
    }
    if (!specificEmail) { if (statusEl) statusEl.textContent = 'Pilih penerima dari daftar atau ketik email yang valid.'; return; }
  }

  if (_ldrBcSeg === 'custom_group') {
    groupId = (document.getElementById(pfx + 'group-select')?.value || '').trim();
    if (!groupId) { if (statusEl) statusEl.textContent = 'Pilih grup terlebih dahulu.'; return; }
  }

  let attachment = null;
  const fileInput = document.getElementById(pfx + 'attachment');
  if (fileInput?.files?.length) {
    const file = fileInput.files[0];
    attachment = await new Promise((res, rej) => {
      const r = new FileReader();
      r.onload  = () => res({ filename: file.name, content: r.result.split(',')[1], content_type: file.type || 'application/octet-stream' });
      r.onerror = rej;
      r.readAsDataURL(file);
    });
  }

  const segLabel = _ldrBcSeg === 'specific'
    ? specificEmail
    : _ldrBcSeg === 'custom_group'
      ? `grup "${(_ldrBcGroups || []).find(g => g.id === groupId)?.name || groupId}"`
      : 'semua siswa aktif';
  if (!confirm(`Kirim email ke ${segLabel}?\n\nSubjek: ${subject}`)) return;

  if (sendBtn) { sendBtn.disabled = true; sendBtn.textContent = 'Mengirim…'; }
  if (statusEl) { statusEl.textContent = ''; statusEl.style.color = '#6B7280'; }

  try {
    const session = (await _supabase?.auth.getSession())?.data?.session;
    const payload = { cohort_id: c.id, segment: _ldrBcSeg, subject, body };
    if (_ldrBcSeg === 'specific')     payload.specific_email = specificEmail;
    if (_ldrBcSeg === 'custom_group') payload.group_id       = groupId;
    if (attachment)                   payload.attachment      = attachment;

    const res = await fetch(`${SUPA_URL}/functions/v1/send-leader-broadcast`, {
      method:  'POST',
      headers: { 'Authorization': `Bearer ${session?.access_token || ''}`, 'Content-Type': 'application/json' },
      body:    JSON.stringify(payload),
    });
    const json = await res.json();

    if (res.ok) {
      const failMsg  = json.failed?.length ? ` Gagal: ${json.failed.length}.${json.fail_reasons?.[0] ? ' (' + json.fail_reasons[0] + ')' : ''}` : '';
      const toList   = (json.recipients || []).join(', ');
      const idHint   = json.resend_ids?.[0] ? ` ID Resend: ${json.resend_ids[0]}.` : '';
      const fromHint = json.from ? ` Dari: ${json.from}.` : '';
      const spamNote = json.sent > 0 ? ' Cek folder spam/promosi jika tidak masuk inbox.' : '';
      if (statusEl) {
        statusEl.textContent = `Diterima Resend (${json.sent}/${json.total_targets || json.sent}) → ${toList || '—'}.${fromHint}${idHint}${failMsg}${spamNote}`;
        statusEl.style.color = json.failed?.length ? '#B45309' : '#1A7A46';
      }
      ['subject','body'].forEach(f => { const el = document.getElementById(pfx + f); if (el) el.value = ''; });
      if (_ldrBcSeg === 'specific') {
        const s = document.getElementById(pfx + 'specific-search'); if (s) s.value = '';
        const h = document.getElementById(pfx + 'specific-email');  if (h) h.value = '';
      }
      if (fileInput) { fileInput.value = ''; const inf = document.getElementById(pfx + 'attachment-info'); if (inf) inf.textContent = ''; }
    } else {
      if (statusEl) statusEl.textContent = `Error: ${json.error || res.status}`;
    }
  } catch (e) {
    if (statusEl) statusEl.textContent = 'Gagal mengirim. Coba lagi.';
  }
  if (sendBtn) { sendBtn.disabled = false; sendBtn.textContent = 'Kirim Email'; }
}

// ── Cohort-tab panel wrappers (prefix: 'ldr-bc-') ────────────────────────────
async function ldrBcInit() {
  const c = _cohortState?.primaryMentorCohort;
  if (!c) return;
  ldrBcSetSeg('all_cohort');
  ['ldr-bc-subject','ldr-bc-body','ldr-bc-specific-search','ldr-bc-specific-email'].forEach(id => {
    const el = document.getElementById(id); if (el) el.value = '';
  });
  const fi = document.getElementById('ldr-bc-attachment');   if (fi) fi.value = '';
  const info = document.getElementById('ldr-bc-attachment-info'); if (info) info.textContent = '';
  const st   = document.getElementById('ldr-bc-status');     if (st) { st.textContent = ''; st.style.color = '#6B7280'; }
  await Promise.all([ldrBcLoadStudents(), ldrGroupLoad()]);
}
function ldrBcSetSeg(seg)              { _ldrEmailSetSeg(seg, 'ldr-bc-'); }
function ldrBcSearchStudent(query)     { _ldrEmailSearchStudent(query, 'ldr-bc-specific-dropdown', 'ldr-bc-specific-email'); }
function ldrBcSelectStudent(e, n)      { _ldrEmailSelectStudent(e, n, 'ldr-bc-specific-dropdown', 'ldr-bc-specific-email'); }
async function ldrBcSend()             { return _ldrEmailSend('ldr-bc-'); }

async function ldrBcLoadStudents() {
  const c = _cohortState?.primaryMentorCohort;
  if (!c || !_supabase) return;
  const { data } = await _supabase.rpc('cohort_student_directory', { p_cohort: c.id });
  _ldrBcStudents = (data || []).filter(s => s.email && s.status === 'active');
}

function ldrBcSearchStudent(query) {
  const dropdown = document.getElementById('ldr-bc-specific-dropdown');
  const hidden   = document.getElementById('ldr-bc-specific-email');
  if (!dropdown) return;
  if (hidden) hidden.value = '';
  const q = query.trim().toLowerCase();
  if (!q) { dropdown.style.display = 'none'; return; }
  const matches = (_ldrBcStudents || []).filter(u =>
    (u.display_name || '').toLowerCase().includes(q) || (u.email || '').toLowerCase().includes(q)
  ).slice(0, 10);
  if (!matches.length) { dropdown.style.display = 'none'; return; }
  const esc = s => (s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/"/g,'&quot;');
  dropdown.innerHTML = matches.map(u => {
    const name  = u.display_name || u.email;
    const safeE = u.email.replace(/\\/g,'\\\\').replace(/'/g,"\\'");
    const safeN = name.replace(/\\/g,'\\\\').replace(/'/g,"\\'");
    return `<div style="padding:9px 12px;cursor:pointer;border-bottom:1px solid #F3F4F6;" onmousedown="ldrBcSelectStudent('${safeE}','${safeN}')">
      <div style="font-size:.78rem;font-weight:700;color:#1A1A1A;">${esc(name)}</div>
      <div style="font-size:.68rem;color:#6B7280;">${esc(u.email)}</div>
    </div>`;
  }).join('');
  dropdown.style.display = 'block';
}

function ldrBcSelectStudent(email, name) {
  const search = document.getElementById('ldr-bc-specific-search');
  const hidden = document.getElementById('ldr-bc-specific-email');
  const dd     = document.getElementById('ldr-bc-specific-dropdown');
  if (search) search.value = name + ' <' + email + '>';
  if (hidden) hidden.value = email;
  if (dd)     dd.style.display = 'none';
}

document.addEventListener('click', e => {
  // Close any open leader-email autocomplete dropdowns
  ['ldr-bc-specific-wrap', 'hbdbc-specific-wrap'].forEach(wrapId => {
    const wrap = document.getElementById(wrapId);
    if (wrap && !wrap.contains(e.target)) {
      const ddId = wrapId.replace('-wrap', '-dropdown');
      const dd = document.getElementById(ddId);
      if (dd) dd.style.display = 'none';
    }
  });
});

document.addEventListener('change', e => {
  const infoMap = { 'ldr-bc-attachment': 'ldr-bc-attachment-info', 'hbdbc-attachment': 'hbdbc-attachment-info' };
  const infoId = infoMap[e.target.id];
  if (!infoId) return;
  const info = document.getElementById(infoId);
  if (info) {
    const file = e.target.files?.[0];
    info.textContent = file ? `${file.name} (${(file.size / 1024).toFixed(1)} KB)` : '';
  }
});

// ─── Group management ─────────────────────────────────────────────────────────

async function ldrGroupLoad() {
  const c = _cohortState?.primaryMentorCohort;
  if (!c || !_supabase) return;
  const { data } = await _supabase.rpc('leader_get_email_groups', { p_cohort: c.id });
  _ldrBcGroups = data || [];
  ldrGroupRender();
  cohortDirGroupRender();
  cohortDirSelGroupRebuild();
  // Sync group dropdowns in both panels
  _ldrEmailRebuildGroupSelect('ldr-bc-');
  _ldrEmailRebuildGroupSelect('hbdbc-');
}

function ldrGroupRender() {
  const wrap = document.getElementById('ldr-group-list');
  if (!wrap) return;
  const groups = _ldrBcGroups || [];
  if (!groups.length) {
    wrap.innerHTML = '<div class="cohort-muted" style="font-size:.75rem;">Belum ada grup. Buat grup baru di atas.</div>';
    return;
  }
  const esc = s => (s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/"/g,'&quot;');
  wrap.innerHTML = groups.map(g => `
    <div id="ldr-grp-${g.id}" style="border:1px solid #E5E7EB;border-radius:8px;margin-bottom:10px;overflow:hidden;">
      <div style="display:flex;align-items:center;justify-content:space-between;padding:10px 12px;background:#F9FAFB;gap:8px;flex-wrap:wrap;">
        <div>
          <span style="font-size:.82rem;font-weight:700;color:#1A1A1A;">${esc(g.name)}</span>
          <span style="font-size:.68rem;color:#6B7280;margin-left:6px;">${g.member_count} siswa</span>
        </div>
        <div style="display:flex;gap:6px;flex-shrink:0;">
          <button type="button" class="cohort-btn secondary" style="padding:4px 10px;font-size:.65rem;" onclick="ldrGroupToggleMembers('${g.id}')">Anggota</button>
          <button type="button" class="cohort-btn secondary" style="padding:4px 10px;font-size:.65rem;" onclick="ldrGroupRename('${g.id}','${esc(g.name)}')">Ganti nama</button>
          <button type="button" class="cohort-btn secondary" style="padding:4px 10px;font-size:.65rem;color:#B5202A;border-color:#B5202A;" onclick="ldrGroupDelete('${g.id}','${esc(g.name)}')">Hapus</button>
        </div>
      </div>
      <div id="ldr-grp-members-${g.id}" style="display:none;padding:10px 12px;border-top:1px solid #E5E7EB;">
        <div class="cohort-muted" style="font-size:.72rem;">Memuat anggota…</div>
      </div>
    </div>
  `).join('');
}

async function ldrGroupCreate() {
  const inp  = document.getElementById('ldr-group-new-name');
  const name = (inp?.value || '').trim();
  const c    = _cohortState?.primaryMentorCohort;
  if (!name) { alert('Masukkan nama grup.'); return; }
  if (!c)    { alert('Tidak ada kohort aktif.'); return; }
  try {
    const { error } = await _supabase.rpc('leader_create_email_group', { p_cohort: c.id, p_name: name });
    if (error) throw error;
    if (inp) inp.value = '';
    await ldrGroupLoad();
  } catch (e) {
    alert('Gagal membuat grup: ' + (e.message || e));
  }
}

async function ldrGroupRename(groupId, currentName) {
  const newName = prompt('Nama baru untuk grup ini:', currentName);
  if (!newName || newName.trim() === currentName) return;
  try {
    const { error } = await _supabase.rpc('leader_rename_email_group', { p_group: groupId, p_name: newName.trim() });
    if (error) throw error;
    await ldrGroupLoad();
  } catch (e) {
    alert('Gagal mengganti nama: ' + (e.message || e));
  }
}

async function ldrGroupDelete(groupId, groupName) {
  if (!confirm(`Hapus grup "${groupName}"? Semua anggota akan dihapus dari grup ini.`)) return;
  try {
    const { error } = await _supabase.rpc('leader_delete_email_group', { p_group: groupId });
    if (error) throw error;
    await ldrGroupLoad();
  } catch (e) {
    alert('Gagal menghapus grup: ' + (e.message || e));
  }
}

async function ldrGroupToggleMembers(groupId) {
  const wrap = document.getElementById('ldr-grp-members-' + groupId);
  if (!wrap) return;
  if (wrap.style.display !== 'none') { wrap.style.display = 'none'; return; }
  wrap.style.display = 'block';
  await ldrGroupLoadMembers(groupId);
}

async function ldrGroupLoadMembers(groupId) {
  const wrap = document.getElementById('ldr-grp-members-' + groupId);
  if (!wrap) return;
  try {
    const { data, error } = await _supabase.rpc('leader_get_email_group_members', { p_group: groupId });
    if (error) throw error;
    const members = data || [];
    const esc = s => (s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/"/g,'&quot;');

    // Build student options for "add member" dropdown (exclude existing members)
    const memberIds = new Set(members.map(m => m.user_id));
    const available = (_ldrBcStudents || []).filter(s => !memberIds.has(s.user_id));

    const addRow = available.length
      ? `<div style="display:flex;gap:6px;margin-bottom:10px;flex-wrap:wrap;">
           <select id="ldr-grp-add-sel-${groupId}" class="cohort-input" style="flex:1;min-width:120px;margin:0;font-size:.72rem;">
             <option value="">— Tambah siswa —</option>
             ${available.map(s => `<option value="${esc(s.user_id)}">${esc(s.display_name || s.email)}</option>`).join('')}
           </select>
           <button type="button" class="cohort-btn secondary" style="padding:5px 10px;font-size:.68rem;" onclick="ldrGroupAddMember('${groupId}')">Tambah</button>
         </div>`
      : `<div class="cohort-muted" style="font-size:.7rem;margin-bottom:10px;">Semua siswa aktif sudah ada di grup ini.</div>`;

    const memberRows = members.length
      ? members.map(m => `
          <div style="display:flex;align-items:center;justify-content:space-between;padding:5px 0;border-bottom:1px solid #F3F4F6;">
            <div style="cursor:pointer;" onclick="cohortOpenStudentDrawer('${m.user_id}','${esc(m.display_name || m.email || '')}','${esc(m.email || '')}')">
              <span style="font-size:.78rem;font-weight:600;color:#1A1A1A;">${esc(m.display_name || m.email)}</span>
              <span style="font-size:.65rem;color:#6B7280;margin-left:5px;">${esc(m.email)}</span>
            </div>
            <button type="button" class="cohort-btn secondary" style="padding:3px 8px;font-size:.62rem;color:#B5202A;border-color:#B5202A;" onclick="ldrGroupRemoveMember('${groupId}','${m.user_id}')">Hapus</button>
          </div>`
        ).join('')
      : '<div class="cohort-muted" style="font-size:.72rem;">Grup ini belum punya anggota.</div>';

    wrap.innerHTML = addRow + memberRows;
  } catch (e) {
    wrap.innerHTML = `<div class="cohort-muted" style="font-size:.72rem;color:#B5202A;">Gagal memuat: ${e.message || e}</div>`;
  }
}

async function ldrGroupAddMember(groupId) {
  const sel    = document.getElementById('ldr-grp-add-sel-' + groupId);
  const userId = sel?.value;
  if (!userId) return;
  try {
    const { error } = await _supabase.rpc('leader_add_email_group_member', { p_group: groupId, p_user_id: userId });
    if (error) throw error;
    await ldrGroupLoad();
    // Re-open the member list after reload
    const wrap = document.getElementById('ldr-grp-members-' + groupId);
    if (wrap) { wrap.style.display = 'block'; await ldrGroupLoadMembers(groupId); }
  } catch (e) {
    alert('Gagal menambah anggota: ' + (e.message || e));
  }
}

async function ldrGroupRemoveMember(groupId, userId) {
  try {
    const { error } = await _supabase.rpc('leader_remove_email_group_member', { p_group: groupId, p_user_id: userId });
    if (error) throw error;
    await ldrGroupLoad();
    const wrap = document.getElementById('ldr-grp-members-' + groupId);
    if (wrap) { wrap.style.display = 'block'; await ldrGroupLoadMembers(groupId); }
  } catch (e) {
    alert('Gagal menghapus anggota: ' + (e.message || e));
  }
}

// ─── Dashboard student roster + group creation ────────────────────────────────

let _hbdSiswaLoaded = false;

async function hbdSiswaProgressLoad(force) {
  const c = _cohortState?.primaryMentorCohort;
  if (!c || !_supabase) return;
  if (_hbdSiswaLoaded && !force) return;
  _hbdSiswaLoaded = true;

  const rowsEl = document.getElementById('hbd-siswa-rows');
  if (rowsEl) rowsEl.innerHTML = '<div class="cohort-muted" style="padding:16px;font-size:.75rem;">Memuat data siswa…</div>';

  const { data, error } = await _supabase.rpc('cohort_student_directory', { p_cohort: c.id });
  if (error) {
    if (rowsEl) rowsEl.innerHTML = `<div class="cohort-muted" style="padding:16px;font-size:.75rem;color:#B5202A;">Gagal memuat: ${error.message}</div>`;
    return;
  }

  const students = data || [];
  // Also update the shared cache used by email panels
  _ldrBcStudents = students.filter(s => s.email && s.status === 'active');

  if (!students.length) {
    if (rowsEl) rowsEl.innerHTML = '<div class="cohort-muted" style="padding:16px;font-size:.75rem;">Belum ada siswa di kohort ini.</div>';
    _hbdUpdateSelCount();
    return;
  }

  const esc      = s => (s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/"/g,'&quot;');
  const statusBadge = st => {
    const color = st === 'active' ? '#1A7A46' : st === 'paused' ? '#B45309' : '#9CA3AF';
    const label = st === 'active' ? 'Aktif'  : st === 'paused' ? 'Jeda'    : 'Keluar';
    return `<span style="font-size:.6rem;font-weight:700;color:${color};background:${color}18;border-radius:4px;padding:2px 6px;">${label}</span>`;
  };

  if (rowsEl) {
    rowsEl.innerHTML = `
      <table style="width:100%;border-collapse:collapse;font-size:.75rem;">
        <thead>
          <tr style="border-bottom:2px solid #F3F4F6;background:#F9FAFB;">
            <th style="padding:8px 10px;text-align:left;width:28px;">
              <input type="checkbox" id="hbd-stu-chk-all" onchange="hbdToggleAllStudents(this.checked)" title="Pilih semua" style="cursor:pointer;">
            </th>
            <th style="padding:8px 10px;text-align:left;color:#6B7280;font-size:.65rem;font-weight:700;text-transform:uppercase;letter-spacing:.04em;">Nama</th>
            <th style="padding:8px 10px;text-align:left;color:#6B7280;font-size:.65rem;font-weight:700;text-transform:uppercase;letter-spacing:.04em;">Email</th>
            <th style="padding:8px 10px;text-align:center;color:#6B7280;font-size:.65rem;font-weight:700;text-transform:uppercase;letter-spacing:.04em;">Status</th>
            <th style="padding:8px 10px;text-align:right;color:#6B7280;font-size:.65rem;font-weight:700;text-transform:uppercase;letter-spacing:.04em;">Skor</th>
          </tr>
        </thead>
        <tbody>
          ${students.map(s => `
            <tr style="border-bottom:1px solid #F3F4F6;">
              <td style="padding:8px 10px;">
                <input type="checkbox" class="hbd-stu-chk" data-uid="${esc(s.user_id)}" data-email="${esc(s.email)}"
                  onchange="hbdUpdateSelCount()" style="cursor:pointer;" ${s.status !== 'active' ? 'disabled title="Hanya siswa aktif yang bisa ditambah ke grup"' : ''}>
              </td>
              <td style="padding:8px 10px;font-weight:600;color:#1A1A1A;max-width:140px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;cursor:pointer;" onclick="cohortOpenStudentDrawer('${esc(s.user_id)}','${esc(s.display_name || s.email || '')}','${esc(s.email || '')}')">${esc(s.display_name || s.email)}</td>
              <td style="padding:8px 10px;color:#6B7280;max-width:180px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${esc(s.email)}</td>
              <td style="padding:8px 10px;text-align:center;">${statusBadge(s.status)}</td>
              <td style="padding:8px 10px;text-align:right;font-weight:700;color:#1A1A1A;">${Math.round(s.engagement_score || 0)}</td>
            </tr>`).join('')}
        </tbody>
      </table>`;
  }
  _hbdUpdateSelCount();
}

function hbdUpdateSelCount() { _hbdUpdateSelCount(); }

function _hbdUpdateSelCount() {
  const checked = document.querySelectorAll('.hbd-stu-chk:checked').length;
  const el = document.getElementById('hbd-stu-sel-count');
  if (el) el.textContent = checked + ' dipilih';
}

function hbdToggleAllStudents(checked) {
  document.querySelectorAll('.hbd-stu-chk:not(:disabled)').forEach(cb => { cb.checked = checked; });
  _hbdUpdateSelCount();
}

async function hbdCreateGroupFromSelection() {
  const c    = _cohortState?.primaryMentorCohort;
  const name = (document.getElementById('hbd-stu-group-name')?.value || '').trim();
  const statusEl = document.getElementById('hbd-stu-group-status');

  if (!c)    { if (statusEl) statusEl.textContent = 'Tidak ada kohort aktif.'; return; }
  if (!name) { if (statusEl) statusEl.textContent = 'Masukkan nama grup terlebih dahulu.'; return; }

  const checked  = [...document.querySelectorAll('.hbd-stu-chk:checked')];
  if (!checked.length) { if (statusEl) statusEl.textContent = 'Pilih minimal satu siswa.'; return; }

  if (statusEl) { statusEl.textContent = 'Membuat grup…'; statusEl.style.color = '#6B7280'; }

  try {
    // Create the group
    const { data: groupId, error: cErr } = await _supabase.rpc('leader_create_email_group', { p_cohort: c.id, p_name: name });
    if (cErr) throw cErr;

    // Add all selected students (ignore individual failures — duplicates etc.)
    await Promise.all(checked.map(async cb => {
      try { await _supabase.rpc('leader_add_email_group_member', { p_group: groupId, p_user_id: cb.dataset.uid }); }
      catch (_) {}
    }));

    // Reset UI
    const inp = document.getElementById('hbd-stu-group-name');
    if (inp) inp.value = '';
    document.querySelectorAll('.hbd-stu-chk:checked').forEach(cb => { cb.checked = false; });
    const allChk = document.getElementById('hbd-stu-chk-all');
    if (allChk) allChk.checked = false;
    _hbdUpdateSelCount();

    // Reload groups so both panels' dropdowns update
    await ldrGroupLoad();

    if (statusEl) {
      statusEl.textContent = `Grup "${name}" berhasil dibuat dengan ${checked.length} siswa.`;
      statusEl.style.color = '#1A7A46';
    }
  } catch (e) {
    if (statusEl) { statusEl.textContent = 'Gagal: ' + (e.message || e); statusEl.style.color = '#B5202A'; }
  }
}

// ─── Dashboard email panel wrappers (prefix: 'hbdbc-') ───────────────────────

async function hbdbcInit() {
  const c = _cohortState?.primaryMentorCohort;
  if (!c) return;
  hbdbcSetSeg('all_cohort');
  ['hbdbc-subject','hbdbc-body','hbdbc-specific-search','hbdbc-specific-email'].forEach(id => {
    const el = document.getElementById(id); if (el) el.value = '';
  });
  const fi   = document.getElementById('hbdbc-attachment');       if (fi) fi.value = '';
  const info = document.getElementById('hbdbc-attachment-info');  if (info) info.textContent = '';
  const st   = document.getElementById('hbdbc-status');           if (st) { st.textContent = ''; st.style.color = '#6B7280'; }
  // Students may already be cached from the roster load; groups need a fresh pull
  if (!_ldrBcStudents) await ldrBcLoadStudents();
  await ldrGroupLoad();
}
function hbdbcSetSeg(seg)          { _ldrEmailSetSeg(seg, 'hbdbc-'); }
function hbdbcSearchStudent(query) { _ldrEmailSearchStudent(query, 'hbdbc-specific-dropdown', 'hbdbc-specific-email'); }
async  function hbdbcSend()        { return _ldrEmailSend('hbdbc-'); }

// ── Extension Linking ─────────────────────────────────────────────────────────

let _extLinkTimer = null;

async function openExtensionLink() {
  document.getElementById('dash-topbar-menu').classList.remove('open');
  const modal = document.getElementById('ext-link-modal');
  modal.style.display = 'flex';
  document.getElementById('ext-link-code-wrap').style.display = 'none';
  document.getElementById('ext-link-loading').style.display   = 'block';
  document.getElementById('ext-link-error').style.display     = 'none';
  document.getElementById('ext-link-regen-btn').style.display = 'none';
  if (_extLinkTimer) clearInterval(_extLinkTimer);
  await extLinkGenerate();
}

async function extLinkGenerate() {
  document.getElementById('ext-link-loading').style.display   = 'block';
  document.getElementById('ext-link-code-wrap').style.display = 'none';
  document.getElementById('ext-link-error').style.display     = 'none';
  document.getElementById('ext-link-regen-btn').style.display = 'none';

  try {
    const { data: { session } } = await _supabase.auth.getSession();
    if (!session) throw new Error('Tidak ada sesi aktif. Silakan login ulang.');

    const { data: code, error } = await _supabase.rpc('create_extension_code', {
      p_access_token:  session.access_token,
      p_refresh_token: session.refresh_token,
    });
    if (error) throw new Error(error.message);

    document.getElementById('ext-link-code').textContent       = code;
    document.getElementById('ext-link-loading').style.display  = 'none';
    document.getElementById('ext-link-code-wrap').style.display = 'block';
    document.getElementById('ext-link-regen-btn').style.display = 'block';
    document.getElementById('ext-link-copy-btn').textContent   = 'Salin Kode';

    // Countdown timer
    let secs = 15 * 60;
    if (_extLinkTimer) clearInterval(_extLinkTimer);
    _extLinkTimer = setInterval(() => {
      secs--;
      const m = String(Math.floor(secs / 60)).padStart(2, '0');
      const s = String(secs % 60).padStart(2, '0');
      document.getElementById('ext-link-ttl').textContent = `${m}:${s}`;
      if (secs <= 0) {
        clearInterval(_extLinkTimer);
        document.getElementById('ext-link-code').textContent = '——————';
        document.getElementById('ext-link-ttl').textContent  = 'Kadaluarsa';
        document.getElementById('ext-link-regen-btn').style.display = 'block';
      }
    }, 1000);

  } catch (e) {
    document.getElementById('ext-link-loading').style.display = 'none';
    document.getElementById('ext-link-error').textContent     = e.message || 'Gagal membuat kode.';
    document.getElementById('ext-link-error').style.display   = 'block';
    document.getElementById('ext-link-regen-btn').style.display = 'block';
  }
}

function extLinkCopyCode() {
  const code = document.getElementById('ext-link-code').textContent.trim();
  if (!code || code.includes('—')) return;
  navigator.clipboard.writeText(code).then(() => {
    document.getElementById('ext-link-copy-btn').textContent = 'Tersalin!';
    setTimeout(() => {
      document.getElementById('ext-link-copy-btn').textContent = 'Salin Kode';
    }, 2000);
  });
}

// ════════════════════════════════════════════════════════════
//  USER JOURNEY — progressive Discover → Deep Dive funnel
// ════════════════════════════════════════════════════════════
const JOURNEY_LS_KEY = 'larisid_journey_v1';
const JOURNEY_HINT_SESSION_KEY = 'larisid_journey_hint_sess';
const JOURNEY_BEGINNER_DISCOVER_CAP = 6;

function journeyLoad() {
  // Simulation gets a true blank-slate journey, independent of the admin's
  // real Deep Dive/tracking history, instead of reading real localStorage.
  if (_admSimulateNewUser) return _admSimShadowJourney || (_admSimShadowJourney = {});
  try { return JSON.parse(localStorage.getItem(JOURNEY_LS_KEY) || '{}'); } catch { return {}; }
}

function journeySave(patch) {
  if (_admSimulateNewUser) {
    _admSimShadowJourney = { ..._admSimShadowJourney, ...patch, updatedAt: Date.now() };
    return _admSimShadowJourney;
  }
  const next = { ...journeyLoad(), ...patch, updatedAt: Date.now() };
  try { localStorage.setItem(JOURNEY_LS_KEY, JSON.stringify(next)); } catch (_) {}
  void journeySyncRemote(next);
  return next;
}

function journeyBypassGating() {
  // SIMULATION ONLY — do not change admin/leader bypass outside this flag.
  // A simulated new user must go through real journey-tier gating so the
  // beginner hints/progressive disclosure actually fire for the admin.
  if (_admSimulateNewUser) return false;
  if (typeof isPlatformAdmin === 'function' && isPlatformAdmin()) return true;
  if (typeof _effectiveLeaderMode === 'function' && _effectiveLeaderMode()) return true;
  return false;
}

function userJourneyTier() {
  if (journeyBypassGating()) return 3;
  const j = journeyLoad();
  if (userHasTrackedProducts()) return 2;
  if ((j.deepdiveCount || 0) >= 3) return 3;
  if ((j.deepdiveCount || 0) >= 1) return 1;
  return 0;
}

function isJourneyBeginner() {
  return userJourneyTier() <= 1;
}

function journeyHintAllowed() {
  try { return !sessionStorage.getItem(JOURNEY_HINT_SESSION_KEY); } catch { return true; }
}

function journeyMarkHintShown() {
  try { sessionStorage.setItem(JOURNEY_HINT_SESSION_KEY, '1'); } catch (_) {}
}

async function journeySyncRemote(j) {
  if (!_supabase || !currentUser) return;
  try {
    await _supabase.from('user_journey_stats').upsert({
      user_id: currentUser.id,
      deepdive_count: j.deepdiveCount || 0,
      first_deepdive_at: j.firstDeepDiveAt || null,
      last_discover_at: j.lastDiscoverAt || null,
      full_deepdive_unlocked: !!j.fullDeepDive,
      updated_at: new Date().toISOString(),
    }, { onConflict: 'user_id' });
  } catch (_) {}
}

function journeyLog(eventType, metadata) {
  void logUserEvent(eventType, { journey_tier: userJourneyTier(), ...(metadata || {}) });
}

let _lidDiveSeen = 0; // dives this session, for first_dive / second_dive steps

function journeyMarkDiscoverView() {
  journeySave({ lastDiscoverAt: new Date().toISOString() });
  funnelStep('first_search', { source: 'discover' });
  journeyLog('discover_view', {});
  refreshDataFreshnessStamp();
}

// "Data pasar discan X" stamp — our data is fresh daily; say so (habit anchor).
async function refreshDataFreshnessStamp() {
  const el = document.getElementById('dsc-freshness');
  if (!el || el.dataset.loaded || !_supabase) return;
  el.dataset.loaded = '1';
  try {
    const { data } = await _supabase
      .from('listings_latest')
      .select('scraped_at')
      .order('scraped_at', { ascending: false })
      .limit(1);
    const at = data && data[0] && data[0].scraped_at;
    if (!at) return;
    const d = new Date(at);
    const hrs = Math.max(1, Math.round((Date.now() - d.getTime()) / 36e5));
    el.textContent = hrs <= 36
      ? `Data pasar terakhir discan ${hrs} jam lalu · di-update tiap hari`
      : `Data pasar terakhir discan ${d.toLocaleDateString('id-ID', { day: 'numeric', month: 'short' })} · di-update tiap hari`;
  } catch (_) {}
}

function journeyNormCardKey(key) {
  if (!key) return '';
  const s = String(key);
  if (s.includes('__')) return s;
  const idx = s.lastIndexOf('_');
  if (idx <= 0) return s;
  return s.slice(0, idx) + '__' + s.slice(idx + 1);
}

function journeyPushViewedCard(key) {
  const norm = journeyNormCardKey(key);
  if (!norm) return;
  const j = journeyLoad();
  const keys = [norm, ...(j.viewedCardKeys || []).filter(k => k !== norm)].slice(0, 12);
  journeySave({ viewedCardKeys: keys });
}

function journeyMarkDiscoverClick(key) {
  journeyPushViewedCard(key);
  journeySave({ lastDiscoverClick: key, lastDiscoverAt: new Date().toISOString() });
  journeyLog('discover_card_click', { item_key: key });
}

function journeyFindListingByKey(key) {
  const norm = journeyNormCardKey(key);
  const [itemId, shopId] = norm.split('__');
  if (!itemId || !shopId) return null;
  const match = r => String(r.item_id) === itemId && String(r.shop_id) === shopId;
  return (_dscAllListings || []).find(match)
    || (_dscBrowsePool || []).find(match)
    || (_dscFiltered || []).find(match)
    || null;
}

function journeyGetLastViewedCards(n) {
  const limit = n || 3;
  const j = journeyLoad();
  const seen = journeySeenProducts();
  const keys = [...(j.viewedCardKeys || [])];
  Object.entries(seen)
    .sort((a, b) => new Date(b[1].seenAt || 0) - new Date(a[1].seenAt || 0))
    .forEach(([k]) => {
      const norm = journeyNormCardKey(k);
      if (norm && !keys.includes(norm)) keys.push(norm);
    });
  return keys.slice(0, limit).map(key => {
    const snap = seen[key] || seen[key.replace(/__/g, '_')];
    const listing = journeyFindListingByKey(key);
    const name = snap?.name || listing?.product_name || '';
    if (!name && !listing) return null;
    return {
      key,
      name: name || 'Produk',
      image: snap?.image_url || listing?.image_url || '',
      price: snap?.price || listing?.price || 0,
      category: listing?.category || '',
    };
  }).filter(Boolean);
}

function journeyEmptyRecoPlan() {
  const j = journeyLoad();
  if (!j.lastDiscoverAt) return { mode: 'discover' };
  if (!userHasTrackedProducts()) {
    const items = journeyGetLastViewedCards(3);
    return items.length ? { mode: 'products', items } : { mode: 'discover' };
  }
  const items = journeyGetLastViewedCards(3);
  return items.length ? { mode: 'products', items } : { mode: 'discover' };
}

function journeyRenderEmptyReco(containerId, view) {
  const el = document.getElementById(containerId);
  if (!el) return;
  const plan = journeyEmptyRecoPlan();
  const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;');
  if (plan.mode === 'discover') {
    el.innerHTML = `
      <p class="nu-empty-reco-msg">Temukan peluang jualan di Discover — data nyata dari ribuan listing Shopee.</p>
      <button type="button" class="nu-empty-btn" onclick="switchDashView('discover')">Buka Discover</button>`;
    return;
  }
  const items = plan.items || [];
  if (!items.length) {
    el.innerHTML = `<button type="button" class="nu-empty-btn" onclick="switchDashView('discover')">Buka Discover</button>`;
    return;
  }
  const cta = view === 'ai' ? 'mulai analisis' : 'buka Deep Dive';
  el.innerHTML = `
    <p class="nu-empty-reco-msg">Ini produk yang baru kamu lihat — ketuk untuk ${cta}.</p>
    <div class="hbd-nu-reco-grid">
      ${items.map(it => `
        <div class="hbd-nu-reco-card" role="button" tabindex="0" onclick="dscOpenDeepDive('${esc(it.key)}')">
          <div class="hbd-nu-reco-thumb"><img src="${esc(it.image)}" onerror="this.style.display='none'" alt=""></div>
          <div class="hbd-nu-reco-meta">
            <div class="hbd-nu-reco-name">${esc((it.name || '').slice(0, 40))}</div>
            <div class="hbd-nu-reco-cat">${it.price ? 'Rp ' + Math.round(it.price).toLocaleString('id-ID') : '—'}</div>
          </div>
        </div>`).join('')}
    </div>
    <a style="font-size:.75rem;color:#B5202A;font-weight:600;cursor:pointer;" onclick="switchDashView('discover')">Cari produk lain di Discover &rarr;</a>`;
}

function journeyMarkDeepDiveOpen(source, listing) {
  const j = journeyLoad();
  const count = (j.deepdiveCount || 0) + 1;
  journeySave({
    deepdiveCount: count,
    firstDeepDiveAt: j.firstDeepDiveAt || new Date().toISOString(),
    lastDeepDiveKey: listing ? `${listing.item_id}__${listing.shop_id}` : null,
  });
  journeyRecordSeenProduct(listing);
  funnelStep(_lidDiveSeen++ === 0 ? 'first_dive' : 'second_dive');
  // NB: the deepdive_open funnel/feed row is emitted once by the caller via
  // cohortLogActivity (which carries cohort_id + journey_tier + source), so we
  // deliberately do NOT log a second row here.
}

function journeySeenProducts() {
  return journeyLoad().seenProducts || {};
}

function journeyRecordSeenProduct(listing) {
  if (!listing || listing.item_id == null) return;
  const key = `${listing.item_id}__${listing.shop_id}`;
  journeyPushViewedCard(key);
  const seen = { ...journeySeenProducts() };
  seen[key] = {
    name: listing.product_name || listing.name || '',
    image_url: listing.image_url || listing.image || '',
    price: listing.price || listing.medianPrice || 0,
    total_sold: listing.total_sold || 0,
    seenAt: new Date().toISOString(),
  };
  journeySave({ seenProducts: seen });
}

function journeyTodayKey() {
  return new Date().toISOString().slice(0, 10);
}

function journeyIsReturningUser() {
  const j = journeyLoad();
  return userJourneyTier() >= 1 && !!(j.lastBerandaAt || j.lastDiscoverAt);
}

function journeyIsNewDaySinceLastBeranda() {
  const j = journeyLoad();
  // Never visited = a FIRST visit, not a return (callers that want to include
  // first visits already OR with !lastBerandaAt explicitly). Returning true
  // here logged journey_return_strip{return_day:true} minutes after signup.
  if (!j.lastBerandaAt) return false;
  return j.lastBerandaAt.slice(0, 10) !== journeyTodayKey();
}

function journeyMarkBerandaVisit() {
  journeySave({ lastBerandaAt: new Date().toISOString() });
}

async function journeyFetchListingSnapshot(key) {
  const [itemId, shopId] = key.split('__');
  const cached = (_dscAllListings || []).find(r => String(r.item_id) === itemId && String(r.shop_id) === shopId);
  if (cached) return cached;
  if (!_supabase) return null;
  try {
    const { data } = await _supabase.from('listings')
      .select('item_id,shop_id,price,total_sold,product_name,image_url,scraped_at')
      .eq('item_id', itemId).eq('shop_id', shopId)
      .order('scraped_at', { ascending: false }).limit(1).maybeSingle();
    return data;
  } catch { return null; }
}

async function journeyCompareSeenProducts() {
  const seen = journeySeenProducts();
  const keys = Object.keys(seen).slice(0, 5);
  if (!keys.length) return [];
  const rows = await Promise.all(keys.map(async key => {
    const prev = seen[key];
    const curr = await journeyFetchListingSnapshot(key);
    if (!curr || !prev) return null;
    const name = (prev.name || curr.product_name || '').split(' ').slice(0, 4).join(' ') || 'Produk';
    const priceDelta = Math.round((curr.price || 0) - (prev.price || 0));
    const soldDelta = Math.max(0, (curr.total_sold || 0) - (prev.total_sold || 0));
    if (soldDelta > 0) {
      return { type: 'sold', name, image: curr.image_url || prev.image_url, msg: `Penjualan naik +${soldDelta.toLocaleString('id-ID')} unit sejak kunjungan terakhir`, key };
    }
    if (Math.abs(priceDelta) >= 500) {
      const dir = priceDelta > 0 ? 'naik' : 'turun';
      return { type: 'price', name, image: curr.image_url || prev.image_url, msg: `Harga ${dir} ke Rp ${Math.round(curr.price || 0).toLocaleString('id-ID')}`, key };
    }
    return null;
  }));
  return rows.filter(Boolean);
}

function journeyRefreshSeenSnapshots() {
  const seen = journeySeenProducts();
  const keys = Object.keys(seen);
  if (!keys.length) return;
  void Promise.all(keys.map(async key => {
    const curr = await journeyFetchListingSnapshot(key);
    if (!curr) return;
    seen[key] = {
      ...seen[key],
      price: curr.price || 0,
      total_sold: curr.total_sold || 0,
      name: curr.product_name || seen[key].name,
      image_url: curr.image_url || seen[key].image_url,
      seenAt: new Date().toISOString(),
    };
  })).then(() => journeySave({ seenProducts: seen }));
}

async function journeyRenderReturnStrip() {
  const strip = document.getElementById('hbd-alerts-strip');
  if (!strip) return;
  if (typeof _effectiveLeaderMode === 'function' && _effectiveLeaderMode()) return;
  if (journeyBypassGating()) return;
  if (userJourneyTier() < 1) {
    strip.style.display = 'none';
    strip.innerHTML = '';
    return;
  }

  const items = [];
  const isReturnDay = journeyIsNewDaySinceLastBeranda();
  const seenKeys = Object.keys(journeySeenProducts());
  const isTracker = userHasTrackedProducts();

  if (isTracker) {
    // Trackers get the strongest payoff: what changed on THEIR products.
    const trkDeltas = await trkFetchDeltas();
    trkDeltas.slice(0, 2).forEach(d => items.push({
      type: d.soldDelta > 0 ? 'sold' : 'price',
      name: d.name,
      image: d.image,
      msg: trkDeltaMsg(d),
      cta: 'Lihat produkmu',
      onclick: "switchDashView('tracker')",
    }));
    if (trkDeltas.length) { trkAckDeltas(); }
  } else if (isReturnDay && seenKeys.length) {
    const deltas = await journeyCompareSeenProducts();
    items.push(...deltas.slice(0, 2));
  }

  if (typeof allProducts !== 'undefined' && allProducts && allProducts.length) {
    const n = recBuildDailyRandom(allProducts, currentUser && currentUser.id, 5, 6).length;
    if (n > 0 && (isReturnDay || !journeyLoad().lastBerandaAt)) {
      items.push({
        type: 'new',
        msg: `${n} produk baru untukmu hari ini di Discover`,
        cta: 'Buka Discover',
        onclick: "switchDashView('discover')",
      });
    }
  }

  if (!items.length) {
    strip.style.display = 'none';
    strip.innerHTML = '';
    return;
  }

  strip.style.display = 'block';
  strip.innerHTML = `<div class="hbd-journey-return">${items.map(it => {
    const cls = it.type === 'sold' ? 'is-up' : it.type === 'price' ? 'is-price' : '';
    const img = it.image ? `<img src="${it.image}" onerror="this.style.display='none'" alt="">` : '';
    const cta = it.cta ? `<span class="hbd-journey-return-cta" onclick="${it.onclick}">${it.cta} &rarr;</span>` : '';
    const open = it.key ? `onclick="dscOpenDeepDive('${it.key}')"` : (it.onclick ? `onclick="${it.onclick}"` : '');
    const label = it.name ? `<strong>${it.name}</strong> — ${it.msg}` : it.msg;
    return `<div class="hbd-journey-return-item ${cls}" style="cursor:pointer;" ${open}><div style="display:flex;align-items:center;gap:10px;flex:1;min-width:0;"><div>${img}</div><div>${label}</div></div>${cta}</div>`;
  }).join('')}</div>`;

  journeyMarkBerandaVisit();
  journeyRefreshSeenSnapshots();
  journeyLog('journey_return_strip', { item_count: items.length, return_day: isReturnDay });
}

