// Smoothly counts a Deep Dive simple-view metric from its current value to a
// new target instead of snapping. `fromZero` (set on first render of a new
// product) starts the count at 0; later streamed corrections glide from the
// value already on screen. Honors prefers-reduced-motion. `fmt` formats each
// frame's value into display text; optional `onFrame` mirrors the value onto a
// companion visual (e.g. the score bar). Pass target=null for non-numeric "—".
function ddAnimateNum(el, target, fmt, fromZero, onFrame, delay) {
  if (!el) return;
  if (el._cuRaf) { cancelAnimationFrame(el._cuRaf); el._cuRaf = null; }
  if (el._cuDelay) { clearTimeout(el._cuDelay); el._cuDelay = null; }
  const box = el.closest ? el.closest('.dd-smetric') : null;
  const clearBoxState = () => { if (box) box.classList.remove('dd-smetric--pending', 'dd-smetric--counting'); };
  if (target == null || !Number.isFinite(target)) {
    el._cuVal = null;
    el.textContent = fmt(target);
    if (onFrame) onFrame(0);
    clearBoxState();
    return;
  }
  const start = fromZero ? 0 : (Number.isFinite(el._cuVal) ? el._cuVal : 0);
  const reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (start === target || reduce) {
    el._cuVal = target;
    el.textContent = fmt(target);
    if (onFrame) onFrame(target);
    clearBoxState();
    return;
  }
  const runCount = () => {
    if (box) { box.classList.remove('dd-smetric--pending'); box.classList.add('dd-smetric--counting'); }
    const dur = 750, t0 = performance.now();
    const ease = t => 1 - Math.pow(1 - t, 3); // easeOutCubic
    const step = now => {
      const t = Math.min(1, (now - t0) / dur);
      const v = start + (target - start) * ease(t);
      el._cuVal = v;
      el.textContent = fmt(v);
      if (onFrame) onFrame(v);
      if (t < 1) { el._cuRaf = requestAnimationFrame(step); }
      else { el._cuVal = target; el.textContent = fmt(target); if (onFrame) onFrame(target); el._cuRaf = null; if (box) box.classList.remove('dd-smetric--counting'); }
    };
    el._cuRaf = requestAnimationFrame(step);
  };
  // A3: stagger — start blank (box pending) and begin counting after `delay` ms.
  if (delay && delay > 0) {
    el.textContent = '';
    if (onFrame) onFrame(0);
    if (box) box.classList.add('dd-smetric--pending');
    el._cuDelay = setTimeout(() => { el._cuDelay = null; runCount(); }, delay);
  } else {
    runCount();
  }
}

let _ddVerdictKey = null; // identifies the product whose verdict is on screen

// A3: reveal a non-counting metric box (komp dots, peluang bar, review wall) on the
// same left-to-right stagger as the counting numbers. `fn` populates the box.
function _ddRevealMetric(box, delay, stagger, fn) {
  if (!stagger) { fn(); return; }
  if (box) box.classList.add('dd-smetric--pending');
  setTimeout(() => {
    if (box) { box.classList.remove('dd-smetric--pending'); box.classList.add('dd-smetric--counting'); }
    fn();
    setTimeout(() => { if (box) box.classList.remove('dd-smetric--counting'); }, 750);
  }, delay);
}

function ddRenderBeginnerVerdict(p) {
  if (!p) return;
  const listing = p._listing || {};
  const price = listing.price || p.medianPrice || 0;
  // New product → count metrics up from 0; same product (streamed update) → glide from current value.
  const _vKey = (p.id != null) ? p.id : (p.name || null);
  const _fromZero = _vKey !== _ddVerdictKey;
  _ddVerdictKey = _vKey;
  // A3: on a fresh product open, reveal the 6 metric boxes one at a time
  // left-to-right (~250ms apart). Streamed updates glide live.
  const _SD = 250;
  const _reduceM = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const _stagger = _fromZero && !_reduceM;
  const _dly = i => _stagger ? i * _SD : 0;
  if (_stagger) {
    document.querySelectorAll('#dd-simple-metrics .dd-smetric').forEach(b => {
      b.classList.add('dd-smetric--pending');
      b.classList.remove('dd-smetric--counting');
    });
  }
  const heroNum = parseInt((document.getElementById('dd-score-num')?.textContent || '').replace(/[^\d]/g, ''), 10);
  const score = Math.round(Number.isFinite(heroNum) ? heroNum : (p.score || 0));
  const lslbl = listingScoreLabel(score);

  _ddRevealMetric(document.getElementById('dd-s-odds')?.closest('.dd-smetric'), _dly(4), _stagger, () => ddRenderOddsTile(p));
  _ddRevealMetric(document.getElementById('dd-s-wall')?.closest('.dd-smetric'), _dly(5), _stagger, () => ddRenderReviewWallTile(p));

  const compBadge = document.getElementById('dd-hero-comp-badge');
  const compLbl = document.getElementById('dd-hero-comp-label');
  if (compBadge && compLbl) {
    if (score > 0) {
      compBadge.style.display = 'inline-flex';
      compBadge.style.background = lslbl.bg;
      compBadge.style.color = lslbl.clr;
      compBadge.style.borderColor = lslbl.border;
      compLbl.textContent = lslbl.lbl;
    } else {
      compBadge.style.display = 'none';
    }
  }

  const sNum = document.getElementById('dd-s-score-num');
  const sBar = document.getElementById('dd-s-score-bar');
  const sHint = document.getElementById('dd-s-score-hint');
  ddAnimateNum(sNum, score > 0 ? score : null,
    v => v == null ? '—' : String(Math.round(v)),
    _fromZero,
    v => { if (sBar) sBar.style.width = Math.min(100, Math.max(0, Math.round(v || 0))) + '%'; },
    _dly(0));
  if (sHint) {
    sHint.textContent = score >= 75
      ? 'Peluang tinggi — pasar masih terbuka'
      : score >= 55
        ? 'Cukup menjanjikan dengan strategi tepat'
        : score >= 35
          ? 'Perlu riset kompetitor sebelum masuk'
          : 'Pasar sangat kompetitif — butuh diferensiasi';
  }

  const omsetEl = document.getElementById('dd-h-omset');
  const omsetTxt = omsetEl?.textContent || '—';
  const omsetSub = document.getElementById('dd-h-omset-sub')?.textContent || '';
  const sOmset = document.getElementById('dd-s-omset');
  const sOmsetHint = document.getElementById('dd-s-omset-hint');
  const _omsetRaw = omsetEl?.dataset.omsetRaw;
  const _fmtOmsetV = v => v >= 1e9 ? 'Rp ' + (v / 1e9).toFixed(1) + 'M' : v >= 1e6 ? 'Rp ' + (v / 1e6).toFixed(1) + 'jt' : 'Rp ' + (v / 1e3).toFixed(0) + 'rb';
  if (sOmset) {
    if (_omsetRaw != null && _omsetRaw !== '') {
      const omsetTarget = parseFloat(_omsetRaw);
      ddAnimateNum(sOmset, omsetTarget > 0 ? omsetTarget : null, v => v == null ? '—' : _fmtOmsetV(v), _fromZero, null, _dly(1));
    } else {
      sOmset.textContent = omsetTxt; // no raw value available → show hero text as-is
    }
  }
  if (sOmsetHint && omsetSub && omsetSub !== '—' && omsetSub !== 'Total estimasi omset') {
    sOmsetHint.textContent = omsetSub;
  }

  const kompTxt = document.getElementById('dd-h-komp')?.textContent || '—';
  const kompSub = document.getElementById('dd-h-komp-sub')?.textContent || '';
  const sKomp = document.getElementById('dd-s-komp');
  const sKompDots = document.getElementById('dd-s-komp-dots');
  const sKompHint = document.getElementById('dd-s-komp-hint');
  _ddRevealMetric(sKomp?.closest('.dd-smetric'), _dly(2), _stagger, () => {
    if (sKomp) {
      sKomp.textContent = kompTxt;
      sKomp.className = 'dd-smetric-value' + (
        kompTxt === 'Rendah' ? ' komp-low' : kompTxt === 'Sedang' ? ' komp-med' : kompTxt === 'Tinggi' ? ' komp-high' : ''
      );
    }
    if (sKompDots) {
      const filled = kompTxt === 'Rendah' ? 2 : kompTxt === 'Sedang' ? 3 : kompTxt === 'Tinggi' ? 4 : 0;
      sKompDots.innerHTML = Array.from({ length: 5 }, (_, i) =>
        `<span class="dd-smetric-dot${i < filled ? ' on' : ''}"></span>`
      ).join('');
    }
    if (sKompHint && kompSub && kompSub !== 'Memuat data…') sKompHint.textContent = kompSub;
  });

  const sPrice = document.getElementById('dd-s-price');
  const sThumb = document.getElementById('dd-s-price-thumb');
  ddAnimateNum(sPrice, price > 0 ? price : null,
    v => v == null ? '—' : `Rp ${Math.round(v).toLocaleString('id-ID')}`,
    _fromZero, null, _dly(3));
  if (sThumb) {
    let left = 50;
    const prices = (_ddKwRows || []).map(r => r.price || 0).filter(v => v > 0).sort((a, b) => a - b);
    if (price > 0 && prices.length >= 2) {
      const pMin = prices[0], pMax = prices[prices.length - 1];
      const span = pMax - pMin || 1;
      left = Math.min(92, Math.max(8, Math.round((price - pMin) / span * 100)));
    } else {
      const zone = document.getElementById('dd-range-zone');
      if (zone?.style.left) {
        const l = parseFloat(zone.style.left);
        const w = parseFloat(zone.style.width || '0');
        if (!isNaN(l) && !isNaN(w)) left = Math.min(92, Math.max(8, l + w / 2));
      }
    }
    sThumb.style.left = left + '%';
  }
}

let _dscStarterKey = null;

function dscGetStarterCardKey() {
  if (_dscStarterKey) return _dscStarterKey;
  const start = (_dscPage - 1) * DSC_PER_PAGE;
  const page = _dscFiltered.slice(start, start + (isJourneyBeginner() ? JOURNEY_BEGINNER_DISCOVER_CAP : DSC_PER_PAGE));
  if (page.length) _dscStarterKey = `${page[0].item_id}__${page[0].shop_id}`;
  return _dscStarterKey;
}

function dscOpenStarterDeepDive() {
  const key = dscGetStarterCardKey();
  if (key) dscOpenDeepDive(key);
}

function dscHighlightStarterCard() {
  if (!isJourneyBeginner() && !_nuOnb.payoff) return;
  const grid = document.getElementById('dsc-card-grid');
  if (!grid) return;
  const key = _nuOnb.payoff ? _nuOnbRichKey : dscGetStarterCardKey();
  if (!key) return;
  grid.querySelectorAll('.dsc-card').forEach(el => {
    el.classList.remove('dsc-starter-card');
    el.querySelector('.dsc-starter-tag')?.remove();
  });
  const start = (_dscPage - 1) * DSC_PER_PAGE;
  const page = _dscFiltered.slice(start, start + DSC_PER_PAGE);
  const idx = page.findIndex(p => `${p.item_id}__${p.shop_id}` === key);
  const cards = [...grid.querySelectorAll('.dsc-card')];
  const el = cards[idx >= 0 ? idx : 0];
  if (!el) return;
  el.classList.add('dsc-starter-card');
  const img = el.querySelector('.dsc-card-img');
  if (img && !img.querySelector('.dsc-starter-tag')) {
    const tag = document.createElement('div');
    tag.className = 'dsc-starter-tag';
    tag.textContent = _nuOnb.payoff ? 'Lihat Deep Dive' : 'Mulai di sini';
    img.appendChild(tag);
  }
}

// ════════════════════════════════════════════════════════════
//  NEW-USER EMPTY STATES & CONTEXTUAL HINTS
// ════════════════════════════════════════════════════════════
const NU_HINT_KEY = 'larisid_hints_v1';
let _nuHintTimer = null;
let _nuHintCurrent = null;

function userHasTrackedProducts() {
  try { return trkLoad().length > 0; } catch { return false; }
}

function userHasAnyProduct() {
  return userHasTrackedProducts() || (savedProducts && savedProducts.size > 0);
}

function _nuHints() {
  try { return JSON.parse(localStorage.getItem(NU_HINT_KEY) || '{}'); } catch { return {}; }
}

function nuHintMark(key) {
  if (_admSimulateNewUser) return; // never mark hints seen on the admin's real account
  const h = _nuHints(); h[key] = true;
  try { localStorage.setItem(NU_HINT_KEY, JSON.stringify(h)); } catch (_) {}
}

function nuHintSeen(key) {
  if (_admSimulateNewUser) return false; // hints always replay during simulation
  return !!_nuHints()[key];
}

function nuHintDismiss(markKey) {
  if (markKey || _nuHintCurrent) nuHintMark(markKey || _nuHintCurrent);
  _nuHintCurrent = null;
  const ov = document.getElementById('hint-overlay');
  if (ov) ov.classList.remove('active');
}

function nuHintShow(key, opts) {
  if (nuHintSeen(key)) return;
  _nuHintCurrent = key;
  const title = document.getElementById('hint-title');
  const body  = document.getElementById('hint-body');
  const cta   = document.getElementById('hint-cta-btn');
  if (title) title.textContent = opts.title || '';
  if (body)  body.textContent  = opts.body  || '';
  if (cta) {
    cta.textContent = opts.cta || 'Lanjut';
    cta.onclick = () => {
      nuHintDismiss(key);
      if (typeof opts.onCta === 'function') opts.onCta();
    };
  }
  const ov = document.getElementById('hint-overlay');
  if (ov) ov.classList.add('active');
}

function nuScheduleHint(view) {
  if (!currentUser) return;
  if (_nuOnb.visible || _nuOnb.payoff) return;
  if (!journeyHintAllowed()) return;
  clearTimeout(_nuHintTimer);
  // Deep-dive popup hints intentionally removed for new users (A2): omit 'deepdive'
  // so no hint timer is scheduled when landing on the Deep Dive simple page.
  const delays = { dashboard: 3000, discover: 2500 };
  const delay = delays[view];
  if (!delay) return;
  _nuHintTimer = setTimeout(() => {
    if (view === 'dashboard' && isJourneyBeginner() && !nuHintSeen('dashboard_reco')) {
      journeyMarkHintShown();
      nuHintShow('dashboard_reco', {
        title: 'Produk untukmu hari ini',
        body: 'Ketuk salah satu rekomendasi di bawah untuk buka analisis — apakah produk ini layak dijual?',
        cta: 'Mengerti',
        onCta: () => {},
      });
    } else if (view === 'dashboard' && !userHasAnyProduct() && !nuHintSeen('dashboard')) {
      journeyMarkHintShown();
      nuHintShow('dashboard', {
        title: 'Mulai dengan mencari produk',
        body: 'Temukan peluang jualan di Discover — data nyata dari 60.000+ listing Shopee.',
        cta: 'Buka Discover',
        onCta: () => switchDashView('discover'),
      });
    } else if (view === 'discover' && isJourneyBeginner() && !nuHintSeen('discover_starter')) {
      journeyMarkHintShown();
      nuHintShow('discover_starter', {
        title: 'Mulai dari produk ini',
        body: 'Ketuk kartu yang ditandai untuk lihat apakah produk ini layak dijual.',
        cta: 'Buka produk ini',
        onCta: () => dscOpenStarterDeepDive(),
      });
    } else if (view === 'deepdive' && isJourneyBeginner() && userJourneyTier() === 0 && !nuHintSeen('deepdive_komp')) {
      journeyMarkHintShown();
      nuHintShow('deepdive_komp', {
        title: 'Lihat siapa kompetitormu',
        body: 'Baca ringkasan di atas, lalu buka tab kompetitor untuk bandingkan harga dan penjualan.',
        cta: 'Lihat kompetitor',
        onCta: () => ddSwitchTab('kompetitor'),
      });
    } else if (view === 'deepdive' && userJourneyTier() >= 1 && _ddCurrentP && !trkIsTracked(_ddCurrentP._listing || _ddKwListing) && !nuHintSeen('deepdive_track')) {
      journeyMarkHintShown();
      nuHintShow('deepdive_track', {
        title: 'Simpan produk ini',
        body: 'Lacak produk untuk cek lagi besok — kami kabari kalau ada perubahan penting.',
        cta: 'Lacak Produk',
        onCta: () => { const btn = document.getElementById('dd-track-btn'); if (btn) btn.click(); },
      });
    }
  }, delay);
}

function nuRefreshView(view) {
  const hasTracked = userHasTrackedProducts();
  const hasAny = userHasAnyProduct();

  const hbdPanel = document.getElementById('hbd-new-user-panel');
  const hbdReco  = document.getElementById('hbd-nu-reco');
  const hbdStats = document.getElementById('hbd-stats-row');
  const hbdOpp   = document.getElementById('hbd-product-opp-col');
  const hbdTrend = document.getElementById('hbd-trending-section');
  const hbdStrip = document.getElementById('hbd-tracked-strip');
  if (view === 'dashboard') {
    const empty = !hasTracked;
    const leaderMode = typeof _effectiveLeaderMode === 'function' && _effectiveLeaderMode();
    const lobby = isJourneyBeginner() && !leaderMode;
    if (leaderMode) {
      if (hbdPanel) hbdPanel.style.display = 'none';
      if (hbdReco)  hbdReco.style.display  = 'none';
      if (hbdStats) hbdStats.style.display = 'none';
      if (hbdOpp)   hbdOpp.style.display   = 'none';
      if (hbdTrend) hbdTrend.style.display  = 'none';
      if (hbdStrip) hbdStrip.style.display  = 'none';
    } else {
      if (hbdPanel) hbdPanel.style.display = (empty && !lobby) ? '' : 'none';
      if (hbdReco && typeof hbdRenderNuReco === 'function') hbdRenderNuReco();
      else if (hbdReco) hbdReco.style.display = 'none';
      if (hbdStats) hbdStats.style.display = (empty || lobby) ? 'none' : '';
      if (hbdOpp)   hbdOpp.style.display   = (empty || lobby) ? 'none' : '';
      if (hbdTrend) hbdTrend.style.display  = (empty || lobby) ? 'none' : '';
      if (hbdStrip) hbdStrip.style.display  = (empty || lobby) ? 'none' : hbdStrip.style.display;
      const sub = document.getElementById('hbd-subtitle');
      const recoTitle = document.getElementById('hbd-nu-reco-title');
      if (sub && lobby) {
        sub.textContent = journeyIsReturningUser() && journeyIsNewDaySinceLastBeranda()
          ? 'Selamat datang kembali — ada update sejak kunjungan terakhir.'
          : 'Ini produk pilihan untukmu hari ini — ketuk untuk analisis lengkap.';
      } else if (sub && !lobby) sub.textContent = 'Selamat datang kembali — berikut ringkasan produk kamu hari ini.';
      if (recoTitle && lobby) recoTitle.textContent = journeyIsReturningUser() ? 'Produk Pilihan Hari Ini' : 'Rekomendasi produk untuk kamu';
      const recoMsg = document.querySelector('#hbd-nu-reco .hbd-nu-reco-msg');
      if (recoMsg && lobby && journeyIsReturningUser()) {
        recoMsg.innerHTML = 'Set baru setiap hari — cek lagi besok. Ketuk produk untuk analisis, atau buka <a onclick="switchDashView(\'discover\')">Discover</a> untuk riset lebih lanjut.';
      }
      if (lobby) void journeyRenderReturnStrip();
    }
  }

  const ddEmpty = document.getElementById('dd-empty-state');
  const ddMain  = document.getElementById('dd-main-content');
  if (view === 'deepdive') {
    const noProd = !_ddCurrentP;
    if (ddEmpty) ddEmpty.style.display = noProd ? '' : 'none';
    if (ddMain)  ddMain.style.display  = noProd ? 'none' : '';
    if (noProd) journeyRenderEmptyReco('dd-empty-reco', 'deepdive');
  }

  // The tracker view has no host-owned empty state any more: LarisTracker
  // renders its own setup/collecting/rollup screens.

  const mlsEmpty = document.getElementById('mls-empty-state');
  const mlsMain  = document.getElementById('mls-main-content');
  if (view === 'ai') {
    const empty = !hasAny;
    if (mlsEmpty) mlsEmpty.style.display = empty ? '' : 'none';
    if (mlsMain)  mlsMain.style.display  = empty ? 'none' : '';
    if (empty) journeyRenderEmptyReco('mls-empty-reco', 'ai');
  }

}

function _mlsNameSimilarity(a, b) {
  const ta = new Set(_dscNormStr(a).split(/\s+/).filter(w => w.length > 2));
  const tb = new Set(_dscNormStr(b).split(/\s+/).filter(w => w.length > 2));
  if (!ta.size || !tb.size) return 0;
  let shared = 0;
  ta.forEach(w => { if (tb.has(w)) shared++; });
  return shared / Math.max(ta.size, tb.size);
}

function _mlsExtractVariant(name) {
  const colors = ['hitam','putih','merah','biru','hijau','kuning','pink','abu','coklat','navy','grey','gray','silver','gold'];
  const lower = (name || '').toLowerCase();
  const found = colors.filter(c => lower.includes(c));
  const sizeMatch = lower.match(/\b(xxl|xl|l|m|s|xs|\d+\s*(cm|ml|gr|kg|inch|"))\b/i);
  return [...found, sizeMatch ? sizeMatch[0] : ''].filter(Boolean).join(', ') || 'Lihat variasi populer di kompetitor';
}

function mlsRenderMarketRec(top5, mPrice) {
  const recEl = document.getElementById('mls-ai-rec');
  if (!recEl || !top5 || !top5.length) { if (recEl) recEl.style.display = 'none'; return; }
  const best = top5[0];
  const set = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v; };
  set('mls-rec-product', (best.product_name || '—').slice(0, 60));
  set('mls-rec-price', mPrice ? 'Rp ' + Math.round(mPrice).toLocaleString('id-ID') : (best.price ? 'Rp ' + Math.round(best.price).toLocaleString('id-ID') : '—'));
  set('mls-rec-variant', _mlsExtractVariant(best.product_name));
  recEl.style.display = '';
}

